const _verNum = (v) => String(v || "0").split(".").reduce((n, x) => n * 10000 + (Number(x) || 0), 0);
// Skupiny {v, items} od najnovšej verzie; okno ukáže prvú, ostatné až po „Staršie zmeny“ (rozhodnutie 24. 10.).
function whatsNewFor(role, seen) {
  return CHANGELOG.filter((c) => _verNum(c.v) > _verNum(seen))
    .sort((a, b) => _verNum(b.v) - _verNum(a.v))
    .map((c) => ({ v: c.v, items: c.items.filter((i) => !i.roles || role === "admin" || i.roles.includes(role)).map((i) => i.text) }))
    .filter((g) => g.items.length);
}
// Oblasť položky „Čo je nové“ podľa rolí, ktorým je určená (na zoskupenie dlhého zoznamu).
function whatsNewAreas(group) {
  const ORDER = ["Pre všetkých", "Požičovňa", "Prepravy a terén", "Servis", "Administrácia"];
  const area = (r) => {
    if (!r) return "Pre všetkých";
    if (r.every((x) => ["admin", "veduci_pozicovne", "veduci_servisu"].includes(x))) return "Administrácia";
    if (r.some((x) => x === "sofer" || x === "externy_sofer") && !r.includes("obchodnik")) return "Prepravy a terén";
    if (r.some((x) => ["dispecer_servisu", "veduci_servisu", "fakturant_servis", "veduci_technik_ba", "technik"].includes(x)) && !r.includes("dispecer_pozicovne")) return "Servis";
    if (r.some((x) => ["dispecer_pozicovne", "veduci_pozicovne", "obchodnik", "fakturant_pozicovna"].includes(x))) return "Požičovňa";
    return "Administrácia";
  };
  const src = CHANGELOG.find((c) => c.v === group.v)?.items || [];
  const out = {};
  group.items.forEach((t) => { const a = area(src.find((i) => i.text === t)?.roles); (out[a] = out[a] || []).push(t); });
  return ORDER.filter((a) => out[a]).map((a) => [a, out[a]]);
}
// Odkaz zákazníka na portál (?portal=<token>) nesmie odísť do hlásenia chýb — v adrese, breadcrumboch ani názve stránky.
function scrubPortalToken(event) {
  try { return JSON.parse(JSON.stringify(event).replace(/(portal=)[^&"#\s\\]+/g, "$1[skryté]")); } catch { return event; }
}
// Sledovanie chýb (Sentry) — zapne sa len s DSN (GitHub secret VITE_SENTRY_DSN), bez mien a e-mailov.
if (import.meta.env.VITE_SENTRY_DSN) {
  Sentry.init({
    dsn: import.meta.env.VITE_SENTRY_DSN,
    release: `mateco@${APP_VERSION}`,
    environment: import.meta.env.MODE,
    sendDefaultPii: false,
    integrations: [Sentry.browserTracingIntegration({ instrumentNavigation: false })],
    tracesSampleRate: 0.2, // ponytail: 20 % obrazoviek stačí na prehľad o používaní a drží free tier
    beforeSend(event) {
      event.tags = { ...event.tags, signal: navigator.onLine ? "áno" : "nie" };
      return scrubPortalToken(event);
    },
    beforeSendTransaction: scrubPortalToken,
  });
}
// Prehľad prepráv: hlavička dňa („Dnes · pi 2. 10.“ / „Po 5. 10.“) a deň v maile („na pondelok“).
const SK_DAY_SHORT = ["ne", "po", "ut", "st", "št", "pi", "so"];
const SK_DAY_ACC = ["nedeľu", "pondelok", "utorok", "stredu", "štvrtok", "piatok", "sobotu"];
const dayShortLabel = (iso) => { const d = new Date(`${iso}T12:00:00`); return `${SK_DAY_SHORT[d.getDay()]} ${d.getDate()}. ${d.getMonth() + 1}.`; };
const dayHead = (iso) => (iso === todayISO() ? `Dnes · ${dayShortLabel(iso)}` : dayShortLabel(iso).replace(/^./, (c) => c.toUpperCase()));
const dayLong = (iso) => SK_DAY_ACC[new Date(`${iso}T12:00:00`).getDay()];
// „14:32“ keď sa poslalo dnes, inak „po 14:32“.
const sentWhen = (iso) => {
  const d = new Date(iso);
  const hm = d.toLocaleTimeString("sk-SK", { hour: "2-digit", minute: "2-digit" });
  return toLocalISO(d) === todayISO() ? hm : `${SK_DAY_SHORT[d.getDay()]} ${hm}`;
};
// Kto je checker pre dané depo k danému dátumu — najprv sa pozrie, či nie je
// aktívna dočasná náhrada (napr. dovolenka checkera), inak vráti dedikovaného checkera.
function resolveCheckerId(depoCheckers, checkerSubstitutions, depo, dateISO) {
  // Ak sa prekrývajú dve náhrady pre to isté depo/dátum (napr. stará zabudnutá
  // a nová opravená), zoberie sa tá NAJNOVŠIE zadaná — platforma ich pridáva vždy
  // na koniec zoznamu, preto sa hľadá od konca, nie od začiatku.
  const list = checkerSubstitutions || [];
  for (let i = list.length - 1; i >= 0; i--) {
    const s = list[i];
    if (s.depo === depo && dateISO >= s.startDate && dateISO <= s.endDate) return s.substituteTechnicianId;
  }
  return depoCheckers?.[depo] || null;
}
// Prekrývajú sa dva dátumové rozsahy? Chýbajúci koniec (null) = bez konca (do nekonečna).
function rangesOverlap(aStart, aEnd, bStart, bEnd) {
  const aEndsAt = aEnd || "9999-12-31";
  const bEndsAt = bEnd || "9999-12-31";
  if (!(aStart <= bEndsAt && bStart <= aEndsAt)) return false;
  // Nadväzujúci prenájom: koniec jednej = začiatok druhej v ten istý deň (ráno zvoz, poobede vývoz) — nie je kolízia.
  if (aEndsAt === bStart && aStart < bStart) return false;
  if (bEndsAt === aStart && bStart < aStart) return false;
  return true;
}
// Stroj je mimo depa od vývozu po zvoz — kolízie rátať z väčšieho rozsahu
// (prednávoz pred začiatkom, zvoz po konci).
// Berie sa najmenší/najväčší zo štyroch dátumov — aj chybne zadaný vývoz po konci.
function jobFrom(j) {
  return [j.startDate, j.departureDate, j.endDate, j.pickupDate].filter(Boolean).sort()[0] || j.startDate;
}
function jobTo(j) {
  if (!j.endDate) return null;
  return [j.startDate, j.departureDate, j.endDate, j.pickupDate].filter(Boolean).sort().pop();
}
// Zákazka po termíne, stroj ešte nevrátený — pre kolízie drží stroj až do dnes.
function jobToBusy(j) {
  const t = jobTo(j);
  // +1 deň: inak by pravidlo „nadväzujúci prenájom“ (koniec = začiatok) pustilo novú zákazku od dnes; od zajtra áno.
  return t && t < todayISO() && j.status !== "completed" && !j.returnDone ? addDaysISO(todayISO(), 1) : t;
}
// Zákazka po termíne, stroj ešte nie je vrátený — ostáva u zákazníka až do vrátenia (rozhodnutie 23. 10.).
const jobStillOut = (j) => { const t = jobTo(j); return !!t && t < todayISO() && j.status !== "completed" && !j.returnDone && !j.notRealized; };
const stillOutWarning = (jobs, machineId, excludeJobId) => {
  const j = (jobs || []).find((x) => x.machineId === machineId && x.id !== excludeJobId && jobStillOut(x));
  return j ? `Stroj je po termíne u zákazníka ${j.customer || "—"} (koniec ${fmtDate(jobTo(j))}) a ešte nie je vrátený — overte termín zvozu.` : null;
};
// Je stroj v období from–to (vrátane prednávozu/zvozu) voľný? Vráti text kolízie alebo null.
function findMachineConflict(jobs, reservations, machineId, excludeJobId, from, to) {
  const clash = (jobs || []).find((x) => x.machineId === machineId && x.id !== excludeJobId && !x.notRealized && rangesOverlap(from, to, jobFrom(x), jobToBusy(x)));
  if (clash) return `Stroj má v tom čase zákazku ${clash.customer || ""} (${fmtDate(jobFrom(clash))}${jobTo(clash) ? " – " + fmtDate(jobTo(clash)) : ""})${jobToBusy(clash) !== jobTo(clash) ? " — po termíne, stroj ešte nie je vrátený" : ""}.`;
  const res = (reservations || []).find((r) => r.machineId === machineId && r.status === "approved" && rangesOverlap(from, to, r.expectedStart, r.expectedEnd));
  if (res) return `Stroj má v tom čase schválenú rezerváciu ${res.customer || ""} (${fmtDate(res.expectedStart)}).`;
  return null;
}
