// Ktoré depá smie daná "vedúci technik" rola vidieť/prideľovať — kľúč = rola.
// Pre ďalší región sa táto rola skopíruje (nové id + label vyššie) s iným
// zoznamom depí tu; undefined/chýbajúci kľúč = bez obmedzenia (napr. dispečer).
const LEAD_TECHNICIAN_DEPOS = {
  veduci_technik_ba: ["Bratislava", "Nitra"],
};
// Veta pod podpisom zákazníka (rovnaká ako v portáli).
function PrivacyNote() {
  return (
    <div style={{ fontSize: 12, color: "var(--text-dim)", marginTop: 2 }}>
      Meno a podpis zákazníka uložíme k protokolu. <a href={PRIVACY_URL} target="_blank" rel="noopener noreferrer" style={{ color: "inherit", textDecoration: "underline", display: "inline-flex", alignItems: "center", minHeight: 44 }}>Ochrana osobných údajov</a>
    </div>
  );
}
function myAssignableDepos(user) {
  return LEAD_TECHNICIAN_DEPOS[user?.role] || null;
}
// Vedúci technik BA: tiket stroja (externá zákazka: zvoleného depa) mimo jeho dep neprideľuje (DB to odmietne).
function damageInDeposOf(user, d, machineById) {
  const allowed = myAssignableDepos(user);
  return !allowed || allowed.includes(d.type === "externa" ? d.assignedDepo : machineById?.[d.machineId]?.depo);
}
// Ktorý modul sa má otvoriť ako prvý hneď po prihlásení, podľa role.
const ROLE_DEFAULT_MODULE = {}; // všetci začínajú na „Dnes“ (etapa 2) — fallback nižšie
function roleLabel(roleId) {
  return ROLES.find((r) => r.id === roleId)?.label || roleId;
}
function isAdminUser(user) {
  return !!user && user.role === "admin";
}
// Ktoré role smie daný človek v module Administratíva prideľovať zamestnancovi —
// vedúci prideľujú len role z vlastnej oblasti, admin ktorúkoľvek (okrem "nezaradený",
// to je len technický stav pred pridelením role).
function assignableRolesFor(user) {
  if (isAdminUser(user)) return ROLES.filter((r) => r.id !== "nezaradeny");
  if (user?.role === "veduci_pozicovne") return ROLES.filter((r) => ["obchodnik", "sofer", "externy_sofer", "dispecer_pozicovne", "fakturant_pozicovna"].includes(r.id));
  if (user?.role === "veduci_servisu") return ROLES.filter((r) => ["technik", "dispecer_servisu", "veduci_technik_ba", "fakturant_servis"].includes(r.id));
  return [];
}
// Ktoré role smie daný človek v Administratíve vôbec VIDIEŤ/spravovať (pridávať,
// upravovať, archivovať) — rovnaké obmedzenie ako pri prideľovaní role.
function manageableEmployeeRoles(user) {
  return assignableRolesFor(user).map((r) => r.id);
}

