      const prevById = new Map(prev.map((x) => [x.id, x]));
      const nextIds = new Set(next.map((x) => x.id));
      const toDelete = [];
      for (const id of prevById.keys()) {
        if (!nextIds.has(id)) toDelete.push(id);
      }
