// Nič nemaže na pozadí: zámok starší ako LOCK_TTL_MS sa jednoducho ignoruje
// (isLockActive), takže zabudnutá/spadnutá karta sa "uvoľní" sama.
const LOCK_TTL_MS = 90 * 1000;
const LOCK_HEARTBEAT_MS = 20 * 1000;
// id MUSÍ obsahovať userId — je to riadok "moja editácia tohto záznamu", nie
// "editácia tohto záznamu" (bez userId by dvaja editori prepisovali ten istý
// riadok navzájom svojím heartbeatom a banner by nezmyslene skákal medzi
// menami podľa toho, kto naposledy zapísal).
function writeRecordLock(table, recordId, userId, userName) {
  if (!userId || !userName) return;
  saveRecordRow("record_locks", { id: `${table}:${recordId}:${userId}`, table, recordId, userId, userName, lockedAt: new Date(serverNowMs()).toISOString() });
}
function clearRecordLock(table, recordId, userId) {
  if (!userId) return;
  deleteRecordRow("record_locks", `${table}:${recordId}:${userId}`);
}
const fmtClockSkew = (ms) => { const m = Math.round(ms / 60000); return m >= 120 ? `${Math.round(m / 60)} h` : m >= 60 ? `${Math.floor(m / 60)} h${m % 60 ? ` ${m % 60} min` : ""}` : `${m} min`; };
// Rozdiel hodín zariadenia voči serveru (lockedAt zapisuje DB, step61) — zlé hodiny
// inak skryli cudzí zámok alebo nechali spadnutý visieť hodinu.
async function syncServerClock() {
  const t0 = Date.now();
  const { data, error } = await supabase.rpc("server_now");
  if (error || !data) return;
  const t1 = Date.now();
  _lastServerMs = new Date(data).getTime();
  _clockOffsetMs = _lastServerMs - (t0 + t1) / 2;
  _clockSynced = true;
  try {
    localStorage.setItem("mateco_clock_offset", String(Math.round(_clockOffsetMs)));
    localStorage.setItem("mateco_clock_server", String(_lastServerMs));
  } catch { /* bez úložiska len v pamäti */ }
  _clockListener?.();
}
let _clockListener = null;
// Hodiny sa overia znova pri návrate siete a návrate do platformy (mohli sa medzitým zmeniť).
// Nie v zákazníckom portáli (main.jsx načíta aj tento súbor) — tam nie je prihlásenie.
if (typeof window !== "undefined" && !new URLSearchParams(window.location.search).get("portal")) {
  window.addEventListener("online", () => syncServerClock());
  document.addEventListener("visibilitychange", () => { if (document.visibilityState === "visible" && navigator.onLine) syncServerClock(); });
}
function isLockActive(lock) {
  return !!lock && Date.now() + _clockOffsetMs - new Date(lock.lockedAt).getTime() < LOCK_TTL_MS;
}
// Nájde aktívny zámok od INÉHO používateľa na danom zázname — vlastný zámok sa
// nezobrazuje (človek nemá vidieť banner "edituje X", keď X je on sám).
function findOtherLock(recordLocks, table, recordId, myUserId) {
  return (recordLocks || []).find((l) => l.table === table && l.recordId === recordId && l.userId !== myUserId && isLockActive(l)) || null;
}

/* ---------------------------------------------------------
   Searchable select
--------------------------------------------------------- */
function SearchInput({ value, onChange, placeholder, style }) {
  // Na mobile (viď @media) je toto pole cez CSS schované za lupu — namiesto
  // trvalo zabratého miesta v riadku filtrov (rovnaký vzor ako GlobalSearch
  // v hlavičke). Rozbalené ostáva otvorené, kým v ňom niečo je — zavrieť ho
  // ide len prázdne (Vymazať/kliknutie mimo pri prázdnej hodnote).
  const [mobileExpanded, setMobileExpanded] = useState(false);
  const boxRef = useRef(null);
  useEffect(() => {
    if (!mobileExpanded) return;
    function onDocClick(e) {
      if (boxRef.current && !boxRef.current.contains(e.target) && !value) setMobileExpanded(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [mobileExpanded, value]);

  return (
    <div ref={boxRef} className={`list-search-box${mobileExpanded ? " list-search-mobile-open" : ""}`} style={{ position: "relative", display: "inline-block", ...style }}>
      <button
        type="button"
        className="list-search-mobile-trigger header-icon-btn"
        onClick={() => setMobileExpanded(true)}
        aria-label="Hľadať"
        title="Hľadať"
        style={{ display: "none", background: "var(--panel-2)", border: "1px solid var(--border)", color: "var(--text-dim)", cursor: "pointer" }}
      >
        <NavIcon id="hladat" />
      </button>
      <div className="list-search-input-wrap" style={{ position: "relative" }}>
        <input
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          autoFocus={mobileExpanded}
          style={{ width: "100%", paddingRight: value ? 26 : undefined }}
        />
        {value && (
          <button
            type="button"
            onClick={() => onChange("")}
            title="Vymazať"
            style={{
              position: "absolute",
              right: 4,
              top: "50%",
              transform: "translateY(-50%)",
              background: "transparent",
              border: "none",
              color: "var(--text-dim)",
              cursor: "pointer",
              fontSize: 16,
              lineHeight: 1,
              padding: 4,
            }}
          >
            ×
          </button>
        )}
      </div>
    </div>
  );
}

// Znovupoužiteľné tlačidlo "Filtre" — schová rôzne filtre (depo, stav,
// archivované a pod.) za jedno tlačidlo s odznakom počtu aktívnych, namiesto
// toho, aby boli trvalo v samostatných riadkoch. activeCount > 0 tlačidlo aj
// vizuálne zvýrazní, nech nie je ľahké zabudnúť na aktívny filter.
function FilterPopover({ activeCount, onClear, children }) {
  const [open, setOpen] = useState(false);
  const btnRef = useRef(null);
  // minWidth:280 s "left:0" vedelo na užších obrazovkách vytiahnuť panel
  // mimo pravý okraj (tlačidlo "Filtre" nie je vždy na začiatku riadku) —
  // pri otvorení sa preto odmeria, koľko miesta ostáva doprava od tlačidla,
  // a ak sa 280px nezmestí, panel sa namiesto toho zarovná napravo (right:0),
  // nech vždy ostane celý na obrazovke.
  const [alignRight, setAlignRight] = useState(false);
  useLayoutEffect(() => {
    if (!open || !btnRef.current) return;
    const rect = btnRef.current.getBoundingClientRect();
    setAlignRight(window.innerWidth - rect.left < 280);
  }, [open]);
  return (
    <div style={{ position: "relative" }} ref={btnRef}>
      <button
        className="btn"
        onClick={() => setOpen((v) => !v)}
        style={{
          display: "flex",
          alignItems: "center",
          gap: 6,
          background: activeCount > 0 ? "var(--accent-light)" : "transparent",
          color: activeCount > 0 ? "var(--accent)" : "var(--text)",
          border: "1px solid " + (activeCount > 0 ? "var(--accent)" : "var(--border)"),
        }}
      >
        Filtre
        {activeCount > 0 && (
          <span className="count-badge">{activeCount}</span>
        )}
        <span style={{ fontSize: 9, opacity: 0.7 }}>{open ? "▴" : "▾"}</span>
      </button>
      {activeCount > 0 && (
        <button
          onClick={onClear}
          style={{ background: "transparent", border: "none", color: "var(--text-dim)", fontSize: 12, marginLeft: 6, cursor: "pointer", textDecoration: "underline" }}
        >
          ✕ Zrušiť filtre
        </button>
      )}
      {open && (
        <>
          <div style={{ position: "fixed", inset: 0, zIndex: 200 }} onClick={() => setOpen(false)} />
          <div
            className="panel"
            style={{
              position: "absolute",
              top: "calc(100% + 6px)",
              left: alignRight ? "auto" : 0,
              right: alignRight ? 0 : "auto",
              minWidth: 280,
              maxWidth: "calc(100vw - 32px)",
              zIndex: 201,
              padding: 14,
            }}
          >
            {children}
          </div>
        </>
      )}
    </div>
  );
}

// Malé ozubené koliesko — schová ľubovoľné nastavenia (zoradenie,
// prepínače...) za jedno ikonové tlačidlo. Na rozdiel od FilterPopover
// vyššie (má vlastný text "Filtre" + odznak počtu) je tu triggerom len
// samotná ikona ⚙ — použité tam, kde by aj krátky text zaberal na mobile
// príliš veľa miesta v riadku filtrov (napr. Kalendár požičovne).
function GearPopover({ children, className }) {
  const [open, setOpen] = useState(false);
  const btnRef = useRef(null);
  const [alignRight, setAlignRight] = useState(false);
  const [shift, setShift] = useState(0); // posun, keď by panel vytŕčal z obrazovky (úzky mobil)
  const panelRef = useRef(null);
  useLayoutEffect(() => {
    if (!open || !btnRef.current) { setShift(0); return; }
    const rect = btnRef.current.getBoundingClientRect();
    setAlignRight(window.innerWidth - rect.left < 260);
  }, [open]);
  useLayoutEffect(() => {
    if (!open || !panelRef.current) return;
    const pr = panelRef.current.getBoundingClientRect();
    if (pr.left < 8) setShift((x) => x + (8 - pr.left));
    else if (pr.right > window.innerWidth - 8) setShift((x) => x - (pr.right - (window.innerWidth - 8)));
  }, [open, alignRight]);
  useEffect(() => {
    if (!open) return;
    const esc = (e) => { if (e.key === "Escape") { setOpen(false); btnRef.current?.querySelector("button")?.focus(); } };
    document.addEventListener("keydown", esc);
    return () => document.removeEventListener("keydown", esc);
  }, [open]);
  return (
    <div className={className} style={{ position: "relative", display: className ? "none" : "inline-block" }} ref={btnRef}>
      <button
        type="button"
        className="btn btn-ghost header-icon-btn"
        onClick={() => setOpen((v) => !v)}
        aria-label="Nastavenia zobrazenia"
        title="Nastavenia zobrazenia"
        style={{ color: "var(--text-dim)" }}
      >
        ⚙
      </button>
      {open && (
        <>
          <div style={{ position: "fixed", inset: 0, zIndex: 200 }} onClick={() => setOpen(false)} />
          <div
            className="panel"
            ref={panelRef}
            onClick={(e) => { if (e.target.closest("button")) setOpen(false); }} // voľba urobená (napr. Legenda otvorí vlastné okno) — panel sa zavrie
            style={{
              position: "absolute",
              transform: shift ? `translateX(${shift}px)` : undefined,
              top: "calc(100% + 6px)",
              left: alignRight ? "auto" : 0,
              right: alignRight ? 0 : "auto",
              minWidth: 220,
              maxWidth: "calc(100vw - 32px)",
              zIndex: 201,
              padding: 12,
              display: "flex",
              flexDirection: "column",
              gap: 10,
            }}
          >
            {children}
          </div>
        </>
      )}
    </div>
  );
}

// Pole, ktoré uloží až pri opustení / Enter (nie po každom znaku); zmena od kolegu sa prejaví, len keď v ňom práve nepíšem.
function BlurInput({ value, onCommit, ...rest }) {
  const [v, setV] = useState(value);
  const focused = useRef(false);
  const dirty = useRef(false); // uložiť len to, čo človek naozaj napísal (nie starú hodnotu, keď ju medzitým zmenil kolega)
  useEffect(() => { if (!focused.current || !dirty.current) setV(value); }, [value]);
  const commit = () => { if (dirty.current && v !== value) onCommit(v); dirty.current = false; };
  return <input {...rest} value={v} onFocus={() => { focused.current = true; }} onChange={(e) => { dirty.current = true; setV(e.target.value); }}
    onBlur={() => { focused.current = false; commit(); }} onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); commit(); } }} />;
}
function SearchSelect({ options, value, onChange, placeholder, disabled }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const selected = options.find((o) => o.value === value);
  const matched = query
    ? options.filter((o) => o.label.toLowerCase().includes(query.toLowerCase()))
    : options;
  const filtered = matched.slice(0, 60);
  const [act, setAct] = useState(-1); // zvýraznená možnosť pre šípky
  const listId = useId();
  // Klik mimo zoznam ho zavrie a zároveň prejde ďalej (predtým ho zachytila priehľadná vrstva cez celé okno).
  const wrapRef = useRef(null);
  useEffect(() => {
    if (!open) return;
    const away = (e) => { if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", away, true);
    document.addEventListener("focusin", away, true);
    return () => { document.removeEventListener("mousedown", away, true); document.removeEventListener("focusin", away, true); };
  }, [open]);

  return (
    <div ref={wrapRef} style={{ position: "relative" }}>
      <input
        data-ss=""
        disabled={disabled}
        value={open ? query : selected ? selected.label : ""}
        role="combobox"
        aria-expanded={open}
        aria-controls={listId}
        aria-autocomplete="list"
        aria-activedescendant={open && act >= 0 && filtered[act] ? `${listId}-${act}` : undefined}
        onFocus={() => {
          setOpen(true);
          setQuery("");
          setAct(-1);
        }}
        onChange={(e) => { setQuery(e.target.value); setOpen(true); setAct(-1); }}
        onClick={() => { if (!open) { setOpen(true); setQuery(""); } }}
        // Enter vyberie prvú možnosť — nie odoslanie celého formulára (Modal).
        onKeyDown={(e) => {
          if (e.key === "Escape" && open) { e.stopPropagation(); setOpen(false); const el = e.currentTarget; setTimeout(() => el.select(), 0); return; } // Esc zavrie len zoznam, nie okno; text označený → písanie ho nahradí
          if (e.key === "ArrowDown" || e.key === "ArrowUp") {
            e.preventDefault();
            if (!open) { setOpen(true); setQuery(""); }
            setAct((i) => Math.max(0, Math.min(filtered.length - 1, i + (e.key === "ArrowDown" ? 1 : -1))));
            return;
          }
          if (e.key !== "Enter") return;
          e.preventDefault();
          if (open && act >= 0 && filtered[act]) { onChange(filtered[act].value); setOpen(false); return; }
          if (open && query && filtered.length > 0) {
            onChange(filtered[0].value);
            setOpen(false);
          }
        }}
        placeholder={placeholder}
        style={{ width: "100%" }}
      />
      {open && (
        <>
          <div
            className="panel"
            tabIndex={-1}
            id={listId}
            role="listbox"
            onMouseDown={(e) => e.preventDefault()} // fokus ostane v poli — inak by ho prevzalo okno a zoznam by sa zavrel pred výberom
            style={{
              position: "absolute",
              top: "calc(100% + 4px)",
              left: 0,
              right: 0,
              maxHeight: 220,
              overflowY: "auto",
              zIndex: 50,
              padding: 4,
            }}
          >
            {filtered.length === 0 && (
              <div style={{ padding: 8, color: "var(--text-dim)", fontSize: 13 }}>
                Žiadne výsledky
              </div>
            )}
            {filtered.map((o, i) => (
              <div
                key={o.value}
                id={`${listId}-${i}`}
                role="option"
                aria-selected={i === act}
                aria-label={o.badge ? `${o.label}, ${o.badge.text}` : undefined}
                ref={i === act ? (el) => el?.scrollIntoView({ block: "nearest" }) : undefined}
                onClick={() => {
                  onChange(o.value);
                  setOpen(false);
                }}
                style={{
                  background: i === act ? "rgba(255,138,30,.18)" : undefined,
                  padding: "6px 8px",
                  borderRadius: 4,
                  cursor: "pointer",
                  fontSize: 13,
                }}
                onMouseEnter={(e) => (e.currentTarget.style.background = "rgba(255,138,30,.12)")}
                onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
              >
                {o.badge ? (
                  <span style={{ display: "flex", justifyContent: "space-between", gap: 8, alignItems: "center" }}>
                    <span style={{ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis" }}>{o.label}</span>
                    <span className={`spill ${o.badge.cls}`} style={{ flexShrink: 0 }}>{o.badge.text}</span>
                  </span>
                ) : o.label}
              </div>
            ))}
            {matched.length > filtered.length && (
              <div style={{ padding: 8, color: "var(--text-dim)", fontSize: 13 }}>… a {plural(matched.length - filtered.length, "ďalší", "ďalšie", "ďalších")} — spresnite hľadanie</div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   Prepínač záložiek nad zlúčenými pohľadmi (Zákazky, Revízie, Podklady,
   Dáta požičovne) — rovné "karty" nad panelom (nie zakladač): aktívna
   karta splýva s panelom pod ňou (biela, hore červený prúžok), neaktívna
   je sivšia a nižšie. Panel pod kartami (rovnaký .panel štýl ako všade
   inde v appke) jasne orámuje, čo pod aktívnu záložku spadá. Prepína
   celé okno pod sebou, žiadne miešanie obsahu.
--------------------------------------------------------- */
function TabSwitcher({ options, active, onSelect, children }) {
  return (
    <div>
      <div className="utabs" role="tablist" style={{ marginTop: 0 }}>
        {options.map((o) => (
          <button key={o.id} type="button" role="tab" aria-selected={o.id === active} className={`utab${o.id === active ? " active" : ""}`} onClick={() => onSelect(o.id)}>
            {o.label}
            {o.count > 0 && <span className="seg-n" style={{ display: "inline-block", minWidth: 20, padding: "0 6px", borderRadius: 10, background: "var(--text)", color: "var(--panel)", fontSize: 13, fontWeight: 600, opacity: 1 }}>{o.count}</span>}
          </button>
        ))}
      </div>
      <div style={{ marginTop: 16 }}>
        {children}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Status badge
--------------------------------------------------------- */
function StatusBadge({ status }) {
  const map = {
    active: { cls: "badge-info", label: "Na zákazke" },
    awaitingOut: { cls: "spill-out", label: "Čaká na vývoz" },
    planned: { cls: "badge-warn", label: "Naplánovaná" },
    overdue: { cls: "badge-danger", label: "Po termíne" },
    completed: { cls: "badge-ok", label: "Dokončená" },
    free: { cls: "badge-ok", label: "Voľný" },
  };
  const m = map[status] || { cls: "badge-ok", label: status };
  return <span className={`badge ${m.cls}`}>{m.label}</span>;
}

// Stav zákazky ako pilulka (zoznam zákaziek) — farby podľa základu dizajnu.
function JobStatusPill({ status }) {
  const m = { active: ["spill-active", "Na zákazke"], awaitingOut: ["spill-out", "Čaká na vývoz"], planned: ["spill-planned", "Naplánovaná"], overdue: ["spill-overdue", "⚠ Po termíne"], completed: ["spill-done", "Dokončená"] }[status] || ["spill-planned", status];
  return <span className={`spill ${m[0]}`}>{m[1]}</span>;
}

// Skeleton riadky — namiesto textu "Načítavam…" počas async načítania (napr.
// audit log zo Supabase). Len šedé pruhy v tvare tabuľky.
function SkeletonRows({ rows = 5, cols = 4 }) {
  return (
    <div style={{ padding: "4px 0" }}>
      {Array.from({ length: rows }).map((_, r) => (
        <div key={r} style={{ display: "flex", gap: 16, padding: "10px 14px", borderBottom: r < rows - 1 ? "1px solid var(--border)" : "none" }}>
          {Array.from({ length: cols }).map((__, c) => (
            <div key={c} className="skeleton-bar" style={{ height: 12, borderRadius: 4, flex: c === 0 ? 1.4 : 1, opacity: 1 - r * 0.08 }} />
          ))}
        </div>
      ))}
    </div>
  );
}

// Kebab menu (⋮) pre riadky s viacerými akciami — namiesto radu tlačidiel v
// riadku tabuľky/karty. actions: [{ label, onClick, href?, danger? }, ...] —
// falsy položky (napr. akcia skrytá podľa práv) sa preskočia.
function KebabMenu({ actions, up, label, name, btnClass, btnStyle }) {
  const [open, setOpen] = useState(false);
  const btnRef = useRef(null);
  // Menu sa kreslí do body (portal) s pozíciou podľa tlačidla — inak ho orezal/posunul
  // bočný panel (transform) a mobilné pravidlo pre zvonček ho pripínalo hore na obrazovku.
  const [pos, setPos] = useState(null);
  const dropRef = useRef(null);
  const kbOpen = useRef(false); // otvorené klávesnicou (Enter/Space) → focus na prvú položku
  const toggle = (e) => {
    if (open) return setOpen(false);
    kbOpen.current = e?.detail === 0;
    const r = btnRef.current.getBoundingClientRect();
    const vw = window.innerWidth, vh = window.innerHeight;
    const n = actions.filter(Boolean).length;
    const below = vh - r.bottom, above = r.top;
    const openUp = up ? above > 120 || above > below : below < Math.min(n * 46 + 24, 320) && above > below;
    const p = { minWidth: Math.min(220, vw - 16), maxWidth: vw - 16, maxHeight: Math.max(160, (openUp ? above : below) - 12) };
    if (openUp) p.bottom = vh - r.top + 4; else p.top = r.bottom + 4;
    // zarovnať k pravej hrane tlačidla; keď by vyšlo mimo obrazovky, k ľavej
    if (r.right - p.minWidth >= 8) p.right = Math.max(8, vw - r.right); else p.left = Math.max(8, Math.min(r.left, vw - 8 - p.minWidth));
    setPos(p);
    setOpen(true);
  };
  // Menu širšie ako minWidth (dlhé položky) — po vykreslení dorovnať, aby nevyšlo mimo obrazovky ani vľavo, ani vpravo.
  useLayoutEffect(() => {
    const d = open && dropRef.current?.getBoundingClientRect();
    const vw = window.innerWidth;
    if (d && (d.left < 8 || d.right > vw - 8)) setPos((p) => ({ ...p, right: undefined, left: Math.max(8, Math.min(d.left, vw - 8 - d.width)) }));
  }, [open]);
  useEffect(() => {
    if (!open) return;
    const close = () => setOpen(false);
    window.addEventListener("resize", close);
    window.addEventListener("scroll", close, true);
    // Klávesnica: Esc zavrie len menu (capture + stop — inak by Modal zavrel celú kartu), ↑/↓ položky, Tab zavrie.
    const onKey = (e) => {
      const its = Array.from(dropRef.current?.querySelectorAll(".kebab-item") || []);
      if (e.key === "Escape") { e.preventDefault(); e.stopImmediatePropagation(); setOpen(false); btnRef.current?.focus(); }
      else if (e.key === "Tab") { if (dropRef.current?.contains(document.activeElement)) btnRef.current?.focus(); setOpen(false); }
      else if ((e.key === "ArrowDown" || e.key === "ArrowUp") && its.length) {
        e.preventDefault();
        const i = its.indexOf(document.activeElement);
        its[(i + (e.key === "ArrowDown" ? 1 : i < 0 ? 0 : -1) + its.length) % its.length].focus();
      }
    };
    document.addEventListener("keydown", onKey, true);
    if (kbOpen.current) dropRef.current?.querySelector(".kebab-item")?.focus();
    return () => { window.removeEventListener("resize", close); window.removeEventListener("scroll", close, true); document.removeEventListener("keydown", onKey, true); };
  }, [open]);
  const items = actions.filter(Boolean);
  if (items.length === 0) return null;
  return (
    <div style={{ position: "relative", display: "inline-block" }} onClick={(e) => e.stopPropagation()}>
      <button
        ref={btnRef}
        className={btnClass || "btn btn-ghost"}
        style={btnStyle || { fontSize: 15, padding: "4px 9px", lineHeight: 1 }}
        onClick={toggle}
        aria-label={name || "Akcie"}
        aria-haspopup="menu"
        aria-expanded={open}
        title={name || "Akcie"}
      >
        {label || "⋮"}
      </button>
      {open && pos && createPortal(
        <div onClick={(e) => e.stopPropagation()} onMouseDown={(e) => e.stopPropagation()}>
          <div style={{ position: "fixed", inset: 0, zIndex: 400 }} onClick={() => setOpen(false)} />
          <div ref={dropRef} className="panel kebab-drop" role="menu" style={{ position: "fixed", ...pos, overflowY: "auto", zIndex: 401, padding: 6 }}>
            {items.map((a, i) =>
              a.href ? (
                <a
                  key={i}
                  href={a.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="kebab-item"
                  role="menuitem"
                  style={{ color: a.danger ? "var(--danger)" : "var(--text)" }}
                  onClick={() => setOpen(false)}
                >
                  {a.label}
                </a>
              ) : (
                <button
                  key={i}
                  className="kebab-item"
                  role="menuitem"
                  style={{ color: a.danger ? "var(--danger)" : "var(--text)" }}
                  onClick={() => { setOpen(false); btnRef.current?.focus({ preventScroll: true }); a.onClick(); }}
                >
                  {a.label}
                </button>
              )
            )}
          </div>
        </div>,
        // do .app-shell (bez transform/overflow) — inak neplatí tmavý režim ani mobilné 44 px pre .kebab-item
        document.querySelector(".app-shell") || document.body
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   Modal shell
--------------------------------------------------------- */
// Počet aktuálne otvorených <Modal> okien naraz (nie React state — potrebné
// vidieť aj cez viac súčasne pripojených inštancií, napr. potvrdzovací
// dialóg nad kartou). Viď použitie nižšie (has-open-modal na body).
let openModalCount = 0;
// Poradie otvorených okien — klávesy (Esc/Enter) patria len najvrchnejšiemu,
// inak Esc v potvrdení zavrel naraz aj formulár pod ním.
const _modalStack = [];
function Modal({ title, eyebrow, onClose, onBack, children, wide, xwide, headerExtra, elevated, form, side, footer }) {
  // Esc zatvorí — jedno miesto, všetky okná postavené na Modal ho tým pádom
  // dostanú automaticky. Zámerne len na Escape (nie iné klávesy) a len
  // onClose (nie onBack) — Esc má vždy znamenať "zavrieť celé okno", nie
  // "krok späť v histórii kariet".
  // Enter v ľubovoľnom textovom poli klikne na hlavné (btn-accent) tlačidlo
  // okna — nie je treba siahať na myš po vyplnení formulára. Polia, ktoré si
  // Enter riešia samé (napr. prompt-dialógy), volajú e.stopPropagation() a
  // sem sa vôbec nedostanú. Vynechané: textarea (Enter = nový riadok),
  // checkbox/radio/file/select a už odoslaný/disabled stav.
  const panelRef = useRef(null);
  const tokenRef = useRef(null);
  // Bočný panel sa na PC zasunie späť (160 ms), až potom sa zavrie; inak (mobil, vypnuté animácie) hneď.
  // Počas zasúvania okno ďalšie kliky zachytí (klik „cez“ by otvoril inú kartu, ktorú by oneskorené zatvorenie hneď zavrelo).
  const closingRef = useRef(null);
  useEffect(() => () => clearTimeout(closingRef.current), []);
  const closeAnimated = () => {
    if (closingRef.current) return;
    const ov = panelRef.current?.parentElement;
    if (!side || !ov || getComputedStyle(ov).animationName === "none" || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return onClose();
    ov.classList.add("closing");
    closingRef.current = setTimeout(onClose, 160);
  };
  // Rozpísané údaje: čokoľvek sa v okne napísalo/zmenilo (alebo je to formulár
  // s podpisom/checklistom — prop form). Také okno sa klikom mimo nezatvorí
  // a Esc sa najprv opýta.
  const dirtyRef = useRef(false);
  const pressedOnOverlay = useRef(false);
  const confirmDiscard = () => !(dirtyRef.current || form) || window.confirm("Zavrieť okno? Rozpísané údaje sa neuložia.");
  // Karta v bočnom paneli (side bez form): výber/zaškrtnutie sa ukladá hneď — nie je čo stratiť;
  // rozpísaný text (poznámka, úprava firmy, výdaj dielov) sa stále chráni.
  // F5 / zatvorenie platformy s rozpísaným oknom — prehliadač sa najprv opýta (inak by sa stratili fotky, podpisy, text).
  useEffect(() => {
    const onBeforeUnload = (e) => { if (dirtyRef.current || form) { e.preventDefault(); e.returnValue = ""; } };
    window.addEventListener("beforeunload", onBeforeUnload);
    return () => window.removeEventListener("beforeunload", onBeforeUnload);
  }, [form]);
  const markDirty = (e) => {
    const t = e.target;
    if (form || !side || t.tagName === "TEXTAREA" || (t.tagName === "INPUT" && !["checkbox", "radio", "file"].includes(t.type))) dirtyRef.current = true;
  };
  // Tlačidlo, ktoré okno otvorilo — zachytené už pri prvom vykreslení (pole s autoFocus v okne by ho inak prebilo).
  const [opener] = useState(() => document.activeElement);
  useEffect(() => {
    const token = {};
    tokenRef.current = token;
    _modalStack.push(token);
    // Klávesnica: fokus do okna; po zatvorení späť na tlačidlo, ktoré ho otvorilo (nie pole — na mobile by vyskočila klávesnica).
    if (panelRef.current && !panelRef.current.contains(document.activeElement)) panelRef.current.focus({ preventScroll: true });
    return () => {
      const i = _modalStack.indexOf(token);
      if (i >= 0) _modalStack.splice(i, 1);
      // Až po prekreslení — tlačidlo (napr. „+“ v mobilnej lište) je pri otvorenom okne skryté a fokus by neprijalo.
      const back = () => {
        if (document.activeElement && document.activeElement !== document.body) return;
        if (opener && opener !== document.body && opener.isConnected && !opener.matches("input, textarea, select")) opener.focus({ preventScroll: true });
        else { const panels = document.querySelectorAll(".modal-panel"); panels[panels.length - 1]?.focus({ preventScroll: true }); } // tlačidlo zmizlo (napr. „Vybavené“) → okno pod ním
      };
      // Okno zavreté Enterom v poli (uloženie): fokus prejde na tlačidlo ešte počas stlačenia — bez preventDefault by ho Enter hneď „klikol“ (napr. znova otvoril menu).
      const ev = window.event;
      if (ev?.type === "keydown" && (ev.key === "Enter" || ev.key === " ")) ev.preventDefault();
      back(); setTimeout(back, 0);
    };
  }, []);
  useEffect(() => {
    function onKeyDown(e) {
      if (_modalStack[_modalStack.length - 1] !== tokenRef.current) return;
      if (e.key === "Escape") { if (confirmDiscard()) closeAnimated(); return; }
      // Tab krúži len po prvkoch otvoreného okna (inak kurzor odišiel na stránku pod oknom).
      if (e.key === "Tab" && panelRef.current) {
        const els = [...panelRef.current.querySelectorAll('a[href], button, input, select, textarea, iframe, [tabindex]:not([tabindex="-1"])')]
          .filter((el) => !el.disabled && el.getClientRects().length > 0 && el.type !== "hidden");
        if (els.length === 0) return;
        const first = els[0], last = els[els.length - 1];
        const inside = panelRef.current.contains(document.activeElement);
        if (!inside || (e.shiftKey && document.activeElement === first)) { e.preventDefault(); (e.shiftKey ? last : first).focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
        return;
      }
      if (e.key === "Enter" && !e.shiftKey && !e.defaultPrevented && e.target.tagName === "INPUT") {
        const skipTypes = ["checkbox", "radio", "file", "button", "submit", "reset", "range", "color"];
        if (skipTypes.includes(e.target.type)) return;
        if (!panelRef.current?.contains(e.target)) return;
        // Hlavné tlačidlo spodnej lišty má prednosť (iné červené tlačidlo v tele okna nie je „uložiť“).
        const btn = panelRef.current.querySelector(".job-form-foot .btn-accent:not(:disabled)") || panelRef.current.querySelector(".btn-accent:not(:disabled)");
        if (btn) { e.preventDefault(); btn.click(); return; }
        // Neúplný formulár s neaktívnym Uložiť — Enter = pokus o uloženie (ukáže „Chýba“), ako klik myšou.
        const tryEl = panelRef.current.querySelector(".ff-btns, .ff-try");
        if (tryEl) { e.preventDefault(); tryEl.click(); }
      }
    }
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onClose, form]);

  // Mobilná spodná lišta (mobile-tech-actions, z-index 150) sa napriek
  // vyššiemu z-indexu tohto okna (160/170) na iOS niekedy vedela prekresliť
  // NAD spodok otvorenej karty — z-index totiž platí len v rámci JEDNÉHO
  // stacking kontextu a lišta je v inej časti stromu (vykresľuje ju
  // <Header>) než táto karta. Namiesto lovenia presnej príčiny sa lišta
  // počas otvoreného okna (počítadlo — okien môže byť otvorených naraz
  // viac, napr. potvrdenie nad kartou) rovno schová celá, nech sa s ničím
  // nemá šancu prekrývať.
  useEffect(() => {
    openModalCount++;
    document.body.classList.add("has-open-modal");
    return () => {
      openModalCount--;
      if (openModalCount <= 0) document.body.classList.remove("has-open-modal");
    };
  }, []);
  return (
    <div
      className={`modal-overlay${side ? " modal-side" : ""}`}
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0,0,0,.55)",
        // Nad mobilnou spodnou lištou (z-index 150) — inak ňou boli na mobile
        // prekryté tlačidlá na spodku otvorenej karty/formulára a nedali sa
        // použiť. Pod dropdown menu a notifikáciami (200+), tie majú ostať
        // dostupné aj cez otvorené okno.
        // elevated (170) je pre potvrdzovacie okná otvárané SPOD inej karty —
        // všetky Modal majú rovnaké 160, takže poradie dvoch takých by sa inak
        // riadilo poradím v kóde, nie poradím otvorenia, a potvrdenie by vedelo
        // vypadnúť pod kartu, z ktorej bolo vyvolané.
        zIndex: elevated ? 170 : 160,
        display: "flex",
        // side: bočný panel cez celú výšku vpravo (karta zákazky), scrolluje sa panel, nie overlay
        alignItems: side ? "stretch" : "flex-start",
        justifyContent: side ? "flex-end" : "center",
        padding: side ? 0 : "40px 16px",
        overflowY: side ? "hidden" : "auto",
      }}
      // Zatvorí sa len klik, ktorý aj ZAČAL mimo okna (ťah myšou z okna von
      // pri označovaní textu/podpise okno nezavrie) a len bez rozpísaných údajov.
      onMouseDown={(e) => { pressedOnOverlay.current = e.target === e.currentTarget; }}
      onClick={(e) => {
        if (e.target !== e.currentTarget || !pressedOnOverlay.current) return;
        if (dirtyRef.current || form) return;
        closeAnimated();
      }}
    >
      <div
        ref={panelRef}
        tabIndex={-1}
        role="dialog"
        aria-modal="true"
        aria-label={typeof title === "string" ? title : typeof eyebrow === "string" ? eyebrow : undefined}
        className={`panel modal-panel${side ? " modal-side-panel" : ""}`}
        onClick={(e) => e.stopPropagation()}
        onInput={markDirty}
        onChange={markDirty}
        style={{ width: side ? 580 : xwide ? 980 : wide ? 640 : 460, maxWidth: "100%", padding: side ? 0 : 20 }}
      >
        {side ? (
          <>
            <div className="side-head">
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span className="side-eyebrow">{eyebrow}</span>
                {onBack && <button className="btn btn-ghost" style={{ marginLeft: "auto" }} onClick={onBack}>← Späť</button>}
                <button className="modal-close-x" style={{ marginLeft: onBack ? 0 : "auto" }} onClick={() => { if (confirmDiscard()) closeAnimated(); }} aria-label="Zavrieť" title="Zavrieť">×</button>
              </div>
              <h3 className="side-title">{title}</h3>
              {headerExtra}
            </div>
            <div className="side-body">{children}</div>
            {footer && <div className="side-foot">{footer}</div>}
          </>
        ) : eyebrow ? (
          <>
            {/* Horný "toolbar" riadok — všetky tlačidlá pohromade vpravo
                (Karta stroja/iná súvisiaca akcia, Späť, ×), vždy na tom istom
                mieste bez ohľadu na dĺžku titulku pod ním (predtým bol
                titulok v tom istom riadku ako tlačidlá a pri dlhšom texte sa
                nepekne lámal popri nich). */}
            <div className="modal-toolbar">
              <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                {headerExtra}
                {onBack && (
                  <button className="btn btn-ghost" onClick={onBack}>
                    ← Späť
                  </button>
                )}
                <button className="modal-close-x" onClick={() => { if (confirmDiscard()) onClose(); }} aria-label="Zavrieť" title="Zavrieť">
                  ×
                </button>
              </div>
            </div>
            <div className="modal-title-block">
              <div className="modal-eyebrow">{eyebrow}</div>
              <h3 className="modal-title-main">{title}</h3>
            </div>
          </>
        ) : (
          <div className="modal-header" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16, gap: 10 }}>
            <h3 className="modal-title-main">
              {title}
            </h3>
            <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
              {onBack && (
                <button className="btn btn-ghost" onClick={onBack}>
                  ← Späť
                </button>
              )}
              {headerExtra}
              <button className="modal-close-x" onClick={() => { if (confirmDiscard()) onClose(); }} aria-label="Zavrieť" title="Zavrieť">
                ×
              </button>
            </div>
          </div>
        )}
        {!side && children}
      </div>
    </div>
  );
}

function ConfirmDeleteModal({ label, onClose, onConfirm, trash }) {
  const [step, setStep] = useState(1);
  if (trash) {
    return (
      <Modal title="Presunúť do Koša?" onClose={onClose} elevated>
        <div style={{ fontSize: 15, marginBottom: 18, lineHeight: 1.45 }}>
          Vymazať {label}? Presunie sa do Koša — vedúci ho tam vie obnoviť.
        </div>
        <FormFoot confirm>
          <button className="btn btn-accent" onClick={() => { onConfirm(); onClose(); }}>
            Presunúť do Koša
          </button>
        </FormFoot>
      </Modal>
    );
  }
  return (
    <Modal title={step === 1 ? "Naozaj vymazať?" : "Potvrďte vymazanie"} onClose={onClose} elevated>
      {step === 1 ? (
        <>
          <div style={{ fontSize: 15, marginBottom: 18, lineHeight: 1.45 }}>Naozaj chcete vymazať {label}?</div>
          <FormFoot confirm>
            <button className="btn btn-accent" onClick={() => setStep(2)}>
              Áno, pokračovať
            </button>
          </FormFoot>
        </>
      ) : (
        <>
          <div className="fnote fnote-r" style={{ fontSize: 15 }}>⚠ 
            Potvrďte vymazanie: {label}. Tento krok sa nedá vrátiť späť.
          </div>
          <FormFoot confirm>
            <button
              className="btn btn-accent"
              onClick={() => {
                onConfirm();
                onClose();
              }}
            >
              Vymazať natrvalo
            </button>
          </FormFoot>
        </>
      )}
    </Modal>
  );
}

// Dvojkrokové potvrdenie pred vyradením protokolu zo zákazky — nech sa nedá omylom
// odkliknúť (napr. keď checker pri umytí stroja omylom klikne na upozornenie na
// otvorenú zákazku a protokol sa priradí nesprávne). Protokol sa nezmaže, len sa
// odpojí od zákazky a vráti na kartu stroja medzi "Ostatné protokoly".
function UnassignProtocolModal({ protocol, onClose, onConfirm }) {
  const [step, setStep] = useState(1);
  return (
    <Modal title={step === 1 ? "Vyradiť protokol zo zákazky?" : "Potvrďte vyradenie"} onClose={onClose} elevated>
      {step === 1 ? (
        <>
          <div style={{ fontSize: 15, marginBottom: 6, lineHeight: 1.45 }}>
            Protokol — {protocol.technicianName || "—"} ({fmtDate(protocol.createdAt)}) — sa odpojí od tejto
            zákazky a vráti sa medzi "Ostatné protokoly" na karte stroja. Samotný protokol sa nezmaže.
          </div>
          <div style={{ fontSize: 14, color: "var(--text-dim)", marginBottom: 18, whiteSpace: "pre-line" }}>
            {protocol.workDescription || "— bez popisu vykonanej práce —"}
          </div>
          <FormFoot confirm>
            <button className="btn btn-accent" onClick={() => setStep(2)}>
              Áno, vyradiť →
            </button>
          </FormFoot>
        </>
      ) : (
        <>
          <div className="fnote fnote-r" style={{ fontSize: 15 }}>⚠ 
            Naozaj vyradiť tento protokol zo zákazky? Zákazka tým môže ostať bez priradeného protokolu.
          </div>
          <FormFoot confirm>
            <button
              className="btn btn-accent"
              onClick={() => { onConfirm(); onClose(); }}
            >
              Vyradiť zo zákazky
            </button>
          </FormFoot>
        </>
      )}
    </Modal>
  );
}

// Dvojkrokové potvrdenie pred zrušením ukončenia zákazky — ukáže, aké protokoly
// zákazka reálne má (prevzatie/vrátenie), nech dispečer vidí presne, čoho sa to
// týka, skôr než to potvrdí. Bez tejto kontroly by sa dala vyviezená/vrátená
// zákazka omylom "znovuotvoriť" jedným klikom bez akéhokoľvek varovania.
// Dvojkrokové potvrdenie pred opätovným otvorením vyriešenej revízie/úradnej
// skúšky — vráti sa medzi nevyriešené, nech sa to nedá omylom odkliknúť.
function ReopenConfirmModal({ label, onClose, onConfirm }) {
  const [step, setStep] = useState(1);
  return (
    <Modal title={step === 1 ? "Otvoriť znova?" : "Potvrďte opätovné otvorenie"} onClose={onClose} elevated>
      {step === 1 ? (
        <>
          <div style={{ fontSize: 15, marginBottom: 18, lineHeight: 1.45 }}>
            Naozaj chcete znova otvoriť {label}? Vráti sa medzi nevyriešené.
          </div>
          <FormFoot confirm>
            <button className="btn btn-black" onClick={() => setStep(2)}>
              Áno, pokračovať →
            </button>
          </FormFoot>
        </>
      ) : (
        <>
          <div className="fnote fnote-y" style={{ fontSize: 15, fontWeight: 600 }}>
            Potvrďte: znova otvoriť {label} a vrátiť medzi nevyriešené.
          </div>
          <FormFoot confirm>
            <button
              className="btn btn-black"
              onClick={() => { onConfirm(); onClose(); }}
            >
              Otvoriť znova
            </button>
          </FormFoot>
        </>
      )}
    </Modal>
  );
}

function UncompleteJobConfirmModal({ job, handoverProtocol, onClose, onConfirm }) {
  const [step, setStep] = useState(1);
  const hasHandover = !!handoverProtocol?.handoverDone;
  const hasReturn = !!handoverProtocol?.returnDone;
  return (
    <Modal title={step === 1 ? "Zrušiť ukončenie zákazky?" : "Potvrďte zrušenie ukončenia"} onClose={onClose} elevated>
      {step === 1 ? (
        <>
          <div style={{ fontSize: 15, marginBottom: 10, lineHeight: 1.45 }}>
            Zákazka {job.code || job.cisloZmluvy ? `${job.code || job.cisloZmluvy} ` : ""}sa vráti medzi aktívne — prestane byť "ukončená". Koniec, zvoz, depo
            návratu aj depo stroja sa vrátia na hodnoty spred ukončenia.
          </div>
          <div className="fnote fnote-i tnum">
            <div style={{ marginBottom: 4 }}>
              Protokol o prevzatí: {hasHandover ? `✓ áno (${fmtDate(handoverProtocol.handoverDate)})` : "— nie je vypísaný"}
            </div>
            <div>
              Protokol o vrátení: {hasReturn ? `✓ áno (${fmtDate(handoverProtocol.returnDate)})` : "— nie je vypísaný"}
            </div>
          </div>
          <FormFoot confirm>
            <button className="btn btn-black" onClick={() => setStep(2)}>
              Áno, zrušiť ukončenie →
            </button>
          </FormFoot>
        </>
      ) : (
        <>
          <div className="fnote fnote-y" style={{ fontSize: 15, fontWeight: 600 }}>
            Naozaj zrušiť ukončenie tejto zákazky? Vráti sa medzi aktívne, kým ju niekto znova neukončí.
          </div>
          <FormFoot confirm>
            <button
              className="btn btn-black"
              onClick={() => { onConfirm(); onClose(); }}
            >
              Zrušiť ukončenie
            </button>
          </FormFoot>
        </>
      )}
    </Modal>
  );
}

/* ---------------------------------------------------------
   Archive with reason (machine sold, staff left, etc.)
--------------------------------------------------------- */
function ArchiveReasonModal({ label, reasons, onClose, onConfirm }) {
  const [reason, setReason] = useState("");
  const [note, setNote] = useState("");
  return (
    <Modal title="Archivovať" onClose={onClose}>
      <div style={{ fontSize: 15, marginBottom: 16, lineHeight: 1.45 }}>
        Chystáte sa archivovať {label}. Archivované položky sa skryjú z bežných zoznamov a nedajú sa ďalej prideľovať, ale dáta zostanú zachované — dá sa to kedykoľvek vrátiť späť.
      </div>
      <Field label="Dôvod archivácie *">
        <select value={reason} onChange={(e) => setReason(e.target.value)} style={{ width: "100%" }}>
          <option value="">— vybrať dôvod —</option>
          {reasons.map((r) => <option key={r} value={r}>{r}</option>)}
        </select>
      </Field>
      <Field label="Poznámka">
        <textarea value={note} onChange={(e) => setNote(e.target.value)} rows={2} placeholder="Voliteľný detail…" style={{ width: "100%" }} />
      </Field>
      <FormFoot confirm missing={!reason ? ["dôvod"] : []}>
        <button
          className="btn btn-accent"
          disabled={!reason}
          onClick={() => {
            onConfirm(reason, note.trim());
            onClose();
          }}
        >
          Potvrdiť archiváciu
        </button>
      </FormFoot>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Generic single-step confirm action (e.g. stop tracking revisions)
--------------------------------------------------------- */
function ConfirmActionModal({ message, confirmLabel, onClose, onConfirm }) {
  return (
    <Modal title="Potvrdenie" onClose={onClose} elevated>
      <div style={{ fontSize: 15, marginBottom: 18, lineHeight: 1.45 }}>{message}</div>
      <FormFoot confirm>
        <button
          className="btn btn-accent"
          onClick={() => {
            onConfirm();
            onClose();
          }}
        >
          {confirmLabel || "Potvrdiť"}
        </button>
      </FormFoot>
    </Modal>
  );
}

function Field({ label, children }) {
  // Popis spojený s poľom (čítačka obrazovky) — len keď je potomok jedno pole.
  const autoId = useId();
  const single = React.isValidElement(children) && ["input", "select", "textarea"].includes(children.type);
  const id = single ? children.props.id || autoId : undefined;
  return (
    <div className="fld">
      <label className="fld-l" htmlFor={id}>{label}</label>
      {single ? React.cloneElement(children, { id }) : children}
    </div>
  );
}

// Zrušiť v spodnej lište = to isté ako × okna (vrátane otázky pri rozpísaných údajoch).
const closeOwnModal = (e) => e.currentTarget.closest(".modal-panel")?.querySelector(".modal-close-x")?.click();
// Spoločná spodná lišta formulára/potvrdenia (v1.0.794): vľavo `left` a čo chýba,
// vpravo Zrušiť + jedno hlavné tlačidlo (children). confirm = potvrdzovacie okno
// (na mobile ostáva Zrušiť vedľa akcie, vo formulári ho nahrádza × v hlavičke).
function FormFoot({ missing, progress, left, cancel = true, confirm, children }) {
  const [tried, onTry] = useSaveTry();
  const has = missing?.length > 0;
  return (
    <div className={`job-form-foot${confirm ? " ff-confirm" : ""}${tried && has ? " ff-tried" : ""}`}>
      {left}
      <MissPill missing={missing} tried={tried} progress={progress} />
      <div className="ff-btns" onClick={has ? onTry : undefined}>
        {cancel && <button type="button" className="btn btn-outline ff-cancel" onClick={closeOwnModal}>Zrušiť</button>}
        {children}
      </div>
    </div>
  );
}
// v1.0.805: „Chýba“ až po pokuse o uloženie. Pokus = klik na neaktívne hlavné tlačidlo (CSS ho prepustí
// na rodiča .ff-btns) alebo na tlačidlo s data-incomplete (vždy aktívne Uložiť pri neúplnom formulári).
// Posunie na prvé pole označené data-miss a zvýrazní ho; nič neukladá.
// Formuláre bez data-miss: prázdne povinné polia (Field s „*“) označiť do najbližšej zmeny a vrátiť prvé.
function markEmptyRequired(panel) {
  if (!panel) return null;
  const empty = [...panel.querySelectorAll(".fld")].map((f) => /\*/.test(f.querySelector(".fld-l")?.textContent || "")
    && f.querySelector("input:not([type=hidden]):not([type=checkbox]):not([type=radio]):not([type=file]):not(:disabled), select:not(:disabled), textarea:not(:disabled)"))
    .filter((c) => c && !String(c.value || "").trim());
  empty.forEach((c) => {
    c.setAttribute("data-miss-auto", "");
    const off = () => c.removeAttribute("data-miss-auto");
    c.addEventListener("input", off, { once: true });
    c.addEventListener("change", off, { once: true });
  });
  return empty[0] || null;
}
// Esc zavrie otvorené rozbaľovacie menu (zvonček, účet) — nie okno pod ním.
function useEscClose(open, setOpen) {
  useEffect(() => {
    if (!open) return;
    const onKey = (e) => { if (e.key === "Escape") { e.stopPropagation(); setOpen(false); } };
    document.addEventListener("keydown", onKey, true);
    return () => document.removeEventListener("keydown", onKey, true);
  }, [open, setOpen]);
}
function useSaveTry() {
  const [tried, setTried] = useState(false);
  const onTry = (e) => {
    if (e.target !== e.currentTarget && !e.target.closest("[data-incomplete]")) return;
    setTried(true);
    const panel = e.currentTarget.closest(".modal-panel");
    const t = panel?.querySelector("[data-miss]") || markEmptyRequired(panel);
    if (!t) return;
    t.scrollIntoView({ behavior: "smooth", block: "center" });
    const el = t.matches("input, select, textarea, button") ? t : t.querySelector("input:not([type=hidden]):not([type=file]):not(:disabled), select, textarea, button:not(:disabled)");
    if (el && !el.hasAttribute("data-ss")) el.focus({ preventScroll: true }); // výber zo zoznamu by sa fokusom otvoril cez celé okno
  };
  return [tried, onTry];
}
function MissPill({ missing, tried, progress }) {
  if (tried && missing?.length) return <span className="miss-pill" role="status">Chýba: {missing.join(", ")}</span>;
  if (progress) return <span className="miss-pill miss-soft tnum">{progress}</span>;
  return missing?.length > 0 ? <span className="miss-pill miss-soft">Ešte treba: {missing.join(", ")}</span> : null;
}
// Očíslovaný nadpis kroku dlhého formulára (protokol, kontrola, meranie, import).
function FormStep({ n, title, right }) {
  return (
    <div className="fstep">
      {n != null && <span className="fstep-n">{n}</span>}
      <span className="fstep-t">{title}</span>
      {right}
    </div>
  );
}

