  const [showUnknownSerialReport, setShowUnknownSerialReport] = useState(false); // volajúci nepozná sériové číslo
  const [attachMachineTarget, setAttachMachineTarget] = useState(null); // poškodenie bez stroja, ktorému sa dopĺňa sériové číslo
  const [undoPartialTarget, setUndoPartialTarget] = useState(null); // U20 — potvrdenie zrušenia čiastočného dokončenia ZZ+EZ
  const [reopenTarget, setReopenTarget] = useState(null); // revízia/úradná skúška, ktorá sa otvára znova — dvojkrokové potvrdenie
  const [uncompleteJobTarget, setUncompleteJobTarget] = useState(null); // zákazka, ktorej sa ruší ukončenie — dvojkrokové potvrdenie
  const [showExternalReport, setShowExternalReport] = useState(false); // manual external service entry
  const [editExternalTarget, setEditExternalTarget] = useState(null); // existujúca externá zákazka na úpravu
  const [serviceEventDetail, setServiceEventDetail] = useState(null); // detail karta poškodenia/externej zákazky
  const [damagesSummaryOpen, setDamagesSummaryOpen] = useState(false); // Zhrnutie — Poškodenia strojov požičovne
  const [externaSummaryOpen, setExternaSummaryOpen] = useState(false); // Zhrnutie — Externé servisné zákazky
  const [jobCardNonce, setJobCardNonce] = useState(0); // klik na upozornenie k už otvorenej karte zákazky → prepne záložku
  const [highlightDamageId, setHighlightDamageId] = useState(null); // "rozsvietený" záznam po kliknutí na notifikáciu
  const [sparePartsTargetDepo, setSparePartsTargetDepo] = useState(null); // po kliknutí na notifikáciu o diele — na ktoré depo sa prepne
  const [highlightLocation, setHighlightLocation] = useState(null); // { module, view } — kam sa dá vrátiť z plávajúcej pripomienky
  const [statDomainTarget, setStatDomainTarget] = useState(null); // {domain, n} — týždenný súhrn otvorí štatistiky svojej časti
  const [plannerTargetDate, setPlannerTargetDate] = useState(null); // ISO dátum, na ktorý sa má Plán servisu odscrollovať (odkaz z notifikácie)
  const [highlightTransportId, setHighlightTransportId] = useState(null); // "<jobId>-vyvoz"/"-zvoz" — zvýraznená preprava po kliknutí na notifikáciu
  const [damageAssignTarget, setDamageAssignTarget] = useState(null); // damage object
  const [completeRevisionTarget, setCompleteRevisionTarget] = useState(null); // revision damage object
  const [completeUradnaSkuskaTarget, setCompleteUradnaSkuskaTarget] = useState(null); // úradná skúška damage object
  const [resolveDamageTarget, setResolveDamageTarget] = useState(null); // poškodenie being resolved (date+comment form)
  const [confirmUnassignProtocol, setConfirmUnassignProtocol] = useState(null); // { protocol, onConfirm } — dvojkrokové potvrdenie pred vyradením protokolu zo zákazky
  const [viewResolutionTarget, setViewResolutionTarget] = useState(null); // resolved damage/revision being viewed from machine card history
  // Všeobecná "história kariet" — keď sa z jednej karty (stroj/zákazka/poškodenie/
  // šofér/technik) otvorí ďalšia, predošlá sa sem odloží, nech je na ňu cesta späť
  // (tlačidlo "Späť"), namiesto toho, aby proste zmizla. "Zavrieť" na najhlbšej
  // karte históriu vyprázdni celú (vráti na pôvodný zoznam), "Späť" len o krok.
  const [cardHistory, setCardHistory] = useState([]); // [{ type, data }]
  function pushCard(type, data) {
    if (!data) return;
    setCardHistory((prev) => [...prev, { type, data }]);
  }
  function goBackCard() {
    const last = cardHistory[cardHistory.length - 1];
    if (!last) return;
    setCardHistory((prev) => prev.slice(0, -1));
    // Vždy sa vráti čerstvá verzia záznamu (nie zamrznutá kópia spred otvorenia
    // ďalšej karty) — inak by po úprave/uložení karta pri návrate ukazovala
    // starý stav, kým by sa appka znova neobnovila.
    if (last.type === "machine") setMachineCard(enrichedMachineById[last.data.id] || last.data);
    else if (last.type === "job") setJobDetail(jobs.find((j) => j.id === last.data.id) || last.data);
    else if (last.type === "serviceEvent") setServiceEventDetail(damages.find((d) => d.id === last.data.id) || last.data);
    else if (last.type === "driver") setDriverCard(drivers.find((d) => d.id === last.data.id) || last.data);
    else if (last.type === "technician") setTechnicianCard(technicians.find((t) => t.id === last.data.id) || last.data);
    else if (last.type === "reservation") setReservationCardTarget(reservations.find((r) => r.id === last.data.id) || last.data);
  }

  function setModule(m) {
    setModuleRaw(m);
    // Prvá záložka modulu podľa menu roly.
    const mod = buildNavModules(effectiveUser, 0, myEmployee).find((x) => x.id === m);
    setView(mod?.tabs.find((t) => !t.dropdown)?.id || (m === "dnes" ? "dnes" : m === "administrativa" ? "zamestnanci" : "calendar"));
  }

  // Zapamätá si aktuálnu obrazovku, nech pri obnovení stránky (F5) ostane
  // zostať na tom istom mieste, namiesto skoku na prednastavenú stránku.
  // Zapisuje sa až po prihlásení (didSetLandingModule nižšie) — keby sa
  // zapísalo hneď pri načítaní (ešte na prihlasovacej obrazovke), úvodná
  // stránka podľa roly by sa po prihlásení nikdy nepoužila.
  useEffect(() => {
    if (!didSetLandingModule.current) return;
    sessionStorage.setItem("mateco_last_module", module);
  }, [module]);
  useEffect(() => {
    if (!didSetLandingModule.current) return;
    sessionStorage.setItem("mateco_last_view", view);
  }, [view]);
  useEffect(() => {
    if (documentsSubView) localStorage.setItem("mateco_last_documents_subview", documentsSubView);
    else localStorage.removeItem("mateco_last_documents_subview");
  }, [documentsSubView]);

  // Prekreslenie o polnoci — inak by otvorené Prepravy ukazovali „Zajtra“ aj po polnoci.
  const [, setDayTick] = useState(0);
  useEffect(() => {
    // Polnoc podľa času servera (nie hodín telefónu); po overení hodín sa prekreslí hneď.
    // Polnoc v Bratislave (nie v časovom pásme zariadenia); strop 1 h kvôli zmene letného času.
    const p = Object.fromEntries(_baClock.formatToParts(new Date(serverNowMs())).map((x) => [x.type, x.value]));
    const ms = ((24 - Number(p.hour)) * 3600 - Number(p.minute) * 60 - Number(p.second)) * 1000 + 5000;
    const t = setTimeout(() => setDayTick((x) => x + 1), Math.max(1000, Math.min(ms, 3600 * 1000)));
    _clockListener = () => setDayTick((x) => x + 1);
    return () => { clearTimeout(t); _clockListener = null; };
  });
  const today = todayISO();
  const tomorrow = addDaysISO(today, 1);
  const dayAfterTomorrow = addDaysISO(today, 2);

  /* ---------------- derived (musí byť pred efektmi nižšie, ktoré tieto hodnoty
     používajú vo svojom dependency array — ten sa vyhodnocuje okamžite, nie až
     pri behu efektu, takže poradie deklarácií tu má význam) ---------------- */
  const machineById = useMemo(() => Object.fromEntries(machines.map((m) => [m.id, m])), [machines]);
  const technicianByIdTop = useMemo(() => Object.fromEntries(technicians.map((t) => [t.id, t])), [technicians]);
  // Offline kontrolu medzitým dostal zástupca (dovolenka) — dozvie sa, že je hotová.
  const inspectionDoneRef = useRef(null);
  inspectionDoneRef.current = (a, base) => {
    const sub = technicianByIdTop[a.technicianId];
    if (!sub) return;
    const m = machineById[a.machineId];
    const by = technicianByIdTop[base.technicianId]?.name || currentUser?.name || "pôvodný checker";
    pushNotification({
      kind: "checker_inspection",
      roles: [],
      userName: sub.name,
      title: "Kontrola stroja je už urobená",
      message: `Kontrolu stroja ${m?.code || "—"}${m?.type ? " (" + m.type + ")" : ""} (${a.phase === "vratenie" ? "po vrátení" : "pred vývozom"}, ${fmtDate(a.date)}) urobil ${by} bez signálu — netreba ju robiť.`,
      link: { module: "servis", view: "plan", plannerDate: a.date },
    });
  };
  useEffect(() => {
    setInspectionDoneListener((a, base) => inspectionDoneRef.current?.(a, base));
    return () => setInspectionDoneListener(null);
  }, []);

  const openDamagesByMachine = useMemo(() => {
    const map = {};
    damages.forEach((d) => {
      if (d.resolved) return;
      if (d.type === "revizia" || d.type === "uradnaSkuska") return;
      if (!map[d.machineId] || (map[d.machineId].prepCheck && !d.prepCheck)) map[d.machineId] = d; // skutočná porucha má prednosť pred prípravou
    });
    return map;
  }, [damages]);

  const hpDoneByJob = useMemo(() => Object.fromEntries(handoverProtocols.map((h) => [h.jobId, h.returnDone ? "return" : h.handoverDone ? "handover" : ""])), [handoverProtocols]);
  const enrichedMachines = useMemo(() => {
    // Zákazky raz zoskupené podľa stroja — inak prechod všetkých zákaziek pre každý stroj pri každej zmene (audit 23. 10.).
    const byMachine = new Map();
    jobs.forEach((j) => { const l = byMachine.get(j.machineId); if (l) l.push(j); else byMachine.set(j.machineId, [j]); });
    return machines.map((m) => {
      const mj = byMachine.get(m.id) || [];
      const cur = currentJobFor(mj, m.id, today);
      const nxt = nextJobFor(mj, m.id, today);
      const status = cur ? effectiveStatus(cur, today) : "free";
      const openDamage = openDamagesByMachine[m.id] || null;
      // Ukončená zákazka, stroj odovzdaný, ale ešte nevrátený (zvoz) — v Dátach požičovne „Čaká na zvoz“, nie „Voľný“.
      const awaitingPickup = !cur && mj.find((j) => j.machineId === m.id && j.status === "completed" && !j.notRealized
        && hpDoneByJob[j.id] === "handover" && (j.pickupDate || j.endDate || "") >= addDaysISO(today, -30)) || null;
      // „V príprave“ (príprava do požičovne) je samostatný stav, nie porucha (rozhodnutie 24. 10.).
      const inPrep = !!openDamage?.prepCheck;
      // Zákazka beží podľa dátumu, ale stroj ešte neodišiel (bez protokolu o prevzatí) — len zobrazenie „Čaká na vývoz“, stav sa nemení.
      const awaitingOut = status === "active" && !cur.notRealized && !hpDoneByJob[cur.id];
      return { ...m, currentJob: cur, nextJob: nxt, status, hasOpenDamage: !!openDamage && !inPrep, inPrep, openDamage, awaitingPickup, awaitingOut };
    });
  }, [machines, jobs, today, openDamagesByMachine, hpDoneByJob]);

  const enrichedMachineById = useMemo(() => Object.fromEntries(enrichedMachines.map((m) => [m.id, m])), [enrichedMachines]);

  // Pripomienka pre obchodníka — ak rezervácia visí bez premeny na zákazku
  // (alebo zamietnutia) príliš dlho, systém upozorní na to obchodníka, nie len dispečera.
  // Posiela sa len raz za rezerváciu (reminderSentAt), nie pri každom obnovení stránky.
  const RESERVATION_STALE_DAYS = 7;
  useEffect(() => {
    if (!loaded) return;
    const stale = reservations.filter((r) => {
      if (r.status !== "pending" && r.status !== "approved") return false;
      if (r.reminderSentAt) return false;
      if (!r.createdAt) return false;
      const ageDays = daysBetween(toLocalISO(new Date(r.createdAt)), today);
      return ageDays >= RESERVATION_STALE_DAYS;
    });
    if (stale.length === 0) return;
    (async () => {
      const sentAt = new Date(serverNowMs()).toISOString();
      const won = [];
      for (const r of stale) {
        if (await claimReminder("reservations", r, { reminderSentAt: sentAt }, "reminderSentAt")) won.push(r.id);
      }
      if (won.length === 0) return;
      stale.filter((r) => won.includes(r.id)).forEach((r) => {
        const machine = machineById[r.machineId];
        if (r.obchodnik) {
          pushNotification({
            system: true,
            kind: "reservation",
            roles: [],
            userName: r.obchodnik,
            title: "Nezáväzná rezervácia dlho nevybavená",
            message: `Rezervácia stroja ${machine?.code || "—"} pre ${r.customer} visí bez vybavenia už ${RESERVATION_STALE_DAYS}+ dní. Over, či je ešte aktuálna.`,
            link: { module: "poziciovna", view: "calendar", reservationId: r.id },
          });
        }
      });
      setReservations((prev) => prev.map((r) => (won.includes(r.id) ? { ...r, reminderSentAt: sentAt } : r)));
    })();
  }, [loaded, reservations, today]);

  // Pripomienka STK/EK áut — jeden dátum, jedno upozornenie (v praxi sa STK aj EK
  // vždy robia naraz, na tú istú platnosť). Spustí sa raz denne per auto, rešpektuje
  // prípadné odloženie (stkEkSnoozeUntil) a nepošle to isté upozornenie dvakrát za deň.
  const VEHICLE_REMINDER_DAYS = 30;
  useEffect(() => {
    if (!loaded || vehicles.length === 0) return;
    (async () => {
      for (const v of vehicles) {
        if (!v.assignedEmployeeId) continue;
        const employee = employees.find((e) => e.id === v.assignedEmployeeId);
        if (!employee) continue;
        const date = v.stkEkDate;
        if (!date) continue;
        if (v.stkEkNotifiedDate === today) continue; // dnes už bolo poslané
        if (v.stkEkSnoozeUntil && today < v.stkEkSnoozeUntil) continue; // odložené
        const daysLeft = Math.round((new Date(date + "T00:00:00") - new Date(today + "T00:00:00")) / 86400000);
        if (daysLeft > VEHICLE_REMINDER_DAYS) continue;
        const won = await claimReminder("vehicles", v, { stkEkNotifiedDate: today }, "stkEkNotifiedDate", today);
        if (!won) continue;
        setVehicles((prev) => prev.map((vv) => (vv.id === v.id ? { ...vv, stkEkNotifiedDate: today } : vv)));
        // Aj vedúcemu oblasti, pod ktorú zamestnanec patrí (autá spravuje on).
        const areaLead = ["technik", "dispecer_servisu", "veduci_technik_ba", "fakturant_servis", "veduci_servisu"].includes(employee.role) ? "veduci_servisu" : "veduci_pozicovne";
        pushNotification({
          system: true,
          kind: "vehicle_stk_ek",
          roles: [areaLead],
          userName: employee.name,
          title: daysLeft < 0 ? "STK/EK auta po termíne" : "Blíži sa STK/EK auta",
          message: `${v.spz || "Auto"}${v.znacka ? " (" + v.znacka + ")" : ""} — STK/EK ${daysLeft < 0 ? "bola splatná" : "je splatná"} ${fmtDate(date)}.`,
          link: { module: "administrativa", view: "auta", vehicleId: v.id },
        });
      }
    })();
  }, [loaded, vehicles, employees, today]);

  useEffect(() => {
    setSaveStatusListener((status, key) => {
      if (status === "error") {
        setSaveErrors((prev) => (prev.includes(key) ? prev : [...prev, key]));
      } else if (status === "ok") {
        setSaveErrors((prev) => prev.filter((k) => k !== key));
      }
    });
    return () => setSaveStatusListener(null);
  }, []);

  useEffect(() => {
    setOutboxCountListener((n, blocked, shown, list) => { setOutboxCount(n); setOutboxBlocked(blocked || 0); setOutboxShown(shown ?? n); setOutboxBlockedList(list || []); });
    let lastBlocked = 0;
    setOfflineBlockedListener((_table, why) => {
      // Viac zápisov jednej akcie = jedna hláška; po návrate spojenia sa načíta aktuálny stav.
      if (Date.now() - lastBlocked > 1500) { // jedna akcia = jedna hláška, ďalšia akcia znova
        lastBlocked = Date.now();
        // „✓ uložené“ z tej istej akcie (výpadok sa zistil až pri ukladaní) nesmie ostať svietiť.
        setToast((t) => (t && (t.startsWith("✓") || t === "Ukladám…") ? null : t)); // ani „Ukladám…“ popri hláške o výpadku
        showNotice(why === "busy"
          ? "Kolega práve ukladá ten istý záznam — vaša zmena sa neuložila.\n\nFormulár ostáva otvorený, skúste uložiť znova."
          : navigator.onLine
          ? "Server je dočasne nedostupný — táto zmena sa neuložila.\n\nSkúste to znova o chvíľu. Ak to trvá dlhšie, dajte vedieť správcovi platformy."
          : "Bez signálu sa táto zmena neuloží.\n\nOffline sa dajú vypĺňať len protokoly v teréne (šofér, technik). Skúste to znova, keď budete pripojení.");
        lastBlocked = Date.now(); // čas čítania hlášky sa nepočíta — zvyšné zápisy tej istej akcie bez ďalšej hlášky
        // Formulár uložený tesne pred výpadkom otvoriť hneď s hláškou (nie až po neúspechu posledného pokusu).
        const ro = reopenFormRef.current;
        if (ro && Date.now() - ro.at < 60000) { reopenFormRef.current = null; ro.open(); }
        // Po návrate spojenia načítať aktuálny stav (opakovane, ak prvý pokus ešte nevyjde).
        [5000, 20000, 60000].forEach((ms) => setTimeout(() => resyncRef.current?.(), ms));
      }
    });
    setMergeConflictListener(async (table, item, fields, kind) => {
      const what = item?.customer || item?.code || item?.name || item?.firma || "záznam";
      const names = (fields || []).map((f) => FIELD_LABELS[f] || f).join(", ");
      if (kind === "deleted") {
        showNotice(`Vaša zmena urobená bez signálu (${what}) sa neuložila — záznam medzitým niekto zmazal.`);
        return;
      }
      if (kind === "onlineDeleted") {
        showNotice(`Vaša zmena (${what}) sa neuložila — záznam medzitým niekto zmazal.`);
        return;
      }
      if (kind === "online") {
        showNotice(`Tie isté údaje (${what}) medzitým zmenil niekto iný — v nich platí jeho verzia, ostatné vaše zmeny sa uložili. Skontrolujte to prosím.\n\nÚdaje: ${names}`);
        return;
      }
      if (kind === "deleteSkipped") {
        showNotice(`Zmazanie urobené bez signálu (${what}) sa nevykonalo — záznam medzitým zmenil niekto iný. Ak ho chcete zmazať, urobte to znova.`);
        const setState = { jobs: setJobs, damages: setDamages, machines: setMachines, customers: setCustomers, reservations: setReservations, assignments: setAssignments, handoverProtocols: setHandoverProtocols, employees: setEmployees, vehicles: setVehicles }[table];
        setState?.((prev) => (prev.some((x) => x.id === item.id) ? prev.map((x) => (x.id === item.id ? item : x)) : [...prev, item]));
        return;
      }
      if (kind === "collision") {
        showNotice(`Zmena termínu urobená bez signálu (${what}) sa neuložila — stroj je v tom čase medzičasom obsadený inou zákazkou. Platí pôvodný termín.\n\nÚdaje: ${names}`);
        return;
      }
      showNotice(`Vaša zmena urobená bez signálu (${what}) sa v niektorých údajoch neuložila — medzitým ich zmenil niekto iný a platí jeho verzia. Skontrolujte to prosím.\n\nÚdaje: ${names}`);
    });
    refreshOutboxCount();
    return () => setOutboxCountListener(null);
  }, []);
  // Šípky v záložkách (role=tab) a v menu (role=menuitem) — jedno miesto pre celú platformu (kolo 32).
  useEffect(() => {
    const onKey = (e) => {
      const t = e.target;
      const role = t?.getAttribute?.("role");
      if (role === "tab" && ["ArrowRight", "ArrowLeft", "Home", "End"].includes(e.key)) {
        const tabs = [...(t.closest('[role="tablist"]')?.querySelectorAll('[role="tab"]') || [])];
        const i = e.key === "Home" ? 0 : e.key === "End" ? tabs.length - 1 : tabs.indexOf(t) + (e.key === "ArrowRight" ? 1 : -1);
        const next = tabs[(i + tabs.length) % tabs.length];
        if (next) { e.preventDefault(); next.focus(); next.click(); }
      } else if (role === "menuitem" && (e.key === "ArrowDown" || e.key === "ArrowUp")) {
        const items = [...(t.closest('[role="menu"]')?.querySelectorAll('[role="menuitem"]') || [])];
        const i = items.indexOf(t) + (e.key === "ArrowDown" ? 1 : -1);
        const next = items[(i + items.length) % items.length];
        if (next) { e.preventDefault(); next.focus(); }
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, []);
  const [droppedN, setDroppedN] = useState(0);
  _droppedListener = setDroppedN;
  // Stav platformy pre admina: verzia a čakajúce zmeny bez signálu (step89; staršia DB → ticho nič).
  useEffect(() => {
    if (!loaded || !session?.user?.id) return;
    const report = () => { if (navigator.onLine) supabase.rpc("report_client_status", { p_version: APP_VERSION, p_queued: outboxShown, p_blocked: outboxBlocked, ...(_droppedNotifs ? { p_dropped: _droppedNotifs } : {}) }).then(() => {}, () => {}); }; // p_dropped len keď treba — DB pred step106 ho nepozná
    const t = setTimeout(report, 5000);
    const iv = setInterval(report, 30 * 60 * 1000);
    return () => { clearTimeout(t); clearInterval(iv); };
  }, [loaded, session?.user?.id, outboxShown, outboxBlocked, droppedN]);

  // Záložný periodický pokus, nezávislý od udalosti "online" — na slabom/zdieľanom
  // WiFi (napr. na predvádzaní) vie prehliadač hlásiť navigator.onLine=true aj keď
  // požiadavky reálne prepadávajú (žiadny skutočný offline→online prechod, takže
  // "online" event nikdy nepríde) — bez tohto by červený/žltý banner ostal visieť
  // navždy, aj keď sa signál medzitým zlepší. Skúša len keď je čo skúšať.
  useEffect(() => {
    const t = setInterval(() => {
      if (outboxCount > 0) { flushOutbox().then(flushCloseInspections); flushPublicTokenClaims(); flushTransportDone(); }
      saveErrors.forEach((k) => retrySave(k));
    }, 20000);
    return () => clearInterval(t);
  }, [outboxCount, saveErrors]);

  useEffect(() => {
    setProtocolOpenListener((html, params) => setProtocolModalData({ html, params }));
    return () => setProtocolOpenListener(null);
  }, []);

  useEffect(() => {
    setPrintProtocolOpenListener((html) => setPrintProtocolHtml(html));
    return () => setPrintProtocolOpenListener(null);
  }, []);

  useEffect(() => {
    setPhotoLightboxOpenListener((url) => setLightboxUrl(url));
    return () => setPhotoLightboxOpenListener(null);
  }, []);

  useEffect(() => {
    setEzMeasurementOpenListener((machine) => setEzMeasurementTarget(machine));
    return () => setEzMeasurementOpenListener(null);
  }, []);

  useEffect(() => {
    setMailComposeListener((mail) => setPendingMail(mail));
    return () => setMailComposeListener(null);
  }, []);

  useEffect(() => {
    const openTicketByMachine = {};
    damages.forEach((d) => {
      if (d.resolved) return;
      if (!PROTOCOL_PAIRABLE_DAMAGE_TYPES.includes(d.type)) return;
      if (!d.machineId) return;
      if (openTicketByMachine[d.machineId]) return;
      const techIds = d.technicianIds && d.technicianIds.length ? d.technicianIds : (d.technicianId ? [d.technicianId] : []);
      const technicianNames = techIds.map((id) => technicianByIdTop[id]?.name).filter(Boolean);
      openTicketByMachine[d.machineId] = {
        damageId: d.id,
        code: d.code,
        type: d.type,
        assignedDate: d.assignedDate || null,
        technicianNames,
      };
    });
    setProtocolMachinesList(
      machines.map((m) => ({ serial: m.code, model: m.type || "", id: m.id, openTicket: openTicketByMachine[m.id] || null }))
    );
  }, [machines, damages, technicianByIdTop]);

