// Tlačidlo "Export fotiek (ZIP)" v Dokumentoch — stiahne celý obsah oboch
// Storage bucketov (protocols, inspections) rovno v prehliadači a ponúkne
// jeden ZIP na uloženie/presun (napr. na SharePoint), bez potreby skriptu
// alebo API mimo appky. Len admin, kvôli objemu aj citlivosti dát.
function ExportPhotosPanel() {
  const [running, setRunning] = useState(false);
  const [progress, setProgress] = useState({ done: 0, total: 0 });
  const [done, setDone] = useState(false);
  const [error, setError] = useState("");
  const [mode, setMode] = useState("all"); // "all" | "since" | "last"
  const [sinceDate, setSinceDate] = useState("");
  const [lastExportAt, setLastExportAt] = useState(undefined); // undefined = ešte sa nenačítalo

  useEffect(() => {
    loadKey("lastPhotoExportAt", null).then(setLastExportAt);
  }, []);

  async function run() {
    setRunning(true);
    setError("");
    setDone(false);
    setProgress({ done: 0, total: 0 });
    try {
      const sinceIso = mode === "since" && sinceDate ? new Date(sinceDate + "T00:00:00").toISOString() : mode === "last" ? lastExportAt || null : null;
      const blob = await exportPhotosAsZip(sinceIso, (n, total) => setProgress({ done: n, total }));
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `mateco-fotky-export-${todayISO()}.zip`;
      a.click();
      URL.revokeObjectURL(url);
      const now = new Date(serverNowMs()).toISOString();
      saveKey("lastPhotoExportAt", now);
      setLastExportAt(now);
      setDone(true);
    } catch (e) {
      setError("Export zlyhal: " + (e?.message || String(e)));
    } finally {
      setRunning(false);
    }
  }

  return (
    <div className="panel" style={{ padding: 24, maxWidth: 560 }}>
      <h2 className="page-h1" style={{ fontSize: 20 }}>Export fotiek (ZIP)</h2>
      <div className="fintro" style={{ marginTop: 0, marginBottom: 18 }}>
        Stiahne fotky a protokoly (tie, na ktoré platforma niekde odkazuje) do jedného ZIP súboru — na
        zálohu, napr. na presun na SharePoint. Pri väčšom počte fotiek to môže trvať niekoľko minút,
        nezatvárajte počas toho túto kartu.
      </div>

      {!running && !done && (
        <>
          <div className="flegend" style={{ marginTop: 0 }}>ČO EXPORTOVAŤ</div>
          <div className="ckl" style={{ marginBottom: 18 }}>
            <label className="cki" style={{ minHeight: 48, fontSize: 15, cursor: "pointer" }}>
              <input type="radio" checked={mode === "all"} onChange={() => setMode("all")} style={{ width: 20, height: 20, accentColor: "var(--text)", margin: 0 }} />
              Exportovať všetko
            </label>
            <label className="cki" style={{ minHeight: 48, fontSize: 15, cursor: lastExportAt ? "pointer" : "not-allowed", color: lastExportAt ? undefined : "var(--text-dim)" }}>
              <input type="radio" checked={mode === "last"} onChange={() => setMode("last")} disabled={!lastExportAt} style={{ width: 20, height: 20, accentColor: "var(--text)", margin: 0 }} />
              <span className="tnum">Len od posledného exportu{lastExportAt ? ` (${new Date(lastExportAt).toLocaleString("sk-SK")})` : " (zatiaľ žiadny)"}</span>
            </label>
            <label className="cki" style={{ minHeight: 48, fontSize: 15, cursor: "pointer" }}>
              <input type="radio" checked={mode === "since"} onChange={() => setMode("since")} style={{ width: 20, height: 20, accentColor: "var(--text)", margin: 0 }} />
              Od dátumu:
              <input
                type="date"
                aria-label="Od dátumu"
                value={sinceDate}
                onChange={(e) => { setSinceDate(e.target.value); setMode("since"); }}
                style={{ minHeight: 44, fontSize: 15 }}
              />
            </label>
          </div>
          <button className="btn btn-accent" style={{ minHeight: 44, fontSize: 14 }} onClick={run} disabled={mode === "since" && !sinceDate}>
            Spustiť export
          </button>
        </>
      )}
      {running && (
        <div className="fnote fnote-i tnum" role="status">
          {progress.total ? `Sťahujem… ${progress.done} / ${progress.total} súborov` : "Hľadám fotky v dátach…"}
        </div>
      )}
      {done && (
        <div className={`fnote ${progress.total ? "fnote-g" : "fnote-y"}`} role="status">
          {progress.total
            ? `Hotovo — ${progress.done} súborov, ZIP sa stiahol do Downloads.`
            : "Nenašla sa žiadna fotka na export."}
        </div>
      )}
      {error && <div className="fnote fnote-r" role="alert" style={{ marginTop: 8 }}>⚠ {error}</div>}
      {done && (
        <button className="btn btn-outline" style={{ minHeight: 44, fontSize: 14 }} onClick={() => setDone(false)}>
          Spustiť ďalší export
        </button>
      )}
    </div>
  );
}

function DocumentsView({
  subView,
  subTabs,
  framoveZmluvy,
  blacklist,
  customers,
  onAddFramovaZmluva,
  onImportFramoveZmluvy,
  onDeleteFramovaZmluva,
  onAddBlacklist,
  onImportBlacklist,
  onDeleteBlacklist,
  canEdit,
  canExportPhotos,
}) {
  const active = subTabs.find((s) => s.id === subView);

  if (subView === "export-foto") {
    return canExportPhotos ? (
      <ExportPhotosPanel />
    ) : (
      <div className="panel" style={{ padding: 30, textAlign: "center", color: "var(--text-dim)" }}>
        Export fotiek môže spustiť len administrátor.
      </div>
    );
  }

  if (subView === "ramcove-zmluvy") {
    return (
      <RecordsTableView
        title="Zoznam rámcových zmlúv"
        fields={FRAMOVA_ZMLUVA_FIELDS}
        items={framoveZmluvy}
        onAdd={onAddFramovaZmluva}
        onImport={onImportFramoveZmluvy}
        onDelete={onDeleteFramovaZmluva}
        canEdit={canEdit}
        customers={customers}
        customerNameKey="najomca"
      />
    );
  }
  if (subView === "blacklist") {
    return (
      <RecordsTableView
        title="BLACKLIST zákazníkov"
        fields={BLACKLIST_FIELDS}
        items={blacklist}
        onAdd={onAddBlacklist}
        onImport={onImportBlacklist}
        onDelete={onDeleteBlacklist}
        canEdit={canEdit}
        customers={customers}
        customerNameKey="nazovZakaznika"
      />
    );
  }

  return (
    <div className="panel" style={{ padding: 30, textAlign: "center", color: "var(--text-dim)" }}>
      {active ? (
        <>Sekcia "{active.label}" sa pripravuje.</>
      ) : (
        <>Táto sekcia sa pripravuje — podzáložky pribudnú čoskoro.</>
      )}
    </div>
  );
}


function GlobalSearch({ searchIndex, onNavigate }) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  // Na mobile (viď @media) je pole hľadania cez CSS schované a namiesto
  // neho je vidno len lupu — kliknutím sa "mobileExpanded" prepne na true a
  // CSS potom pole zobrazí ako pevný pruh cez celú šírku pod hlavičkou
  // (na webe sa mobileExpanded nikdy nepoužije, tam je input vidno vždy).
  const [mobileExpanded, setMobileExpanded] = useState(false);
  const boxRef = useRef(null);

  useEffect(() => {
    function onDocClick(e) {
      if (boxRef.current && !boxRef.current.contains(e.target)) {
        setOpen(false);
        setMobileExpanded(false);
      }
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

  const q = query.trim().toLowerCase();
  const results =
    q.length < 2
      ? []
      : (searchIndex || [])
          .filter((r) => r.searchText.includes(q))
          .slice(0, 8);

  return (
    <div
      ref={boxRef}
      className={`global-search-box${mobileExpanded ? " global-search-mobile-open" : ""}`}
      style={{ position: "relative", width: "100%", maxWidth: 480, minWidth: 200, display: "flex", justifyContent: "center" }}
    >
      <button
        type="button"
        className="global-search-mobile-trigger header-icon-btn"
        onClick={() => setMobileExpanded(true)}
        aria-label="Hľadať"
        style={{ display: "none", background: "#fff", border: "none", color: "var(--accent-fill)", cursor: "pointer" }}
      >
        <NavIcon id="hladat" />
      </button>
      <div className="global-search-input-wrap" style={{ position: "relative", width: "100%" }}>
        <input
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setOpen(true);
          }}
          onFocus={() => setOpen(true)}
          onKeyDown={(e) => { if (e.key === "ArrowDown") { const f = boxRef.current?.querySelector("[data-sr]"); if (f) { e.preventDefault(); f.focus(); } } }}
          aria-label="Hľadať"
          role="combobox"
          aria-expanded={open && q.length >= 2}
          aria-autocomplete="list"
          placeholder="Hľadať stroj, zákazku, zákazníka, poškodenie..."
          style={{
            width: "100%",
            border: "1px solid rgba(0,0,0,.1)",
            background: "var(--panel-2)",
            color: "var(--text)",
            borderRadius: 6,
            padding: "5px 10px",
            fontSize: 13,
          }}
        />
        {mobileExpanded && (
          <button
            type="button"
            className="global-search-mobile-close header-icon-btn"
            onClick={() => { setMobileExpanded(false); setOpen(false); setQuery(""); }}
            aria-label="Zavrieť hľadanie"
            style={{ display: "none", flex: "0 0 auto", background: "rgba(0,0,0,.14)", border: "1px solid rgba(255,255,255,.3)", color: "#fff", cursor: "pointer" }}
          >
            ✕
          </button>
        )}
        {open && q.length >= 2 && (
          <div
            className="panel"
            style={{
              position: "absolute",
              top: "calc(100% + 4px)",
              left: 0,
              width: 340,
              maxWidth: "80vw",
              maxHeight: 380,
              overflowY: "auto",
              zIndex: 200,
              padding: 6,
            }}
            role="listbox"
            aria-label="Výsledky hľadania"
            onKeyDown={(e) => {
              if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return;
              e.preventDefault();
              const items = [...e.currentTarget.querySelectorAll("[data-sr]")];
              const i = items.indexOf(document.activeElement) + (e.key === "ArrowDown" ? 1 : -1);
              if (i < 0) boxRef.current?.querySelector("input")?.focus(); else items[Math.min(i, items.length - 1)]?.focus();
            }}
          >
            {results.length === 0 ? (
              <div style={{ padding: 10, fontSize: 13, color: "var(--text-dim)" }}>Žiadne výsledky.</div>
            ) : (
              results.map((r) => (
                <div
                  key={r.type + r.id}
                  data-sr=""
                  role="option"
                  aria-selected="false"
                  {...rowOpenKeys(() => { onNavigate(r); setQuery(""); setOpen(false); setMobileExpanded(false); })}
                  onClick={() => {
                    onNavigate(r);
                    setQuery("");
                    setOpen(false);
                    setMobileExpanded(false);
                  }}
                  style={{
                    padding: "8px 10px",
                    borderRadius: 6,
                    cursor: "pointer",
                    borderBottom: "1px solid var(--border)",
                  }}
                  onMouseDown={(e) => e.preventDefault()}
                >
                  <div style={{ fontSize: 11, color: "var(--accent)", fontWeight: 700, textTransform: "uppercase" }}>{r.kindLabel}</div>
                  <div style={{ fontSize: 14, fontWeight: 600 }}>{r.title}</div>
                  {r.subtitle && <div style={{ fontSize: 12, color: "var(--text-dim)" }}>{r.subtitle}</div>}
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// Zoznam modulov + ich záložiek — zdieľané medzi ľavým menu na počítači
// (SideMenu) a spodnou lištou na mobile (MobileTabBar),
// nech sa tabuľka záložiek nemusí udržiavať na dvoch miestach naraz.
function buildNavModules(effectiveUser, damageAlertCount, myEmployee, counts = {}) {
  // Revízie EZ: dispečer/vedúci servisu (ez_measurement_view) len na dohľad,
  // EZ technik (employees.alsoEzTechnik — nie je to rola) navyše aj na
  // spracovanie — obaja musia záložku vidieť, appka rozlíši práva až vnútri.
  // myEmployee.role === effectiveUser.role: keď admin simuluje inú rolu
  // ("Zobraziť ako"), jeho VLASTNÝ príznak alsoEzTechnik sa nemá premietnuť
  // do toho, čo simulovaná rola vidí — inak by fakturant servisu (ktorý
  // reálne prístup nemá) videl záložku len preto, že ju má admin.
  const canSeeEz = can(effectiveUser, "ez_measurement_view") || !!(myEmployee?.alsoEzTechnik && myEmployee.role === effectiveUser?.role) || isAdminUser(effectiveUser);
  const poziciovnaTabs = [
    { id: "calendar", label: "Kalendár" },
    { id: "jobs", label: "Zákazky" },
    { id: "prepravy", label: "Prepravy" },
    { id: "dispeceri", label: "Dispečeri" },
    { id: "dashboard", label: "Dáta požičovne", group: ["dashboard", "drivers", "customers"] },
    ...(can(effectiveUser, "erp_pozicovna_view") ? [{ id: "erp_pozicovna", label: "ERP podklady" }] : []),
    { id: "dokumenty", label: "Dokumenty", dropdown: true },
  ];
  const canErp = can(effectiveUser, "erp_view");
  const podkladySubs = [...(canSeeEz ? ["ez_merania"] : []), ...(canErp ? ["erp"] : [])];
  const servisTabs = [
    { id: "plan", label: "Plán servisu" },
    { id: "diely", label: "Náhradné diely", group: ["diely", "vydaj"] },
    { id: "poskodenia", label: "Poškodenia", group: ["poskodenia", "externe"] },
    { id: "revizie", label: "Revízie/Úradné skúšky", group: ["revizie", "uradne_skusky"] },
    // Dispečer servisu nemá Administratívu — Kôš (len tikety) má v Servise.
    ...(!can(effectiveUser, "employee_manage") && can(effectiveUser, "trash_view") ? [{ id: "kos", label: "Kôš" }] : []),
    ...(podkladySubs.length > 0
      ? [{ id: podkladySubs[0], key: "podklady", label: podkladySubs.length > 1 ? "Podklady" : podkladySubs[0] === "ez_merania" ? "Revízie EZ" : "ERP — kontroly", group: podkladySubs }]
      : []),
    { id: "dokumenty", label: "Dokumenty", dropdown: true },
  ];
  const administrativaTabs = [
    ...(can(effectiveUser, "statistics_view") ? [{ id: "statistiky", label: "Štatistiky" }] : []),
    { id: "modely", label: "Modely strojov" },
    { id: "zamestnanci", label: "Zamestnanci" },
    { id: "checkeri", label: "Checkeri podľa depa" },
    ...(can(effectiveUser, "vehicle_manage") ? [{ id: "auta", label: "Autá" }] : []),
    ...(can(effectiveUser, "trash_view") ? [{ id: "kos", label: "Kôš" }] : []),
    ...(isAdminUser(effectiveUser) ? [{ id: "audit", label: "Audit log" }, { id: "stav", label: "Stav platformy" }] : []),
  ];
  // Menu podľa roly (ako pred „Dnes“): externý šofér má len „Dnes“ (svoje prepravy); šofér Prepravy +
  // Kalendár (bez Servisu); technik Servis + Kalendár požičovne na nahliadnutie. „Dnes“ je pre všetkých prvé.
  const role = effectiveUser?.role;
  const pozTabIds = role === "externy_sofer" ? [] : role === "sofer" ? ["prepravy", "calendar", "dispeceri", "dokumenty"] : role === "technik" ? ["calendar", "dispeceri"] : null;
  // Počty pri záložkách (čo čaká na túto rolu); modul = súčet jeho záložiek.
  const tabCount = { prepravy: counts.prepravy, diely: counts.diely, poskodenia: damageAlertCount, [podkladySubs[0]]: counts.podklady };
  const withCounts = (m) => {
    const tabs = m.tabs.map((t) => ({ ...t, badge: tabCount[t.id] || 0 }));
    return { ...m, tabs, badge: tabs.reduce((n, t) => n + t.badge, 0) };
  };
  return [
    ...(role !== "nezaradeny" ? [{ id: "dnes", label: "Dnes", tabs: [{ id: "dnes", label: "Dnes", badge: counts.dnes || 0 }], badge: counts.dnes || 0 }] : []),
    ...(pozTabIds && pozTabIds.length === 0 ? [] : [{
      id: "poziciovna",
      label: "Požičovňa",
      tabs: pozTabIds ? poziciovnaTabs.filter((t) => pozTabIds.includes(t.id)).sort((a, b) => pozTabIds.indexOf(a.id) - pozTabIds.indexOf(b.id)) : poziciovnaTabs,
      badge: 0,
    }].map(withCounts)),
    ...(role !== "externy_sofer" && role !== "sofer" ? [withCounts({ id: "servis", label: "Servis", tabs: servisTabs })] : []),
    ...(can(effectiveUser, "employee_manage") ? [{ id: "administrativa", label: "Administratíva", tabs: administrativaTabs, badge: 0 }] : []),
  ];
}

