// Zoznam položiek menu po sekciách (moduloch) — zdieľa ho ľavý panel aj „Viac“ na mobile.
function NavList({ modules, module, view, exclude = [], collapsed, rowClass, onGo, onPickDoc, onExpand }) {
  const [docsOpen, setDocsOpen] = useState(null);
  return modules.map((m) => {
    const tabs = m.tabs.filter((t) => !exclude.includes(navKey(t)));
    if (!tabs.length) return null;
    return (
      <React.Fragment key={m.id}>
        {m.id !== "dnes" && (collapsed ? <div className="nav-sec-line" /> : <div className="nav-sec">{m.label}</div>)}
        {tabs.map((t) => {
          const active = module === m.id && !t.dropdown && (t.group || [t.id]).includes(view);
          const open = docsOpen === m.id;
          return (
            <React.Fragment key={t.id}>
              <button
                className={`${rowClass}${active ? " active" : ""}`}
                aria-label={t.label}
                onClick={() => {
                  if (!t.dropdown) return onGo(m.id, t.id);
                  if (collapsed) onExpand?.();
                  setDocsOpen(open ? null : m.id);
                }}
              >
                <NavIcon id={navKey(t)} />
                {!collapsed && <span className="nav-lbl">{t.label}{t.dropdown ? (open ? " ▴" : " ▾") : ""}</span>}
                {t.badge > 0 && <span className={`nav-b${navKey(t) === "poskodenia" ? " nav-b-problem" : ""}`}>{t.badge}</span>}
              </button>
              {t.dropdown && open && !collapsed &&
                (DOCUMENT_SUBTABS[m.id] || []).map((st) => (
                  <button key={st.id} className={`${rowClass} nav-sub`} onClick={() => onPickDoc(m.id, st)}>
                    {st.label}{st.url ? " ↗" : ""}
                  </button>
                ))}
            </React.Fragment>
          );
        })}
      </React.Fragment>
    );
  });
}

// Ľavý panel na počítači (fixed, pod hlavičkou). Zbalený = len ikony; voľba sa pamätá v prehliadači.
function SideMenu({ modules, module, view, onGo, onPickDoc, onOpenPhoneDirectory }) {
  const [collapsed, setCollapsed] = useState(() => { try { return localStorage.getItem("mateco_menu_collapsed") === "1"; } catch { return false; } });
  const [tip, setTip] = useState(null); // { label, y } — popisok ikony v zbalenom menu
  const setC = (v) => { setCollapsed(v); try { localStorage.setItem("mateco_menu_collapsed", v ? "1" : "0"); } catch { /* bez úložiska len na túto reláciu */ } };
  // Pozícia pod hlavičkou sa meria (hlavička sa zalamuje), panel je fixed — viď predošlý IconRail.
  const wrapRef = useRef(null);
  const [top, setTop] = useState(0);
  useLayoutEffect(() => {
    const measure = () => wrapRef.current && setTop(wrapRef.current.getBoundingClientRect().top + window.scrollY);
    measure();
    window.addEventListener("resize", measure);
    // Pásy nad plochou (chyba ukladania, nová verzia, offline fronta) sa pridávajú/uberajú ako deti .app-shell
    // a posúvajú začiatok menu — premerať pri každej takej zmene (aj keď výška stránky ostane rovnaká).
    const shell = wrapRef.current?.closest(".app-shell");
    const mo = new MutationObserver(() => requestAnimationFrame(measure));
    if (shell) mo.observe(shell, { childList: true, subtree: false });
    const ro = new ResizeObserver(measure);
    if (shell) Array.from(shell.children).forEach((c) => { if (!c.contains(wrapRef.current)) ro.observe(c); });
    return () => { window.removeEventListener("resize", measure); mo.disconnect(); ro.disconnect(); };
  }, []);
  // aj pri prechode klávesnicou (Tab) — focus/blur
  const showTip = (e) => {
    if (!collapsed) return;
    const b = e.target.closest(".nav-it");
    const label = b?.getAttribute("aria-label");
    if (!label) return setTip(null);
    const r = b.getBoundingClientRect();
    setTip({ label, y: r.top + r.height / 2 });
  };
  return (
    <div className={`side-menu-wrap${collapsed ? " collapsed" : ""}`} ref={wrapRef}>
      {/* Zbalené menu: popisok ikony hneď pri prejdení myšou (natívny title má oneskorenie). */}
      <nav className="side-menu" style={{ top }} onClick={() => setTip(null)} onMouseLeave={() => setTip(null)} onBlurCapture={() => setTip(null)} onMouseOver={showTip} onFocusCapture={showTip}>
        <div className="side-menu-scroll" onScroll={() => setTip(null)}>
          <NavList modules={modules} module={module} view={view} collapsed={collapsed} rowClass="nav-it" onGo={onGo} onPickDoc={onPickDoc} onExpand={() => setC(false)} />
        </div>
        <div className="side-menu-foot">
          <button className="nav-it" aria-label="Telefónny zoznam" onClick={onOpenPhoneDirectory}><NavIcon id="telefon" />{!collapsed && <span className="nav-lbl">Telefónny zoznam</span>}</button>
          <button className="nav-it" aria-label="Poslať pripomienku" onClick={sendFeedbackMail}><NavIcon id="mail" />{!collapsed && <span className="nav-lbl">Poslať pripomienku</span>}</button>
          <button className="nav-it nav-dim" aria-label={collapsed ? "Rozbaliť menu" : "Zbaliť menu"} onClick={() => setC(!collapsed)}>{collapsed ? "»" : "« Zbaliť menu"}</button>
        </div>
      </nav>
      {collapsed && tip && <div className="nav-tip" role="tooltip" style={{ top: tip.y }}>{tip.label}</div>}
    </div>
  );
}

// Spodná lišta na mobile: Dnes · záložka · + · záložka · Viac (záložky podľa role).
const MOBILE_BAR_SLOTS = {
  sofer: ["prepravy", "telefon"],
  externy_sofer: [null, "telefon"],
  technik: ["plan", "poskodenia"],
  veduci_technik_ba: ["plan", "poskodenia"],
  dispecer_servisu: ["plan", "poskodenia"],
  veduci_servisu: ["plan", "poskodenia"],
  fakturant_servis: ["podklady", "poskodenia"],
  dispecer_pozicovne: ["jobs", "prepravy"],
  veduci_pozicovne: ["jobs", "prepravy"],
  obchodnik: ["jobs", "calendar"],
  fakturant_pozicovna: ["jobs", null],
  admin: ["calendar", "plan"],
};
function mobileBarHasPhone(role) {
  return (MOBILE_BAR_SLOTS[role] || []).includes("telefon");
}
function MobileTabBar({ modules, module, view, role, actions, onGo, onPickDoc, onOpenPhoneDirectory }) {
  const [sheet, setSheet] = useState(null); // null | "plus" | "viac"
  // Esc zavrie ponuku aj keď fokus ostal na stránke (tlačidlo v lište sa pri otvorenej ponuke skryje); fokus späť až po prekreslení.
  useEffect(() => {
    if (!sheet) return;
    const onKey = (e) => {
      if (e.key !== "Escape") return;
      e.preventDefault(); e.stopImmediatePropagation(); setSheet(null);
      setTimeout(() => document.querySelector(sheet === "plus" ? ".mnav-plus" : ".mnav-viac")?.closest("button")?.focus({ preventScroll: true }), 0);
    };
    document.addEventListener("keydown", onKey, true);
    return () => document.removeEventListener("keydown", onKey, true);
  }, [sheet]);
  const all = modules.flatMap((m) => m.tabs.map((t) => ({ ...t, mod: m.id })));
  const pick = (k) => (k === "telefon" ? { id: "telefon", label: "Telefón" } : k ? all.find((t) => navKey(t) === k) : null);
  const [s0, s1] = (MOBILE_BAR_SLOTS[role] || ["calendar", "plan"]).map(pick);
  const used = ["dnes", ...[s0, s1].filter(Boolean).map(navKey)];
  const rest = modules.filter((m) => m.id !== "dnes");
  const restTabs = rest.flatMap((m) => m.tabs).filter((t) => !used.includes(navKey(t)));
  const restBadge = restTabs.reduce((n, t) => n + (t.badge || 0), 0);
  const phoneInBar = mobileBarHasPhone(role);
  const go = (m, v) => { setSheet(null); onGo(m, v); };
  const isActive = (t) => t && t.mod && module === t.mod && (t.group || [t.id]).includes(view);
  const item = (t) =>
    t && (
      <button key={t.id} className={`mnav-t${isActive(t) ? " active" : ""}`} onClick={() => (t.id === "telefon" ? onOpenPhoneDirectory() : go(t.mod, t.id))}>
        <NavIcon id={navKey(t)} size={22} />
        <span>{{ plan: "Plán", podklady: "Podklady" }[navKey(t)] || t.label}</span>
        {t.badge > 0 && <span className="mnav-b">{t.badge}</span>}
      </button>
    );
  const restActive = !isActive(all.find((t) => t.id === "dnes")) && !isActive(s0) && !isActive(s1);
  return (
    <>
      <div className="mobile-tech-actions mnav-bar">
        {item(all.find((t) => t.id === "dnes"))}
        {item(s0)}
        {actions.length > 0 && (
          <button className="mnav-t" aria-label="Nové" onClick={() => setSheet("plus")}>
            <span className="mnav-plus"><NavIcon id="plus" size={26} /></span>
          </button>
        )}
        {item(s1)}
        {(restTabs.length > 0 || !phoneInBar) && (
          <button className={`mnav-t mnav-viac${restActive ? " active" : ""}`} onClick={() => setSheet("viac")} aria-label={restBadge > 0 ? `Viac — ${restBadge} čaká v ďalších častiach` : "Viac"}>
            <NavIcon id="viac" size={22} />
            <span>Viac</span>
            {restBadge > 0 && <span className="mnav-b dot" title={`Niečo čaká v ďalších častiach (${restBadge})`} aria-label={`${restBadge} v ďalších častiach`} />}
          </button>
        )}
      </div>
      {sheet && (
        <div className="mobile-nav-overlay">
          <div className="mobile-nav-scrim" onClick={() => setSheet(null)} />
          <div className="mnav-sheet">
            <div className="mnav-grab" />
            {sheet === "plus" ? (
              <>
                <div className="mnav-sheet-title">Nové</div>
                {actions.map((a) => (
                  <button key={a.key} className="mnav-row" onClick={() => { setSheet(null); setTimeout(() => { document.querySelector(".mnav-plus")?.closest("button")?.focus({ preventScroll: true }); a.onClick(); }, 0); }}>{/* lišta je pri otvorenom „Nové“ skrytá — fokus až keď sa zobrazí */}
                    <NavIcon id="plus" />{a.label}
                  </button>
                ))}
              </>
            ) : (
              <>
                <NavList modules={rest} module={module} view={view} exclude={used} rowClass="mnav-row" onGo={go} onPickDoc={(m, st) => { setSheet(null); onPickDoc(m, st); }} />
                <div className="nav-sec">Ostatné</div>
                {!phoneInBar && (
                  <button className="mnav-row" onClick={() => { setSheet(null); setTimeout(() => { document.querySelector(".mnav-viac")?.focus({ preventScroll: true }); onOpenPhoneDirectory(); }, 0); }}><NavIcon id="telefon" />Telefónny zoznam</button>
                )}
                <button className="mnav-row" onClick={() => { setSheet(null); sendFeedbackMail(); }}><NavIcon id="mail" />Poslať pripomienku</button>
              </>
            )}
          </div>
        </div>
      )}
    </>
  );
}

// „+ Nové ▾“ v hlavičke na počítači — rovnaké akcie ako „+“ v mobilnej lište.
function NewMenu({ actions }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const close = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    // Esc zavrie menu (focus späť na tlačidlo), Tab mimo menu ho zavrie — ako menu ⋯.
    const onKey = (e) => {
      if (e.key === "Escape") { e.stopPropagation(); setOpen(false); ref.current?.querySelector(".header-new-btn")?.focus(); }
    };
    const onFocus = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", close);
    document.addEventListener("keydown", onKey, true);
    document.addEventListener("focusin", onFocus);
    return () => { document.removeEventListener("mousedown", close); document.removeEventListener("keydown", onKey, true); document.removeEventListener("focusin", onFocus); };
  }, [open]);
  return (
    <div className="header-new-wrap" ref={ref}>
      <button className="header-new-btn" aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen((v) => !v)}
        onKeyDown={(e) => { if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setTimeout(() => ref.current?.querySelector('[role="menuitem"]')?.focus(), 0); } }}>＋ Nové ▾</button>
      {open && (
        <div className="header-new-drop" role="menu">
          {actions.map((a) => (
            <button key={a.key} role="menuitem" className="kebab-item" onClick={() => { setOpen(false); ref.current?.querySelector(".header-new-btn")?.focus({ preventScroll: true }); a.onClick(); }}>{a.label}</button>
          ))}
        </div>
      )}
    </div>
  );
}

function PhoneIcon({ size = 15 }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M4 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L14 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 2 6a2 2 0 0 1 2-2z" />
    </svg>
  );
}
function MailIcon({ size = 15 }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="3" y="5" width="18" height="14" rx="2" />
      <path d="m3 6 9 7 9-7" />
    </svg>
  );
}
// Vytiahne telefónne číslo z voľného textu (napr. "Kontakt na zákazníka" pri
// poškodení/externej zákazke, kde sa meno+telefón+email píšu do jedného
// políčka) — nech aj tam funguje "klik a zavolaj", nielen pri štruktúrovanom
// job.customerPhone poli.
function extractPhone(text) {
  const m = (text || "").match(/(\+?\d[\d \/-]{6,}\d)/);
  return m ? m[1].trim() : null;
}
function Header({ onOpenTour, darkMode, onToggleDarkMode, onExportBackup, onImportBackup, currentUser, onSaveNotificationPrefs, pushEnabled, onEnablePush, onDisablePush, effectiveUser, viewAsRole, onSetViewAsRole, onLogout, onOpenUserAdmin, myNotifications, unreadNotificationCount, onMarkNotificationRead, onMarkAllNotificationsRead, onNavigateNotification, onOpenPhoneDirectory, searchIndex, onSearchNavigate, quickActions, phoneInBar }) {
  // Skutočná výška hlavičky sa mení (mobile zalomenie na 2 riadky, rôzne
  // zoom/rozlíšenie) — meria sa a ukladá do --header-h, aby sa podľa nej
  // vedeli "prilepiť" hlavičky tabuliek presne POD hlavičku, nie pod ňu.
  const headerRef = useRef(null);
  useEffect(() => {
    const el = headerRef.current;
    if (!el) return;
    const set = () => document.documentElement.style.setProperty("--header-h", el.offsetHeight + "px");
    set();
    const ro = new ResizeObserver(set);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  // Trvalý odznak „Bez signálu“ — kancelária vidí výpadok dopredu, nie až pri Uložiť.
  const [online, setOnline] = useState(() => typeof navigator === "undefined" || navigator.onLine);
  useEffect(() => {
    const upd = () => setOnline(navigator.onLine);
    window.addEventListener("online", upd);
    window.addEventListener("offline", upd);
    return () => { window.removeEventListener("online", upd); window.removeEventListener("offline", upd); };
  }, []);
  return (
    <div ref={headerRef} style={{ background: "var(--panel)", position: "sticky", top: 0, zIndex: 100, marginTop: "calc(-1 * env(safe-area-inset-top))" }}>
      {/* Červená aj pod stavovou lištou iPhonu. iOS 26 rozmazáva pás o niečo vyšší než stavová lišta — +14 px len tam, kde lišta je (na PC 0). */}
      <div style={{ background: "var(--accent-fill)", paddingTop: "calc(env(safe-area-inset-top) + min(14px, env(safe-area-inset-top)))" }}>
        <div className="header-topbar" style={{ width: "100%", padding: "9px 24px", display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap", rowGap: 6, boxSizing: "border-box" }}>
          {/* Logo je z tlačového watermarku — kreslené na biele pozadie, na
              červenej hlavičke bez neho vyzeralo rozmazane/nekontrastne.
              Biela "pilulka" okolo je preto rovnaká vo svetlom aj tmavom
              režime appky (hlavička je vždy červená, nie je to podľa témy appky). */}
          <span className="header-logo-pill" style={{ display: "inline-flex", alignItems: "center", background: "#fff", borderRadius: 6, padding: "3px 10px", flex: "0 0 auto" }}>
            <img src={`data:image/png;base64,${MATECO_LOGO_B64}`} alt="mateco" className="header-logo-img" style={{ height: 20, display: "block" }} />
          </span>
          {/* Popis/verzia — na webe hneď vedľa loga (divider medzi nimi), na
              mobile (viď @media) sa cez CSS "order" presunú na vlastný riadok
              POD logo (header-brand-sub), nech na prvom riadku ostane vždy
              dosť miesta pre vyhľadávanie a zvonček aj na užších telefónoch. */}
          <div className="header-brand-sub" style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <span className="header-divider" style={{ width: 1, height: 16, background: "rgba(255,255,255,.35)" }} />
            <span className="header-subtitle" style={{ fontSize: 12, fontWeight: 500, letterSpacing: "0.02em", textTransform: "uppercase", color: "#fff" }}>
              Interná platforma
            </span>
            <span style={{ fontSize: 11, color: "#fff", fontWeight: 600 }}>v{APP_VERSION}</span>
          </div>
          <div className="header-search-wrap" style={{ flex: "1 1 auto", display: "flex", justifyContent: "center", minWidth: 120 }}>
            {effectiveUser?.role !== "externy_sofer" && <GlobalSearch searchIndex={searchIndex} onNavigate={onSearchNavigate} />}
          </div>
          <div className="header-top-actions" style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", rowGap: 6 }}>
            {!online && (
              <span
                className="header-offline-badge"
                role="status"
                title="Zariadenie je bez signálu. Zmeny v kancelárii sa teraz neuložia; protokoly v teréne sa odošlú samé po pripojení."
                style={{ background: "#fff", color: "var(--accent-fill)", borderRadius: 999, padding: "3px 9px", fontSize: 11, fontWeight: 700, whiteSpace: "nowrap" }}
              >
                ⚠ Bez signálu
              </span>
            )}
            {quickActions?.length > 0 && <NewMenu actions={quickActions} />}
            {!phoneInBar && (
              <button className="header-phone-mobile" aria-label="Telefónny zoznam" onClick={onOpenPhoneDirectory}><PhoneIcon size={18} /></button>
            )}
            <NotificationBell
              notifications={myNotifications}
              unreadCount={unreadNotificationCount}
              currentUserId={currentUser?.id}
              onMarkRead={onMarkNotificationRead}
              onMarkAllRead={onMarkAllNotificationsRead}
              onNavigate={onNavigateNotification}
            />
            {currentUser && (
              <>
                {/* Na mobile sa táto celá-menom verzia cez CSS schová a
                    namiesto nej je vidno len malé kolieskové tlačidlo s
                    iniciálami (user-menu-mobile-wrap nižšie) — nech sa meno
                    zmestí do jedného riadku s logom, vyhľadávaním a zvončekom. */}
                <div className="user-menu-desktop-wrap">
                  <UserMenu
                    currentUser={currentUser}
                    onSaveNotificationPrefs={onSaveNotificationPrefs}
                    onOpenTour={onOpenTour}
                    pushEnabled={pushEnabled}
                    onEnablePush={onEnablePush}
                    onDisablePush={onDisablePush}
                    viewAsRole={viewAsRole}
                    onSetViewAsRole={onSetViewAsRole}
                    darkMode={darkMode}
                    onToggleDarkMode={onToggleDarkMode}
                    onOpenUserAdmin={onOpenUserAdmin}
                    onExportBackup={onExportBackup}
                    onImportBackup={onImportBackup}
                    canExport={can(effectiveUser, "backup_export")}
                    canImport={can(effectiveUser, "backup_import")}
                    onLogout={onLogout}
                  />
                </div>
                <div className="user-menu-mobile-wrap" style={{ display: "none" }}>
                  <UserMenu
                    variant="mobile-compact"
                    currentUser={currentUser}
                    onSaveNotificationPrefs={onSaveNotificationPrefs}
                    onOpenTour={onOpenTour}
                    pushEnabled={pushEnabled}
                    onEnablePush={onEnablePush}
                    onDisablePush={onDisablePush}
                    viewAsRole={viewAsRole}
                    onSetViewAsRole={onSetViewAsRole}
                    darkMode={darkMode}
                    onToggleDarkMode={onToggleDarkMode}
                    onOpenUserAdmin={onOpenUserAdmin}
                    onExportBackup={onExportBackup}
                    onImportBackup={onImportBackup}
                    canExport={can(effectiveUser, "backup_export")}
                    canImport={can(effectiveUser, "backup_import")}
                    onLogout={onLogout}
                  />
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Assignment detail modal ("karta zákazky" from Servis Prehľad)
--------------------------------------------------------- */
function AssignmentDetailModal({ assignment, machine, damage, technicians, user, onClose, onReschedule, onOpenMachineCard }) {
  const a = assignment;
  const technician = technicians.find((t) => t.id === a.technicianId);
  const protocolParams = damage
    ? { ...buildProtocolParams(damage, technicians, machine ? { [machine.id]: machine } : {}), ...(a.id ? { assignmentId: a.id } : {}) }
    : (() => {
        const params = {};
        const serial = machine?.code || a.stroj || "";
        if (serial) params.serial = serial;
        if (machine?.id) params.machineId = machine.id;
        if (a.id) params.assignmentId = a.id;
        if (technician?.name) params.tech = technician.name;
        const liveAddr = machineCurrentLocation(machine);
        if (liveAddr || a.umiestnenie) params.address = liveAddr || a.umiestnenie;
        return params;
      })();

  const canReschedule = damage && !damage.resolved && onReschedule && can(user, "plan_assign");
  const canProtocol = can(user, "protocol_write");
  return (
    <Modal
      eyebrow="Servisné pridelenie"
      title={<>{machine?.code || a.stroj || "Zákazka"}{machine?.type && <span className="side-title-sub">{machine.type}</span>}</>}
      onClose={onClose}
      side
      headerExtra={
        <div className="side-summary">
          <div><span>Technik</span><b>{technician?.name || "—"}</b></div>
          <div><span>Dátum</span><b className="tnum">{fmtDate(a.date) || "—"}</b></div>
          <div><span>Firma</span><b>{a.firma || "—"}</b></div>
          <div><span>Umiestnenie</span><b>{machineCurrentLocation(machine) || a.umiestnenie || "—"}</b></div>
        </div>
      }
      footer={(canReschedule || canProtocol || (machine && onOpenMachineCard)) && (
        <>
          {machine && onOpenMachineCard && (
            <KebabMenu up label="⋯" actions={[{ label: "Karta stroja", onClick: () => onOpenMachineCard(machine) }]} />
          )}
          <div style={{ marginLeft: "auto", display: "flex", gap: 10, flexWrap: "wrap" }}>
            {canReschedule && (
              <button className="btn btn-ghost" style={{ borderColor: "var(--text)" }} onClick={() => onReschedule(damage)}>
                Preplánovať (zmeniť dátum alebo technika)
              </button>
            )}
            {canProtocol && machine && isEzRevision(damage) && (
              <button className="btn btn-ghost" style={{ borderColor: "var(--text)" }} onClick={() => openEzMeasurement(machine)}>
                Záznam z merania pre VTZ EZ
              </button>
            )}
            {canProtocol && (
              <button className="btn btn-accent" onClick={() => openProtocol(protocolParams)}>
                Vypísať protokol
              </button>
            )}
          </div>
        </>
      )}
    >
      {/* Technik, dátum, firma a umiestnenie sú v súhrne hore — tu len ostatné (údaj raz, ako na ostatných kartách). */}
      <dl className="side-dl">
        {a.poznamka && <><dt>Poznámka</dt><dd style={{ whiteSpace: "pre-wrap" }}>{a.poznamka}</dd></>}
        {damage && <><dt>Stav</dt><dd>{damageLabel(damage)}</dd></>}
      </dl>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Protocol modal — full-screen iframe showing the embedded
   servisný protokol. window.open() is blocked in this sandbox
   (same restriction as native confirm()), so it's rendered
   inline instead of as a new tab.
--------------------------------------------------------- */
function ProtocolModal({ html, params, onClose }) {
  const entries = Object.entries(params || {}).filter(([, v]) => v);
  // Odznak o (ne)predvyplnení je len informatívny — nemá zmysel držať ho na
  // obrazovke natrvalo a uberať tým miesto, sám zmizne po pár sekundách.
  const [showBadge, setShowBadge] = useState(true);
  useEffect(() => {
    const t = setTimeout(() => setShowBadge(false), 2800);
    return () => clearTimeout(t);
  }, []);
  // F5 / zatvorenie stránky pri otvorenom protokole — prehliadač sa opýta (ako Modal), rozpísané údaje v iframe by sa stratili.
  useEffect(() => {
    const onBeforeUnload = (e) => { e.preventDefault(); e.returnValue = ""; };
    window.addEventListener("beforeunload", onBeforeUnload);
    return () => window.removeEventListener("beforeunload", onBeforeUnload);
  }, []);
  return (
    <div className="protocol-overlay" style={{ position: "fixed", inset: 0, background: "#fff", zIndex: 200, overflow: "hidden" }}>
      {/* Obal iframe začína AŽ pod stavovým riadkom telefónu (nie súčasť
          protokolu samotného — appka beží na celú výšku obrazovky, takže inak
          by hlavička protokolu (aj náš odznak/✕ nižšie) skončila pod hodinami/
          signálom). */}
      <div className="protocol-frame-wrap" style={{ position: "absolute", inset: 0, top: "env(safe-area-inset-top)", background: "#fff" }}>
        <iframe
          title="Servisný protokol"
          srcDoc={html}
          sandbox="allow-scripts allow-forms allow-modals allow-downloads allow-same-origin allow-popups"
          style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: "none" }}
        />
      </div>
      {showBadge && (
        <div
          style={{
            position: "absolute",
            top: "calc(env(safe-area-inset-top) + 8px)",
            left: 8,
            fontSize: 12,
            color: "#fff",
            background: entries.length ? "rgba(34,139,34,.85)" : "rgba(180,60,60,.85)",
            padding: "4px 10px",
            borderRadius: 4,
            pointerEvents: "none",
            transition: "opacity .4s",
          }}
        >
          {entries.length > 0
            ? `Predvyplnené: ${entries.map(([k, v]) => `${k}=${v}`).join(" · ")}`
            : "Žiadne údaje neboli predvyplnené (prázdny formulár)"}
        </div>
      )}
      {/* Len "✕", nie plné tlačidlo s textom — sedí do rovnakého riadku ako
          názov/adresa firmy v hlavičke samotného protokolu (tá je vykreslená
          v iframe pod ním), nie ako samostatný pás navyše. */}
      <button
        className="btn"
        title="Zavrieť protokol"
        onClick={() => window.confirm("Zavrieť protokol? Rozpísané údaje sa neuložia.") && onClose()}
        style={{
          position: "absolute",
          top: "calc(env(safe-area-inset-top) + 6px)",
          right: 8,
          width: 32,
          height: 32,
          padding: 0,
          borderRadius: "50%",
          background: "var(--panel-2)",
          color: "var(--text)",
          fontSize: 16,
          lineHeight: "32px",
          textAlign: "center",
        }}
      >
        ✕
      </button>
    </div>
  );
}

// Náhľad/tlač VYPLNENÉHO servisného protokolu (openPrintableServiceProtocol) — rovnaký
// princíp ako ProtocolModal vyššie (iframe namiesto window.open, ktoré je v appke
// blokované), len bez "predvyplnené" odznaku, ktorý sem nepatrí.
function PhotoLightboxModal({ src, onClose }) {
  // Tmavé pozadie bez presvitania stránky, horná lišta so „✕ Zavrieť“, fotka na celú plochu; klik mimo fotky zatvára.
  return (
    <div
      className="fullscreen-overlay"
      style={{ position: "fixed", inset: 0, background: "#111", zIndex: 300, display: "flex", flexDirection: "column", cursor: "zoom-out" }}
      onClick={onClose}
    >
      <div style={{ display: "flex", justifyContent: "flex-end", padding: "max(12px, env(safe-area-inset-top)) 16px 8px" }}>
        <button
          className="btn"
          style={{ minHeight: 48, fontSize: 15, background: "transparent", color: "#fff", border: "1px solid #fff", cursor: "pointer" }}
          onClick={onClose}
        >
          ✕ Zavrieť
        </button>
      </div>
      <div style={{ flex: 1, minHeight: 0, display: "flex", alignItems: "center", justifyContent: "center", padding: "8px 16px max(16px, env(safe-area-inset-bottom))" }}>
        <img
          src={src}
          alt="Náhľad fotky"
          style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain", borderRadius: 6, cursor: "default" }}
          onClick={(e) => e.stopPropagation()}
        />
      </div>
    </div>
  );
}

// Ovládacia lišta tlačového náhľadu (v1.0.794): „✕ Zavrieť“ a názov ležia nad ľavou časťou
// panela s akciami dokumentu (ten sa sem len preštýluje) — samotný dokument sa nemení.
const PRINT_BAR_CSS = `.toolbar{display:flex!important;justify-content:flex-end!important;align-items:center;text-align:right!important;gap:8px!important;flex-wrap:wrap;margin:0 0 10px!important;padding:10px 16px 10px min(46vw,520px)!important;min-height:64px;background:#fff!important;border-bottom:1px solid #E2E2E2;box-shadow:none!important}
.toolbar .btn{min-height:44px;font-size:14px;border-radius:8px;padding:0 14px}
.toolbar .btn-ghost{border-color:#CFCFCF;color:#1A1A1A}
@media (max-width:720px){.toolbar{padding:8px 10px 8px 52vw!important;min-height:60px}}
@media print{.toolbar{display:none!important}}`;
const _htmlDecode = (t) => t.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&amp;/g, "&");
function PrintProtocolModal({ html, onClose }) {
  const title = _htmlDecode((html.match(/<meta name="mateco-bar" content="([^"]*)"/) || html.match(/<title>([^<]*)<\/title>/) || [])[1] || "Protokol");
  const doc = html.replace("</head>", `<style>${PRINT_BAR_CSS}</style></head>`);
  return (
    <div className="protocol-overlay" style={{ position: "fixed", inset: 0, background: "#fff", zIndex: 200, overflow: "hidden" }}>
      <div className="protocol-frame-wrap" style={{ position: "absolute", inset: 0, top: "env(safe-area-inset-top)", background: "#fff" }}>
        <iframe
          title="Servisný protokol"
          srcDoc={doc}
          sandbox="allow-scripts allow-forms allow-modals allow-downloads allow-same-origin allow-popups"
          style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: "none" }}
        />
      </div>
      <div className="print-bar-x">
        <button className="btn btn-outline" title="Zavrieť protokol" onClick={onClose}>✕<span className="print-bar-long"> Zavrieť</span></button>
        <span className="print-bar-title">{title}</span>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Dashboard
--------------------------------------------------------- */
function Dashboard({
  stats,
  filteredMachines,
  search,
  setSearch,
  statusFilter,
  setStatusFilter,
  depoFilter,
  setDepoFilter,
  user,
  onAddMachine,
  onImport,
  onExportCsv,
  onOpenCard,
  onClearAll,
  today,
}) {
  const [showArchived, setShowArchived] = useState(false);
  const depoOptions = DEPO_OPTIONS;
  let visibleMachines = showArchived ? filteredMachines : filteredMachines.filter((m) => !m.archived);
  if (depoFilter) {
    visibleMachines = visibleMachines.filter((m) => (m.depo || "").toLowerCase() === depoFilter.toLowerCase());
  }
  const activeFilterCount = (statusFilter !== "all" ? 1 : 0) + (depoFilter ? 1 : 0) + (showArchived ? 1 : 0);
  function clearFilters() {
    setStatusFilter("all");
    setDepoFilter(null);
    setShowArchived(false);
  }
  const STATUS_LABELS = { free: "Voľné", active: "Na zákazke", broken: "V poruche", prep: "V príprave", overdue: "Po termíne" };
  const tileFilter = (id) => ({ on: statusFilter === id, onClick: () => setStatusFilter(statusFilter === id ? "all" : id) });

  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px,1fr))", gap: 12, marginBottom: 16 }}>
        <StatCard label="Strojov celkom" value={stats.total} />
        {/* Klik na dlaždicu = filter tabuľky, druhý klik ho vypne (návrh z6). */}
        <StatCard label="Na zákazke" value={stats.onJob} {...tileFilter("active")} />
        <StatCard label="Voľné" value={stats.free} {...tileFilter("free")} />
        {stats.broken > 0 && <StatCard label="V poruche" value={stats.broken} color="var(--danger)" {...tileFilter("broken")} />}
        {stats.prep > 0 && <StatCard label="V príprave" value={stats.prep} color="var(--warn)" {...tileFilter("prep")} />}
        <StatCard label="⚠ Po termíne" value={stats.overdue} color={stats.overdue > 0 ? "var(--warn)" : undefined} {...tileFilter("overdue")} />
      </div>

      <div className="tbar">
        <SearchInput placeholder="Hľadať stroj, zákazníka…" value={search} onChange={setSearch} style={{ minWidth: 300 }} />
        <FilterPopover activeCount={activeFilterCount} onClear={clearFilters}>
          <div style={{ marginBottom: 12 }}>
            <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 6 }}>Stav</div>
            <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={{ width: "100%" }}>
              <option value="all">Všetky stavy</option>
              <option value="free">Voľné</option>
              <option value="active">Na zákazke</option>
              <option value="broken">V poruche</option>
              <option value="prep">V príprave</option>
              <option value="overdue">Po termíne</option>
            </select>
          </div>
          <div style={{ marginBottom: 12 }}>
            <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 6 }}>Depo</div>
            <div className="seg" role="group" aria-label="Depo">
              {depoOptions.map((d) => (
                <button key={d} type="button" className={depoFilter === d ? "on" : ""} aria-pressed={depoFilter === d} onClick={() => setDepoFilter(depoFilter === d ? null : d)} style={{ padding: "0 9px" }}>
                  {DEPO_SHORT_LABELS[d] || d}
                </button>
              ))}
            </div>
          </div>
          <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 14 }}>
            <input type="checkbox" checked={showArchived} onChange={(e) => setShowArchived(e.target.checked)} />
            Zobraziť archivované
          </label>
        </FilterPopover>
        {statusFilter !== "all" && <>
          <span className="fchip on">{STATUS_LABELS[statusFilter]}<button type="button" className="fchip-x" aria-label={`Zrušiť filter ${STATUS_LABELS[statusFilter]}`} onClick={() => setStatusFilter("all")}>×</button></span>
          <span role="status" style={{ fontSize: 14, color: "var(--text-dim)" }}>{visibleMachines.length} z {plural(stats.total, "stroja", "strojov", "strojov")}</span>
        </>}
        <div style={{ flex: 1 }} />
        {can(user, "machine_import_csv") && (
          <button className="btn btn-outline who-hide-mobile" onClick={onImport}>Import CSV</button>
        )}
        {can(user, "machine_import_csv") && (
          <button className="btn btn-outline who-hide-mobile" onClick={onExportCsv}>Export CSV</button>
        )}
        {can(user, "machine_add") && (
          <button className="btn btn-accent" onClick={onAddMachine}>+ Pridať stroj</button>
        )}
        <span className="who-hide-mobile">
          <KebabMenu label="⋯" name="Ďalšie akcie" actions={[
            can(user, "machine_clear_all") && { label: "Vymazať všetky stroje", danger: true, onClick: onClearAll },
          ]} />
        </span>
        <span className="m-only">
          <KebabMenu label="⋯" name="Ďalšie akcie" actions={[
            can(user, "machine_import_csv") && { label: "Import CSV", onClick: onImport },
            can(user, "machine_import_csv") && { label: "Export CSV", onClick: onExportCsv },
            can(user, "machine_clear_all") && { label: "Vymazať všetky stroje", danger: true, onClick: onClearAll },
          ]} />
        </span>
      </div>

      <div className="panel jobs-wrap" style={{ boxShadow: "none", borderRadius: 12 }}>
        <table className="table-cards jobs-table tc900">
          <thead>
            <tr>
              <th>Stroj</th>
              <th>Revízia ZZ</th>
              <th>Revízia EZ</th>
              <th>Stav</th>
              <th>Zákazka</th>
              <th>Ďalšia zákazka</th>
            </tr>
          </thead>
          <tbody>
            {visibleMachines.length === 0 && (
              <tr>
                <td colSpan={6} className="td-plain" style={{ textAlign: "center", color: "var(--text-dim)", padding: 30 }}>
                  Žiadne stroje. Pridajte ich ručne alebo cez CSV import.
                </td>
              </tr>
            )}
            {visibleMachines.map((m) => {
              const overdueDays = m.currentJob && m.status === "overdue" ? daysBetween(m.currentJob.endDate, today) : 0;
              const revCell = (track, date) => {
                if (track === false) return <span style={{ color: "var(--text-dim)" }}>Nesledované</span>;
                if (!date) return <span style={{ color: "var(--text-dim)" }}>—</span>;
                const d = daysBetween(today, date);
                if (d < 0) return <span className="spill spill-overdue tnum">⚠ {fmtDate(date)}</span>;
                return <span className="tnum" style={{ color: d <= 30 ? "var(--warn)" : undefined, fontWeight: d <= 30 ? 600 : undefined }}>{fmtDate(date)}</span>;
              };
              const statusPill = m.status === "overdue"
                ? <span className="spill spill-overdue">⚠ Po termíne +{plural(overdueDays, "deň", "dni", "dní")}</span>
                : m.status === "active" ? (m.awaitingOut ? <span className="spill spill-out">Čaká na vývoz</span> : <span className="spill spill-active">Na zákazke</span>)
                : m.awaitingPickup ? <span className="spill spill-wait" title={`Ukončené ${fmtDate(m.awaitingPickup.endDate)} · ${m.awaitingPickup.customer || ""}`}>Čaká na zvoz</span>
                : m.hasOpenDamage ? <span className="spill spill-problem">V poruche</span>
                : m.inPrep ? <span className="spill spill-wait">V príprave</span>
                : <span className="spill spill-done">Voľný</span>;
              return (
                <tr
                  key={m.id}
                  id={"machine-row-" + m.id}
                  className={m.hasOpenDamage || m.status === "overdue" ? "row-problem" : ""}
                  style={{ cursor: "pointer", opacity: m.archived ? 0.55 : 1 }}
                  onClick={() => onOpenCard(m)}
                  {...rowOpenKeys(() => onOpenCard(m))}
                >
                  <td className="td-plain">
                    <span style={{ display: "flex", alignItems: "center", gap: 8, justifyContent: "space-between" }}>
                      <strong className="tnum">{m.code}{m.archived ? " (archivovaný)" : ""}</strong>
                      <span className="m-only">{statusPill}</span>
                    </span>
                    <div className="cell-sub">{[m.type, m.depo].filter(Boolean).join(" · ") || "—"}</div>
                    {m.hasOpenDamage && <div style={{ marginTop: 4 }}><span className="spill spill-problem">⚠ otvorená porucha</span></div>}
                  </td>
                  <td data-label="Revízia ZZ">{revCell(m.trackRevisions, m.revizia)}</td>
                  <td data-label="Revízia EZ">{revCell(m.trackRevisionsEZ, m.reviziaEZ)}</td>
                  <td data-label="Stav" className="who-hide-mobile">{statusPill}</td>
                  <td data-label="Zákazka" className={m.currentJob ? "" : "who-hide-mobile"}>
                    {m.currentJob ? (m.currentJob.customer || m.currentJob.toLocation) : <span style={{ color: "var(--text-dim)" }}>—</span>}
                    {m.currentJob && <div className="cell-sub tnum">{m.currentJob.endDate ? `do ${fmtDate(m.currentJob.endDate)}` : <span style={{ color: "var(--warn)" }}>bez konca</span>}</div>}
                  </td>
                  <td data-label="Ďalšia zákazka" className={m.nextJob ? "tnum" : "who-hide-mobile"} style={{ color: "var(--text-dim)" }}>
                    {m.nextJob ? `${fmtDate(m.nextJob.startDate)} → ${m.nextJob.toLocation}` : "—"}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function StatCard({ label, value, color, delta, spark, onClick, on }) {
  const Tag = onClick ? "button" : "div";
  return (
    <Tag type={onClick ? "button" : undefined} className={`panel${onClick ? " stat-click" : ""}${on ? " on" : ""}`} aria-pressed={onClick ? !!on : undefined} onClick={onClick} style={{ padding: "14px 16px" }}>
      <div className="label-font" style={{ fontSize: 13, color: on ? "var(--text)" : "var(--text-dim)", marginBottom: 4 }}>{label}{onClick && <span aria-hidden="true">{on ? " ✓" : " ›"}</span>}</div>
      <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", gap: 8 }}>
        <div className="mono" style={{ fontSize: 28, fontWeight: 600, color }}>{value}</div>
        {spark && <Spark values={spark} />}
      </div>
      {delta && (
        <div style={{ fontSize: 12, fontWeight: 600, marginTop: 2, color: delta.direction === "flat" ? "var(--text-dim)" : (delta.direction === "up") !== !!delta.upIsBad ? "var(--ok)" : "var(--danger)" }}>
          {delta.direction === "up" ? "▲" : delta.direction === "down" ? "▼" : "–"} {delta.text}
        </div>
      )}
    </Tag>
  );
}

/* ---------------------------------------------------------
   Jobs board
--------------------------------------------------------- */
function JobsBoard({ jobs, reservations, machineById, driverById, hpDoneByJob, today, user, myEmployee, salespeople, initialQuickCategory, onQuickCategoryConsumed, onAddJob, onImportJobs, onComplete, onEdit, onOpenJob, onOpenReservation, onClearAll }) {
  const [shown, setShown] = useState(200); // veľa dokončených zákaziek naraz zamrazí stránku → po 200
  const [search, setSearch] = useState("");
  const [depoFilter, setDepoFilter] = useState(null);
  const [activeFilters, setActiveFilters] = useState(() => new Set(["planned", "active"]));
  const [quickCategory, setQuickCategory] = useState(initialQuickCategory || null);
  const depoOptions = DEPO_OPTIONS;
  // Obchodník sa po prihlásení pozerá prioritne na svoje vlastné zákazky —
  // platforma to prednastaví, ale dá sa to jedným klikom zrušiť a vidieť všetky.
  const isMyselfObchodnik = user?.role === "obchodnik" && myEmployee?.role === "obchodnik";
  const [obchodnikFilter, setObchodnikFilter] = useState(() => (isMyselfObchodnik ? myEmployee.name : ""));

  useEffect(() => {
    if (initialQuickCategory) {
      setQuickCategory(initialQuickCategory);
      onQuickCategoryConsumed?.();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialQuickCategory]);

  function matchesSearchAndDepo(j) {
    if (obchodnikFilter && j.obchodnik !== obchodnikFilter) return false;
    if (depoFilter && (j.fromDepo || "").toLowerCase() !== depoFilter.toLowerCase() && (j.returnDepo || "").toLowerCase() !== depoFilter.toLowerCase()) {
      return false;
    }
    if (search.trim()) {
      const q = search.toLowerCase();
      const m = machineById[j.machineId];
      const hit =
        (m?.code || "").toLowerCase().includes(q) ||
        (m?.type || "").toLowerCase().includes(q) ||
        (j.fromDepo || "").toLowerCase().includes(q) ||
        (j.returnDepo || "").toLowerCase().includes(q) ||
        (j.customer || "").toLowerCase().includes(q);
      if (!hit) return false;
    }
    return true;
  }

  const overdueJobs = jobs.filter((j) => effectiveStatus(j, today) === "overdue" && matchesSearchAndDepo(j));
  const endingSoonJobs = jobs.filter((j) => effectiveStatus(j, today) === "active" && j.endDate && daysBetween(today, j.endDate) <= 5 && matchesSearchAndDepo(j));
  const noDriverJobs = jobs.filter((j) => j.status !== "completed" && !j.driverId && !j.selfPickup && (j.departureDate || j.startDate) >= today && matchesSearchAndDepo(j));
  const noEndDateJobs = jobs.filter((j) => j.status !== "completed" && !j.endDate && matchesSearchAndDepo(j));
  function matchesSearchAndDepoRes(r) {
    if (obchodnikFilter && r.obchodnik !== obchodnikFilter) return false;
    const m = machineById[r.machineId];
    if (depoFilter && (m?.depo || "").toLowerCase() !== depoFilter.toLowerCase()) return false;
    if (search.trim()) {
      const q = search.toLowerCase();
      const hit =
        (m?.code || "").toLowerCase().includes(q) ||
        (m?.type || "").toLowerCase().includes(q) ||
        (m?.depo || "").toLowerCase().includes(q) ||
        (r.customer || "").toLowerCase().includes(q);
      if (!hit) return false;
    }
    return true;
  }
  const approvedReservations = (reservations || []).filter((r) => r.status === "approved" && matchesSearchAndDepoRes(r));
  const pendingReservations = (reservations || []).filter((r) => r.status === "pending" && matchesSearchAndDepoRes(r));
  const quickTiles = [
    { id: "pendingReservations", label: "Rezervácie čakajúce na schválenie", color: "var(--warn)", items: pendingReservations, isReservation: true },
    { id: "overdue", label: "Zákazka po termíne", color: "var(--warn)", items: overdueJobs },
    { id: "endingSoon", label: "Zákazka končí čoskoro (do 5 dní)", color: "var(--warn)", items: endingSoonJobs },
    { id: "noDriver", label: "Zákazka bez šoféra", color: "var(--info)", items: noDriverJobs },
    { id: "noEndDate", label: "Zákazka bez dátumu ukončenia", color: "var(--warn)", items: noEndDateJobs },
    { id: "reservations", label: "Nezáväzné rezervácie (schválené)", color: "var(--accent)", items: approvedReservations, isReservation: true },
  ];
  const activeTile = quickTiles.find((t) => t.id === quickCategory);

  function statusBucket(j) {
    const st = effectiveStatus(j, today);
    if (st === "completed") return "completed";
    if (st === "planned") return "planned";
    return "active"; // "active" and "overdue" both count as "na zákazke"
  }

  const filterButtons = [
    { id: "planned", label: "Naplánovaná" },
    { id: "active", label: "Na zákazke" },
    { id: "completed", label: "Dokončená" },
  ];
  function toggleFilter(id) {
    setActiveFilters((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  let filtered = jobs.filter((j) => activeFilters.has(statusBucket(j)));
  if (obchodnikFilter) {
    filtered = filtered.filter((j) => j.obchodnik === obchodnikFilter);
  }
  if (search.trim()) {
    const q = search.toLowerCase();
    filtered = filtered.filter((j) => {
      const m = machineById[j.machineId];
      return (
        (m?.code || "").toLowerCase().includes(q) ||
        (m?.type || "").toLowerCase().includes(q) ||
        (j.fromDepo || "").toLowerCase().includes(q) ||
        (j.returnDepo || "").toLowerCase().includes(q) ||
        (j.customer || "").toLowerCase().includes(q) ||
        (j.toLocation || "").toLowerCase().includes(q)
      );
    });
  }
  if (depoFilter) {
    filtered = filtered.filter(
      (j) => (j.fromDepo || "").toLowerCase() === depoFilter.toLowerCase() || (j.returnDepo || "").toLowerCase() === depoFilter.toLowerCase()
    );
  }
  const sorted = [...filtered].sort((a, b) => (a.startDate < b.startDate ? 1 : -1));
  const bucketCount = (id) => jobs.filter((j) => statusBucket(j) === id && matchesSearchAndDepo(j)).length;
  return (
    <div>
      <div style={{ display: "flex", gap: 10, marginBottom: 12, flexWrap: "wrap", alignItems: "center" }}>
        <SearchInput placeholder="Hľadať stroj, zákazníka…" value={search} onChange={setSearch} style={{ minWidth: 260 }} />
        <div className="fchips chip-scroll" role="group" aria-label="Stav zákazky">
          {filterButtons.map((f) => (
            <button key={f.id} type="button" className={`fchip${activeFilters.has(f.id) ? " on" : ""}`} aria-pressed={activeFilters.has(f.id)} onClick={() => toggleFilter(f.id)}>
              {activeFilters.has(f.id) && "✓ "}{f.label}<span className="seg-n">{bucketCount(f.id)}</span>
            </button>
          ))}
        </div>
        <select aria-label="Depo" value={depoFilter || ""} onChange={(e) => setDepoFilter(e.target.value || null)} style={{ minHeight: 40 }}>
          <option value="">Všetky depá</option>
          {depoOptions.map((d) => <option key={d} value={d}>{d}</option>)}
        </select>
        <div style={{ display: "flex", gap: 10, marginLeft: "auto" }}>
          {can(user, "job_import_csv") && <button className="btn btn-ghost" onClick={onImportJobs}>Import z CSV</button>}
          {can(user, "job_clear_all") && <KebabMenu label="⋯" name="Ďalšie akcie" actions={[{ label: "Vymazať všetky zákazky", danger: true, onClick: onClearAll }]} />}
        </div>
      </div>
      {(isMyselfObchodnik || quickTiles.some((t) => t.items.length > 0)) && (
        <div className="chip-scroll" role="group" aria-label="Rýchle filtre" style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap" }}>
          {isMyselfObchodnik && (
            <button type="button" className={`fchip${obchodnikFilter ? " on" : ""}`} aria-pressed={!!obchodnikFilter} onClick={() => setObchodnikFilter(obchodnikFilter ? "" : myEmployee.name)}>
              {obchodnikFilter ? "👤 Zobrazujem len moje — klik pre všetky" : "Zobraziť len moje zákazky"}
            </button>
          )}
          {quickTiles.filter((t) => t.items.length > 0).map((t) => (
            <button key={t.id} type="button" className={`fchip${t.id === "overdue" ? " overdue" : ""}`} onClick={() => setQuickCategory(t.id)}>
              {t.id === "overdue" && "⚠ "}{t.label}<span className="seg-n">{t.items.length}</span>
            </button>
          ))}
        </div>
      )}
      {sorted.length === 0 ? (
        <div className="panel" style={{ padding: 30, textAlign: "center", color: "var(--text-dim)" }}>
          {activeFilters.size === 0 ? "Vyberte aspoň jeden filter." : "Žiadne zákazky nezodpovedajú filtru."}
          {(search.trim() || depoFilter || quickCategory || [...activeFilters].sort().join() !== "active,planned") && (
            <button type="button" className="btn btn-outline" style={{ marginLeft: 8 }} onClick={() => { setSearch(""); setDepoFilter(null); setQuickCategory(null); setActiveFilters(new Set(["planned", "active"])); }}>Zrušiť filter</button>
          )}
        </div>
      ) : (
        <div className="panel jobs-wrap" style={{ boxShadow: "none", borderRadius: 12 }}>
          <table className="table-cards jobs-table tc900">
            <thead>
              <tr><th>Stroj</th><th>Zákazník · Kam</th><th>Obdobie</th><th>Šofér</th><th>Stav</th><th><span className="sr-only">Akcie</span></th></tr>
            </thead>
            <tbody>
              {sorted.slice(0, shown).map((j) => {
                const st = effectiveStatus(j, today);
                const m = machineById[j.machineId];
                return (
                  <tr key={j.id} id={"job-row-" + j.id} className={`${st === "overdue" ? "row-problem" : ""}${onOpenJob ? " row-click" : ""}`} style={{ cursor: onOpenJob ? "pointer" : "default" }} onClick={() => onOpenJob && onOpenJob(j)}>
                    <td className="td-plain">
                      <strong className="tnum">{m?.code || "?"}</strong>
                      <div className="cell-sub">{[j.machineDisplayName || m?.type, j.fromDepo].filter(Boolean).join(" · ")}</div>
                    </td>
                    <td className="td-plain">
                      {j.customer || "—"}
                      <div className="cell-sub">{j.selfPickup ? `Vyzdvihnutie v depe ${j.fromDepo || ""}` : j.toLocation || "—"}</div>
                      {j.notes && <div className="cell-sub" style={{ overflowWrap: "anywhere" }}>Pozn.: {j.notes}</div>}
                    </td>
                    <td data-label="Obdobie" className="tnum" style={{ whiteSpace: "nowrap" }}>
                      {j.startDate && j.endDate ? fmtRange(j.startDate, j.endDate) : `${fmtDate(j.startDate)} – bez určeného konca`}
                    </td>
                    <td data-label="Šofér">{j.selfPickup ? "Vlastná doprava" : driverById[j.driverId]?.name || <span style={{ color: "var(--text-dim)" }}>— neurčený —</span>}</td>
                    <td data-label="Stav">
                      <span style={{ display: "inline-flex", gap: 6, flexWrap: "wrap", justifyContent: "flex-end" }}>
                        <JobStatusPill status={st === "active" && !j.notRealized && !hpDoneByJob?.[j.id] ? "awaitingOut" : st} />
                        {!j.endDate && j.status !== "completed" && <span className="spill spill-wait" title="Zákazka nemá zadaný dátum ukončenia">⚠ Bez konca</span>}
                      </span>
                    </td>
                    <td className="td-actions" style={{ textAlign: "right", whiteSpace: "nowrap" }} onClick={(e) => e.stopPropagation()}>
                      {onOpenJob && <button type="button" className="btn btn-outline" style={{ borderColor: "var(--line-strong)" }} onClick={() => onOpenJob(j)}>Otvoriť</button>}{" "}
                      <KebabMenu label="⋯" actions={[
                        can(user, "job_edit") && { label: "Upraviť", onClick: () => onEdit(j) },
                        st !== "completed" && can(user, "job_complete") && { label: "Ukončiť", onClick: () => onComplete(j) },
                      ]} />
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {sorted.length > shown && (
            <div style={{ textAlign: "center", padding: 12 }}>
              <button type="button" className="btn btn-outline" onClick={() => setShown((n) => n + 200)}>Zobraziť ďalších {Math.min(200, sorted.length - shown)} (zobrazených {shown} z {sorted.length})</button>
            </div>
          )}
        </div>
      )}
      {activeTile && (
        <JobsQuickDrilldownModal tile={activeTile} machineById={machineById} salespeople={salespeople} onClose={() => setQuickCategory(null)} onOpenJob={onOpenJob} onOpenReservation={onOpenReservation} />
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   Zdieľané rozbaľovacie okno pre rýchle prehľady zákaziek/rezervácií —
   používané v Zákazkách aj v Prehľade Požičovne (rovnaké chovanie,
   rovnaké rýchle filtre podľa depa a obchodníka).
--------------------------------------------------------- */
function JobsQuickDrilldownModal({ tile, machineById, salespeople, onClose, onOpenJob, onOpenReservation }) {
  const [drillDepoFilter, setDrillDepoFilter] = useState(null);
  const [drillObchodnikFilter, setDrillObchodnikFilter] = useState("");

  function itemDepo(item, isReservation) {
    if (isReservation) return machineById[item.machineId]?.depo || "";
    return item.fromDepo || item.returnDepo || "";
  }
  const drillItems = tile.items.filter(
    (item) =>
      (!drillDepoFilter || itemDepo(item, tile.isReservation).toLowerCase() === drillDepoFilter.toLowerCase()) &&
      (!drillObchodnikFilter || item.obchodnik === drillObchodnikFilter)
  );

  return (
    <Modal eyebrow="Rýchly prehľad" title={<>{tile.id === "overdue" && "⚠ "}{tile.label} <span className="tnum" style={{ color: "var(--text-dim)", fontWeight: 500 }}>({drillItems.length}{drillItems.length !== tile.items.length ? ` z ${tile.items.length}` : ""})</span></>} onClose={onClose} wide>
      <div className="seg" role="group" aria-label="Depo" style={{ marginBottom: 10, flexWrap: "wrap" }}>
        {DEPO_OPTIONS.map((d) => (
          <button
            key={d}
            type="button"
            className={drillDepoFilter === d ? "on" : ""}
            aria-pressed={drillDepoFilter === d}
            onClick={() => setDrillDepoFilter(drillDepoFilter === d ? null : d)}
          >
            {d}
          </button>
        ))}
      </div>
      <div style={{ marginBottom: 14 }}>
        <select aria-label="Obchodník" value={drillObchodnikFilter} onChange={(e) => setDrillObchodnikFilter(e.target.value)} style={{ minWidth: 240, maxWidth: "100%" }}>
          <option value="">— všetci obchodníci —</option>
          {salespeople.map((s) => <option key={s.name} value={s.name}>{s.name}</option>)}
        </select>
      </div>
      <div className={drillItems.length ? "flist" : undefined} style={{ maxHeight: "60vh", overflowY: "auto" }}>
        {drillItems.length === 0 ? (
          <div className="fnote fnote-i">Žiadne záznamy.</div>
        ) : tile.isReservation ? (
          drillItems.map((r) => {
            const m = machineById[r.machineId];
            return (
              <div key={r.id} className="frow quick-job-row">
                <div className="quick-job-info" style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", minWidth: 0 }}>
                  <span
                    className="mono"
                    style={{ fontWeight: 700, fontSize: 15, color: "var(--text)", cursor: "pointer", textDecoration: "underline", whiteSpace: "nowrap", fontVariantNumeric: "tabular-nums" }}
                    onClick={() => onOpenReservation(r)}
                  >
                    {m?.code || "—"}
                  </span>
                  <span className="tnum" style={{ fontSize: 15 }}>
                    od {fmtDate(r.expectedStart)}{r.expectedEnd ? ` do ${fmtDate(r.expectedEnd)}` : ""} · {r.customer}
                    {r.obchodnik ? ` · ${r.obchodnik}` : ""}
                  </span>
                </div>
              </div>
            );
          })
        ) : (
          drillItems.map((j) => {
            const m = machineById[j.machineId];
            return (
              <div key={j.id} className="frow quick-job-row" style={tile.id === "overdue" ? { background: "var(--danger-bg)" } : undefined}>
                <div className="quick-job-info" style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", minWidth: 0 }}>
                  <span
                    className="mono"
                    style={{ fontWeight: 700, fontSize: 15, color: "var(--text)", cursor: "pointer", textDecoration: "underline", whiteSpace: "nowrap", fontVariantNumeric: "tabular-nums" }}
                    onClick={() => onOpenJob(j)}
                  >
                    {m?.code || "—"}
                  </span>
                  <span className="tnum" style={{ fontSize: 15, color: tile.id === "overdue" ? "var(--danger-text)" : undefined }}>
                    {tile.id === "overdue" && `⚠ mal skončiť ${fmtDate(j.endDate)}`}
                    {tile.id === "endingSoon" && `do ${fmtDate(j.endDate)}`}
                    {tile.id === "noDriver" && `od ${fmtDate(j.startDate)} → ${j.toLocation}`}
                    {tile.id === "noEndDate" && `beží od ${fmtDate(j.startDate)} — dátum konca nezadaný`}
                    {j.customer ? ` · ${j.customer}` : ""}
                    {j.obchodnik ? ` · ${j.obchodnik}` : ""}
                  </span>
                </div>
                {tile.id === "endingSoon" && (
                  <button
                    className="btn btn-outline quick-job-btn"
                    style={{ marginLeft: "auto" }}
                    title={!j.customerEmail ? "Zákazka nemá vyplnený email — doplníte ho priamo v maile" : ""}
                    onClick={() => {
                      const portalLink = j.publicToken ? `${window.location.origin}${window.location.pathname}?portal=${j.publicToken}` : "";
                      composeMail({
                        to: j.customerEmail || "",
                        subject: `Blížiaci sa koniec prenájmu — ${m?.code || ""}`,
                        body:
                          `Dobrý deň,\n\nradi by sme Vás upozornili, že prenájom stroja ${m?.code || ""}${j.toLocation ? " na adrese " + j.toLocation : ""} sa blíži ku koncu (${fmtDate(j.endDate)}).\n\nAk máte záujem o predĺženie, prosím kontaktujte nás. V opačnom prípade si Vás dovoľujeme požiadať o súčinnosť pri príprave stroja na zvoz.\n\nĎakujeme.` +
                          (portalLink ? `\n\nStav zákazky aj odovzdávací protokol si môžete kedykoľvek pozrieť tu:\n${portalLink}` : ""),
                      });
                    }}
                  >
                    ✉️ Upozorniť zákazníka
                  </button>
                )}
              </div>
            );
          })
        )}
      </div>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Zjednodušený mobilný pohľad na prepravy pre šoféra — namiesto dispečerského
   hustého zoznamu (vyhľadávanie, depo filtre, priraďovanie, rýchly prehľad,
   ktoré šofér ani nemôže/nepotrebuje používať) veľké karty zoskupené podľa dňa,
   so stavom protokolu ako výraznou akciou.
--------------------------------------------------------- */
function DriverTransportsList({ dnes, unsavedProtocols = 0, items, doneZvozCount = 0, machineById, handoverProtocols, onOpenJob, today, tomorrow, highlightTransportId, onDismissTransportHighlight, myTransportNotes, onMarkTransportNoteDriverDone, onReportIssue }) {
  useEffect(() => {
    if (!highlightTransportId) return;
    document.getElementById(`transport-${highlightTransportId}`)?.scrollIntoView({ behavior: "smooth", block: "center" });
  }, [highlightTransportId]);

  // Klik na "Prevezené" je nevratný (pošle upozornenie dispečerovi), preto ešte
  // jedno potvrdenie navyše — rovnaký vzor ako inde v appke (ConfirmActionModal).
  const [confirmDoneNote, setConfirmDoneNote] = useState(null);

  // "Prevoz" dlaždice — poznámky o presune stroja medzi depami, ktoré šoférovi
  // priradil dispečer/vedúci požičovne (samostatné od bežných vývoz/zvoz kariet
  // nižšie, viď step46 pre prístupovú logiku).
  const transportNotesPanel = myTransportNotes.length > 0 && (
    <div>
      <div style={{ fontSize: 12, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 10 }}>
        🚚 Prevoz strojov medzi depami
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 22 }}>
        {myTransportNotes.map((t) => {
          const m = machineById[t.machineId];
          return (
            <div key={t.id} className="panel" style={{ padding: 16, borderRadius: 12 }}>
              <div style={{ fontSize: 14, marginBottom: 8 }}>
                {t.date && <div className="tnum" style={{ fontWeight: 700, marginBottom: 4 }}>{t.date === today ? "Dnes" : t.date === tomorrow ? "Zajtra" : fmtDate(t.date)}</div>}
                Previezť stroj <strong>{m?.code || t.machineCode || "—"}</strong> z depa <strong>{m?.depo || t.fromDepo || "—"}</strong> do depa <strong>{t.targetDepo}</strong>
                {t.note && t.note.trim() !== "Prevoz" ? ` — ${t.note}` : ""}
              </div>
              <button className="btn btn-accent" style={{ minHeight: 48, width: "100%" }} onClick={() => setConfirmDoneNote(t)}>
                ✓ Prevezené
              </button>
            </div>
          );
        })}
      </div>
      {confirmDoneNote && (
        <ConfirmActionModal
          message={`Naozaj ste previezli stroj ${machineById[confirmDoneNote.machineId]?.code || confirmDoneNote.machineCode || "—"} do depa ${confirmDoneNote.targetDepo}?`}
          confirmLabel="Áno, prevezené"
          onClose={() => setConfirmDoneNote(null)}
          onConfirm={() => onMarkTransportNoteDriverDone(confirmDoneNote.id)}
        />
      )}
    </div>
  );

  // Vývoz s vyplneným protokolom je hotový — nie je „ďalšia“ úloha, ostáva dole (QR, protokol pre zákazníka).
  const isDone = (t) => t.type === "vyvoz" && handoverProtocols.some((h) => h.jobId === t.jobId);
  // „Dnes“ šoféra: prvá preprava (po termíne / dnes) ako veľká karta, ostatné ako kompaktné riadky (ťuk = celá karta).
  if (dnes) {
    const card = (t, hero) => (
      <DriverTransportCard key={t.id} t={t} hero={hero} machineById={machineById} handoverProtocols={handoverProtocols} onOpenJob={onOpenJob}
        highlighted={t.id === highlightTransportId} onDismissHighlight={onDismissTransportHighlight} onReportIssue={onReportIssue} preview={t.date > today} />
    );
    const row = (t) => (
      <TodayCompactRow key={t.id} id={`transport-${t.id}`} problem={t.overdue} defaultOpen={t.id === highlightTransportId}
        title={`${t.type === "vyvoz" ? "Vývoz" : "Zvoz"} · ${machineById[t.machineId]?.code || "—"}`}
        sub={[t.customer, t.date !== today ? fmtDate(t.date) : ""].filter(Boolean).join(" · ")}>{card(t)}</TodayCompactRow>
    );
    const nowAll = items.filter((t) => t.overdue || t.date === today);
    const doneNow = nowAll.filter(isDone);
    const [first, ...restNow] = nowAll.filter((t) => !isDone(t));
    const later = items.filter((t) => !t.overdue && t.date > today);
    return (
      <div>
        {transportNotesPanel}
        {first ? card(first, true) : <EmptyLift text={unsavedProtocols ? `${unsavedProtocols > 1 && unsavedProtocols < 5 ? "Čakajú" : "Čaká"} ${plural(unsavedProtocols, "neuložený protokol", "neuložené protokoly", "neuložených protokolov")}.` : doneNow.length || doneZvozCount ? "Všetko na dnes je hotové." : "Na dnes žiadne prepravy."} />}
        {/* Rovnako ako u technika: pod hlavnou kartou vždy „Ďalej dnes“ (v1.0.805). */}
        {first && <div className="today-sec">Ďalej dnes · {restNow.length}</div>}
        {restNow.map(row)}
        {first && restNow.length === 0 && <div style={{ fontSize: 14, color: "var(--text-dim)", marginBottom: 10 }}>Na dnes nič ďalšie.</div>}
        {later.length > 0 && <><div className="today-sec">Zajtra a neskôr · {later.length}</div>{later.map(row)}</>}
        {/* hotové vývozy s kartou (QR, protokol); hotové zvozy len počtom — šofér ich už nepotrebuje otvárať */}
        {(doneNow.length > 0 || doneZvozCount > 0) && <><div className="today-sec">Hotové dnes · {doneNow.length + doneZvozCount}</div>{doneNow.map(row)}
          {doneZvozCount > 0 && <div style={{ fontSize: 14, color: "var(--text-dim)", marginBottom: 10 }}>+ {plural(doneZvozCount, "hotový zvoz", "hotové zvozy", "hotových zvozov")}</div>}</>}
      </div>
    );
  }

  if (items.length === 0) {
    return (
      <div>
        {transportNotesPanel}
        <div className="panel" style={{ padding: 30, textAlign: "center", color: "var(--text-dim)" }}>
          Žiadne prepravy.
        </div>
      </div>
    );
  }

  const rest = items.filter((t) => !t.overdue);
  const buckets = [
    { label: "Po termíne", items: items.filter((t) => t.overdue), danger: true },
    { label: "Dnes", items: rest.filter((t) => t.date === today) },
    { label: "Zajtra", items: rest.filter((t) => t.date === tomorrow) },
    { label: "Neskôr", items: rest.filter((t) => t.date > tomorrow) },
  ].filter((b) => b.items.length > 0);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 22 }}>
      {transportNotesPanel}
      {buckets.map((b) => (
        <div key={b.label}>
          <div
            style={{
              fontSize: 12,
              fontWeight: 700,
              textTransform: "uppercase",
              letterSpacing: ".06em",
              color: b.danger ? "var(--danger)" : "var(--text-dim)",
              marginBottom: 10,
            }}
          >
            {b.danger ? "⚠️ " : ""}
            {b.label}
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10, maxWidth: 720 }}>
            {/* hotový vývoz len jedným riadkom na konci dňa (návrh terénu k34) */}
            {[...b.items.filter((t) => !isDone(t)), ...b.items.filter(isDone)].map((t) => isDone(t) ? (
              <button key={t.id} id={`transport-${t.id}`} type="button" className="today-row" style={{ display: "block", minHeight: 52, padding: "14px 16px", marginBottom: 0, outline: t.id === highlightTransportId ? "2px solid var(--accent)" : "none" }}
                onClick={() => { if (t.id === highlightTransportId) onDismissTransportHighlight?.(); onOpenJob?.(t.jobId, t.type); }}>
                <span style={{ color: "var(--ok)", fontWeight: 700 }}>✓</span> Vývoz <strong className="tnum">{machineById[t.machineId]?.code || "—"}</strong>{t.customer ? ` · ${t.customer}` : ""} <span style={{ color: "var(--text-dim)" }}>— protokol / QR</span>
              </button>
            ) : (
              <DriverTransportCard
                key={t.id}
                t={t}
                machineById={machineById}
                handoverProtocols={handoverProtocols}
                onOpenJob={onOpenJob}
                highlighted={t.id === highlightTransportId}
                onDismissHighlight={onDismissTransportHighlight}
                onReportIssue={onReportIssue}
                preview={t.date > today}
              />
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

function DriverTransportCard({ t, hero, machineById, handoverProtocols, onOpenJob, highlighted, onDismissHighlight, onReportIssue, preview }) {
  const machine = machineById[t.machineId];
  const isVyvoz = t.type === "vyvoz";
  const hp = handoverProtocols.find((h) => h.jobId === t.jobId);
  // Zvoz sa dá vyplniť aj bez protokolu o prevzatí (napr. vývoz prebehol mimo
  // platformy) — šofér vyplní rovno protokol o vrátení.
  const clickable = true;
  // Pred dňom prepravy sa protokol ešte vyplniť nedá — karta otvorí len náhľad.
  const isPreview = preview && (isVyvoz ? !hp : !hp?.returnDone);
  const statusText = isPreview
    ? `Náhľad — protokol od ${fmtDate(t.date)}`
    : isVyvoz
    ? !hp
      ? "Vyplniť protokol"
      : "✓ Hotovo — zobraziť protokol"
    : "Dokončiť vrátenie";
  const statusIcon = isPreview ? "oko" : isVyvoz && hp ? null : "protokol";
  const statusLabel = <>{statusIcon && <NavIcon id={statusIcon} size={20} />}{statusText}</>;
  const statusColor = isVyvoz && hp ? "var(--ok)" : "var(--accent)";
  const open = () => { if (highlighted) onDismissHighlight?.(); onOpenJob && onOpenJob(t.jobId, t.type); };
  if (hero) {
    return (
      <section id={`transport-${t.id}`} aria-label="Ďalšia preprava" className={`today-hero${t.overdue ? " today-problem" : ""}`} style={{ outline: highlighted ? "2px solid var(--accent)" : "none" }}>
        <div className={`today-hero-tag${t.overdue ? " today-problem-title" : ""}`}>{t.overdue ? `⚠ Po termíne · ${fmtDate(t.date)} · ` : "Ďalšia · "}{isVyvoz ? "Vývoz" : "Zvoz"}</div>
        <div className="today-hero-id">{machine?.code || "—"} {machine?.type && <small>{machine.type}</small>}</div>
        <div className="today-hero-sub">{t.customer && <>{t.customer}<br /></>}{t.from} → {t.to}</div>
        {t.issue && <div style={{ fontSize: 14, color: "var(--danger-text)", fontWeight: 600, whiteSpace: "pre-line" }}>🚨 {t.issue}</div>}
        <button type="button" className={`btn ${isVyvoz && hp ? "btn-ghost" : "btn-accent"} today-main`} onClick={open}>{statusLabel}</button>
        {t.site && !(isVyvoz && hp) && <a className="btn btn-ghost today-nav" href={`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(t.site)}`} target="_blank" rel="noopener noreferrer"><NavIcon id="navigovat" size={20} /> Navigovať</a>}
        {(t.customerPhone || t.dispatcher?.phone || onReportIssue) && (
          <div className="today-hero-more">
            {t.customerPhone && <a className="btn btn-ghost" href={`tel:${t.customerPhone}`}><PhoneIcon size={16} /> Zavolať</a>}
            {t.dispatcher?.phone && <a className="btn btn-ghost" href={`tel:${t.dispatcher.phone}`} title={`Dispečer zákazky: ${t.dispatcher.name}`}><PhoneIcon size={16} /> Dispečer</a>}
            {onReportIssue && <button type="button" className="btn btn-ghost" style={{ color: "var(--danger)" }} onClick={() => onReportIssue(t.jobId)}><NavIcon id="problem" /> Problém</button>}
          </div>
        )}
      </section>
    );
  }

  return (
    <div
      id={`transport-${t.id}`}
      onClick={() => {
        if (!clickable) return;
        if (highlighted) onDismissHighlight?.();
        onOpenJob && onOpenJob(t.jobId, t.type);
      }}
      style={{
        padding: 16,
        borderRadius: 12,
        border: "1px solid " + (t.overdue ? "var(--danger)" : "var(--border)"),
        background: "var(--panel)",
        cursor: clickable ? "pointer" : "default",
        opacity: clickable ? 1 : 0.7,
        outline: highlighted ? "2px solid var(--accent)" : "none",
        boxShadow: highlighted ? "0 0 0 4px var(--accent-light)" : "none",
        transition: "box-shadow .3s, outline .3s",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <span className={`badge ${isVyvoz ? "badge-info" : "badge-warn"}`}>{isVyvoz ? "Vývoz" : "Zvoz"}</span>
        <span style={{ fontSize: 13, fontWeight: 600 }}>{fmtDate(t.date)}</span>
      </div>
      <div style={{ fontSize: 17, fontWeight: 700, marginBottom: 2 }}>{machine?.code || "—"}</div>
      {machine?.type && <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 6 }}>{machine.type}</div>}
      {t.customer && <div style={{ fontSize: 13, marginBottom: 6 }}>{t.customer}</div>}
      <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 12 }}>
        {t.from} <span>→</span> {t.to}
      </div>
      {t.issue && <div style={{ fontSize: 12, color: "var(--danger)", fontWeight: 600, marginBottom: 10, whiteSpace: "pre-line" }}>🚨 {t.issue}</div>}
      {/* Rovnaké poradie ako karta na Dnes: hlavná akcia → Navigovať → Dispečer / Zavolať / Problém (návrh dizajnu 23. 10.) */}
      <button type="button" className={`btn ${isVyvoz && hp ? "btn-ghost" : isPreview ? "btn-outline" : "btn-accent"}`} style={{ width: "100%", minHeight: 46, marginBottom: 8, display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8, ...(isVyvoz && hp ? { color: statusColor } : {}) }} onClick={(e) => { e.stopPropagation(); open(); }}>{statusLabel}</button>
      {t.site && !(isVyvoz && hp) && (
        <a className="btn btn-ghost" onClick={(e) => e.stopPropagation()} style={{ width: "100%", minHeight: 46, marginBottom: 8, display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 6, fontWeight: 700, border: "2px solid var(--text)" }} href={`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(t.site)}`} target="_blank" rel="noopener noreferrer">
          <NavIcon id="navigovat" size={20} /> Navigovať
        </a>
      )}
      <div className="today-hero-more" onClick={(e) => e.stopPropagation()}>
        {t.customerPhone && (
          <a className="btn btn-ghost" style={{ minHeight: 40, display: "inline-flex", alignItems: "center", gap: 6 }} href={`tel:${t.customerPhone}`}>
            <PhoneIcon size={14} /> Zavolať
          </a>
        )}
        {t.dispatcher?.phone && (
          <a className="btn btn-ghost" style={{ minHeight: 40, display: "inline-flex", alignItems: "center", gap: 6 }} href={`tel:${t.dispatcher.phone}`} title={`Dispečer zákazky: ${t.dispatcher.name}`}>
            <PhoneIcon size={14} /> Dispečer
          </a>
        )}
        {onReportIssue && (
          <button type="button" className="btn btn-ghost" style={{ minHeight: 40, color: "var(--danger)", display: "inline-flex", alignItems: "center", gap: 6 }} onClick={() => onReportIssue(t.jobId)}>
            <NavIcon id="problem" size={16} /> Problém
          </button>
        )}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Transports overview (Prepravy) — future vývoz/zvoz by driver
--------------------------------------------------------- */
// Dátum prepravy sa uloží až po dopísaní (opustenie poľa / Enter), nie po každom
// klávese — inak sa uložil napr. rok 0005 a preprava zmizla zo zoznamu.
function TransportDateInput({ date, onSave, title, check }) {
  // Dátum ako text s ✎ — pole až po ťuknutí, nech sa pri posúvaní nezmení omylom (návrh dizajnu k34/5).
  const [editing, setEditing] = useState(false);
  const ref = useRef(null);
  // Dotyk: rovno kalendár; PC: len fokus (dátum sa dá písať klávesnicou, Enter/Esc ako doteraz).
  useEffect(() => { if (!editing) return; ref.current?.focus(); try { if (window.matchMedia?.("(pointer: coarse)").matches) ref.current?.showPicker?.(); } catch { /* bez showPicker */ } }, [editing]);
  const commit = (el) => {
    const v = el.value;
    const ok = /^\d{4}-\d{2}-\d{2}$/.test(v) && v >= addDaysISO(todayISO(), -366) && v <= addDaysISO(todayISO(), 366);
    const err = ok && v !== date && check ? check(v) : null;
    if (err) { showNotice(err); el.value = date; return; }
    // Preklep (10. 3. namiesto 3. 10.) — dátum v minulosti alebo o viac ako 30 dní inde treba potvrdiť.
    const unusual = ok && v !== date && (v < todayISO() || (date && (v > addDaysISO(date, 30) || v < addDaysISO(date, -30))));
    const rest = ok && v !== date ? restDayNote(v) : null;
    if ((unusual || rest) && !window.confirm(`Naozaj presunúť prepravu na ${fmtDate(v)}?${v < todayISO() ? " Dátum je v minulosti." : ""}${rest ? ` ${rest[0].toUpperCase()}${rest.slice(1)}.` : ""}`)) { el.value = date; return; }
    if (ok && v !== date && onSave(v) !== false) return;
    el.value = date;
  };
  if (!editing) {
    return (
      <button type="button" className="tr-date tnum" onClick={(e) => { e.stopPropagation(); setEditing(true); }} title={title} aria-label={`${title}: ${fmtDate(date)}`}>
        {fmtDate(date)} <span aria-hidden="true">✎</span>
      </button>
    );
  }
  return (
    <input
      ref={ref}
      key={date}
      type="date"
      defaultValue={date}
      onClick={(e) => e.stopPropagation()}
      onBlur={(e) => { commit(e.target); setEditing(false); }}
      onKeyDown={(e) => {
        if (e.key === "Enter") { e.preventDefault(); e.target.blur(); }
        if (e.key === "Escape") { e.preventDefault(); e.stopPropagation(); e.target.value = date; e.target.blur(); }
      }}
      style={{ fontSize: 11, padding: "3px 5px", width: 130 }}
      title={title}
      aria-label={title}
    />
  );
}
function TransportsOverview({ dnes, jobs, drivers, jobDispatcher, machineById, today, tomorrow, dayAfterTomorrow, user, myEmployee, assignDriver, assignReturnDriver, onSetTransportDate, onCheckTransportDate, depoCheckers, checkerSubstitutions, technicianById, handoverProtocols, onOpenJob, getTransportSendStatus, recordTransportSend, highlightTransportId, onDismissTransportHighlight, transportNotes, onReportTransportIssue, notesRefreshKey, assignments, unsavedProtocols = 0 }) {
  // Šoférovi patriace "Prevoz" dlaždice — poznámky o presune stroja medzi
  // depami, ktoré mu priradil dispečer/vedúci požičovne, ešte nenahlásené
  // ako hotové. Tabuľka "transportNotes" ostáva v DB prísne zamknutá len na
  // dispečera/vedúceho (žiadny iný SELECT) — šofér preto svoje vlastné
  // priradenia číta cez samostatnú RPC funkciu (get_my_transport_notes,
  // security definer — viď step46), nie z bežného React stavu.
  // Rola sa overuje podľa profilu (user.role) — presne ako pri existujúcom
  // toku so zákazkami (isMyselfSofer nižšie), NIE podľa employees.role (to sa
  // môže od profilu líšiť). Aj tak je to len kozmetické — samotné RPC si
  // správneho šoféra overí samo cez linkedUserId, nezávisle od tejto property.
  const [myTransportNotes, setMyTransportNotes] = useState([]);
  const refetchMyTransportNotes = useCallback(async () => {
    if (!user) { setMyTransportNotes([]); return; }
    const { data, error } = await supabase.rpc("get_my_transport_notes");
    // Bez signálu posledný stiahnutý zoznam (aj po obnovení stránky); odoslané/čakajúce „Prevezené“ v ňom nie sú.
    const queued = new Set((await idbGetAll("outbox")).filter((x) => x?.kind === "transportDone").map((x) => x.id));
    let rows;
    if (error) {
      console.error("get_my_transport_notes zlyhalo", error);
      if (error.code) return;
      rows = (await idbGet("tables", "myTransportNotes")) || null;
      if (!rows) return;
    } else {
      rows = (data || []).map((row) => ({ ...row.data, id: row.id }));
      if (!_cacheOff) idbPut("tables", "myTransportNotes", rows);
    }
    setMyTransportNotes(rows.filter((t) => !queued.has(t.id)));
  }, [user?.id]);
  // Nový prevoz príde šoférovi ako upozornenie → načítaj znova; aj pri návrate do okna.
  useEffect(() => { refetchMyTransportNotes(); }, [refetchMyTransportNotes, notesRefreshKey]);
  useEffect(() => {
    const onVis = () => { if (document.visibilityState === "visible") refetchMyTransportNotes(); };
    document.addEventListener("visibilitychange", onVis);
    return () => document.removeEventListener("visibilitychange", onVis);
  }, [refetchMyTransportNotes]);
  // Poznámka: NEvoláme tu App-level onMarkTransportNoteDriverDone (ten by
  // upozornenie postavil z lokálneho stavu "transportNotes", ktorý šofér
  // kvôli zamknutej tabuľke vôbec nemá) — RPC funkcia v DB si upozornenie aj
  // aktualizáciu poznámky rieši sama (viď step46).
  async function handleMarkTransportNoteDriverDone(id) {
    const { error } = navigator.onLine
      ? await supabase.rpc("mark_transport_note_driver_done", { note_id: id, p_done_at: new Date(serverNowMs()).toISOString() })
      : { error: { code: "" } };
    if (error && !error.code) {
      await queueTransportDone(id);
      showNotice("Bez signálu — „Prevezené“ sa odošle samo, keď bude signál.");
    } else if (error) {
      console.error("mark_transport_note_driver_done zlyhalo", error);
      showNotice("„Prevezené“ sa nepodarilo odoslať — skontrolujte signál a skúste znova.");
      return;
    }
    setMyTransportNotes((prev) => prev.filter((t) => t.id !== id));
  }
  // Prehľad pre dispečera/vedúceho — VŠETKY priradené a ešte nedokončené
  // poznámky Prevoz (tí majú na "transportNotes" plný RLS prístup, viď step44).
  const canManageTransportNotes = can(user, "machine_transport_note");
  const assignedTransportNotes = useMemo(() => {
    if (!canManageTransportNotes) return [];
    return (transportNotes || []).filter((t) => t.driverId && !t.driverDone);
  }, [transportNotes, canManageTransportNotes]);
  const [search, setSearch] = useState("");
  useEffect(() => {
    if (!highlightTransportId) return;
    document.getElementById(`transport-${highlightTransportId}`)?.scrollIntoView({ behavior: "smooth", block: "center" });
  }, [highlightTransportId]);
  const [depoFilter, setDepoFilter] = useState(null);
  // Podľa roly ÚČTU (nie karty zamestnanca) — šofér bez karty nevidí prepravy všetkých.
  const isMyselfSofer = user?.role === "sofer";
  // Externý šofér má toto NAVYŠE natvrdo uzamknuté — na rozdiel od bežného šoféra
  // (ten len má tento filter predvolený, ale vie si ho zmeniť), externý smie
  // vidieť VÝLUČNE svoje vlastné prepravy, nemá ako to obísť.
  // Zámok podľa roly ÚČTU — aj keď záznam zamestnanca chýba alebo má inú rolu,
  // externý šofér nikdy neuvidí cudzie prepravy (bez prepojenia neuvidí nič).
  const isLockedExternalSofer = user?.role === "externy_sofer";
  const [driverFilter, setDriverFilterRaw] = useState(() => (isMyselfSofer ? myEmployee?.id || "__none__" : isLockedExternalSofer ? myEmployee?.id || "__none__" : ""));
  const setDriverFilter = isLockedExternalSofer ? () => {} : setDriverFilterRaw;
  const effectiveDriverFilter = isLockedExternalSofer ? myEmployee?.id || "__none__" : driverFilter;
  const depoOptions = DEPO_OPTIONS;

  const allTransports = useMemo(() => {
    const list = [];
    jobs.forEach((j) => {
      const hpForJob = (handoverProtocols || []).find((h) => h.jobId === j.id);
      // Osobný odber (vlastná doprava) — žiadny šofér, v zozname pre dispečera
      // zvlášť, kým ho checker neodovzdá zákazníkovi.
      if (j.selfPickup && j.status !== "completed" && !hpForJob?.handoverDone) {
        list.push({
          id: j.id + "-vyvoz", jobId: j.id, type: "vyvoz", self: true,
          date: j.departureDate || j.startDate, driverId: null, machineId: j.machineId,
          from: j.fromDepo || "—", to: j.fromDepo || "—", customer: j.customer,
          overdue: (j.departureDate || j.startDate) < today,
        });
      }
      // Vývoz — po ukončení zákazky už dávno prebehol, netreba ho ukazovať.
      // Vývoz sa zobrazuje podľa skutočného dátumu vývozu a kým neprebehlo
      // prevzatie (aj oneskorený) — staršie ako 14 dní bez protokolu sa už
      // neukazujú (zákazky spred zavedenia protokolov).
      const depDate = j.departureDate || j.startDate;
      // R2: staré vývozy len bez prevzatia — so šoférom 14 dní, bez šoféra 30 dní po termíne.
      if (!j.selfPickup && j.status !== "completed" && (depDate >= today || (!hpForJob?.handoverDone && depDate >= addDaysISO(today, j.driverId ? -14 : -30)))) {
        list.push({
          id: j.id + "-vyvoz",
          jobId: j.id,
          type: "vyvoz",
          date: j.departureDate || j.startDate,
          driverId: j.driverId || null,
          machineId: j.machineId,
          from: j.fromDepo || "—",
          to: j.toLocation || "—",
          customer: j.customer,
          customerPhone: j.customerPhone,
          dispatcher: jobDispatcher?.(j) || null,
          site: j.toLocation,
          issue: j.transportIssueNote,
          overdue: (j.departureDate || j.startDate) < today,
        });
      }
      // Zvoz — viditeľný a akcieschopný výlučne po reálnom ukončení zákazky
      // ("Ukončiť zákazku"), nikdy podľa dátumu ani podľa toho, či je vopred
      // priradený šofér. Ak dispečer ukončenie zruší (vráti zákazku do aktívneho
      // stavu), zvoz sa má hneď stratiť rovnako ako vývoz — vrátenie stroja
      // koncepčne nedáva zmysel riešiť na zákazke, ktorá nie je ukončená.
      if (j.endDate && j.status === "completed" && !j.notRealized) {
        const hp = (handoverProtocols || []).find((h) => h.jobId === j.id);
        const returnDone = hp?.returnDone;
        // Rovnako ako vývoz: zvoz starší ako 14 dní bez protokolu sa už neukazuje.
        if (!returnDone && (j.pickupDate || j.endDate) >= addDaysISO(today, !j.selfReturn && !j.returnDriverId ? -30 : -14)) {
          list.push({
            id: j.id + "-zvoz",
            jobId: j.id,
            type: "zvoz",
            self: !!j.selfReturn,
            date: j.pickupDate || j.endDate,
            driverId: j.returnDriverId || null,
            machineId: j.machineId,
            from: j.toLocation || "—",
            to: j.returnDepo || j.fromDepo || "—",
            customer: j.customer,
            customerPhone: j.customerPhone,
            dispatcher: jobDispatcher?.(j) || null,
            site: j.toLocation,
            issue: j.transportIssueNote,
            overdue: (j.pickupDate || j.endDate) < today,
          });
        }
      }
    });
    return list.sort((a, b) => (a.date < b.date ? -1 : 1));
  }, [jobs, today, handoverProtocols, jobDispatcher]); // eslint-disable-line react-hooks/exhaustive-deps
  const transports = useMemo(() => allTransports.filter((t) => !t.self), [allTransports]);
  const selfTransports = allTransports.filter((t) => t.self);

  function matchesDepoAndSearch(t) {
    if (depoFilter && t.from.toLowerCase() !== depoFilter.toLowerCase() && t.to.toLowerCase() !== depoFilter.toLowerCase()) {
      return false;
    }
    if (search.trim()) {
      const q = search.toLowerCase();
      const m = machineById[t.machineId];
      const hit =
        (m?.code || "").toLowerCase().includes(q) ||
        (m?.type || "").toLowerCase().includes(q) ||
        t.from.toLowerCase().includes(q) ||
        t.to.toLowerCase().includes(q) ||
        (t.customer || "").toLowerCase().includes(q);
      if (!hit) return false;
    }
    return true;
  }

  // Rýchly prehľad dnes/zajtra/pozajtra teraz rešpektuje rovnaké filtre depa
  // a hľadania, čo sú nižšie nad zoznamom (filter na šoféra ostáva samostatný,
  // ten sa už rieši cez summaryDriverIds).
  // Dni prehľadu: dnes + 2 najbližšie pracovné dni; sobota/nedeľa len ak je na ňu preprava.
  const summaryDays = useMemo(() => {
    const days = [today];
    let d = today;
    let work = 0;
    while (work < 2) {
      d = addDaysISO(d, 1);
      const wd = new Date(`${d}T12:00:00`).getDay();
      if (wd !== 0 && wd !== 6) { days.push(d); work++; }
      else if (transports.some((t) => t.date === d && matchesDepoAndSearch(t))) days.push(d);
    }
    return days;
  }, [transports, today, depoFilter, search]);
  const summary = useMemo(() => {
    const map = {};
    transports.forEach((t) => {
      if (!summaryDays.includes(t.date)) return;
      if (!matchesDepoAndSearch(t)) return;
      const key = t.driverId || "unassigned";
      if (!map[key]) map[key] = {};
      if (!map[key][t.date]) map[key][t.date] = { vyvoz: 0, zvoz: 0 };
      map[key][t.date][t.type === "vyvoz" ? "vyvoz" : "zvoz"] += 1;
    });
    return map;
  }, [transports, summaryDays, depoFilter, search]);
  // Aj šofér, ktorému všetky prepravy dňa odpadli, ale mail už dostal — treba mu dať vedieť.
  const sentButGone = (dId) => summaryDays.some((d) => getTransportSendStatus?.(dId, d, []).newCount > 0);
  const summaryDriverIds = [
    ...drivers.filter((d) => !d.archived && (summary[d.id] || sentButGone(d.id))).map((d) => d.id),
    ...(summary.unassigned ? ["unassigned"] : []),
  ].filter((key) => !effectiveDriverFilter || key === effectiveDriverFilter);

  let filtered = transports;
  if (effectiveDriverFilter) filtered = filtered.filter((t) => (effectiveDriverFilter === "unassigned" ? !t.driverId : t.driverId === effectiveDriverFilter));
  if (depoFilter) {
    filtered = filtered.filter(
      (t) => t.from.toLowerCase() === depoFilter.toLowerCase() || t.to.toLowerCase() === depoFilter.toLowerCase()
    );
  }
  if (search.trim()) {
    const q = search.toLowerCase();
    filtered = filtered.filter((t) => {
      const m = machineById[t.machineId];
      return (
        (m?.code || "").toLowerCase().includes(q) ||
        (m?.type || "").toLowerCase().includes(q) ||
        t.from.toLowerCase().includes(q) ||
        t.to.toLowerCase().includes(q) ||
        (t.customer || "").toLowerCase().includes(q)
      );
    });
  }

  // Šofér nepotrebuje dispečerský hustý zoznam (vyhľadávanie, depo filtre, rýchly
  // prehľad, priraďovanie) — vidí len svoje vlastné prepravy, zoskupené podľa dňa,
  // ako veľké karty s jasnou akciou.
  if (isMyselfSofer || isLockedExternalSofer) {
    return (
      <DriverTransportsList
        dnes={dnes}
        unsavedProtocols={unsavedProtocols}
        items={filtered}
        doneZvozCount={dnes ? jobs.filter((j) => j.returnDriverId && j.returnDriverId === effectiveDriverFilter && (handoverProtocols || []).some((h) => h.jobId === j.id && h.returnDone && String(h.returnDate || "").slice(0, 10) === today)).length : 0}
        machineById={machineById}
        handoverProtocols={handoverProtocols}
        onOpenJob={onOpenJob}
        today={today}
        tomorrow={tomorrow}
        highlightTransportId={highlightTransportId}
        onDismissTransportHighlight={onDismissTransportHighlight}
        myTransportNotes={myTransportNotes}
        onMarkTransportNoteDriverDone={handleMarkTransportNoteDriverDone}
        onReportIssue={can(user, "transport_issue_report") ? onReportTransportIssue : null}
      />
    );
  }

  // Checker = komu je kontrola naozaj pridelená; bez úlohy podľa depa a dňa.
  function checkerIdOf(t) {
    const insp = (assignments || []).find((a) => a.kind === "kontrolaStroja" && a.jobId === t.jobId && (a.phase === "vratenie") === (t.type !== "vyvoz"));
    return insp?.technicianId || resolveCheckerId(depoCheckers, checkerSubstitutions, t.type === "vyvoz" ? t.from : t.to, t.date);
  }
  function transportLine(t) {
    const machine = machineById[t.machineId];
    const isVyvoz = t.type === "vyvoz";
    const highlighted = t.id === highlightTransportId;
    const checkerId = checkerIdOf(t);
    const checker = checkerId ? technicianById?.[checkerId] : null;
    const hp = handoverProtocols.find((h) => h.jobId === t.jobId);
    const showProtocol = (hp || can(user, "handover_protocol_write")) && (!hp || can(user, "handover_protocol_write") || can(user, "handover_protocol_edit_locked"));
    // Vývoz sleduje handoverDone (fáza prevzatia), zvoz sleduje returnDone
    // (fáza vrátenia) — každá karta len svoju vlastnú fázu, nie tú druhú.
    const protocol = isVyvoz ? (!hp ? ["", "Bez protokolu"] : ["spill-done", "Hotovo"]) : !hp?.returnDone ? ["spill-wait", "Čaká na vrátenie"] : ["spill-done", "Hotovo"];
    return (
      <div
        key={t.id}
        id={`transport-${t.id}`}
        className={`tr-row${t.overdue ? " row-problem" : ""}`}
        onClick={() => {
          if (highlighted) onDismissTransportHighlight?.();
          onOpenJob && onOpenJob(t.jobId, t.type);
        }}
        style={{
          cursor: onOpenJob ? "pointer" : "default",
          outline: highlighted ? "2px solid var(--accent)" : "none",
          boxShadow: highlighted ? "0 0 0 4px var(--accent-light)" : "none",
          transition: "box-shadow .3s, outline .3s",
        }}
      >
        <span style={{ fontWeight: 700 }}>{isVyvoz ? "VÝVOZ" : "ZVOZ"}</span>
        <span style={{ minWidth: 0 }}>
          <strong className="tnum">{machine?.code || "—"}</strong>{t.customer ? ` · ${t.customer}` : ""}
          <span className="cell-sub" style={{ display: "block" }}>{t.from} → {t.to}</span>
          <span className="cell-sub" style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
            {/* v1.0.805: dátum len raz — kto ho smie meniť, vidí len pole. */}
            {!can(user, "transport_assign_driver") && <span className="tnum" style={{ color: t.overdue ? "var(--danger-text)" : undefined, fontWeight: t.overdue ? 600 : undefined }}>{fmtDate(t.date)}</span>}
            {can(user, "transport_assign_driver") && (
              <TransportDateInput
                date={t.date}
                onSave={(d) => onSetTransportDate && onSetTransportDate(t.jobId, t.type, d)}
                check={(d) => onCheckTransportDate?.(t.jobId, t.type, d)}
                title={isVyvoz ? "Zmeniť skutočný dátum vývozu" : "Zmeniť skutočný dátum zvozu"}
              />
            )}
            <span title={`Depo: ${isVyvoz ? t.from : t.to}`}>Checker {isVyvoz ? "(vývoz)" : "(zvoz)"}: {checker ? checker.name : "— nenastavené pre toto depo —"}</span>
          </span>
        </span>
        <div onClick={(e) => e.stopPropagation()}>
          {can(user, "transport_assign_driver") ? (
            <select
              aria-label="Šofér"
              value={t.driverId || ""}
              onChange={(e) => (isVyvoz ? assignDriver(t.jobId, e.target.value) : assignReturnDriver(t.jobId, e.target.value))}
              className={t.driverId ? undefined : "tr-assign"}
            >
              <option value="">{t.driverId ? "— neurčený —" : "Prideliť šoféra…"}</option>
              {driverOptionsGrouped(drivers)}
            </select>
          ) : (
            <span style={{ color: t.driverId ? undefined : "var(--text-dim)" }}>{t.driverId ? drivers.find((d) => d.id === t.driverId)?.name : "— neurčený —"}</span>
          )}
        </div>
        <span style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          {t.overdue && <span className="spill spill-overdue">⚠ Po termíne</span>}
          {!t.driverId && <span className="spill spill-problem">Bez šoféra</span>}
          {showProtocol && <span className={`spill ${protocol[0]}`}>{protocol[1]}</span>}
        </span>
      </div>
    );
  }

  const filterDesc = [depoFilter && `depo ${depoFilter}`, driverFilter && `šofér ${driverFilter === "unassigned" ? "Nepridelené" : drivers.find((d) => d.id === driverFilter)?.name || ""}`, search.trim() && `„${search.trim()}“`].filter(Boolean).join(", ");
  const clearFilters = () => { setDepoFilter(null); setDriverFilter(""); setSearch(""); };
  const dayLabel = (d) => {
    const dt = new Date(`${d}T12:00:00`);
    const base = `${dt.toLocaleDateString("sk-SK", { weekday: "long" })} ${dt.getDate()}. ${dt.getMonth() + 1}.`;
    return d === today ? `Dnes · ${base}` : d === tomorrow ? `Zajtra · ${base}` : d < today ? `⚠ Po termíne · ${base}` : base;
  };
  const dayKeys = [...new Set([today, tomorrow, ...filtered.map((t) => t.date)])].sort();

  return (
    <div>
      {selfTransports.length > 0 && (
        <div className="panel" style={{ padding: 14, marginBottom: 14 }}>
          <div style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 8 }}>
            🏢 Osobný odber / vrátenie v depe (vlastná doprava — rieši checker)
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {selfTransports.map((t) => {
              const m = machineById[t.machineId];
              return (
                <div
                  key={t.id}
                  onClick={() => onOpenJob && onOpenJob(t.jobId, t.type)}
                  style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", fontSize: 12, cursor: onOpenJob ? "pointer" : "default" }}
                >
                  <span className={`badge ${t.type === "vyvoz" ? "badge-info" : "badge-warn"}`} style={{ minWidth: 70, textAlign: "center" }}>
                    {t.type === "vyvoz" ? "Odber" : "Vrátenie"}
                  </span>
                  {!can(user, "transport_assign_driver") && <span className="mono" style={{ fontWeight: 600, color: t.overdue ? "var(--danger)" : "inherit" }}>{fmtDate(t.date)}</span>}
                  {can(user, "transport_assign_driver") && (
                    <TransportDateInput
                      date={t.date}
                      onSave={(d) => onSetTransportDate && onSetTransportDate(t.jobId, t.type, d)}
                      check={(d) => onCheckTransportDate?.(t.jobId, t.type, d)}
                      title="Zmeniť dátum — kontrola checkera sa presunie spolu s ním"
                    />
                  )}
                  {t.overdue && <span className="badge badge-danger" style={{ fontSize: 11 }}>Po termíne</span>}
                  <span className="mono">{m?.code || "—"}</span>
                  <span>depo {t.type === "vyvoz" ? t.from : t.to}</span>
                  {t.customer && <span style={{ color: "var(--text-dim)" }}>· {t.customer}</span>}
                </div>
              );
            })}
          </div>
        </div>
      )}
      {assignedTransportNotes.length > 0 && (
        <div className="panel" style={{ padding: 14, marginBottom: 14 }}>
          <div style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 8 }}>
            🚚 Prevozy priradené šoférom (čakajú na potvrdenie)
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {assignedTransportNotes.map((t) => {
              const m = machineById[t.machineId];
              const driver = (drivers || []).find((d) => d.id === t.driverId);
              return (
                <div key={t.id} style={{ fontSize: 12, color: "var(--text-dim)" }}>
                  {m?.code || "—"} → {t.targetDepo} · šofér: {driver?.name || "—"} · čaká na šoféra
                </div>
              );
            })}
          </div>
        </div>
      )}
      <div style={{ display: "flex", gap: 10, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
        <SearchInput placeholder="Hľadať stroj, zákazníka…" value={search} onChange={setSearch} style={{ minWidth: 260 }} />
        <div className="tr-filt2">
        {isLockedExternalSofer ? (
          <div style={{ fontSize: 13, fontWeight: 600, color: "var(--text-dim)" }}>Vaše prepravy: {myEmployee.name}</div>
        ) : (
          <select aria-label="Šofér" value={driverFilter} onChange={(e) => setDriverFilter(e.target.value)} style={{ minWidth: 200, minHeight: 40 }}>
            <option value="">— všetci šoféri —</option>
            <option value="unassigned">Nepridelené</option>
            {driverOptionsGrouped(drivers)}
          </select>
        )}
        <select aria-label="Depo" value={depoFilter || ""} onChange={(e) => setDepoFilter(e.target.value || null)} style={{ minHeight: 40 }}>
          <option value="">Všetky depá</option>
          {depoOptions.map((d) => <option key={d} value={d}>{d}</option>)}
        </select>
        </div>
        {depoFilter && <span className="fchip">Filter: depo {depoFilter}<button type="button" className="fchip-x" aria-label="Zrušiť filter depa" onClick={() => setDepoFilter(null)}>×</button></span>}
        {driverFilter && !isLockedExternalSofer && <span className="fchip">Filter: šofér {driverFilter === "unassigned" ? "Nepridelené" : drivers.find((d) => d.id === driverFilter)?.name}<button type="button" className="fchip-x" aria-label="Zrušiť filter šoféra" onClick={() => setDriverFilter("")}>×</button></span>}
      </div>

      {summaryDriverIds.length > 0 && (
        <div className="panel" style={{ padding: 14, marginBottom: 14, overflowX: "auto" }}>
          <div style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 8 }}>
            Rýchly prehľad — dnes a 2 pracovné dni{effectiveDriverFilter ? " (len vybraný šofér)" : ""} · ↑ vývoz · ↓ zvoz
          </div>
          {/* Mobil: 3 dlaždice (dnes a 2 pracovné dni) namiesto tabuľky, ktorej stĺpce sa nezmestia. */}
          <div className="qs-tiles">
            {summaryDays.map((d) => {
              const c = summaryDriverIds.reduce((a, k) => ({ v: a.v + (summary[k]?.[d]?.vyvoz || 0), z: a.z + (summary[k]?.[d]?.zvoz || 0) }), { v: 0, z: 0 });
              const un = summaryDriverIds.includes("unassigned") ? (summary.unassigned?.[d]?.vyvoz || 0) + (summary.unassigned?.[d]?.zvoz || 0) : 0;
              const go = () => (un ? transports.filter((t) => !t.driverId && t.date === d && matchesDepoAndSearch(t)).map((t) => `transport-${t.id}`) : [`tr-day-${d}`]).reverse().forEach(flashById);
              return (
                <button key={d} type="button" className={`qs-tile${un ? " red" : ""}`} onClick={go}>
                  <b>{dayHead(d)}</b>
                  <span className="qs-tile-n tnum"><span className={c.v ? "" : "qs-n"}>↑{c.v}</span> <span className={c.z ? "" : "qs-n"}>↓{c.z}</span></span>
                  <span className="qs-tile-s">{un ? `${un} bez šoféra` : c.v + c.z ? "všetko pridelené" : "bez prepráv"}</span>
                </button>
              );
            })}
          </div>
          <table className="qs-table qs-wide">
            <thead>
              <tr>
                <th>Šofér</th>
                {summaryDays.map((d) => <th key={d} colSpan={2}>{dayHead(d)}</th>)}
              </tr>
            </thead>
            <tbody>
              {summaryDriverIds.map((key) => {
                const driver = key === "unassigned" ? null : drivers.find((d) => d.id === key);
                // Klik na číslo posunie na príslušné karty a zvýrazní ich (ako dlaždice na Dnes).
                const cellClick = (dateVal, type) => {
                  const ids = transports.filter((t) => (key === "unassigned" ? !t.driverId : t.driverId === key) && t.date === dateVal && t.type === type && matchesDepoAndSearch(t)).map((t) => `transport-${t.id}`);
                  ids.reverse().forEach(flashById);
                };

                function sendCell(dateVal) {
                  const ids = transports.filter((t) => t.driverId === key && t.date === dateVal).map((t) => t.id);
                  const status = driver ? getTransportSendStatus(driver.id, dateVal, ids) : null;
                  // Nič na ten deň a nič neodoslané → bez tlačidla; odoslané a všetko odpadlo → treba dať vedieť.
                  if (!driver || (ids.length === 0 && !(status?.sent && status.newCount > 0))) return null;
                  if (!can(user, "transport_assign_driver")) {
                    return <span style={{ color: "var(--text-dim)", fontSize: 11 }}>{status.sent ? "odoslané" : ""}</span>;
                  }
                  return (
                    <button
                      className="btn btn-ghost qs-send-btn"
                      style={{ color: status.sent && !status.newCount ? "var(--ok)" : "var(--text)" }}
                      title={!driver.email ? "Šofér nemá vyplnený email v karte — adresu doplníte priamo v maile" : ""}
                      onClick={() => {
                        const items = transports.filter((t) => t.driverId === driver.id && t.date === dateVal);
                        const checkerEmails = new Set();
                        const lines = items.map((t) => {
                          const m = machineById[t.machineId];
                          const kind = t.type === "vyvoz" ? "VÝVOZ" : "ZVOZ";
                          const checkerId = checkerIdOf(t);
                          const checker = checkerId ? technicianById?.[checkerId] : null;
                          if (checker) checkerEmails.add(checker.email || nameToEmail(checker.name));
                          return `${kind}: ${m?.code || "—"} — ${t.from} → ${t.to}${t.customer ? " (" + t.customer + ")" : ""}${checker ? ` · checker: ${checker.name}` : ""}`;
                        });
                        const dayWord = dateVal === today ? "dnes" : dayLong(dateVal);
                        const body = lines.length
                          ? `Dobrý deň, ${driver.name},\n\nna ${dayWord} (${fmtDate(dateVal)}) máte naplánované tieto prepravy:\n\n${lines.join("\n")}\n\nĎakujeme.`
                          : `Dobrý deň, ${driver.name},\n\nna ${dayWord} (${fmtDate(dateVal)}) už nemáte naplánované žiadne prepravy — predchádzajúci zoznam neplatí.\n\nĎakujeme.`;
                        const toAll = [driver.email || (driver.role === "externy_sofer" ? "" : nameToEmail(driver.name)), ...checkerEmails].filter(Boolean).join(MAILTO_SEP);
                        composeMail({ to: toAll, subject: `Prepravy na ${dayWord} ${fmtDate(dateVal)}`, body });
                        recordTransportSend(driver.id, dateVal, items.map((t) => t.id));
                      }}
                    >
                      {!status.sent
                        ? <><MailIcon size={14} /> Odoslať</>
                        : status.newCount > 0
                        ? <><MailIcon size={14} /> Odoslať znova (zmeny: {status.newCount})</>
                        : `✓ Odoslané ${sentWhen(status.sentAt)}`}
                    </button>
                  );
                }

                // v1.0.805: nuly sivo, nenulové tučne; „Odoslať“ v samostatnom stĺpci s pevnou šírkou.
                const num = (dateVal, type, n) => (
                  <span
                    className={`tnum qs-n${n ? " on" : ""}`}
                    style={{ cursor: n ? "pointer" : "default", textDecoration: n ? "underline" : "none" }}
                    onClick={() => n && cellClick(dateVal, type, `${type === "vyvoz" ? "Vývoz" : "Zvoz"} ${dateVal === today ? "dnes" : dayHead(dateVal)}`)}
                  >
                    {n || "—"}{n ? (type === "vyvoz" ? " ↑" : " ↓") : ""}
                  </span>
                );
                return (
                  <tr key={key}>
                    <td style={{ fontWeight: 600 }}>{driver ? driver.name : "Nepridelené"}</td>
                    {summaryDays.map((d) => {
                      const c = summary[key]?.[d] || { vyvoz: 0, zvoz: 0 };
                      return (
                        <React.Fragment key={d}>
                          <td style={{ whiteSpace: "nowrap" }}>{c.vyvoz || c.zvoz ? <>{num(d, "vyvoz", c.vyvoz)} · {num(d, "zvoz", c.zvoz)}</> : <span className="qs-n">—</span>}</td>
                          <td className="qs-send">{sendCell(d)}</td>
                        </React.Fragment>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {dayKeys.map((d) => {
        const items = filtered.filter((t) => t.date === d);
        return (
          <section key={d}>
            <h2 id={`tr-day-${d}`} className={`day-sec${d < today ? " red" : ""}`}>{dayLabel(d)} · {items.length}</h2>
            {items.length === 0 ? (
              <div className="panel" style={{ boxShadow: "none", border: "1px dashed var(--line-strong)", borderRadius: 12, padding: "14px 20px", color: "var(--text-dim)" }}>
                {filterDesc ? <>Žiadne prepravy nezodpovedajú filtru ({filterDesc}). <button type="button" className="btn btn-outline" style={{ marginLeft: 8 }} onClick={clearFilters}>Zrušiť filter</button></> : "Žiadne prepravy."}
              </div>
            ) : (
              <div className="panel" style={{ boxShadow: "none", borderRadius: 12, overflow: "hidden" }}>{items.map(transportLine)}</div>
            )}
          </section>
        );
      })}
    </div>
  );
}

/* ---------------------------------------------------------
   Drivers view
--------------------------------------------------------- */
/* ---------------------------------------------------------
   Administratíva — jednotný zoznam osôb (technici, šoféri, obchodníci,
   dispečeri...), viditeľné len pre vedúceho požičovne/servisu a admina.
   Každý vidí a spravuje len role z vlastnej oblasti (okrem admina).
--------------------------------------------------------- */
// Rola účtu ≠ rola jeho karty (Zamestnanci, Stav platformy). Admin účet môže mať kartu inej roly zámerne.
const accountRoleDiffers = (p, e) => !!p && !!e && !isAdminUser(p) && p.role !== e.role;
function AdministrativaView({ employees, profiles, user, onAdd, onEdit, onArchive, onDelete, onOpenUser }) {
  const [showArchived, setShowArchived] = useState(false);
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState("");
  const [depoFilter, setDepoFilter] = useState("");
  const manageableRoles = manageableEmployeeRoles(user);
  const q = search.trim().toLowerCase();
  const mine = employees.filter((e) => manageableRoles.includes(e.role) && (showArchived || !e.archived));
  const depoOptions = [...new Set(mine.map((e) => e.depo).filter(Boolean))].sort((a, b) => a.localeCompare(b, "sk"));
  const visible = mine.filter(
    (e) => (!q || e.name.toLowerCase().includes(q)) && (!roleFilter || e.role === roleFilter) && (!depoFilter || e.depo === depoFilter)
  );
  const profileById = Object.fromEntries(profiles.map((p) => [p.id, p]));

  // Kontrola duplicitných zamestnancov — rovnaké meno (bez ohľadu na veľkosť
  // písmen) medzi aktívnymi (nearchivovanými) záznamami. Nič sa neblokuje, len
  // upozorní — napr. presne situácia, čo raz vznikla pri chybnej migrácii.
  const nameCounts = {};
  const nameDisplay = {};
  employees.forEach((e) => {
    if (e.archived) return;
    const key = e.name.trim().toLowerCase();
    if (!key) return;
    nameCounts[key] = (nameCounts[key] || 0) + 1;
    if (!nameDisplay[key]) nameDisplay[key] = e.name.trim();
  });
  const duplicateKeys = Object.keys(nameCounts).filter((k) => nameCounts[k] > 1);

  return (
    <div>
      <h1 className="page-h1">Zamestnanci</h1>
      <p className="page-intro who-hide-mobile">
        Zoznam zamestnancov — odtiaľto platforma ťahá zoznamy technikov, šoférov a obchodníkov na
        ostatných miestach. Vidíte a spravujete len role z vlastnej oblasti.
      </p>
      {duplicateKeys.length > 0 && (
        <div style={{ background: "var(--warn-bg)", border: "1px solid var(--warn)", color: "var(--warn)", borderRadius: 8, padding: "10px 14px", marginBottom: 14, fontSize: 13 }}>
          ⚠ Duplicitný záznam — {duplicateKeys.map((k) => `"${nameDisplay[k]}" (${nameCounts[k]}×)`).join(", ")}. Skontrolujte nižšie (označené) a jeden zo záznamov zmažte.
        </div>
      )}
      <div className="tbar">
        <SearchInput placeholder="Hľadať zamestnanca…" value={search} onChange={setSearch} style={{ minWidth: 260 }} />
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 14 }}>
          <input type="checkbox" checked={showArchived} onChange={(e) => setShowArchived(e.target.checked)} />
          Zobraziť archivovaných
        </label>
        <select aria-label="Rola" value={roleFilter} onChange={(e) => setRoleFilter(e.target.value)} style={{ minHeight: 40 }}>
          <option value="">Všetky roly</option>
          {ROLES.filter((r) => manageableRoles.includes(r.id)).map((r) => <option key={r.id} value={r.id}>{r.label}</option>)}
        </select>
        <select aria-label="Depo" value={depoFilter} onChange={(e) => setDepoFilter(e.target.value)} style={{ minHeight: 40 }}>
          <option value="">Všetky depá</option>
          {depoOptions.map((d) => <option key={d} value={d}>{d}</option>)}
        </select>
        <button className="btn btn-accent" style={{ marginLeft: "auto" }} onClick={onAdd}>+ Pridať zamestnanca</button>
      </div>
      <div className="panel jobs-wrap" style={{ boxShadow: "none", borderRadius: 12 }}>
      <table className="table-cards jobs-table dense">
        <thead>
          <tr>
            <th>Meno</th>
            <th>Rola</th>
            <th>Depo</th>
            <th>Telefón</th>
            <th>Email</th>
            <th>Prepojený účet</th>
            {showArchived && <th>Stav</th>}
            <th><span className="sr-only">Akcie</span></th>
          </tr>
        </thead>
        <tbody>
          {visible.length === 0 && (
            <tr><td className="td-plain" colSpan={showArchived ? 8 : 7} style={{ textAlign: "center", padding: 30, color: "var(--text-dim)" }}>{roleFilter || depoFilter || q ? "Žiadny zamestnanec nezodpovedá filtru." : "Zatiaľ žiadni zamestnanci."}</td></tr>
          )}
          {visible.map((e) => {
            const linkedProfile = e.linkedUserId ? profileById[e.linkedUserId] : null;
            const isDuplicate = !e.archived && duplicateKeys.includes(e.name.trim().toLowerCase());
            const statusPill = e.archived ? <span className="spill">Archivovaný</span> : <span className="spill spill-done">Aktívny</span>;
            return (
              <tr key={e.id} id={"emp-row-" + e.id} style={isDuplicate ? { background: "var(--warn-bg)", color: "var(--text)" } : undefined}>
                <td className="td-plain">
                  <span style={{ display: "flex", alignItems: "center", gap: 8, justifyContent: "space-between" }}>
                    <span style={{ fontWeight: 600 }}>
                      {e.name}
                      {isDuplicate && (
                        <span style={{ marginLeft: 6, fontSize: 13, fontWeight: 700, color: "var(--warn)" }} title="Rovnaké meno má aj iný aktívny záznam">
                          ⚠ duplicita
                        </span>
                      )}
                    </span>
                    {showArchived && <span className="m-only">{statusPill}</span>}
                  </span>
                  <div className="cell-sub m-only">{[roleLabel(e.role), e.depo].filter(Boolean).join(" · ")}</div>
                  {!e.archived && accountRoleDiffers(linkedProfile, e) && <span className="spill spill-warn m-only" style={{ marginLeft: 6 }}>rola účtu: {roleLabel(linkedProfile.role)}</span>}
                </td>
                <td data-label="Rola" className="who-hide-mobile">{roleLabel(e.role)}{e.alsoObchodnik && <span className="spill spill-active" style={{ marginLeft: 6 }}>aj obchodník</span>}{e.alsoEzTechnik && <span className="spill spill-active" style={{ marginLeft: 6 }}>EZ technik</span>}{e.alsoVeduciDispecer && <span className="spill spill-active" style={{ marginLeft: 6 }}>vedúci dispečer</span>}</td>
                <td data-label="Depo" className="who-hide-mobile">{e.depo || "—"}</td>
                <td data-label="Telefón" className="tnum">{e.phone || <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                <td data-label="Email" className="who-hide-mobile">{e.email || <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                <td data-label="Prepojený účet" className="who-hide-mobile">
                  {linkedProfile ? (
                    onOpenUser ? <button type="button" className="btn-link" title="Otvoriť v Správe používateľov" onClick={() => onOpenUser(linkedProfile)}>✓ {linkedProfile.name}</button> : <span>✓ {linkedProfile.name}</span>
                  ) : (
                    <span className="spill spill-wait">Nepriradený</span>
                  )}
                  {!e.archived && accountRoleDiffers(linkedProfile, e) && <span className="spill spill-warn" style={{ marginLeft: 6 }} title="Rola prihlasovacieho účtu sa líši od roly tejto karty">rola účtu: {roleLabel(linkedProfile.role)}</span>}
                </td>
                {showArchived && <td data-label="Stav" className="who-hide-mobile">{statusPill}</td>}
                <td className="td-actions" style={{ textAlign: "right" }}>
                  <KebabMenu
                    label="⋯"
                    name="Ďalšie akcie"
                    actions={[
                      { label: "Upraviť", onClick: () => onEdit(e) },
                      { label: e.archived ? "Aktivovať" : "Archivovať", onClick: () => onArchive(e) },
                      isAdminUser(user) && { label: "Zmazať", onClick: () => onDelete(e.id), danger: true },
                    ]}
                  />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      </div>
    </div>
  );
}

// Firma externého šoféra — výber zo Zákazníkov alebo nová firma (uloží sa aj do Zákazníkov).
// Podobní zákazníci: rovnaké IČO alebo názov bez diakritiky, právnej formy a interpunkcie (jeden obsahuje druhý).
const custKey = (x) => (x || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
  .replace(/\b(spol|s\.?\s*r\.?\s*o|a\.?\s*s|k\.?\s*s|v\.?\s*o\.?\s*s|sro|as|ks|vos)\b\.?/g, " ").replace(/[^a-z0-9]+/g, "");
// Podobný (nie presne zhodný) existujúci zákazník — upozorniť, inak vznikne duplicita. Uloženie neblokuje.
function SimilarCustomerNote({ customers, value, selectedId, onUse }) {
  const v = (value || "").trim();
  if (selectedId || !v || (customers || []).some((c) => (c.firma || "").trim().toLowerCase() === v.toLowerCase())) return null;
  const list = similarCustomers(customers, v);
  if (!list.length) return null;
  return (
    <div role="alert" className="fnote fnote-y" style={{ marginTop: 6 }}>
      <strong>Podobný zákazník už existuje — nie je to ten istý?</strong>
      {list.map((c) => (
        <div key={c.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, marginTop: 6 }}>
          <span>{c.firma}{c.ico ? ` · IČO ${c.ico}` : ""}</span>
          <button type="button" className="btn btn-outline" style={{ minHeight: 36 }} onClick={() => onUse(c)}>Použiť ho</button>
        </div>
      ))}
    </div>
  );
}
const icoKey = (v) => String(v || "").replace(/\s+/g, "").toUpperCase();
function similarCustomers(customers, firma, ico) {
  const k = custKey(firma), i = icoKey(ico);
  return (customers || []).filter((c) => (i && icoKey(c.ico) === i)
    || (k.length >= 3 && custKey(c.firma) && (custKey(c.firma) === k || (Math.min(k.length, custKey(c.firma).length) >= 5 && (custKey(c.firma).includes(k) || k.includes(custKey(c.firma))))))).slice(0, 5);
}
function CarrierPickModal({ customers, onPick, onClose }) {
  const [q, setQ] = useState("");
  const [newName, setNewName] = useState("");
  const [newIco, setNewIco] = useState("");
  const low = (x) => (x || "").trim().toLowerCase();
  const hits = q.trim() ? customers.filter((c) => low(c.firma).includes(low(q)) || (c.ico || "").includes(q.trim())).slice(0, 8) : [];
  return (
    <Modal title="Firma externého šoféra" onClose={onClose} elevated>
      <Field label="Hľadať v Zákazníkoch (názov alebo IČO)"><input autoFocus value={q} onChange={(e) => setQ(e.target.value)} style={{ width: "100%" }} /></Field>
      {hits.length > 0 && (
        <div className="flist">
          {hits.map((c) => (
            <button key={c.id} type="button" onClick={() => onPick({ id: c.id, name: c.firma })}>
              <b>{c.firma}</b>{c.ico && <small className="tnum">IČO {c.ico}</small>}
            </button>
          ))}
        </div>
      )}
      {q.trim() && !hits.length && <div className="fhint" style={{ marginTop: -6, marginBottom: 8 }}>Nenašla sa — pridajte ju nižšie.</div>}
      <div className="flegend">Alebo nová firma <span style={{ textTransform: "none", letterSpacing: 0, fontWeight: 500, color: "var(--text-dim)" }}>(uloží sa aj do Zákazníkov)</span></div>
      <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 12 }}>
        <Field label="Názov firmy"><input value={newName} onChange={(e) => setNewName(e.target.value)} style={{ width: "100%" }} /></Field>
        <Field label="IČO"><input value={newIco} onChange={(e) => setNewIco(e.target.value)} style={{ width: "100%" }} /></Field>
      </div>
      {newName.trim() && similarCustomers(customers, newName, newIco).map((c) => (
        <div key={c.id} className="fnote fnote-y" style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}>
          <span>⚠ Už existuje podobná: <b>{c.firma}</b>{c.ico ? ` · IČO ${c.ico}` : ""}</span>
          <button type="button" className="btn btn-outline" style={{ minHeight: 36 }} onClick={() => onPick({ id: c.id, name: c.firma })}>Použiť ju</button>
        </div>
      ))}
      <FormFoot cancel={false} confirm left={<button className="btn btn-outline" style={{ borderColor: "var(--line-strong)" }} onClick={() => onPick(null)}>Bez firmy</button>}>
        <button className="btn btn-accent" disabled={!newName.trim() || customers.some((c) => (c.firma || "").trim().toLowerCase() === newName.trim().toLowerCase())} onClick={() => onPick({ newName: newName.trim(), ico: newIco.trim() })}>Pridať firmu</button>
      </FormFoot>
    </Modal>
  );
}

function AddEmployeeModal({ existing, draft, canSetEz, assignableRoles, profiles = [], employees = [], customers = [], onAddCustomer, onClose, onSave }) {
  const init = draft ? { ...existing, ...draft } : existing; // po výpadku servera znova otvorené s rozpísaným
  // Prepojenie s prihlasovacím účtom priamo tu. Admin účty sa ponúkať nesmú —
  // prepojenie synchronizuje rolu a omylom by im prepísalo práva.
  const linkedElsewhere = new Set(employees.filter((e) => e.linkedUserId && e.id !== existing?.id).map((e) => e.linkedUserId));
  // Len nezaradené účty a účty z vlastnej oblasti (inak DB zmenu roly odmietne).
  const accountOptions = profiles.filter(
    (p) => !linkedElsewhere.has(p.id) && !isAdminUser(p) &&
      (p.role === "nezaradeny" || assignableRoles.some((r) => r.id === p.role) || p.id === existing?.linkedUserId)
  );
  const [linkedUserId, setLinkedUserId] = useState(init?.linkedUserId || "");
  const [name, setName] = useState(init?.name || "");
  const [role, setRole] = useState(init?.role || assignableRoles[0]?.id || "");
  const [depo, setDepo] = useState(init?.depo || "");
  const [phone, setPhone] = useState(init?.phone || "");
  const [email, setEmail] = useState(init?.email || "");
  const [skratka, setSkratka] = useState(init?.skratka || "");
  const [alsoObchodnik, setAlsoObchodnik] = useState(init?.alsoObchodnik || false);
  const [alsoEzTechnik, setAlsoEzTechnik] = useState(init?.alsoEzTechnik || false);
  const [alsoVeduciDispecer, setAlsoVeduciDispecer] = useState(init?.alsoVeduciDispecer || false);
  const [color, setColor] = useState(init?.color || "#2563EB");
  const [carrier, setCarrier] = useState(init?.carrierName ? { id: init.carrierCustomerId || null, name: init.carrierName } : null);
  const [pickCarrier, setPickCarrier] = useState(false);
  function pickedCarrier(c) {
    setPickCarrier(false);
    if (!c?.newName) return setCarrier(c);
    // Nová firma: ak už v Zákazníkoch je (rovnaký názov), použije sa tá; inak sa založí.
    const same = customers.find((x) => (x.firma || "").trim().toLowerCase() === c.newName.toLowerCase());
    // Nová firma sa do Zákazníkov zapíše až pri uložení karty (zrušené okno nezanechá osirelého zákazníka).
    setCarrier(same ? { id: same.id, name: same.firma } : { id: null, name: c.newName, ico: c.ico, isNew: true });
  }

  const canSave = name.trim() && role && depo.trim();
  const isSalesperson = role === "obchodnik" || alsoObchodnik;

  return (
    <Modal title={existing ? "Upraviť zamestnanca" : "Pridať zamestnanca"} onClose={onClose} xwide>
      <div className="job-form-cols">
        <fieldset>
          <legend>ZAMESTNANEC</legend>
          <Field label="Meno *"><input value={name} onChange={(e) => setName(e.target.value)} style={{ width: "100%" }} /></Field>
          <Field label="Rola *">
            <select value={role} onChange={(e) => { setRole(e.target.value); if (e.target.value === "externy_sofer" && !carrier) setPickCarrier(true); }} style={{ width: "100%" }}>
              {assignableRoles.map((r) => <option key={r.id} value={r.id}>{r.label}</option>)}
            </select>
          </Field>
          {role === "externy_sofer" && (
            <Field label="Firma (dopravca)">
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ flex: 1, fontSize: 15 }}>{carrier?.name || <span style={{ color: "var(--text-dim)" }}>— bez firmy —</span>}</span>
                <button className="btn btn-outline" style={{ borderColor: "var(--line-strong)" }} onClick={() => setPickCarrier(true)}>{carrier ? "Zmeniť" : "Vybrať firmu"}</button>
              </div>
            </Field>
          )}
          {pickCarrier && <CarrierPickModal customers={customers} onPick={pickedCarrier} onClose={() => setPickCarrier(false)} />}
          <div className="fgrid2">
            <Field label="Depo *">
              <select value={depo} onChange={(e) => setDepo(e.target.value)} style={{ width: "100%" }}>
                <option value="">— vybrať depo —</option>
                {DEPO_OPTIONS.map((d) => <option key={d} value={d}>{d}</option>)}
              </select>
            </Field>
            {role === "technik" && (
              <Field label="Skratka"><input value={skratka} onChange={(e) => setSkratka(e.target.value)} style={{ width: "100%" }} /></Field>
            )}
          </div>
        </fieldset>
        <fieldset>
          <legend>KONTAKT A PRIHLÁSENIE</legend>
          <div className="fgrid2">
            <Field label="Telefón"><input value={phone} onChange={(e) => setPhone(e.target.value)} style={{ width: "100%" }} /></Field>
            <Field label="Email"><input value={email} onChange={(e) => setEmail(e.target.value)} style={{ width: "100%" }} /></Field>
          </div>
          <Field label="Prihlasovací účet">
            <select value={linkedUserId} onChange={(e) => setLinkedUserId(e.target.value)} style={{ width: "100%" }}>
              <option value="">— nepriradený —</option>
              {accountOptions.map((p) => <option key={p.id} value={p.id}>{p.name}{p.email ? ` (${p.email})` : ""}</option>)}
            </select>
            <div className="fhint">
              Účet dostane rovnakú rolu ako zamestnanec — rozhoduje o tom, čo človek v platforme uvidí a môže robiť.
            </div>
          </Field>
          <div className="flegend" style={{ marginTop: 6 }}>ĎALŠIE ÚLOHY</div>
          {role !== "obchodnik" && (
            <label className="fck">
              <input type="checkbox" checked={alsoObchodnik} onChange={(e) => setAlsoObchodnik(e.target.checked)} />
              <span>Počítať aj ako obchodníka<small>objaví sa v zozname obchodníkov pri zákazkách/rezerváciách</small></span>
            </label>
          )}
          <label className="fck">
            <input type="checkbox" checked={alsoEzTechnik} disabled={!canSetEz} onChange={(e) => setAlsoEzTechnik(e.target.checked)} />
            <span>Revízny technik EZ<small>{canSetEz ? "vidí a spracúva frontu záznamov z merania VTZ EZ" : "nastavuje admin alebo vedúci servisu"}</small></span>
          </label>
          {DISPATCHER_ROLES.includes(role) && (
            <label className="fck">
              <input type="checkbox" checked={alsoVeduciDispecer} onChange={(e) => setAlsoVeduciDispecer(e.target.checked)} />
              <span>Vedúci dispečer<small>v Požičovni → Dispečeri nastavuje zástupy dispečerov; dostáva upozornenia „Prepravy bez šoféra“</small></span>
            </label>
          )}
          {isSalesperson && (
            <Field label="Farba v kalendári (voliteľné)">
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <input type="color" value={color} onChange={(e) => setColor(e.target.value)} style={{ width: 44, height: 32, padding: 2, border: "1px solid var(--border)", borderRadius: 4, cursor: "pointer" }} />
                <span className="fhint" style={{ marginTop: 0 }}>Použije sa pri jeho zákazkách/rezerváciách v Kalendári</span>
              </div>
            </Field>
          )}
        </fieldset>
      </div>
      <FormFoot missing={[!name.trim() && "meno", !role && "rola", !depo.trim() && "depo"].filter(Boolean)}>
      <button
        className="btn btn-accent"
        disabled={!canSave}
        onClick={() =>
          onSave({
            name: name.trim(),
            role,
            depo: depo.trim(),
            phone: phone.trim(),
            email: email.trim(),
            skratka: skratka.trim(),
            alsoObchodnik: role === "obchodnik" ? false : alsoObchodnik,
            alsoEzTechnik,
            alsoVeduciDispecer: DISPATCHER_ROLES.includes(role) ? alsoVeduciDispecer : false,
            color: isSalesperson ? color : (existing?.color || undefined),
            carrierCustomerId: role === "externy_sofer" ? (carrier?.isNew ? onAddCustomer({ firma: carrier.name, ico: carrier.ico }) : carrier?.id) || null : null,
            carrierName: role === "externy_sofer" ? carrier?.name || "" : "",
          }, linkedUserId || null)
        }
      >
        {existing ? "Uložiť zmeny" : "Uložiť"}
      </button>
      </FormFoot>
    </Modal>
  );
}

function DriversView({ drivers, jobs, today, vehicleByEmployeeId, onOpenCard }) {
  const [showArchived, setShowArchived] = useState(false);
  const visible = drivers.filter((d) => (showArchived ? true : !d.archived));
  return (
    <div>
      <div className="tbar" style={{ justifyContent: "flex-end" }}>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 14 }}>
          <input type="checkbox" checked={showArchived} onChange={(e) => setShowArchived(e.target.checked)} />
          Zobraziť archivovaných
        </label>
      </div>
      <div className="panel jobs-wrap" style={{ boxShadow: "none", borderRadius: 12 }}>
        <table className="table-cards jobs-table">
          <thead>
            <tr>
              <th>Meno</th>
              <th>Telefón</th>
              <th>Email</th>
              <th>Depo</th>
              <th>Auto</th>
              <th>Dnes</th>
            </tr>
          </thead>
          <tbody>
            {visible.length === 0 && (
              <tr><td className="td-plain" colSpan={6} style={{ textAlign: "center", padding: 30, color: "var(--text-dim)" }}>Zatiaľ žiadni šoféri.</td></tr>
            )}
            {visible.map((d) => {
              const activeJob = jobs.find((j) => j.driverId === d.id && j.status !== "completed" && j.startDate <= today && (!j.endDate || j.endDate >= today));
              return (
                <tr key={d.id} id={"drv-row-" + d.id} {...rowOpenKeys(() => onOpenCard(d))} onClick={() => onOpenCard(d)} style={{ cursor: "pointer", opacity: d.archived ? 0.6 : 1 }}>
                  <td className="td-plain" style={{ fontWeight: 600 }}>{d.name}{d.archived ? " (archivovaný)" : ""}</td>
                  <td className="tnum" data-label="Telefón">{d.phone || <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                  <td data-label="Email">{d.email || <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                  <td data-label="Depo">{d.depo || "—"}</td>
                  <td className="tnum" data-label="Auto">{vehicleByEmployeeId[d.id]?.spz ? <strong>{vehicleByEmployeeId[d.id].spz}</strong> : <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                  <td data-label="Dnes">{activeJob ? <span className="spill spill-active">Na zákazke</span> : <span className="spill spill-done">Voľný</span>}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Zákazníci — zoznam, karta zákazníka (aj s kontaktnými osobami
   a súhrnom naprieč zákazkami/blacklistom/rámcovými zmluvami)
--------------------------------------------------------- */
function CustomersView({ customers, jobs, blacklist, user, onAdd, onImport, onOpenCard }) {
  const [search, setSearch] = useState("");
  const canAdd = can(user, "customer_add");
  const q = search.trim().toLowerCase();
  const visible = (q ? customers.filter((c) => (c.firma || "").toLowerCase().includes(q)) : customers)
    .slice()
    .sort((a, b) => (a.firma || "").localeCompare(b.firma || ""));
  // Po 200 ako Zákazky (rozhodnutie 24. 10.) — pri tisícoch zákazníkov sa nevykresľujú všetci naraz.
  const [shown, setShown] = useState(200);
  useEffect(() => setShown(200), [q]);
  const activeByFirma = useMemo(() => {
    const m = {};
    jobs.forEach((j) => { if (j.status !== "completed") m[j.customer] = (m[j.customer] || 0) + 1; });
    return m;
  }, [jobs]);
  function jobCountFor(c) {
    return activeByFirma[c.firma] || 0;
  }
  function isBlacklisted(c) {
    return blacklist.some((b) => (b.nazovZakaznika || "").toLowerCase() === (c.firma || "").toLowerCase());
  }

  return (
    <div>
      <div className="tbar">
        <SearchInput placeholder="Hľadať firmu…" value={search} onChange={setSearch} style={{ minWidth: 260 }} />
        {canAdd && (
          <div style={{ display: "flex", gap: 8, marginLeft: "auto" }}>
            {isAdminUser(user) && <button className="btn btn-outline" onClick={onImport}>Import zákazníkov</button>}
            <button className="btn btn-accent" onClick={onAdd}>+ Pridať zákazníka</button>
          </div>
        )}
      </div>
      <div className="panel jobs-wrap" style={{ boxShadow: "none", borderRadius: 12 }}>
        <table className="table-cards jobs-table">
          <thead>
            <tr>
              <th>Firma</th>
              <th>IČO</th>
              <th>Číslo odberateľa</th>
              <th>Kontaktné osoby</th>
              <th>Aktívne zákazky</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {visible.length === 0 && (
              <tr><td className="td-plain" colSpan={6} style={{ textAlign: "center", padding: 30, color: "var(--text-dim)" }}>{q ? "Žiadny zákazník nezodpovedá hľadaniu." : "Zatiaľ žiadni zákazníci."}</td></tr>
            )}
            {visible.slice(0, shown).map((c) => (
              <tr key={c.id} id={"cust-row-" + c.id} {...rowOpenKeys(() => onOpenCard(c))} onClick={() => onOpenCard(c)} style={{ cursor: "pointer" }}>
                <td className="td-plain" style={{ fontWeight: 600 }}>{c.firma}</td>
                <td className="tnum" data-label="IČO">{c.ico || <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                <td className="tnum" data-label="Číslo odberateľa">{c.cisloOdberatela || <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                <td className="tnum" data-label="Kontaktné osoby">{(c.contacts || []).length || <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                <td className="tnum" data-label="Aktívne zákazky">{jobCountFor(c) || <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                <td className="td-actions">
                  {isBlacklisted(c) && (
                    <span className="spill spill-problem">⚠ Blacklist</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {visible.length > shown && (
          <div style={{ padding: 12, textAlign: "center" }}>
            <button type="button" className="btn btn-outline" onClick={() => setShown((n) => n + 200)}>Zobraziť ďalších {Math.min(200, visible.length - shown)} (zobrazených {shown} z {visible.length})</button>
          </div>
        )}
      </div>
    </div>
  );
}

function AddCustomerModal({ customers = [], onOpenExisting, onClose, onSave }) {
  const [firma, setFirma] = useState("");
  const [ico, setIco] = useState("");
  const [cisloOdberatela, setCisloOdberatela] = useState("");
  const [email, setEmail] = useState("");
  const [telefon, setTelefon] = useState("");
  const sameName = customers.some((c) => (c.firma || "").trim().toLowerCase() === firma.trim().toLowerCase());
  const similar = firma.trim() || ico.trim() ? similarCustomers(customers, firma, ico) : [];
  const canSave = firma.trim().length > 0 && !sameName;
  return (
    <Modal title="Pridať zákazníka" onClose={onClose}>
      <Field label="Firma *">
        <input value={firma} onChange={(e) => setFirma(e.target.value)} style={{ width: "100%" }} />
      </Field>
      {similar.length > 0 && (
        <div role="alert" className="fnote fnote-y" style={{ marginTop: -6 }}>
          <strong>{sameName ? "Zákazník s týmto názvom už existuje:" : "Podobný zákazník už existuje — nie je to ten istý?"}</strong>
          {similar.map((c) => (
            <div key={c.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, marginTop: 6 }}>
              <span>{c.firma}{c.ico ? ` · IČO ${c.ico}` : ""}</span>
              {onOpenExisting && <button className="btn btn-outline" style={{ minHeight: 36 }} onClick={() => onOpenExisting(c)}>Otvoriť</button>}
            </div>
          ))}
        </div>
      )}
      <div className="fgrid2">
        <Field label="IČO">
          <input value={ico} onChange={(e) => setIco(e.target.value)} style={{ width: "100%" }} />
        </Field>
        <Field label="Číslo odberateľa">
          <input value={cisloOdberatela} onChange={(e) => setCisloOdberatela(e.target.value)} style={{ width: "100%" }} />
        </Field>
        <Field label="Všeobecný email firmy">
          <input value={email} onChange={(e) => setEmail(e.target.value)} style={{ width: "100%" }} />
        </Field>
        <Field label="Všeobecný telefón firmy">
          <input value={telefon} onChange={(e) => setTelefon(e.target.value)} style={{ width: "100%" }} />
        </Field>
      </div>
      <div className="fhint" style={{ marginTop: 0, marginBottom: 16 }}>
        Kontaktné osoby (meno, funkcia, telefón, e-mail) pridáš po uložení, priamo v karte zákazníka.
      </div>
      <FormFoot missing={!firma.trim() ? ["firma"] : []}>
        <button className="btn btn-accent" disabled={!canSave} onClick={() => onSave({ firma, ico, cisloOdberatela, email, telefon })}>
          {similar.length && !sameName ? "Aj tak pridať nového" : "Uložiť"}
        </button>
      </FormFoot>
    </Modal>
  );
}

function CustomerContactRow({ contact, canEdit, onEdit, onDelete, startEditing }) {
  const [editing, setEditing] = useState(!!startEditing);
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const [name, setName] = useState(contact.name || "");
  const [role, setRole] = useState(contact.role || "");
  const [phone, setPhone] = useState(contact.phone || "");
  const [email, setEmail] = useState(contact.email || "");
  if (editing) {
    return (
      <div
        className="fnote fnote-i"
        style={{ padding: 14 }}
        // Enter v poli kontaktu uloží kontakt.
        onKeyDown={(e) => { if (e.key === "Enter" && e.target.tagName === "INPUT") { e.preventDefault(); e.currentTarget.querySelector(".btn-black")?.click(); } }}
      >
        <div className="fgrid2">
          <Field label="Meno"><input value={name} onChange={(e) => setName(e.target.value)} style={{ width: "100%", minHeight: 44, fontSize: 15 }} /></Field>
          <Field label="Funkcia"><input value={role} onChange={(e) => setRole(e.target.value)} style={{ width: "100%", minHeight: 44, fontSize: 15 }} /></Field>
          <Field label="Telefón"><input type="tel" value={phone} onChange={(e) => setPhone(e.target.value)} style={{ width: "100%", minHeight: 44, fontSize: 15 }} /></Field>
          <Field label="Email"><input type="email" value={email} onChange={(e) => setEmail(e.target.value)} style={{ width: "100%", minHeight: 44, fontSize: 15 }} /></Field>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <button className="btn btn-outline" style={{ minHeight: 44, fontSize: 14 }} onClick={() => { setEditing(false); if (startEditing) onDelete(); }}>Zrušiť</button>
          <button
            className="btn btn-black"
            style={{ minHeight: 44, fontSize: 14 }}
            onClick={() => {
              onEdit({ name, role, phone, email });
              setEditing(false);
            }}
          >
            Uložiť kontakt
          </button>
        </div>
      </div>
    );
  }
  return (
    <div style={{ padding: "12px 0", borderBottom: "1px solid var(--border)", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
      <div style={{ minWidth: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", fontWeight: 600, fontSize: 15 }}>
          {contact.name || "—"}
          {contact.role && <span className="spill">{contact.role}</span>}
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "4px 16px", marginTop: 4, fontSize: 14 }}>
          {contact.phone && (
            <a href={`tel:${contact.phone}`} className="tnum" style={{ display: "inline-flex", alignItems: "center", gap: 6, color: "var(--text)" }}>
              <PhoneIcon size={14} /> {contact.phone}
            </a>
          )}
          {contact.email && (
            <a href={`mailto:${contact.email}`} style={{ display: "inline-flex", alignItems: "center", gap: 6, color: "var(--text)", overflowWrap: "anywhere" }}>
              <MailIcon size={14} /> {contact.email}
            </a>
          )}
        </div>
      </div>
      {canEdit && (
        <div style={{ display: "flex", gap: 8, flexShrink: 0, alignItems: "center" }}>
          <button className="btn btn-outline" style={{ minHeight: 40, fontSize: 14 }} onClick={() => setEditing(true)}>Upraviť</button>
          <KebabMenu label="⋯" name="Ďalšie akcie" btnClass="btn btn-outline" btnStyle={{ minHeight: 40, minWidth: 40, padding: "0 10px", borderColor: "var(--line-strong)" }} actions={[{ label: "Zmazať", danger: true, onClick: () => setConfirmingDelete(true) }]} />
        </div>
      )}
      {confirmingDelete && (
        <ConfirmDeleteModal label={`kontaktnú osobu${contact.name ? ` "${contact.name}"` : ""}`} onClose={() => setConfirmingDelete(false)} onConfirm={onDelete} />
      )}
    </div>
  );
}

// Karta zákazníka → súhrn za 12 mesiacov (návrh 7): prenájmy, dni, poškodenia, nesúhlasy, oneskorené vrátenia, najčastejšie stroje.
function CustomerSummary({ firma, jobs, damages, handoverProtocols, machineById }) {
  const today = todayISO(), from = addDaysISO(today, -365), key = (x) => String(x || "").trim().toLowerCase();
  const k = key(firma);
  if (!k) return null;
  const hpBy = Object.fromEntries((handoverProtocols || []).map((h) => [h.jobId, h]));
  const mine = (jobs || []).filter((j) => key(j.customer) === k && !j.notRealized && isRealISODate(jobFrom(j)) && jobFrom(j) <= today && (jobTo(j) || today) >= from);
  // Dni podľa skutočného vývozu a vrátenia z protokolov (rozhodnutie 23. 10.); staré zákazky bez protokolu podľa zmluvy.
  const span = (j) => {
    const h = hpBy[j.id], d10 = (x) => (x ? String(x).slice(0, 10) : "");
    if (h?.handoverDone && isRealISODate(d10(h.handoverDate))) return [d10(h.handoverDate), h.returnDone && isRealISODate(d10(h.returnDate)) ? d10(h.returnDate) : today];
    if (h || j.status !== "completed") return null; // ešte nevyvezený (protokol vzniká až pri vývoze)
    return [jobFrom(j), jobTo(j) || today]; // stará ukončená zákazka bez protokolu — podľa zmluvy
  };
  const dayList = (j) => { const sp = span(j); if (!sp) return []; const a = sp[0] < from ? from : sp[0], b = [sp[1], today].sort()[0]; const out = []; for (let d = a; d <= b && out.length < 400; d = addDaysISO(d, 1)) out.push(d); return out; };
  const months = Array.from({ length: 12 }, (_, i) => { const d = new Date(today.slice(0, 7) + "-01T00:00:00"); d.setMonth(d.getMonth() - 11 + i); return toLocalISO(d).slice(0, 7); });
  const perMonth = Object.fromEntries(months.map((m) => [m, 0]));
  let days = 0;
  mine.forEach((j) => dayList(j).forEach((d) => { days++; if (perMonth[d.slice(0, 7)] != null) perMonth[d.slice(0, 7)]++; }));
  const late = mine.map((j) => { const r = hpBy[j.id]?.returnDate; const rd = r ? String(r).slice(0, 10) : null; return rd && j.endDate && rd > j.endDate ? daysBetween(j.endDate, rd) : 0; }).filter((x) => x > 0);
  const disputes = mine.filter((j) => [hpBy[j.id]?.handoverCustomerConfirm, hpBy[j.id]?.returnCustomerConfirm].some((c) => c?.status === "disputed")).length;
  const dmg = (damages || []).filter((d) => d.type === "poskodenie" && !d.prepCheck && isRealISODate(d.dateReported) && d.dateReported >= from
    && (key(d.customer) === k || mine.some((j) => j.machineId === d.machineId && j.status === "completed" && jobTo(j) && jobTo(j) <= d.dateReported && addDaysISO(jobTo(j), 2) >= d.dateReported)));
  const models = {};
  mine.forEach((j) => { const t = machineById?.[j.machineId]?.type || j.machineDisplayName; if (t) models[t] = (models[t] || 0) + 1; });
  const top = Object.entries(models).sort((a, b) => b[1] - a[1]).slice(0, 3);
  const max = Math.max(1, ...Object.values(perMonth));
  const label = (m) => new Date(m + "-01T00:00:00").toLocaleDateString("sk-SK", { month: "short" }).replace(".", "");
  const card = (t, v, danger) => <div style={{ border: "1px solid var(--border)", borderRadius: 10, padding: "8px 10px" }}><div style={{ fontSize: 12, color: "var(--text-dim)" }}>{t}</div><div className="tnum" style={{ fontSize: 22, fontWeight: 700, color: danger && v ? "var(--danger)" : undefined }}>{v}</div></div>;
  return (
    <section aria-label="Súhrn zákazníka" style={{ marginTop: 16, display: "flex", flexDirection: "column", gap: 12 }}>
      <div className="today-sec" style={{ margin: 0 }}>Posledných 12 mesiacov</div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(110px, 1fr))", gap: 8 }}>
        {card("Prenájmy", mine.length)}{card("Dní prenájmu", `${days} / ${plural(new Set(mine.map((j) => j.machineId)).size, "stroj", "stroje", "strojov")}`)}{card("Poškodenia", dmg.length, true)}{card("Nesúhlas s protokolom", disputes, true)}
      </div>
      {days > 0 && (
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 6 }}>Dni prenájmu po mesiacoch</div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(12, minmax(0, 1fr))", gap: 4, alignItems: "end", height: 90, borderBottom: "1px solid var(--line-strong)" }}>
            {months.map((m) => <div key={m} title={`${label(m)}: ${perMonth[m]} dní`} style={{ display: "flex", flexDirection: "column", justifyContent: "flex-end", alignItems: "center", height: "100%" }}>
              <span className="tnum" style={{ fontSize: 10, color: "var(--text-dim)" }}>{perMonth[m] || ""}</span>
              <span style={{ width: "100%", height: `${(perMonth[m] / max) * 70}px`, background: "var(--c1)", borderRadius: "3px 3px 0 0" }} />
            </div>)}
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(12, minmax(0, 1fr))", gap: 4, fontSize: 10, color: "var(--text-dim)", textAlign: "center", marginTop: 2 }}>
            {months.map((m) => <span key={m}>{label(m)}</span>)}
          </div>
        </div>
      )}
      {late.length > 0 && <div className="fnote fnote-y" style={{ margin: 0 }}>{plural(late.length, "vrátenie", "vrátenia", "vrátení")} po termíne (priemerne o {(() => { const v = Math.round(late.reduce((a, b) => a + b, 0) / late.length * 10) / 10; return Number.isInteger(v) ? plural(v, "deň", "dni", "dní") : `${fmt1(v)} dňa`; })()})</div>}
      {dmg.length > 0 && <div className="fnote fnote-r" style={{ margin: 0 }}>Poškodenia: {dmg.slice(0, 5).map((d) => `${machineById?.[d.machineId]?.code || d.code || "—"} (${fmtDate(d.dateReported)})`).join(", ")}{dmg.length > 5 ? "…" : ""}</div>}
      {top.length > 0 && (
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
          <span style={{ fontSize: 13, color: "var(--text-dim)" }}>Najčastejšie:</span>
          {top.map(([t, n]) => <span key={t} className="spill">{t} · {n}×</span>)}
        </div>
      )}
    </section>
  );
}
function CustomerDetailModal({
  customer,
  customers = [],
  jobs,
  damages,
  handoverProtocols,
  machineById,
  blacklist,
  framoveZmluvy,
  user,
  onClose,
  onEditInfo,
  onAddContact,
  onUpdateContact,
  onDeleteContact,
  onDeleteCustomer,
  blockingRefs,
}) {
  const [editingInfo, setEditingInfo] = useState(false);
  const infoSnapRef = useRef(null);
  const [firma, setFirma] = useState(customer.firma || "");
  const [ico, setIco] = useState(customer.ico || "");
  const [cisloOdberatela, setCisloOdberatela] = useState(customer.cisloOdberatela || "");
  const [email, setEmail] = useState(customer.email || "");
  const [telefon, setTelefon] = useState(customer.telefon || "");
  const [showAddContact, setShowAddContact] = useState(false);
  const [binderTab, setBinderTab, forgetBinder] = useBinderTab("cust:" + customer.id);
  const canEdit = can(user, "customer_edit");
  const canDelete = can(user, "customer_delete");
  // Rovnaké IČO u iného zákazníka — len upozornenie (rozhodnutie 24. 10.), porovnanie bez medzier.
  const icoTwin = editingInfo && icoKey(ico) && icoKey(ico) !== icoKey(customer.ico) ? customers.find((c) => c.id !== customer.id && icoKey(c.ico) === icoKey(ico)) : null;

  const activeJobs = jobs.filter((j) => j.customer === customer.firma && j.status !== "completed");
  const blEntry = blacklist.find((b) => (b.nazovZakaznika || "").toLowerCase() === (customer.firma || "").toLowerCase());
  const contract = framoveZmluvy.find((z) => (z.najomca || "").toLowerCase() === (customer.firma || "").toLowerCase());

  return (
    <Modal
      eyebrow="Zákazník"
      title={<>{customer.firma}{customer.ico && <span className="side-title-sub">IČO {customer.ico}</span>}{blEntry && <span className="spill spill-problem">⚠ Blacklist</span>}</>}
      onClose={() => { forgetBinder(); onClose(); }}
      side
      headerExtra={
        <div className="side-summary">
          <div><span>Číslo odberateľa</span><b>{customer.cisloOdberatela || "—"}</b></div>
          <div><span>Aktívne zákazky</span><b className="tnum">{activeJobs.length}</b></div>
          <div><span>Rámcová zmluva</span><b>{contract ? `Áno — č. ${contract.cisloRZ || "—"}` : "Nie"}</b></div>
          <div><span>Blacklist</span><b style={blEntry ? { color: "var(--danger)" } : undefined}>{blEntry ? "Áno" : "Nie"}</b></div>
        </div>
      }
      footer={((canDelete && blockingRefs.length === 0) || (canEdit && !editingInfo)) && (
        <>
          {canDelete && blockingRefs.length === 0 && (
            <KebabMenu up label="⋯" actions={[{ label: "Zmazať zákazníka →", danger: true, onClick: onDeleteCustomer }]} />
          )}
          {canEdit && !editingInfo && (
            <button className="btn btn-accent" style={{ marginLeft: "auto" }} onClick={() => {
              const snap = { firma: customer.firma || "", ico: customer.ico || "", cisloOdberatela: customer.cisloOdberatela || "", email: customer.email || "", telefon: customer.telefon || "" };
              infoSnapRef.current = snap;
              setFirma(snap.firma); setIco(snap.ico); setCisloOdberatela(snap.cisloOdberatela); setEmail(snap.email); setTelefon(snap.telefon);
              setBinderTab(null);
              setEditingInfo(true);
            }}>Upraviť údaje firmy →</button>
          )}
        </>
      )}
    >
      <BinderLayout
        horizontal
        tabs={[{ id: "kontakty", label: "Kontakty", count: (customer.contacts || []).length, title: "Kontaktné osoby" }]}
        active={binderTab}
        setActive={setBinderTab}
        panel={<>
      {(customer.contacts || []).length === 0 && <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 8 }}>Zatiaľ žiadne kontaktné osoby.</div>}
      {(customer.contacts || []).map((k) => (
        <CustomerContactRow
          key={k.id}
          contact={k}
          canEdit={canEdit}
          onEdit={(data) => onUpdateContact(k.id, data)}
          onDelete={() => onDeleteContact(k.id)}
        />
      ))}
      {canEdit && !showAddContact && (
        <button className="btn btn-ghost" onClick={() => setShowAddContact(true)}>+ Pridať kontaktnú osobu</button>
      )}
      {showAddContact && (
        <CustomerContactRow
          contact={{ name: "", role: "", phone: "", email: "" }}
          canEdit={true}
          startEditing
          onEdit={(data) => { onAddContact(data); setShowAddContact(false); }}
          onDelete={() => setShowAddContact(false)}
        />
      )}

        </>}
        main={<>
      {editingInfo ? (
        <>
          <Field label="Firma *">
            {/* Premenovanie mení aj zákazky/blacklist — len roly, ktoré ich smú upravovať. */}
            <input value={firma} disabled={!can(user, "job_edit")} title={!can(user, "job_edit") ? "Názov firmy mení dispečer alebo vedúci požičovne" : ""} onChange={(e) => setFirma(e.target.value)} style={{ width: "100%" }} />
          </Field>
          <Field label="IČO"><input value={ico} onChange={(e) => setIco(e.target.value)} style={{ width: "100%" }} /></Field>
          {icoTwin && <div role="alert" className="fnote fnote-y" style={{ marginTop: -6 }}>⚠ Toto IČO má už zákazník <b>{icoTwin.firma}</b>{/\.$/.test(icoTwin.firma || "") ? "" : "."} Uložiť sa dá aj tak (napr. iná pobočka).</div>}
          <Field label="Číslo odberateľa"><input value={cisloOdberatela} onChange={(e) => setCisloOdberatela(e.target.value)} style={{ width: "100%" }} /></Field>
          <Field label="Všeobecný email firmy"><input value={email} onChange={(e) => setEmail(e.target.value)} style={{ width: "100%" }} /></Field>
          <Field label="Všeobecný telefón firmy"><input value={telefon} onChange={(e) => setTelefon(e.target.value)} style={{ width: "100%" }} /></Field>
          <div style={{ display: "flex", gap: 8 }}>
            <button className="btn btn-ghost" onClick={() => setEditingInfo(false)}>Zrušiť</button>
            <button
              className="btn btn-accent"
              disabled={!firma.trim()}
              onClick={() => {
                // Len zmenené polia — otvorená karta inak ticho prepísala zmenu kolegu.
                const mine = { firma: firma.trim(), ico: icoKey(ico), cisloOdberatela, email, telefon }; // IČO bez medzier (import páruje podľa neho)
                const snap = infoSnapRef.current || {};
                const patch = Object.fromEntries(Object.entries(mine).filter(([k, v]) => (v || "") !== (snap[k] || "")));
                const clash = Object.keys(patch).filter((k) => (customer[k] || "") !== (snap[k] || "") && (customer[k] || "") !== (patch[k] || ""));
                if (clash.length) { showNotice("Tieto údaje medzičasom zmenil niekto iný. Zavrite úpravu a otvorte ju znova, nech sa nič neprepíše."); return; }
                if (Object.keys(patch).length) onEditInfo(patch);
                setEditingInfo(false);
              }}
            >
              {icoTwin ? "Uložiť aj tak" : "Uložiť"}
            </button>
          </div>
        </>
      ) : (
        <dl className="side-dl">
          {/* v1.0.806: firma, IČO, číslo odberateľa, zákazky, zmluva a blacklist sú v nadpise a súhrne hore. */}
          {!customer.ico && <><dt>IČO</dt><dd>—</dd></>}
          <dt>Všeobecný email</dt><dd>{customer.email ? <a href={`mailto:${customer.email}`}>{customer.email}</a> : "—"}</dd>
          <dt>Všeobecný telefón</dt><dd className="tnum">{customer.telefon ? <a href={`tel:${customer.telefon}`}>{customer.telefon}</a> : "—"}</dd>
          {blEntry && <><dt>Dôvod blacklistu</dt><dd><span style={{ color: "var(--danger)", fontWeight: 600 }}>⚠ {blEntry.dovod || "bez uvedeného dôvodu"}</span></dd></>}
        </dl>
      )}
      {!editingInfo && <CustomerSummary firma={customer.firma} jobs={jobs} damages={damages} handoverProtocols={handoverProtocols} machineById={machineById} />}

      {canDelete && blockingRefs.length > 0 && (
        <div style={{ fontSize: 13, color: "var(--danger)", marginTop: 14 }}>
          Zákazníka nie je možné zmazať — má naviazané: {blockingRefs.join(", ")}. Najprv doriešte tieto veci.
        </div>
      )}
      </>} />
    </Modal>
  );
}

/* ---------------------------------------------------------
   Driver card modal (karta šoféra)
--------------------------------------------------------- */
// Telefónny zoznam — všetci aktívni zamestnanci naprieč rolami, s klikateľným
// číslom (tel: odkaz). Na mobile to rovno otvorí telefón, na počítači to závisí
// od toho, či má človek telefón prepojený s počítačom (napr. Windows Phone Link).
// maSKot — AI asistent appky, plávajúce tlačidlo + jednoduché chat okno.
// Zatiaľ len na testovanie (pozri podmienku vyššie, kde sa toto renderuje).
// Ikona je od v1.0.490 čierny box s červenou bublinou (ChatBubbleIcon), nie logo.

// Jednoduché vykreslenie základného markdownu (tabuľky, odrážky, **tučné**) v
// odpovedi maSKota — appka posiela čistý text, bez tohto by sa znaky "|" a
// "---" tabuľky zobrazili doslovne, nie ako poriadna tabuľka. Kódy strojov v
// tvare [[GS-2032]] sa navyše vykreslia ako klikateľné tlačidlo, čo priamo
// otvorí kartu stroja (ak sa nájde v aktuálne dostupnom zozname).
// Telefónne čísla (+421... alebo 0...) a e-maily v odpovedi sa rovno urobia
// klikateľné (tel:/mailto:) — telefón nemá čo skopírovať a vytočiť ručne.
const PHONE_RE = /(?:\+\d[\d ]{7,}\d|\b0\d[\d ]{7,}\d\b)/;
const EMAIL_RE = /[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}/;
function renderInlineMd(text, keyPrefix, machineByCode, onOpenCard, navLink) {
  const parts = String(text).split(new RegExp(`(\\*\\*[^*]+\\*\\*|\\[\\[[^\\]]+\\]\\]|${EMAIL_RE.source}|${PHONE_RE.source})`, "g"));
  return parts.map((p, i) => {
    const key = `${keyPrefix}-${i}`;
    if (p.startsWith("**") && p.endsWith("**")) return <strong key={key}>{p.slice(2, -2)}</strong>;
    if (new RegExp(`^${EMAIL_RE.source}$`).test(p)) {
      return <a key={key} href={`mailto:${p}`} style={{ color: "inherit", textDecoration: "underline" }}>{p}</a>;
    }
    if (new RegExp(`^${PHONE_RE.source}$`).test(p)) {
      return <a key={key} href={`tel:${p.replace(/\s+/g, "")}`} style={{ color: "inherit", textDecoration: "underline" }}>{p}</a>;
    }
    // maSKot príručka: [[nav:modul/záložka|Text]] a [[new:kľúč|Text]] — klikateľné, len ak ich rola má.
    const navM = p.match(/^\[\[(nav|new):([^|\]]+)\|([^\]]+)\]\]$/);
    if (navM) {
      const go = navLink?.(navM[1], navM[2].trim());
      return go ? (
        <button key={key} className="btn btn-ghost" onClick={go} style={{ padding: "0 6px", fontSize: "inherit", fontWeight: 600, color: "var(--accent)", border: "1px solid var(--accent)", borderRadius: 4, verticalAlign: "baseline" }}>
          {navM[3]} →
        </button>
      ) : <strong key={key}>{navM[3]}</strong>;
    }
    if (p.startsWith("[[") && p.endsWith("]]")) {
      const code = p.slice(2, -2).trim();
      const machine = machineByCode?.get(norm(code));
      if (machine && onOpenCard) {
        return (
          <button
            key={key}
            onClick={() => onOpenCard(machine)}
            style={{
              background: "var(--accent-light, #fdf0f0)",
              color: "var(--accent)",
              border: "1px solid var(--accent)",
              borderRadius: 4,
              padding: "0 5px",
              fontSize: "inherit",
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            {code}
          </button>
        );
      }
      return <React.Fragment key={key}>{code}</React.Fragment>; // stroj sa nenašiel — ukáž aspoň čistý text
    }
    return <React.Fragment key={key}>{p}</React.Fragment>;
  });
}
const norm = (s) => String(s ?? "").toLowerCase();
function MaskotMessageContent({ text, machineByCode, onOpenCard, navLink }) {
  const lines = String(text).split("\n");
  const blocks = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line.trim().startsWith("|") && lines[i + 1] && /^\s*\|?[\s:-]+\|[\s:|-]*\|?\s*$/.test(lines[i + 1])) {
      const header = line.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
      i += 2;
      const rows = [];
      while (i < lines.length && lines[i].trim().startsWith("|")) {
        rows.push(lines[i].trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim()));
        i++;
      }
      blocks.push({ type: "table", header, rows });
      continue;
    }
    if (/^\s*[-*]\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
        i++;
      }
      blocks.push({ type: "list", items });
      continue;
    }
    if (line.trim() === "") {
      i++;
      continue;
    }
    blocks.push({ type: "p", text: line });
    i++;
  }
  return (
    <>
      {blocks.map((b, bi) => {
        if (b.type === "table") {
          return (
            <div key={bi} style={{ overflowX: "auto", margin: "4px 0" }}>
              <table style={{ borderCollapse: "collapse", fontSize: 11, minWidth: "100%" }}>
                <thead>
                  <tr>
                    {b.header.map((h, hi) => (
                      <th key={hi} style={{ border: "1px solid rgba(0,0,0,.15)", padding: "3px 6px", textAlign: "left", background: "rgba(0,0,0,.06)", whiteSpace: "nowrap" }}>
                        {renderInlineMd(h, `h${bi}-${hi}`, machineByCode, onOpenCard, navLink)}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {b.rows.map((r, ri) => (
                    <tr key={ri}>
                      {r.map((c, ci) => (
                        <td key={ci} style={{ border: "1px solid rgba(0,0,0,.1)", padding: "3px 6px", whiteSpace: "nowrap" }}>
                          {renderInlineMd(c, `c${bi}-${ri}-${ci}`, machineByCode, onOpenCard, navLink)}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }
        if (b.type === "list") {
          return (
            <ul key={bi} style={{ margin: "4px 0", paddingLeft: 18 }}>
              {b.items.map((it, ii) => (
                <li key={ii}>{renderInlineMd(it, `l${bi}-${ii}`, machineByCode, onOpenCard, navLink)}</li>
              ))}
            </ul>
          );
        }
        return (
          <div key={bi} style={{ whiteSpace: "pre-wrap" }}>
            {renderInlineMd(b.text, `p${bi}`, machineByCode, onOpenCard, navLink)}
          </div>
        );
      })}
    </>
  );
}

function MaskotChatWidget({ session, machines, onOpenCard, askTrigger, navModules, quickActions, onNavGo, screen, viewAsRole }) {
  const [open, setOpen] = useState(false);
  // Namiesto natívneho window.confirm (jediné miesto v appke, čo ho ešte
  // používalo) — rovnaký dvojkrokový vzor ako inde (klik → červené
  // upozornenie + druhé tlačidlo na potvrdenie).
  const [confirmingClear, setConfirmingClear] = useState(false);
  const machineByCode = useMemo(() => new Map((machines || []).map((m) => [String(m.code || "").toLowerCase(), m])), [machines]);
  // Odkaz z odpovede → klik, len ak cieľ v menu / „＋ Nové“ tejto role naozaj je (inak null = len text).
  const navLink = (kind, target) => {
    if (viewAsRole === "nezaradeny") return null;
    const close = () => { if (window.innerWidth < 700) setOpen(false); };
    if (kind === "new") {
      const a = (quickActions || []).find((x) => x.key === target);
      return a ? () => { close(); a.onClick(); } : null;
    }
    const [m, v] = target.split("/");
    const tab = (navModules || []).find((x) => x.id === m)?.tabs.find((t) => !t.dropdown && (t.group || [t.id]).includes(v));
    return tab ? () => { close(); onNavGo(m, v); } : null;
  };
  // Konverzácia sa teraz uchováva aj po zavretí okna/appky (localStorage,
  // viazané na konkrétneho prihláseného, nie zdieľané medzi ľuďmi na tom istom
  // počítači). Načíta sa len raz, pri prvom vytvorení komponentu.
  const storageKeyBase = `maskot_${session?.user?.id || "anon"}`;
  const [messages, setMessages] = useState(() => {
    try {
      const saved = localStorage.getItem(storageKeyBase + "_messages");
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  }); // [{ role: "user"|"assistant", text }]
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);
  const [history, setHistory] = useState(() => {
    try {
      const saved = localStorage.getItem(storageKeyBase + "_history");
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  }); // surové kolá konverzácie vo formáte Anthropic API
  const [listening, setListening] = useState(false);
  const [conversationMode, setConversationMode] = useState(false); // "rozhovor" — číta odpovede nahlas a sám počúva ďalej
  const scrollRef = useRef(null);
  const recognitionRef = useRef(null);
  const historyRef = useRef([]); // aktuálna história pre send() volaný z hlasového callbacku (mimo React render cyklu)
  const conversationModeRef = useRef(false); // to isté — nech onend/onresult callbacky vidia aktuálnu hodnotu, nie tú zo starého uzáveru
  const listeningRef = useRef(false); // to isté pre "listening" — potrebné pri rozhodovaní štart/stop mimo renderu
  // Rastúce číslo pri každom novom spustení počúvania — starý ("zastaraný")
  // objekt tak vie sám spoznať, že už nie je ten aktuálny, a jeho oneskorené
  // udalosti (onend/onresult) sa jednoducho ignorujú namiesto toho, aby
  // omylom prepísali stav novšieho počúvania. Presne toto spôsobovalo dojem
  // "zapína/vypína sa samo".
  const recognitionGenRef = useRef(0);

  useEffect(() => { conversationModeRef.current = conversationMode; }, [conversationMode]);
  useEffect(() => { historyRef.current = history; }, [history]);
  useEffect(() => {
    try { localStorage.setItem(storageKeyBase + "_messages", JSON.stringify(messages)); } catch {}
  }, [messages, storageKeyBase]);
  useEffect(() => {
    try { localStorage.setItem(storageKeyBase + "_history", JSON.stringify(history)); } catch {}
  }, [history, storageKeyBase]);

  function clearConversation() {
    setMessages([]);
    setHistory([]);
    try {
      localStorage.removeItem(storageKeyBase + "_messages");
      localStorage.removeItem(storageKeyBase + "_history");
    } catch {}
  }

  // Hlasový vstup — natívne vstavané v prehliadači (Chrome/Edge/Safari), nič
  // sa preň neinštaluje ani neplatí. Firefox to (zatiaľ) nepodporuje — v tom
  // prípade sa mikrofón jednoducho nezobrazí, appka funguje ďalej normálne
  // cez písanie.
  const SpeechRecognitionApi = typeof window !== "undefined" && (window.SpeechRecognition || window.webkitSpeechRecognition);
  const canSpeak = typeof window !== "undefined" && !!window.speechSynthesis;

  function speak(text, onDone) {
    if (!canSpeak || !text) {
      onDone?.();
      return;
    }
    window.speechSynthesis.cancel(); // nič rozhovorené navyše, keby toto prišlo uprostred niečoho iného
    const utter = new SpeechSynthesisUtterance(String(text).replace(/\[\[(?:nav|new):[^|\]]*\|([^\]]+)\]\]/g, "$1").replace(/\[\[([^\]]+)\]\]/g, "$1"));
    utter.lang = "sk-SK";
    utter.onend = () => onDone?.();
    utter.onerror = () => onDone?.();
    window.speechSynthesis.speak(utter);
  }

  function stopListening() {
    recognitionGenRef.current++; // zneplatní čokoľvek prebiehajúce, nech jeho udalosti už nič nerobia
    recognitionRef.current?.stop();
    listeningRef.current = false;
    setListening(false);
  }

  function startListening() {
    if (!SpeechRecognitionApi) return;
    // Nikdy nespúšťaj dve naraz — najprv poriadne ukonči prípadné predošlé.
    if (listeningRef.current) stopListening();
    const myGen = ++recognitionGenRef.current;
    const recognition = new SpeechRecognitionApi();
    recognition.lang = "sk-SK";
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    recognition.onresult = (e) => {
      if (recognitionGenRef.current !== myGen) return; // zastaraná inštancia, ignoruj
      const transcript = e.results[0][0].transcript;
      // Explicitne zastav počúvanie HNEĎ, nech appka určite nezachytáva mikrofón
      // ešte aj počas toho, čo sama odpovedá nahlas (tam by mohla "začuť" samu seba).
      recognition.stop();
      if (conversationModeRef.current) {
        send(transcript); // v rozhovore sa pýtaj rovno, netreba ešte klikať na odoslanie
      } else {
        setInput((prev) => (prev ? prev + " " + transcript : transcript));
      }
    };
    recognition.onerror = (e) => {
      if (recognitionGenRef.current !== myGen) return;
      listeningRef.current = false;
      setListening(false);
      // "no-speech" = jednoducho ešte nikto nič nepovedal — v rozhovore to nie
      // je dôvod celý rozhovor ukončiť, len to skús počúvať znova.
      if (conversationModeRef.current && e?.error === "no-speech") {
        setTimeout(() => {
          if (conversationModeRef.current && !listeningRef.current) startListening();
        }, 400);
      }
    };
    recognition.onend = () => {
      if (recognitionGenRef.current !== myGen) return;
      listeningRef.current = false;
      setListening(false);
    };
    recognitionRef.current = recognition;
    recognition.start();
    listeningRef.current = true;
    setListening(true);
  }

  function toggleVoiceInput() {
    if (listeningRef.current) stopListening();
    else startListening();
  }

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, open]);

  // Zapnutie/vypnutie rozhovoru priamo prerušené — vypnutie zastaví aj
  // prípadné aktuálne prehrávanie/počúvanie, nech sa to "nezacyklí" navyše.
  function toggleConversationMode() {
    setConversationMode((v) => {
      const next = !v;
      conversationModeRef.current = next; // hneď, nech to callbacky vidia okamžite (nie až po budúcom renderi)
      if (!next) {
        window.speechSynthesis?.cancel();
        stopListening();
      } else {
        // Hneď pri zapnutí začni počúvať, nech netreba ešte extra kliknúť na mikrofón.
        startListening();
      }
      return next;
    });
  }

  const [pendingImage, setPendingImage] = useState(null); // { dataUrl, mediaType, base64 } — fotka pripravená na odoslanie
  const fileInputRef = useRef(null);

  function handleFileSelected(e) {
    const file = e.target.files?.[0];
    e.target.value = ""; // nech sa dá vybrať tá istá fotka znova nabudúce
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const dataUrl = reader.result;
      const base64 = dataUrl.split(",")[1];
      setPendingImage({ dataUrl, mediaType: file.type || "image/jpeg", base64 });
    };
    reader.readAsDataURL(file);
  }

  async function send(voiceText) {
    const text = (voiceText ?? input).trim();
    if ((!text && !pendingImage) || sending) return;
    const imageForThisSend = pendingImage;
    setMessages((m) => [...m, { role: "user", text: text || "(fotka)", imagePreview: imageForThisSend?.dataUrl || null }]);
    setInput("");
    setPendingImage(null);
    setSending(true);
    // Prázdna "placeholder" správa, čo sa priebežne dopĺňa, ako appka streamuje
    // text zo servera — presne to dáva ten pocit plynulého "písania naživo".
    setMessages((m) => [...m, { role: "assistant", text: "" }]);
    try {
      const resp = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/maskot-agent-v2`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          apikey: import.meta.env.VITE_SUPABASE_ANON_KEY,
          Authorization: `Bearer ${session?.access_token}`,
        },
        body: JSON.stringify({
          message: text || "Pozri sa prosím na priloženú fotku a pomôž mi s ňou.",
          history: historyRef.current,
          screen: { ...screen, mobile: window.innerWidth < 700 },
          viewAsRole: viewAsRole || undefined,
          image: imageForThisSend ? { mediaType: imageForThisSend.mediaType, base64: imageForThisSend.base64 } : undefined,
        }),
      });
      if (!resp.ok || !resp.body) {
        const rawText = await resp.text().catch(() => "");
        setMessages((m) => {
          const copy = [...m];
          copy[copy.length - 1] = { role: "assistant", text: resp.status >= 500 ? "⚠️ maSKot je teraz nedostupný — skúste to o chvíľu." : `⚠️ Neočakávaná odpoveď (HTTP ${resp.status}): ${rawText.slice(0, 200) || "(prázdne telo)"}` };
          console.warn("maSKot", resp.status, rawText.slice(0, 300));
          return copy;
        });
        return;
      }
      // Server posiela čistý text priebežne; na konci je oddelovač "\u0000META\u0000"
      // (alebo "\u0000ERROR\u0000") + JSON s históriou/chybou — nulový znak sa v
      // bežnom texte nikdy nevyskytne, takže sa dá takto bezpečne oddeliť to, čo
      // sa má reálne zobraziť, od toho, čo je len technická informácia navyše.
      const reader = resp.body.getReader();
      const decoder = new TextDecoder();
      let raw = "";
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        raw += decoder.decode(value, { stream: true });
        const visible = raw.split("\u0000")[0];
        setMessages((m) => {
          const copy = [...m];
          copy[copy.length - 1] = { role: "assistant", text: visible };
          return copy;
        });
      }

      let finalText = raw;
      let errorMsg = null;
      let incomplete = false;
      if (raw.includes("\u0000ERROR\u0000")) {
        const [before, after] = raw.split("\u0000ERROR\u0000");
        finalText = before;
        errorMsg = after;
      } else if (raw.includes("\u0000META\u0000")) {
        const [before, metaJson] = raw.split("\u0000META\u0000");
        finalText = before;
        try {
          const meta = JSON.parse(metaJson);
          setHistory(meta.history || []);
        } catch {
          // ak by sa META z nejakého dôvodu nedala rozobrať, aspoň zobrazený text ostáva v poriadku
        }
      } else {
        // Stream sa skončil (done), ale bez koncového oddeľovača, čo server
        // vždy pripája na záver — spojenie sa teda pravdepodobne prerušilo
        // skôr, než agent dopísal celú odpoveď (napr. studený štart edge
        // funkcie pri prvom dopyte). To, čo prišlo, NIE je hotová odpoveď.
        incomplete = true;
      }

      if (errorMsg) {
        setMessages((m) => {
          const copy = [...m];
          copy[copy.length - 1] = { role: "assistant", text: "⚠️ " + errorMsg };
          return copy;
        });
        if (conversationModeRef.current) speak("Nastala chyba: " + errorMsg);
      } else if (incomplete) {
        setMessages((m) => {
          const copy = [...m];
          copy[copy.length - 1] = {
            role: "assistant",
            text: (finalText ? finalText + "\n\n" : "") + "⚠️ Odpoveď sa neprijala celá (spojenie sa asi prerušilo) — skús sa opýtať znova.",
          };
          return copy;
        });
        return null; // neber ako platnú odpoveď — napr. askDaily si to nesmie zacachovať
      } else {
        const replyText = finalText || "(prázdna odpoveď)";
        setMessages((m) => {
          const copy = [...m];
          copy[copy.length - 1] = { role: "assistant", text: replyText };
          return copy;
        });
        if (conversationModeRef.current) {
          // Po dohovorení appka sama znova začne počúvať — plynulý rozhovor
          // bez ďalšieho klikania, kým rozhovor niekto ručne nevypne.
          speak(replyText, () => {
            if (conversationModeRef.current) startListening();
          });
        }
        // finalText, nie replyText — ten obsahuje aj náhradný text "(prázdna
        // odpoveď)" pre zobrazenie v bubline, čo by sa inak vydávalo za
        // skutočnú odpoveď (a napr. askDaily by si to zbytočne zacachoval).
        return finalText || null;
      }
    } catch (e) {
      setMessages((m) => {
        const copy = [...m];
        copy[copy.length - 1] = { role: "assistant", text: "⚠️ Nepodarilo sa spojiť s agentom (" + String(e) + ")." };
        return copy;
      });
    } finally {
      setSending(false);
    }
  }

  // "Čo vyriešiť dnes?" — spúšťa sa z tlačidla na „Dnes“ (admin). Agent si
  // dáta ťahá sám, naživo z databázy — appka tu nemá žiadnu vlastnú kópiu, s
  // ktorou by sa dalo spoľahlivo porovnať "zmenilo sa niečo odvtedy?" (skúšané:
  // appka mala lokálnu kópiu revízií, tá sa vedela rozísť so skutočným stavom
  // v databáze a ukazovala starú odpoveď ako aktuálnu). Namiesto porovnávania
  // obsahu preto len obmedzenie v čase — opakovaný klik do pár minút ukáže tú
  // istú odpoveď (chráni pred omylom viacnásobným klikaním), po uplynutí sa
  // spýta agenta odznova a dostane naozaj čerstvé dáta.
  const DAILY_ASK_COOLDOWN_MS = 2 * 60 * 1000;
  async function askDaily() {
    setOpen(true);
    let cached = null;
    try { cached = JSON.parse(localStorage.getItem(storageKeyBase + "_daily_v3") || "null"); } catch {}
    if (cached && Date.now() - cached.ts < DAILY_ASK_COOLDOWN_MS) {
      // Ak je táto odpoveď už posledná v chate, len otvor okno — neduplikuj
      // ju s každým ďalším klikom na to isté tlačidlo.
      const last = messages[messages.length - 1];
      if (last?.role === "assistant" && last.text === cached.answer) return;
      setMessages((m) => [...m, { role: "user", text: "Čo mám dnes vyriešiť?" }, { role: "assistant", text: cached.answer }]);
      return;
    }
    const answer = await send("Čo mám dnes vyriešiť?");
    if (answer) {
      try { localStorage.setItem(storageKeyBase + "_daily_v3", JSON.stringify({ ts: Date.now(), answer })); } catch {}
    }
  }
  const prevAskTrigger = useRef(askTrigger);
  useEffect(() => {
    if (!open) return;
    const esc = (e) => { if (e.key === "Escape" && !document.body.classList.contains("has-open-modal")) { setOpen(false); document.querySelector(".maskot-fab")?.focus(); } };
    document.addEventListener("keydown", esc);
    return () => document.removeEventListener("keydown", esc);
  }, [open]);
  useEffect(() => {
    if (!askTrigger || askTrigger === prevAskTrigger.current) return;
    prevAskTrigger.current = askTrigger;
    askDaily();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [askTrigger]);

  return (
    <>
      {/* Úchytka na pravom okraji (rozhodnutie 24. 10.) — nezakrýva spodok stránok; panel sa vysunie sprava na celú výšku. */}
      <button
        className={`maskot-fab${open ? " open" : ""}`}
        onClick={() => setOpen((v) => !v)}
        title="maSKot — AI asistent (beta verzia)"
        aria-label={open ? "Zasunúť maSKota" : "Otvoriť maSKota"}
        aria-expanded={open}
      >
        <ChatBubbleIcon size={13} />
        <span>maSKot</span>
      </button>
      {open && (
        <div
          className="maskot-panel"
          style={{
            position: "fixed",
            top: 0,
            right: 0,
            bottom: 0,
            zIndex: 260,
            width: "min(400px, calc(100vw - 24px))",
            background: "var(--panel)",
            borderLeft: "1px solid var(--border)",
            boxShadow: "-8px 0 30px rgba(0,0,0,.22)",
            display: "flex",
            flexDirection: "column",
            overflow: "hidden",
          }}
        >
          <div style={{ padding: "10px 12px", background: "var(--accent-fill)", color: "#fff", fontWeight: 600, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ width: 26, height: 26, borderRadius: 7, background: "#1a1a1a", color: "#e6392e", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                <ChatBubbleIcon size={15} />
              </span>
              maSKot (beta)
            </span>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              {messages.length > 0 && !confirmingClear && (
                <button
                  onClick={() => setConfirmingClear(true)}
                  title="Vymazať rozhovor"
                  style={{ background: "none", border: "none", color: "#fff", cursor: "pointer", fontSize: 13, opacity: 0.85 }}
                >
                  🗑️
                </button>
              )}
              {confirmingClear && (
                <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <button
                    onClick={() => { clearConversation(); setConfirmingClear(false); }}
                    title="Naozaj vymazať celý rozhovor"
                    style={{ background: "#fff", border: "none", color: "var(--accent-fill)", cursor: "pointer", fontSize: 11, fontWeight: 700, borderRadius: 6, padding: "3px 8px" }}
                  >
                    Vymazať?
                  </button>
                  <button
                    onClick={() => setConfirmingClear(false)}
                    title="Zrušiť"
                    style={{ background: "none", border: "none", color: "#fff", cursor: "pointer", fontSize: 13, opacity: 0.85 }}
                  >
                    ✕
                  </button>
                </span>
              )}
              {/* Rozhovor (hands-free) a mikrofón vypnuté 8. 10. — hlasový vstup cez prehliadač/klávesnicu; vrátiť s ElevenLabs. */}
              <button onClick={() => setOpen(false)} aria-label="Zavrieť maSKota" title="Zavrieť" style={{ background: "none", border: "none", color: "#fff", cursor: "pointer", fontSize: 16 }}>✕</button>
            </div>
          </div>
          {conversationMode && (
            <div style={{ padding: "6px 12px", background: "var(--panel-2)", fontSize: 11, color: "var(--text-dim)", textAlign: "center" }}>
              {listening ? "🔴 Počúvam..." : sending ? "Premýšľam..." : "Rozhovor zapnutý — po odpovedi sa spýtaj ďalej."}
            </div>
          )}
          <div ref={scrollRef} style={{ flex: 1, overflowY: "auto", padding: 10, display: "flex", flexDirection: "column", gap: 8 }}>
            {messages.length === 0 && (
              <div style={{ fontSize: 12, color: "var(--text-dim)" }}>Skús napríklad: "kde je stroj GS-2032?" alebo "aké máme voľné nožnicové plošiny vo Zvolene?"</div>
            )}
            {messages.map((m, i) => (
              <div
                key={i}
                style={{
                  alignSelf: m.role === "user" ? "flex-end" : "flex-start",
                  background: m.role === "user" ? "var(--accent-fill)" : "var(--panel-2)",
                  color: m.role === "user" ? "#fff" : "var(--text)",
                  padding: "6px 10px",
                  borderRadius: 8,
                  maxWidth: m.role === "user" ? "85%" : "100%",
                  fontSize: 13,
                }}
              >
                {m.imagePreview && <img src={m.imagePreview} alt="" style={{ maxWidth: "100%", borderRadius: 6, marginBottom: 4, display: "block" }} />}
                <MaskotMessageContent text={m.text} machineByCode={machineByCode} onOpenCard={onOpenCard} navLink={navLink} />
              </div>
            ))}
            {sending && <div style={{ fontSize: 12, color: "var(--text-dim)" }}>maSKot píše...</div>}
          </div>
          {pendingImage && (
            <div style={{ padding: "6px 10px", borderTop: "1px solid var(--border)", display: "flex", alignItems: "center", gap: 8 }}>
              <img src={pendingImage.dataUrl} alt="" style={{ height: 40, borderRadius: 4 }} />
              <span style={{ fontSize: 11, color: "var(--text-dim)", flex: 1 }}>Fotka pripravená na odoslanie</span>
              <button onClick={() => setPendingImage(null)} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 14 }}>✕</button>
            </div>
          )}
          <div style={{ display: "flex", gap: 6, padding: 8, borderTop: "1px solid var(--border)" }}>
            <input type="file" accept="image/*" capture="environment" ref={fileInputRef} onChange={handleFileSelected} style={{ display: "none" }} />
            <button
              onClick={() => fileInputRef.current?.click()}
              disabled={sending}
              title="Priložiť fotku"
              style={{ padding: "4px 10px", border: "1px solid var(--border)", borderRadius: 6, background: "var(--panel-2)", color: "var(--text)", cursor: "pointer" }}
            >
              📷
            </button>
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && send()}
              placeholder="Opýtaj sa maSKota..."
              aria-label="Otázka pre maSKota"
              autoFocus={!window.matchMedia?.("(pointer: coarse)").matches} // na dotyku by hneď vyskočila klávesnica a zakryla rozhovor
              style={{ flex: 1, fontSize: 13 }}
              disabled={sending}
            />
            <button className="btn btn-accent" onClick={() => send()} disabled={sending} style={{ padding: "4px 12px" }}>
              →
            </button>
          </div>
        </div>
      )}
    </>
  );
}

// Len čísla s funkciou — „Kto je dnes kde“ je na obrazovke Dnes (rozhodnutie 7. 10.).
function PhoneDirectoryModal({ employees, onClose }) {
  const [search, setSearch] = useState("");
  const q = search.trim().toLowerCase();
  const list = (employees || [])
    .filter((e) => !e.archived && e.phone)
    .filter((e) => !q || e.name.toLowerCase().includes(q) || roleLabel(e.role).toLowerCase().includes(q) || (e.depo || "").toLowerCase().includes(q))
    .sort((a, b) => a.name.localeCompare(b.name));
  return (
    <Modal title="Telefónny zoznam" onClose={onClose}>
      <Field label="Hľadať meno, rolu alebo depo">
        <input type="search" value={search} onChange={(e) => setSearch(e.target.value)} style={{ width: "100%" }} />
      </Field>
      <div className={list.length ? "flist" : undefined} style={{ maxHeight: "calc(100vh - 240px)", overflowY: "auto", marginBottom: 0 }}>
        {list.length === 0 && <div className="fnote fnote-i">Nikto nezodpovedá hľadaniu.</div>}
        {list.map((e) => (
          <div key={e.id} className="frow" style={{ flexWrap: "nowrap" }}>
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: 15, fontWeight: 600 }}>{e.name}</div>
              <div className="cell-sub">{roleLabel(e.role)}{e.depo ? ` · ${e.depo}` : ""}</div>
            </div>
            <a href={`tel:${e.phone}`} className="btn btn-outline tnum" style={{ textDecoration: "none", whiteSpace: "nowrap", display: "inline-flex", alignItems: "center", gap: 6, fontSize: 15 }}>
              <PhoneIcon size={15} /> {e.phone}
            </a>
          </div>
        ))}
      </div>
    </Modal>
  );
}

function DriverCardModal({ driver, jobs, today, onClose, vehicleSpz }) {
  const d = driver;
  const upcoming = jobs
    .filter((j) => j.driverId === d.id && j.status !== "completed" && (!j.endDate || j.endDate >= today))
    .sort((a, b) => (a.startDate < b.startDate ? -1 : 1));
  const upcomingCount = upcoming.length;
  upcoming.splice(8);

  return (
    <Modal
      eyebrow="Vodič"
      title={<>{d.name}{d.depo && <span className="side-title-sub">{d.depo}</span>}</>}
      onClose={onClose}
      side
      headerExtra={
        <div className="side-summary">
          <div><span>Depo</span><b>{d.depo || "—"}</b></div>
          <div><span>Auto</span><b>{vehicleSpz || "—"}</b></div>
          <div><span>Telefón</span><b className="tnum">{d.phone ? <a href={`tel:${d.phone}`}>{d.phone}</a> : "—"}</b></div>
          <div><span>Nadchádzajúce</span><b className="tnum">{upcomingCount}</b></div>
        </div>
      }
    >
      {/* v1.0.806: depo, auto a telefón sú v súhrne hore; email tu (v súhrne by sa lámal). */}
      <dl className="side-dl">
        <dt>Email</dt><dd>{d.email ? <a href={`mailto:${d.email}`}>{d.email}</a> : "—"}</dd>
      </dl>
      <div className="side-sec">Nadchádzajúce zákazky</div>
      {upcoming.length === 0 ? (
        <div style={{ fontSize: 14, color: "var(--text-dim)", marginBottom: 14 }}>Zatiaľ nič naplánované.</div>
      ) : (
        <dl className="side-dl">
          {upcoming.map((j) => (
            <React.Fragment key={j.id}>
              <dt className="tnum">{fmtDate(j.startDate)}</dt>
              <dd><b>{j.toLocation}</b><span style={{ color: "var(--text-dim)" }}>{j.customer ? " · " + j.customer : ""}</span></dd>
            </React.Fragment>
          ))}
        </dl>
      )}
      <div style={{ fontSize: 13, color: "var(--text-dim)", marginTop: 14 }}>
        Úprava údajov a archivácia sa robí v Administratíve → Zamestnanci.
      </div>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Add Machine Modal
--------------------------------------------------------- */
function AddMachineModal({ existing, machineModels, machines, onClose, onSave, onCreateModel }) {
  const NEW_MODEL_VALUE = "__new__";
  const [code, setCode] = useState(existing?.code || "");
  const [note, setNote] = useState(existing?.note || "");
  const [objekt, setObjekt] = useState(existing?.objekt || "Požičovňový stroj");
  const [type, setType] = useState(existing?.type || "");
  const [depo, setDepo] = useState(existing?.depo || "");
  const [revizia, setRevizia] = useState(existing?.revizia || "");
  const [reviziaEZ, setReviziaEZ] = useState(existing?.reviziaEZ || "");
  const [uradnaSkuska, setUradnaSkuska] = useState(existing?.uradnaSkuska || "");
  const [trackRevisions, setTrackRevisions] = useState(existing ? existing.trackRevisions !== false : true);
  const [trackRevisionsEZ, setTrackRevisionsEZ] = useState(existing ? existing.trackRevisionsEZ !== false : true);
  const [trackUradnaSkuska, setTrackUradnaSkuska] = useState(existing ? existing.trackUradnaSkuska !== false : true);
  const [prepareForRental, setPrepareForRental] = useState(true);
  const [creatingNewModel, setCreatingNewModel] = useState(false);
  const [newModelCategory, setNewModelCategory] = useState("");
  const [newModelLiftHeight, setNewModelLiftHeight] = useState("");
  const [newModelOutreach, setNewModelOutreach] = useState("");
  const [newModelWidth, setNewModelWidth] = useState("");
  const [newModelCapacity, setNewModelCapacity] = useState("");
  const [newModelOutriggers, setNewModelOutriggers] = useState("");
  const [newModelWeight, setNewModelWeight] = useState("");

  const isStroj = objekt === "Požičovňový stroj";
  const isExterny = objekt === "Externý stroj";
  const canSave = code.trim() && depo.trim() && (isExterny || type.trim());
  // Len upozornenie, nič neblokuje — sériové číslo sa zámerne dá aj tak uložiť
  // (napr. legitímne znovupoužitie čísla po vyradenom stroji).
  const duplicateMachine = code.trim()
    ? (machines || []).find(
        (m) => m.id !== existing?.id && (m.code || "").trim().toLowerCase() === code.trim().toLowerCase()
      )
    : null;

  function handleSave() {
    const patch = {
      code: code.trim(),
      note: note.trim(),
      objekt,
      type: isExterny ? "Externý stroj" : type.trim(),
      depo: depo.trim(),
    };
    if (isStroj) {
      patch.revizia = revizia;
      patch.reviziaEZ = reviziaEZ;
      patch.uradnaSkuska = uradnaSkuska;
      patch.trackRevisions = trackRevisions;
      patch.trackRevisionsEZ = trackRevisionsEZ;
      patch.trackUradnaSkuska = trackUradnaSkuska;
      if (creatingNewModel && type.trim()) {
        onCreateModel({
          name: type.trim(),
          category: newModelCategory,
          liftHeight: newModelLiftHeight,
          outreach: newModelOutreach,
          width: newModelWidth,
          capacity: newModelCapacity,
          outriggers: newModelOutriggers === "ano" ? true : newModelOutriggers === "nie" ? false : null,
          weight: newModelWeight,
        });
      }
    } else {
      // Externý stroj a Príslušenstvo nemajú revízie/skúšky — vyprázdni pole,
      // nech pri prepnutí Objektu na existujúcom zázname nezostane nič zabudnuté.
      patch.revizia = "";
      patch.reviziaEZ = "";
      patch.uradnaSkuska = "";
      patch.trackRevisions = false;
      patch.trackRevisionsEZ = false;
      patch.trackUradnaSkuska = false;
    }
    onSave(patch, !existing && prepareForRental);
  }

  return (
    <Modal title={existing ? "Upraviť údaje stroja" : "Pridať stroj"} onClose={onClose} xwide={(isStroj || !existing)}>
      <div className="job-form-cols">
        <fieldset>
          <legend>STROJ</legend>
      <Field label="Sériové číslo *"><input value={code} onChange={(e) => setCode(e.target.value)} style={{ width: "100%" }} /></Field>
      {duplicateMachine && (
        <div className="fnote fnote-y" style={{ marginTop: -6 }}>
          ⚠ Stroj s týmto sériovým číslom už existuje: <b className="tnum">{duplicateMachine.code}</b>
          {duplicateMachine.type ? ` · ${duplicateMachine.type}` : ""}
          {duplicateMachine.depo ? ` · ${duplicateMachine.depo}` : ""}
          {duplicateMachine.archived ? " (archivovaný)" : ""}. Uložením vznikne duplicita.
        </div>
      )}
      <Field label="Objekt *">
        <select value={objekt} onChange={(e) => setObjekt(e.target.value)} style={{ width: "100%" }}>
          {MACHINE_OBJEKT_OPTIONS.map((o) => <option key={o} value={o}>{o}</option>)}
        </select>
      </Field>

      {isStroj && (
        <Field label="Model stroja *">
          <select
            value={creatingNewModel ? NEW_MODEL_VALUE : type}
            onChange={(e) => {
              if (e.target.value === NEW_MODEL_VALUE) {
                setCreatingNewModel(true);
                setType("");
              } else {
                setCreatingNewModel(false);
                setType(e.target.value);
              }
            }}
            style={{ width: "100%" }}
          >
            <option value="">— vybrať model —</option>
            {[...machineModels].sort((a, b) => (a.name || "").localeCompare(b.name || "")).map((mm) => (
              <option key={mm.id} value={mm.name}>{mm.name}</option>
            ))}
            <option value={NEW_MODEL_VALUE}>+ Vytvoriť nový model...</option>
          </select>
          {creatingNewModel && (
            <div style={{ marginTop: 10, padding: 12, background: "var(--panel-2)", borderRadius: 8 }}>
              <Field label="Názov nového modelu *">
                <input value={type} onChange={(e) => setType(e.target.value)} placeholder="napr. GS-3246" style={{ width: "100%" }} />
              </Field>
              <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                <Field label="Kategória">
                  <select value={newModelCategory} onChange={(e) => setNewModelCategory(e.target.value)} style={{ width: "100%" }}>
                    <option value="">— vybrať —</option>
                    {MACHINE_CATEGORY_OPTIONS.map((c) => <option key={c} value={c}>{c}</option>)}
                  </select>
                </Field>
                <Field label="Pracovná výška (m)"><input type="number" value={newModelLiftHeight} onChange={(e) => setNewModelLiftHeight(e.target.value)} style={{ width: "100%" }} /></Field>
                <Field label="Stranový dosah (m)"><input type="number" value={newModelOutreach} onChange={(e) => setNewModelOutreach(e.target.value)} style={{ width: "100%" }} /></Field>
                <Field label="Šírka (m)"><input type="number" value={newModelWidth} onChange={(e) => setNewModelWidth(e.target.value)} style={{ width: "100%" }} /></Field>
                <Field label="Nosnosť (kg)"><input type="number" value={newModelCapacity} onChange={(e) => setNewModelCapacity(e.target.value)} style={{ width: "100%" }} /></Field>
                <Field label="Podpery">
                  <select value={newModelOutriggers} onChange={(e) => setNewModelOutriggers(e.target.value)} style={{ width: "100%" }}>
                    <option value="">—</option>
                    <option value="ano">Áno</option>
                    <option value="nie">Nie</option>
                  </select>
                </Field>
                <Field label="Hmotnosť (kg)"><input type="number" value={newModelWeight} onChange={(e) => setNewModelWeight(e.target.value)} style={{ width: "100%" }} /></Field>
              </div>
            </div>
          )}
        </Field>
      )}
      {objekt === "Príslušenstvo" && (
        <Field label="Názov príslušenstva *"><input value={type} onChange={(e) => setType(e.target.value)} style={{ width: "100%" }} /></Field>
      )}
      {isExterny && (
        <div className="fnote fnote-i">
          Externý stroj — model sa tu nezadáva, zobrazí sa ako "Externý stroj". Pri konkrétnej zákazke sa dá názov upraviť (napr. na skutočný model subdodávky).
        </div>
      )}

      <Field label="Depo *">
        <select value={depo} onChange={(e) => setDepo(e.target.value)} style={{ width: "100%" }}>
          <option value="">— vybrať depo —</option>
          {DEPO_OPTIONS.map((d) => <option key={d} value={d}>{d}</option>)}
        </select>
      </Field>
      <Field label="Poznámka"><input value={note} onChange={(e) => setNote(e.target.value)} placeholder="Voliteľné, napr. VOLVO nie" style={{ width: "100%" }} /></Field>
        </fieldset>
        {(isStroj || !existing) && (
        <fieldset>
          {isStroj && (
            <>
            <legend>TERMÍNY REVÍZIÍ</legend>
            <div className="fgrid2">
              <Field label="Najbližšia revízia ZZ"><input type="date" value={revizia} onChange={(e) => setRevizia(e.target.value)} style={{ width: "100%" }} /></Field>
              <label className="fck" style={{ marginTop: 32 }}>
                <input type="checkbox" checked={trackRevisions} onChange={(e) => setTrackRevisions(e.target.checked)} />
                <span>Sledovať revíziu ZZ</span>
              </label>
            </div>
            <div className="fgrid2">
              <Field label="Najbližšia revízia EZ"><input type="date" value={reviziaEZ} onChange={(e) => setReviziaEZ(e.target.value)} style={{ width: "100%" }} /></Field>
              <label className="fck" style={{ marginTop: 32 }}>
                <input type="checkbox" checked={trackRevisionsEZ} onChange={(e) => setTrackRevisionsEZ(e.target.checked)} />
                <span>Sledovať revíziu EZ</span>
              </label>
            </div>
            <div className="fgrid2">
              <Field label="Najbližšia úradná skúška"><input type="date" value={uradnaSkuska} onChange={(e) => setUradnaSkuska(e.target.value)} style={{ width: "100%" }} /></Field>
              <label className="fck" style={{ marginTop: 32 }}>
                <input type="checkbox" checked={trackUradnaSkuska} onChange={(e) => setTrackUradnaSkuska(e.target.checked)} />
                <span>Sledovať úradnú skúšku</span>
              </label>
            </div>
            <div className="fhint" style={{ marginTop: -4, marginBottom: 14 }}>Niektoré stroje revíziu/skúšku proste nemajú — vtedy zrušte „Sledovať“.</div>
            </>
          )}
          {!existing && (
            <>
              <div className="flegend">PO ULOŽENÍ</div>
              <label className="fck">
                <input type="checkbox" checked={prepareForRental} onChange={(e) => setPrepareForRental(e.target.checked)} />
                <span>Pripraviť do požičovne<small>založí poškodenie „Príprava do požičovne"; kým sa nevyrieši, na stroj sa nedá vytvoriť zákazka</small></span>
              </label>
            </>
          )}
        </fieldset>
        )}
      </div>

      <FormFoot missing={[!code.trim() && "sériové číslo", !isExterny && !type.trim() && (objekt === "Príslušenstvo" ? "názov" : "model"), !depo.trim() && "depo"].filter(Boolean)}>
        <button className="btn btn-accent" disabled={!canSave} onClick={handleSave}>
          {existing ? "Uložiť zmeny" : "Uložiť"}
        </button>
      </FormFoot>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Autá (vozový park) — zoznam, pridanie/úprava, karta so STK/EK
--------------------------------------------------------- */
function vehicleDateStatus(date, today) {
  // cls: "" = obyčajný text (badge len na termíny, ktoré si to zaslúžia).
  if (!date) return { cls: "", label: "—" };
  if (date < today) return { cls: "badge-danger", label: "po termíne" };
  const daysLeft = Math.round((new Date(date + "T00:00:00") - new Date(today + "T00:00:00")) / 86400000);
  if (daysLeft <= 30) return { cls: "badge-warn", label: `o ${plural(daysLeft, "deň", "dni", "dní")}` };
  return { cls: "", label: "" };
}
function VehiclesView({ vehicles, employees, today, onAdd, onEdit, onOpenCard, onDelete }) {
  const employeeById = Object.fromEntries(employees.map((e) => [e.id, e]));
  return (
    <div>
      <h1 className="page-h1">Autá</h1>
      <p className="page-intro">
        Vozový park — STK a emisná kontrola (jeden spoločný termín, robia sa vždy naraz). Priradená osoba dostane upozornenie 30 dní vopred a klikom naň otvorí kartu auta (aj bez prístupu do Administratívy).
      </p>
      <div className="tbar" style={{ justifyContent: "flex-end" }}>
        <button className="btn btn-accent" onClick={onAdd}>+ Pridať auto</button>
      </div>
      <div className="panel jobs-wrap" style={{ boxShadow: "none", borderRadius: 12 }}>
        <table className="table-cards jobs-table">
          <thead>
            <tr>
              <th>ŠPZ</th>
              <th>Značka / model</th>
              <th>Priradená osoba</th>
              <th>STK/EK</th>
              <th><span className="sr-only">Akcie</span></th>
            </tr>
          </thead>
          <tbody>
            {vehicles.length === 0 && (
              <tr><td className="td-plain" colSpan={5} style={{ textAlign: "center", padding: 30, color: "var(--text-dim)" }}>Zatiaľ žiadne autá.</td></tr>
            )}
            {vehicles.map((v) => {
              const stkEk = vehicleDateStatus(v.stkEkDate, today);
              return (
                <tr key={v.id}>
                  <td className="td-plain tnum" style={{ fontWeight: 700, cursor: "pointer" }} onClick={() => onOpenCard(v)}>{v.spz || "—"}</td>
                  <td data-label="Značka / model">{v.znacka || "—"}</td>
                  <td data-label="Priradená osoba">{employeeById[v.assignedEmployeeId]?.name || <span style={{ color: "var(--text-dim)" }}>— nepriradené —</span>}</td>
                  <td data-label="STK/EK" className="tnum">{v.stkEkDate ? <>{fmtDate(v.stkEkDate)}{stkEk.cls && stkEk.label ? <span className={`spill ${stkEk.cls === "badge-danger" ? "spill-problem" : "spill-wait"}`} style={{ marginLeft: 8 }}>{stkEk.cls === "badge-danger" ? "⚠ " : ""}{stkEk.label}</span> : null}</> : <span style={{ color: "var(--text-dim)" }}>—</span>}</td>
                  <td className="td-actions" style={{ textAlign: "right", whiteSpace: "nowrap" }}>
                    <button className="btn btn-outline" onClick={() => onEdit(v)}>Upraviť</button>{" "}
                    <KebabMenu label="⋯" name="Ďalšie akcie" actions={[{ label: "Zmazať", danger: true, onClick: () => onDelete(v) }]} />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}
function AddVehicleModal({ existing, employees, onClose, onSave }) {
  const [spz, setSpz] = useState(existing?.spz || "");
  const [znacka, setZnacka] = useState(existing?.znacka || "");
  const [assignedEmployeeId, setAssignedEmployeeId] = useState(existing?.assignedEmployeeId || "");
  const [stkEkDate, setStkEkDate] = useState(existing?.stkEkDate || existing?.stkDate || existing?.ekDate || "");
  const canSave = spz.trim();
  return (
    <Modal title={existing ? "Upraviť auto" : "Pridať auto"} onClose={onClose}>
      <div className="fgrid2">
        <Field label="ŠPZ *"><input value={spz} onChange={(e) => setSpz(e.target.value)} style={{ width: "100%" }} /></Field>
        <Field label="Značka / model"><input value={znacka} onChange={(e) => setZnacka(e.target.value)} style={{ width: "100%" }} /></Field>
      </div>
      <Field label="Priradená osoba">
        <select value={assignedEmployeeId} onChange={(e) => setAssignedEmployeeId(e.target.value)} style={{ width: "100%" }}>
          <option value="">— nepriradené —</option>
          {employees.filter((e) => !e.archived).sort((a, b) => a.name.localeCompare(b.name)).map((e) => (
            <option key={e.id} value={e.id}>{e.name}</option>
          ))}
        </select>
        <div className="fhint">Dostáva upozornenia (30 dní pred STK/EK).</div>
      </Field>
      <Field label="Dátum platnosti STK/EK"><input type="date" value={stkEkDate} onChange={(e) => setStkEkDate(e.target.value)} style={{ width: "100%" }} /></Field>
      <FormFoot missing={!spz.trim() ? ["ŠPZ"] : []}>
      <button
        className="btn btn-accent"
        disabled={!canSave}
        onClick={() => onSave({ spz: spz.trim(), znacka: znacka.trim(), assignedEmployeeId: assignedEmployeeId || null, stkEkDate: stkEkDate || null })}
      >
        {existing ? "Uložiť zmeny" : "Uložiť"}
      </button>
      </FormFoot>
    </Modal>
  );
}
// Karta jedného auta — otvára sa buď zo zoznamu v Administratíve, alebo priamo
// z notifikácie (klik na upozornenie), a to aj bez prístupu do Administratívy.
function VehicleCardModal({ vehicle, employees, today, user, myEmployee, onClose, onSetDate, onSnooze }) {
  const [editing, setEditing] = useState(false);
  const [newDate, setNewDate] = useState("");
  const employee = employees.find((e) => e.id === vehicle.assignedEmployeeId);
  // Karta sa dá otvoriť aj priamo odkazom z notifikácie (aj cez URL pri studenom
  // štarte) — bez tejto poistky by na zápis dosiahol ktokoľvek, kto sa k
  // takémuto odkazu dostane, nielen ten, komu je auto naozaj pridelené.
  const canEdit = can(user, "vehicle_manage") || (myEmployee && myEmployee.id === vehicle.assignedEmployeeId);
  const date = vehicle.stkEkDate;
  const status = vehicleDateStatus(date, today);
  const pillCls = status.cls === "badge-danger" ? "spill-problem" : status.cls === "badge-warn" ? "spill-wait" : "";

  return (
    <Modal
      eyebrow="Auto"
      title={<>{vehicle.spz || "—"}{vehicle.znacka && <span className="side-title-sub">{vehicle.znacka}</span>}{pillCls && <span className={`spill ${pillCls}`}>{pillCls === "spill-problem" ? "⚠ " : ""}STK/EK {status.label}</span>}</>}
      onClose={onClose}
      side
      headerExtra={
        <div className="side-summary">
          <div><span>Typ</span><b>{vehicle.znacka || "—"}</b></div>
          <div><span>Priradené</span><b>{employee?.name || "— nikto —"}</b></div>
          <div><span>STK/EK</span><b className="tnum">{date ? fmtDate(date) : "— nezadané —"}</b></div>
          <div><span>Naposledy zmenené</span><b className="tnum">{vehicle.stkEkChangedAt ? fmtDate(vehicle.stkEkChangedAt) : "—"}</b></div>
        </div>
      }
      footer={canEdit && !editing && (
        <>
          <button className="btn btn-ghost" onClick={() => onSnooze(vehicle.id, 1)}>Odložiť o 24 h</button>
          <button className="btn btn-ghost" onClick={() => onSnooze(vehicle.id, 7)}>Odložiť o 7 dní</button>
          <button className="btn btn-accent" style={{ marginLeft: "auto" }} onClick={() => { setEditing(true); setNewDate(""); }}>Hotovo — nový dátum</button>
        </>
      )}
    >
      <dl className="side-dl">
        <dt>ŠPZ</dt><dd>{vehicle.spz || "—"}</dd>
        <dt>Typ</dt><dd>{vehicle.znacka || "—"}</dd>
        <dt>Priradené</dt><dd>{employee?.name || "— nikto —"}</dd>
        <dt>STK/EK</dt>
        <dd className={`tnum${status.cls === "badge-danger" ? " warn" : ""}`}>
          {date ? `${status.cls === "badge-danger" ? "⚠ " : ""}${fmtDate(date)}${status.cls && status.label ? " · " + status.label : ""}` : "— nezadané —"}
        </dd>
        {vehicle.stkEkChangedAt && <><dt>Naposledy zmenené</dt><dd className="tnum">{fmtDate(vehicle.stkEkChangedAt)}{vehicle.stkEkChangedBy ? ` · ${vehicle.stkEkChangedBy}` : ""}</dd></>}
      </dl>
      {!canEdit ? (
        <div style={{ fontSize: 13, color: "var(--text-dim)", marginTop: 14 }}>Len na čítanie — zadať nový dátum smie priradený zamestnanec alebo vedúci.</div>
      ) : editing ? (
        <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", marginTop: 14 }}>
          <input type="date" value={newDate} onChange={(e) => setNewDate(e.target.value)} />
          <button className="btn btn-accent" disabled={!newDate} onClick={() => { onSetDate(vehicle.id, newDate); setEditing(false); setNewDate(""); }}>Uložiť</button>
          <button className="btn btn-ghost" onClick={() => setEditing(false)}>Zrušiť</button>
        </div>
      ) : null}
    </Modal>
  );
}

