  const [portalQr, setPortalQr] = useState(null);
  const [expandedChecklist, setExpandedChecklist] = useState(null); // null | "chooser" — výber, ktorý z dvoch checklistov zobraziť ako náhľad
  const portalLink = job.publicToken
