// Okno výkazu: šofér (len externí; pre samotného šoféra pevne on) + obdobie → náhľad → Excel / PDF.
function DriverReportModal({ drivers, selfOnly, selfId, issuedBy, onClose }) {
  const today = todayISO();
  const mon = (iso) => { const d = new Date(iso + "T00:00:00"); return addDaysISO(iso, -((d.getDay() + 6) % 7)); };
  const monthStart = (iso) => iso.slice(0, 8) + "01";
  const prevMonthEnd = addDaysISO(monthStart(today), -1);
  const presets = [
    ["Tento týždeň", mon(today), addDaysISO(mon(today), 6)],
    ["Minulý týždeň", addDaysISO(mon(today), -7), addDaysISO(mon(today), -1)],
    ["Tento mesiac", monthStart(today), addDaysISO(monthStart(addDaysISO(monthStart(today), 31)), -1)],
    ["Minulý mesiac", monthStart(prevMonthEnd), prevMonthEnd],
  ];
  const [driverId, setDriverId] = useState(selfOnly ? "" : drivers[0]?.id || "");
  const [from, setFrom] = useState(presets[2][1]);
  const [to, setTo] = useState(presets[2][2]);
  const [rep, setRep] = useState(null);
  const [err, setErr] = useState("");
  useEffect(() => {
    setErr("");
    if ((!selfOnly && !driverId) || !from || !to || from > to) { setRep(null); return; }
    let live = true;
    supabase.rpc("driver_transport_report", { p_driver_id: selfOnly ? selfId || null : driverId, p_from: from, p_to: to }).then(({ data, error }) => {
      if (!live) return;
      if (error) { setRep(null); setErr(navigator.onLine ? "Výkaz sa nepodarilo načítať." : "Výkaz sa dá načítať len so signálom."); console.error("driver_transport_report", error); }
      else setRep(data);
    });
    return () => { live = false; };
  }, [selfOnly, driverId, from, to]);
  const rows = rep?.rows || [];
  // Celý mesiac → „Október 2026“, inak rozsah dátumov.
  const monthName = from ? new Date(from + "T12:00:00").toLocaleDateString("sk-SK", { month: "long" }) : "";
  const period = from && to && from.slice(8) === "01" && to === addDaysISO(monthStart(addDaysISO(from, 31)), -1) ? `${monthName.charAt(0).toUpperCase()}${monthName.slice(1)} ${from.slice(0, 4)}` : from && to ? `${fmtDate(from)} – ${fmtDate(to)}` : "";
  return (
    <Modal eyebrow="Výkaz prepráv externého šoféra" title={period || "Výkaz prepráv externého šoféra"} onClose={onClose} wide>
      <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: selfOnly ? "1fr 1fr" : "2fr 1fr 1fr", gap: "0 12px" }}>
        {!selfOnly && (
          <Field label="Šofér">
            <select value={driverId} onChange={(e) => setDriverId(e.target.value)} style={{ width: "100%" }}>
              {drivers.length === 0 && <option value="">— žiadny externý šofér —</option>}
              {drivers.map((d) => <option key={d.id} value={d.id}>{d.name}{d.carrierName ? ` — ${d.carrierName}` : ""}{d.archived ? " (archivovaný)" : ""}</option>)}
            </select>
          </Field>
        )}
        <Field label="Od"><input type="date" value={from} onChange={(e) => setFrom(e.target.value)} style={{ width: "100%" }} /></Field>
        <Field label="Do"><input type="date" value={to} onChange={(e) => setTo(e.target.value)} style={{ width: "100%" }} /></Field>
      </div>
      <div className="seg" role="group" aria-label="Obdobie" style={{ marginBottom: 14, flexWrap: "wrap" }}>
        {presets.map(([label, f, t]) => (
          <button key={label} type="button" aria-pressed={from === f && to === t} className={from === f && to === t ? "on" : ""} onClick={() => { setFrom(f); setTo(t); }}>{label}</button>
        ))}
      </div>
      {err && <div className="fnote fnote-r">⚠ {err}</div>}
      {rep && (
        <>
          <div className="tnum" style={{ fontSize: 15, marginBottom: 8 }}>
            <strong>{rows.length}</strong> {rows.length === 1 ? "vykonaná preprava" : rows.length >= 2 && rows.length <= 4 ? "vykonané prepravy" : "vykonaných prepráv"} — {DR_TYPES.map((t) => `${t.toLowerCase()}y ${rows.filter((r) => r.type === t).length}`).join(" · ")}
          </div>
          <div style={{ overflow: "auto", maxHeight: 320, border: "1px solid var(--border)", borderRadius: 8, marginBottom: 10 }}>
            <table className="ftable tnum" style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead><tr>{["Dátum", "Typ", "Zmluva", "Zákazník", "Stroj", "Trasa"].map((h) => <th key={h} style={{ position: "sticky", top: 0, zIndex: 1 }}>{h}</th>)}</tr></thead>
              <tbody>
                {rows.length === 0 && <tr><td colSpan={6} style={{ color: "var(--text-dim)" }}>Za toto obdobie žiadne vykonané prepravy.</td></tr>}
                {rows.map((r, i) => (
                  <tr key={i} style={{ borderTop: "1px solid var(--border)" }}>
                    <td style={{ whiteSpace: "nowrap" }}>{fmtDate(r.date)}</td><td>{r.type}</td><td>{r.contract || "—"}</td>
                    <td>{r.customer || (r.type === "Prevoz" ? "presun medzi depami" : "—")}</td>
                    <td>{[r.machineType, r.machineCode].filter(Boolean).join(" · ")}</td><td>{r.from || "—"} → {r.to || "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="fhint" style={{ marginBottom: 12 }}>Rátajú sa len vykonané prepravy: podpísaný protokol vývozu / zvozu a prevoz označený ako prevezený, podľa dátumu vykonania.</div>
        </>
      )}
      <FormFoot cancel={false}>
        <button className="btn btn-outline" disabled={!rep} onClick={() => downloadDriverReportCsv(rep, from, to)}>Stiahnuť Excel</button>
        <button className="btn btn-accent" disabled={!rep} onClick={() => openPrintableDriverReport(rep, from, to, issuedBy)}>PDF / tlač</button>
      </FormFoot>
    </Modal>
  );
}

function openPrintablePartHandover(rec) {
  const esc = (s) => (s ?? "").toString().replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  const escAttr = (s) => esc(s).replace(/"/g, "&quot;");
  const items = rec.items || [];
  const priced = items.filter((it) => phPrice(it.price) != null);
  const total = priced.reduce((s, it) => s + phPrice(it.price) * phQty(it.qty), 0);
  const qtyTotal = items.reduce((s, it) => s + (phQty(it.qty) || 0), 0);
  const when = rec.handedAt ? new Date(rec.handedAt).toLocaleString("sk-SK", { timeZone: "Europe/Bratislava", day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }) : (rec.date ? fmtDate(rec.date) : "");
  const method = rec.method === "delivery" ? `Doručenie${rec.deliveryAddress ? ` – ${rec.deliveryAddress}` : ""}` : `Osobný odber${rec.depo ? ` – depo ${rec.depo}` : ""}`;
  const sig = (url, label) => `<div class="sigbox"><div class="siglabel">${label}</div>${safeImgUrl(url) ? `<img class="sigimg" src="${escAttr(url)}">` : `<div class="signone">— zatiaľ bez podpisu —</div>`}</div>`;
  const customerSig = rec.customerAbsent
    ? `<div class="sigbox"><div class="siglabel">Prevzal (odberateľ)</div><div class="signone" style="color:#c62828">Odberateľ nebol prítomný — bez podpisu</div>${(rec.absentPhotos || []).filter(safeImgUrl).map((u) => `<img class="photo" src="${escAttr(u)}">`).join("")}</div>`
    : sig(rec.customerSignature, `Prevzal (odberateľ)${rec.customerName ? `: ${esc(rec.customerName)}` : ""}`);
  const rows = items.map((it, i) => {
    const p = phPrice(it.price);
    return `<tr><td>${i + 1}</td><td>${esc(it.name)}</td><td>${esc(it.pn)}</td><td class="n">${esc(it.qty)} ks</td><td class="n">${p != null ? phMoney(p) : "—"}</td><td class="n">${p != null ? phMoney(p * phQty(it.qty)) : "—"}</td></tr>`;
  }).join("");
  const docHtml = `<!DOCTYPE html><html lang="sk"><head><meta charset="UTF-8"><title>Dodací list ${esc(rec.dlNumber || "")} ${esc(rec.customer)}</title><style>
  * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  body { font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #1a1a1a; margin: 0; background: #e8e8e8; }
  .toolbar { text-align: center; padding: 10px 0; position: sticky; top: 0; background: #e8e8e8; box-shadow: 0 2px 6px rgba(0,0,0,.08); }
  .btn { padding: 7px 14px; border-radius: 6px; font-weight: 600; font-size: 13px; cursor: pointer; border: none; background: #E30613; color: #fff; }
  .page { width: 210mm; min-height: 297mm; margin: 16px auto; background: #fff; padding: 14mm 14mm 12mm; box-shadow: 0 2px 12px rgba(0,0,0,.15); display: flex; flex-direction: column; }
  .body-content { flex: 1; } .head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 14px; } .logo { height: 34px; }
  h1 { font-size: 18px; color: #E30613; margin: 22px 0 0; text-align: right; } .sub { font-size: 12px; color: #555; margin-top: 4px; text-align: right; }
  .meta { display: grid; grid-template-columns: 1fr 1fr; gap: 5px 26px; margin-bottom: 18px; } .meta > div { display: flex; } .meta span.l { color: #666; flex: 0 0 auto; min-width: 120px; margin-right: 8px; }
  .colhead { font-weight: bold; font-size: 13px; border-bottom: 2px solid #E30613; padding-bottom: 5px; margin: 6px 0 7px; }
  table { width: 100%; border-collapse: collapse; margin-bottom: 6px; } th { text-align: left; font-size: 11px; color: #666; font-weight: normal; border-bottom: 1px solid #ccc; padding: 5px 4px; }
  td { padding: 6px 4px; border-bottom: 1px solid #eee; } td.n, th.n { text-align: right; white-space: nowrap; } .total td { border-top: 2px solid #ccc; border-bottom: none; font-weight: bold; }
  .note { margin: 10px 0 16px; padding: 8px 10px; background: #fafafa; border-left: 3px solid #E30613; font-size: 11.5px; }
  .sigs { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 10px; } .sigbox { border: 1px solid #ccc; border-radius: 4px; padding: 7px; }
  .siglabel { font-size: 11px; color: #666; margin-bottom: 4px; } .sigimg { max-width: 100%; height: 64px; } .signone { font-size: 11px; color: #999; min-height: 40px; display: flex; align-items: center; }
  .photo { height: 70px; margin: 4px 4px 0 0; border-radius: 3px; } .confirm { font-size: 11px; color: #444; margin-top: 14px; } .corr { font-size: 11px; color: #c62828; margin-top: 6px; }
  .footer { margin-top: auto; padding-top: 12px; border-top: 1px solid #ccc; font-size: 11px; color: #555; line-height: 1.7; } .footer .legal { margin-top: 6px; color: #888; font-size: 10px; }
  @media print { .toolbar { display: none; } body { background: #fff; } .page { box-shadow: none; margin: 0; } @page { size: A4; margin: 0; } }
</style></head><body>
<div class="toolbar"><button class="btn" onclick="window.print()">🖨 Tlačiť / uložiť ako PDF</button></div>
<div class="page"><div class="body-content">
<div class="head"><img class="logo" src="data:image/png;base64,${MATECO_LOGO_B64}" alt="mateco"><div><h1>DODACÍ LIST – VÝDAJ NÁHRADNÝCH DIELOV</h1><div class="sub">Číslo: ${esc(rec.dlNumber || "")}</div></div></div>
<div class="meta">
<div><span class="l">Odberateľ:</span>${esc(rec.customer)}</div><div><span class="l">Dátum odovzdania:</span>${esc(when)}</div>
<div><span class="l">Adresa:</span>${esc(rec.customerAddress)}</div><div><span class="l">Spôsob:</span>${esc(method)}</div>
<div><span class="l">Kontakt:</span>${esc([rec.contactName, rec.contactPhone].filter(Boolean).join(", "))}</div><div><span class="l">K stroju:</span>${esc(rec.machineText)}</div>
<div><span class="l">Vypracoval:</span>${esc(rec.createdBy)}</div><div><span class="l">Číslo objednávky zákazníka:</span>${esc(rec.orderNumber)}</div>
</div>
<div class="colhead">Vydané diely</div>
<table><tr><th>#</th><th>Názov dielu</th><th>PN (číslo dielu)</th><th class="n">Počet</th><th class="n">Cena/ks bez DPH</th><th class="n">Spolu bez DPH</th></tr>${rows}
<tr class="total"><td></td><td colspan="2">Spolu</td><td class="n">${qtyTotal} ks</td><td></td><td class="n">${priced.length ? phMoney(total) : "—"}</td></tr></table>
${rec.note || rec.handoverNote ? `<div class="note">${rec.note ? `<b>Poznámka:</b> ${esc(rec.note)}` : ""}${rec.note && rec.handoverNote ? "<br>" : ""}${rec.handoverNote ? `<b>Pri odovzdaní:</b> ${esc(rec.handoverNote)}` : ""}</div>` : ""}
<div class="colhead">Odovzdanie a prevzatie</div>
<div class="sigs">${sig(rec.handerSignature, `Odovzdal (mateco)${rec.handedBy ? `: ${esc(rec.handedBy)}` : ""}`)}${customerSig}</div>
${rec.correctedAt ? `<div class="corr">Opravené dispečerom ${esc(fmtDate(toLocalISO(new Date(rec.correctedAt))))}${rec.correctedBy ? ` (${esc(rec.correctedBy)})` : ""}.</div>` : ""}
<div class="confirm">Odberateľ svojím podpisom potvrdzuje prevzatie vyššie uvedených dielov v uvedenom množstve a bez zjavných vád. Ceny sú uvedené bez DPH, ak sú vyplnené; záväzná je faktúra.</div>
</div>
<div class="footer">mateco Slovakia s.r.o. · Strážska cesta 7892 · 960 01 Zvolen<br>T +421 (0)45 5410763 · www.matecoslovakia.sk · info@matecoslovakia.sk<br>Zásady ochrany osobných údajov: ${PRIVACY_URL}<br>IČO 36620114 · DIČ 2020083076 · IČ DPH SK2020083076 · ČSOB banka · IBAN SK51 7500 0000 0040 1776 6094 · SWIFT CEKO SKBX<div class="legal">Spoločnosť je zapísaná v Obchodnom registri Okresného súdu Banská Bystrica, vložka číslo 8576/S, oddiel s.r.o.</div></div>
</div></body></html>`;
  if (_printProtocolOpenListener) _printProtocolOpenListener(docHtml);
  else console.error("Zobrazenie dodacieho listu ešte nie je pripravené.");
  return docHtml;
}

// Údaje výdaja (zákazník, spôsob, diely…) — spoločné pre zadanie dispečerom aj vypísanie v teréne.
function PartHandoverFields({ value, onChange, customers, machines, withPrices }) {
  const v = value;
  const set = (patch) => onChange({ ...v, ...patch });
  const items = v.items && v.items.length ? v.items : [{ name: "", pn: "", qty: "", price: "" }];
  const setItem = (i, patch) => set({ items: items.map((it, idx) => (idx === i ? { ...it, ...patch } : it)) });
  const pickCustomer = (name) => {
    const c = (customers || []).find((x) => (x.firma || "").toLowerCase() === name.trim().toLowerCase());
    const contact = c?.contacts?.[0];
    set({ customer: name, ...(c ? { customerId: c.id, contactName: v.contactName || contact?.name || c.kontakt || "", contactPhone: v.contactPhone || contact?.phone || c.telefon || "", customerEmail: v.customerEmail || contact?.email || c.email || "" } : { customerId: null }) });
  };
  return (
    <div>
      <Field label="Odberateľ (zákazník) *">
        <input list="ph-customers" value={v.customer || ""} onChange={(e) => pickCustomer(e.target.value)} placeholder="Firma zo zoznamu alebo nový názov" style={{ width: "100%" }} />
        <datalist id="ph-customers">{(customers || []).map((c) => <option key={c.id} value={c.firma} />)}</datalist>
      </Field>
      <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
        <Field label="Adresa"><input value={v.customerAddress || ""} onChange={(e) => set({ customerAddress: e.target.value })} style={{ width: "100%" }} /></Field>
        <Field label="Kontaktná osoba"><input value={v.contactName || ""} onChange={(e) => set({ contactName: e.target.value })} style={{ width: "100%" }} /></Field>
        <Field label="Telefón"><input value={v.contactPhone || ""} onChange={(e) => set({ contactPhone: e.target.value })} style={{ width: "100%" }} /></Field>
        <Field label="Email"><input type="email" value={v.customerEmail || ""} onChange={(e) => set({ customerEmail: e.target.value })} style={{ width: "100%" }} /></Field>
        <Field label="Spôsob odovzdania">
          <select value={v.method || "pickup"} onChange={(e) => set({ method: e.target.value })} style={{ width: "100%" }}>
            <option value="pickup">Osobný odber v depe</option>
            <option value="delivery">Doručenie zákazníkovi</option>
          </select>
        </Field>
        {v.method === "delivery" ? (
          <Field label="Adresa doručenia"><input value={v.deliveryAddress || ""} onChange={(e) => set({ deliveryAddress: e.target.value })} style={{ width: "100%" }} /></Field>
        ) : (
          <Field label="Depo *">
            <select value={v.depo || ""} onChange={(e) => set({ depo: e.target.value })} style={{ width: "100%" }}>
              <option value="">— vybrať —</option>
              {DEPO_OPTIONS.filter((d) => d !== "Externé").map((d) => <option key={d} value={d}>{d}</option>)}
            </select>
          </Field>
        )}
        <Field label="K stroju (voliteľné)">
          <input list="ph-machines" value={v.machineText || ""} onChange={(e) => set({ machineText: e.target.value })} placeholder="Sériové číslo alebo popis" style={{ width: "100%" }} />
          <datalist id="ph-machines">{(machines || []).map((m) => <option key={m.id} value={`${m.code}${m.type ? ` (${m.type})` : ""}`} />)}</datalist>
        </Field>
        <Field label="Číslo objednávky zákazníka (voliteľné)"><input value={v.orderNumber || ""} onChange={(e) => set({ orderNumber: e.target.value })} style={{ width: "100%" }} /></Field>
      </div>
      <div style={{ fontWeight: 600, fontSize: 13, margin: "6px 0 8px" }}>Diely *</div>
      {items.map((it, i) => (
        <div key={i} style={{ display: "grid", gridTemplateColumns: withPrices ? "2fr 1.3fr 0.7fr 0.9fr auto" : "2fr 1.3fr 0.7fr auto", gap: 6, marginBottom: 6 }}>
          <input value={it.name || ""} onChange={(e) => setItem(i, { name: e.target.value })} placeholder="Názov dielu *" aria-label="Názov dielu" />
          <input value={it.pn || ""} onChange={(e) => setItem(i, { pn: e.target.value })} placeholder="PN *" aria-label="PN dielu" />
          <input value={it.qty ?? ""} onChange={(e) => setItem(i, { qty: e.target.value })} placeholder="Ks *" inputMode="decimal" aria-label="Počet kusov" />
          {withPrices && <input value={it.price ?? ""} onChange={(e) => setItem(i, { price: e.target.value })} placeholder="€/ks bez DPH" inputMode="decimal" aria-label="Cena za kus" />}
          <button type="button" className="btn btn-ghost" style={{ padding: "4px 8px" }} disabled={items.length === 1} onClick={() => set({ items: items.filter((_, idx) => idx !== i) })} aria-label="Odstrániť diel">✕</button>
        </div>
      ))}
      <button type="button" className="btn btn-ghost" style={{ fontSize: 12, marginBottom: 12 }} onClick={() => set({ items: [...items, { name: "", pn: "", qty: "", price: "" }] })}>+ Pridať diel</button>
    </div>
  );
}

// Odovzdanie: výdaj zadaný dispečerom (údaje len na čítanie) alebo nový výdaj vypísaný priamo v teréne.
function PartHandoverSignModal({ rec, customers, machines, user, myEmployee, onClose, onSave, prefill }) {
  const isNew = !rec;
  const [recId] = useState(() => rec?.id || uid());
  const [draft, setDraft] = useState(() => rec || { method: "pickup", depo: myEmployee?.depo && myEmployee.depo !== "Externé" ? myEmployee.depo : "", items: [{ name: "", pn: "", qty: "", price: "" }], ...(prefill || {}) });
  const [handoverNote, setHandoverNote] = useState("");
  const [customerAbsent, setCustomerAbsent] = useState(false);
  const [customerName, setCustomerName] = useState(rec?.contactName || "");
  const [customerSig, setCustomerSig] = useState(null);
  const [handerSig, setHanderSig] = useState(null);
  const [photos, setPhotos] = useState([]);
  const [uploading, setUploading] = useState(0);
  const [photoError, setPhotoError] = useState("");
  const myName = myEmployee?.name || user?.name || "";
  // Existujúci výdaj: ukazuje sa živý záznam. Ak dispečer medzitým zmení diely/zákazníka, podpis sa zastaví,
  // kým to odovzdávajúci so zákazníkom neskontroluje (podpis viaže to, čo odberateľ videl — signedItems, DB step78).
  const [seen, setSeen] = useState(() => (rec ? { items: rec.items, customer: rec.customer } : null));
  const shown = isNew ? draft : rec;
  const changedSinceOpen = !isNew && (JSON.stringify(rec.items || []) !== JSON.stringify(seen.items || []) || (rec.customer || "") !== (seen.customer || ""));
  async function addPhotos(files) {
    setPhotoError("");
    for (const file of Array.from(files)) {
      setUploading((n) => n + 1);
      try {
        const blob = await compressImageToBlob(file);
        const pathPrefix = `vydaj-dielov/${recId}`;
        const photoId = String(Date.now());
        try {
          const path = `${pathPrefix}/${photoId}.jpg`;
          await uploadToStorageWithRetry("inspections", path, blob, "image/jpeg");
          const { data: pub } = supabase.storage.from("inspections").getPublicUrl(path);
          setPhotos((prev) => [...prev, pub.publicUrl]);
        } catch (e) {
          // Bez signálu — fotka ide do záznamu ako data: a po návrate signálu sa dohrá do úložiska.
          console.error("Nahranie fotky výdaja zlyhalo (asi offline) — čaká vo fronte:", e);
          const dataUrl = await blobToDataUrl(blob);
          setPhotos((prev) => [...prev, dataUrl]);
          queuePhotoMigration({ photoId, table: "partHandovers", recordId: recId, field: "absentPhotos", oldValue: dataUrl, pathPrefix });
        }
      } catch (e) {
        console.error("Spracovanie fotky zlyhalo", e);
        setPhotoError("Nahranie fotky zlyhalo, skúste to znova.");
      } finally {
        setUploading((n) => n - 1);
      }
    }
  }
  const dataOk = !!(shown.customer || "").trim() && phItemsValid(shown.items) && (!!rec || phPlaceOk(shown));
  const customerOk = customerAbsent ? photos.length > 0 : !!(customerSig && customerName.trim());
  const canSave = uploading === 0 && dataOk && customerOk && !!handerSig && !changedSinceOpen;
  function save() {
    if (!canSave) return;
    const nowIso = new Date(serverNowMs()).toISOString();
    const base = isNew
      ? { ...draft, id: recId, source: "field", createdAt: nowIso, createdBy: myName, date: todayISO(),
          items: draft.items.map((it) => ({ name: it.name.trim(), pn: it.pn.trim(), qty: String(it.qty).trim(), price: "" })) }
      : rec;
    const record = {
      ...base, status: "check", handedAt: nowIso, handedBy: myName, handedById: user?.id || null,
      handoverNote: handoverNote.trim(), customerAbsent, customerName: customerAbsent ? "" : customerName.trim(),
      customerSignature: customerAbsent ? null : customerSig, handerSignature: handerSig, absentPhotos: customerAbsent ? photos : [],
      signedItems: base.items, signedCustomer: base.customer,
    };
    if (onSave(record) === false) return;
    onClose();
  }
  const r = shown;
  return (
    <Modal
      eyebrow="Výdaj dielov"
      title={isNew ? "Nový výdaj dielov" : r.customer || "Výdaj dielov"}
      onClose={onClose}
      side
      headerExtra={!isNew && (
        <div className="side-summary">
          <div><span>Spôsob</span><b>{r.method === "delivery" ? `Doručenie${r.deliveryAddress ? ` – ${r.deliveryAddress}` : ""}` : `Osobný odber${r.depo ? ` – depo ${r.depo}` : ""}`}</b></div>
          <div><span>Dátum</span><b className="tnum">{r.date ? fmtDate(r.date) : "—"}</b></div>
          <div><span>Kontakt</span><b>{[r.contactName, r.contactPhone].filter(Boolean).join(" · ") || "—"}</b></div>
          <div><span>Položky</span><b className="tnum">{(r.items || []).length}</b></div>
        </div>
      )}
      footer={
        <>
          {!canSave && (
            <span style={{ fontSize: 13, color: "var(--text-dim)", flex: "1 1 220px" }}>
              Ešte treba: {[changedSinceOpen && "kontrola zmenených dielov so zákazníkom", !dataOk && "odberateľ a diely (názov, PN, počet)", !customerOk && (customerAbsent ? "fotka" : "meno a podpis odberateľa"), !handerSig && "podpis odovzdávajúceho", uploading > 0 && "dokončenie nahrávania fotiek"].filter(Boolean).join(", ")}.
            </span>
          )}
          <button className="btn btn-accent" style={{ marginLeft: "auto" }} disabled={!canSave} onClick={save}>Odovzdať a podpísať</button>
        </>
      }
    >
      {isNew ? (
        <PartHandoverFields value={draft} onChange={setDraft} customers={customers} machines={machines} withPrices={false} />
      ) : (
        <div style={{ fontSize: 14, marginBottom: 12 }}>
          <dl className="side-dl">
            <dt>Odberateľ</dt><dd><b>{r.customer}</b></dd>
            {r.contactName && <><dt>Kontakt</dt><dd>{r.contactName}{r.contactPhone ? <> · <a href={`tel:${r.contactPhone}`} className="tnum">{r.contactPhone}</a></> : ""}</dd></>}
            {r.machineText && <><dt>Stroj</dt><dd>{r.machineText}</dd></>}
            {r.note && <><dt>Poznámka</dt><dd style={{ whiteSpace: "pre-wrap" }}>{r.note}</dd></>}
          </dl>
          <table style={{ width: "100%", marginTop: 12, borderCollapse: "collapse", fontSize: 14 }}>
            <thead><tr style={{ fontSize: 13, color: "var(--text-dim)", textAlign: "left" }}><th style={{ padding: "6px 0" }}>Názov</th><th>PN</th><th style={{ textAlign: "right" }}>Počet</th></tr></thead>
            <tbody>{(r.items || []).map((it, i) => <tr key={i} style={{ borderTop: "1px solid var(--border)" }}><td style={{ padding: "8px 0" }}>{it.name}</td><td>{it.pn}</td><td className="tnum" style={{ textAlign: "right" }}>{it.qty} ks</td></tr>)}</tbody>
          </table>
        </div>
      )}
      {changedSinceOpen && (
        <div style={{ background: "var(--danger-bg, #fde8e8)", border: "1px solid var(--danger)", borderRadius: 8, padding: "8px 10px", marginBottom: 12, fontSize: 13 }}>
          ⚠ Dispečer medzitým zmenil diely alebo odberateľa (vyššie sú aktuálne). Skontrolujte ich so zákazníkom — podpis odberateľa treba dať znova.
          <div style={{ marginTop: 6 }}>
            <button className="btn btn-ghost" onClick={() => { setSeen({ items: rec.items, customer: rec.customer }); setCustomerSig(null); }}>Skontrolované so zákazníkom</button>
          </div>
        </div>
      )}
      <Field label="Poznámka pri odovzdaní (napr. chýba kus, iný diel)">
        <textarea value={handoverNote} onChange={(e) => setHandoverNote(e.target.value)} rows={2} style={{ width: "100%" }} />
      </Field>
      <label style={{ display: "flex", gap: 8, alignItems: "center", fontSize: 13, margin: "4px 0 10px" }}>
        <input type="checkbox" checked={customerAbsent} onChange={(e) => setCustomerAbsent(e.target.checked)} /> Odberateľ nie je prítomný (namiesto podpisu fotka)
      </label>
      {customerAbsent ? (
        <div style={{ marginBottom: 12 }}>
          <PhotoPickButtons onFiles={addPhotos} />
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>{photos.map((p, i) => <img key={i} src={p} alt={`Foto ${i + 1}`} style={{ height: 60, borderRadius: 4 }} />)}</div>
          {uploading > 0 && <div style={{ fontSize: 12 }}>Nahrávam fotky…</div>}
          {photoError && <div style={{ fontSize: 12, color: "var(--danger)" }}>{photoError}</div>}
        </div>
      ) : (
        <Field label="Meno preberajúceho *"><input value={customerName} onChange={(e) => setCustomerName(e.target.value)} style={{ width: "100%" }} /></Field>
      )}
      <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 12 }}>
        {customerAbsent ? <div /> : <div><SignaturePad label="Podpis odberateľa" value={customerSig} onChange={setCustomerSig} /><PrivacyNote /></div>}
        <SignaturePad label={`Podpis odovzdávajúceho (${myName || "ja"})`} value={handerSig} onChange={setHanderSig} />
      </div>
    </Modal>
  );
}

// Rýchla akcia „Výdaj dielov“ — výdaje čakajúce na odovzdanie + nový výdaj priamo v teréne.
function PartHandoverQuickModal({ partHandovers, myEmployee, onClose, onHandover, onNew }) {
  const waiting = phMineWaiting(partHandovers, myEmployee).sort((a, b) => (a.date || "").localeCompare(b.date || ""));
  return (
    <Modal eyebrow="Výdaj dielov" title="Odovzdanie dielov zákazníkovi" onClose={onClose}>
      <FormStep title={`Pridelené mne na odovzdanie`} right={<span className="spill tnum">{waiting.length}</span>} />
      {waiting.length === 0 && <div className="fnote fnote-i">Nemáte pridelený žiadny výdaj.</div>}
      {waiting.length > 0 && (
        <div className="flist">
          {waiting.map((p) => (
            <div key={p.id} className="frow">
              <div style={{ fontSize: 15, minWidth: 0, flex: "1 1 180px" }}>
                <div style={{ fontWeight: 600 }}>{p.customer}</div>
                <div className="cell-sub tnum">{[p.date ? fmtDate(p.date) : "", p.method === "delivery" ? "doručenie" : p.depo ? `depo ${p.depo}` : "osobný odber", phItemsSummary(p.items)].filter(Boolean).join(" · ")}</div>
              </div>
              <button className="btn btn-black" onClick={() => onHandover(p)}>Odovzdať</button>
            </div>
          ))}
        </div>
      )}
      <FormFoot confirm>
        <button className="btn btn-accent" onClick={onNew}>+ Vypísať nový výdaj</button>
      </FormFoot>
    </Modal>
  );
}

// Zadanie výdaja vopred / kontrola a oprava dispečerom servisu.
function PartHandoverEditModal({ rec, customers, machines, employees, onClose, onSave }) {
  const isNew = !rec;
  const [draft, setDraft] = useState(() => rec || { method: "pickup", depo: "", date: todayISO(), items: [{ name: "", pn: "", qty: "", price: "" }] });
  const signed = !!rec && rec.status !== "waiting";
  const valid = !!(draft.customer || "").trim() && phItemsValid(draft.items) && (signed || phPlaceOk(draft)) && (draft.items || []).every((it) => it.price === "" || it.price == null || phPrice(it.price) >= 0);
  function save(checked) {
    if (!valid) return;
    if (onSave({ ...draft, items: draft.items.map((it) => ({ ...it, name: it.name.trim(), pn: it.pn.trim(), qty: String(it.qty).trim(), price: it.price === "" || it.price == null ? "" : String(it.price).trim() })) }, { isNew, checked }) === false) return;
    onClose();
  }
  return (
    <Modal eyebrow="Výdaj dielov" title={isNew ? "Nový výdaj dielov" : signed ? "Kontrola výdaja dielov" : "Úprava výdaja dielov"} onClose={onClose} wide form>
      {signed && <div className="fnote fnote-y">Výdaj je podpísaný ({rec.handedBy || "—"}). Oprava sa zapíše a na dodacom liste bude „Opravené dispečerom“.{rec.handoverNote ? ` Poznámka pri odovzdaní: ${rec.handoverNote}` : ""}</div>}
      {!signed && (
        <div className="fgrid2">
          <Field label="Dátum odovzdania"><input type="date" value={draft.date || ""} onChange={(e) => setDraft({ ...draft, date: e.target.value })} /></Field>
          <Field label="Odovzdá"><PhAssigneeSelect value={draft.assigneeId} employees={employees} onChange={(id) => setDraft({ ...draft, assigneeId: id, assigneeName: (employees || []).find((e) => e.id === id)?.name || null, _assigneeTouched: true })} /></Field>
        </div>
      )}
      <PartHandoverFields value={draft} onChange={setDraft} customers={customers} machines={machines} withPrices />
      <Field label="Poznámka (na dodací list)"><textarea value={draft.note || ""} onChange={(e) => setDraft({ ...draft, note: e.target.value })} rows={2} style={{ width: "100%" }} /></Field>
      <FormFoot missing={[!(draft.customer || "").trim() && "odberateľ", !phItemsValid(draft.items) && "diely", !signed && !phPlaceOk(draft) && "miesto odovzdania"].filter(Boolean)}>
        <button className={rec?.status === "check" ? "btn btn-outline" : "btn btn-accent"} disabled={!valid} onClick={() => save(false)}>{isNew ? "Uložiť výdaj" : "Uložiť"}</button>
        {rec?.status === "check" && <button className="btn btn-accent" disabled={!valid} onClick={() => save(true)}>Uložiť a označiť ako skontrolované</button>}
      </FormFoot>
    </Modal>
  );
}

// Servis → Náhradné diely → Výdaj dielov: zoznam podľa stavu, kontrola a fakturácia.
function PartHandoversView({ partHandovers, user, myEmployee, employees, onAssign, onNew, onHandover, onEdit, onPrint, onSendMail, onBill, onDelete, focusId }) {
  const [tab, setTab] = useState(() => (phCanManage(user) ? "check" : phCanBill(user) ? "billing" : "waiting"));
  const counts = Object.fromEntries(Object.keys(PH_STATUS).map((s) => [s, (partHandovers || []).filter((p) => p.status === s).length]));
  const [billDraft, setBillDraft] = useState({});
  const [assigning, setAssigning] = useState(null); // výdaj, ktorému kancelária prideľuje odovzdávajúceho
  useEffect(() => {
    const f = focusId && (partHandovers || []).find((p) => p.id === focusId);
    if (f) setTab(f.status);
  }, [focusId]); // eslint-disable-line react-hooks/exhaustive-deps
  const list = (partHandovers || []).filter((p) => p.status === tab)
    .sort((a, b) => (tab === "waiting" ? (a.date || "").localeCompare(b.date || "") : (b.handedAt || b.createdAt || "").localeCompare(a.handedAt || a.createdAt || "")));
  const bd = (p) => billDraft[p.id] || { dlNumber: p.dlNumber || "", erpDoc: p.erpDoc || "" };
  return (
    <div>
      <div className="tbar">
        <div className="seg" role="group" aria-label="Stav výdaja">
          {Object.entries(PH_STATUS).map(([s, label]) => (
            <button key={s} type="button" className={tab === s ? "on" : ""} aria-pressed={tab === s} onClick={() => setTab(s)}>
              {label}<span className="seg-n">{counts[s]}</span>
            </button>
          ))}
        </div>
        <div style={{ flex: 1 }} />
        {phCanManage(user) && <button className="btn btn-accent" onClick={onNew}>+ Zadať výdaj</button>}
      </div>
      {list.length === 0 && <div className="panel" style={{ padding: 30, color: "var(--text-dim)", textAlign: "center", boxShadow: "none", borderRadius: 12 }}>Žiadne výdaje v stave „{PH_STATUS[tab]}“.</div>}
      {list.length > 0 && (
      <div className="panel jobs-wrap" style={{ boxShadow: "none", borderRadius: 12 }}>
      <table className="table-cards jobs-table">
        <thead><tr><th>Zákazník</th><th>Diely</th><th>Odovzdal</th><th><span className="sr-only">Akcie</span></th></tr></thead>
        <tbody>
      {list.map((p) => (
        <React.Fragment key={p.id}>
        <tr style={{ outline: p.id === focusId ? "2px solid var(--accent)" : "none", outlineOffset: -2 }}>
          <td className="td-plain">
            <strong>{p.customer}</strong>
            {p.source === "field" && <span className="spill spill-wait" style={{ marginLeft: 8 }}>Vypísané v teréne</span>}
            {p.dlNumber && <div className="cell-sub tnum">DL {p.dlNumber}</div>}
          </td>
          <td className="td-plain">
            {phItemsSummary(p.items)}
            {p.handoverNote && <div style={{ marginTop: 4 }}><span className="spill spill-problem" style={{ whiteSpace: "normal" }}>⚠ Pri odovzdaní: {p.handoverNote}</span></div>}
          </td>
          <td className="td-plain">
            {p.handedAt ? <>{p.handedBy || "—"}<div className="cell-sub tnum">{new Date(p.handedAt).toLocaleString("sk-SK", { timeZone: "Europe/Bratislava", day: "numeric", month: "numeric", hour: "2-digit", minute: "2-digit" })}</div></> : <span className="tnum">{`${p.date ? fmtDate(p.date) : ""} · ${p.method === "delivery" ? "doručenie" : p.depo ? `depo ${p.depo}` : "osobný odber"}`}</span>}
            <div className="cell-sub">
              {p.status === "waiting" ? (!p.assigneeId ? "nepridelené" : phAssignable(employees).some((e) => e.id === p.assigneeId) ? `odovzdá ${p.assigneeName || "—"}` : <span className="spill spill-problem" style={{ whiteSpace: "normal" }}>⚠ {p.assigneeName || "odovzdávajúci"} už nemôže odovzdať — prideľte znova</span>) : null}
              {[p.createdBy ? `vypracoval ${p.createdBy}` : "", p.correctedAt ? "opravené" : "", p.sentAt ? "poslané zákazníkovi" : ""].filter(Boolean).join(" · ")}
            </div>
          </td>
          <td className="td-actions" style={{ textAlign: "right" }}>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", justifyContent: "flex-end", alignItems: "center" }}>
              {p.status === "waiting" && phCanManage(user) && <button className="btn btn-outline" onClick={() => setAssigning(p)}>{p.assigneeId ? "Zmeniť odovzdávajúceho" : "+ Prideliť odovzdávajúceho"}</button>}
              {p.status === "waiting" && (phCanManage(user) || (myEmployee && p.assigneeId === myEmployee.id)) && <button className="btn btn-outline" onClick={() => onHandover(p)}>Odovzdať</button>}
              {phCanManage(user) && (p.status === "waiting" || p.status === "check" || p.status === "billing") && (
                <button className="btn btn-outline" onClick={() => onEdit(p)}>{p.status === "check" ? "Skontrolovať" : "Upraviť"}</button>
              )}
              {p.status !== "waiting" && <button className="btn btn-ghost" style={{ background: "var(--panel-2)" }} onClick={() => onPrint(p)}>Dodací list</button>}
              {phCanManage(user) && p.status === "billing" && <button className="btn btn-ghost" onClick={() => onSendMail(p)}>✉️ Poslať zákazníkovi</button>}
              <KebabMenu label="⋯" name="Ďalšie akcie" actions={[
                phCanManage(user) && p.status !== "done" && { label: "Zmazať", danger: true, onClick: () => onDelete(p) },
              ]} />
            </div>
          </td>
        </tr>
          {phCanBill(user) && (p.status === "billing" || p.status === "done") && (
            <tr>
            <td colSpan={4} className="td-plain" style={{ paddingTop: 0 }}>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-end" }}>
              <label style={{ fontSize: 13 }}>Číslo dodacieho listu (ERP)<br />
                <input value={bd(p).dlNumber} disabled={p.status === "done"} onChange={(e) => setBillDraft({ ...billDraft, [p.id]: { ...bd(p), dlNumber: e.target.value } })} />
              </label>
              <label style={{ fontSize: 13 }}>Číslo dokladu / faktúry<br />
                <input value={bd(p).erpDoc} disabled={p.status === "done"} onChange={(e) => setBillDraft({ ...billDraft, [p.id]: { ...bd(p), erpDoc: e.target.value } })} />
              </label>
              {p.status === "billing" ? (
                <button className="btn btn-outline" disabled={!bd(p).dlNumber.trim()} onClick={() => onBill(p, { ...bd(p), done: true })}>Spracované</button>
              ) : (
                <button className="btn btn-outline" onClick={() => onBill(p, { done: false })}>Vrátiť na fakturáciu</button>
              )}
            </div>
            </td>
            </tr>
          )}
        </React.Fragment>
      ))}
        </tbody>
      </table>
      </div>
      )}
      {assigning && (
        <Modal eyebrow="Výdaj dielov" title="Prideliť odovzdávajúceho" onClose={() => setAssigning(null)}>
          <div style={{ fontSize: 13, marginBottom: 10 }}>{assigning.customer} · {phItemsSummary(assigning.items)}</div>
          <Field label="Odovzdá (len on ho uvidí na „Dnes“ a dostane upozornenie)">
            <PhAssigneeSelect value={assigning.assigneeId} employees={employees} onChange={(id) => setAssigning({ ...assigning, assigneeId: id })} />
          </Field>
          <button className="btn btn-accent" onClick={() => { if (onAssign(assigning, assigning.assigneeId || null) !== false) setAssigning(null); }}>Uložiť</button>
        </Modal>
      )}
    </div>
  );
}

function exportSparePartsCSV(rows, filename) {
  const data = rows.map((p) => ({
    Depo: p.depo || "",
    Určenie: p.urcenie !== undefined ? urcenieLabel(p.urcenie) : "",
    Dodávateľ: p.dodavatel || "",
    "Číslo položky": p.cisloPolozky || "",
    "Počet kusov": p.pocetKusov || "",
    "Číslo dielu": p.cisloDielu || "",
    "Popis dielu": p.popisDielu || "",
    "Stav objednania": p.stav || "",
    "Dátum objednania": p.datumObjednania ? fmtDate(p.datumObjednania) : "",
    "Nákupná objednávka": p.nakupnaObjednavka || "",
    Poznámka: p.poznamka || "",
    "Zadal(a)": p.requestedBy || "",
  }));
  const csv = Papa.unparse(data, { escapeFormulae: true });
  const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" }); // BOM, nech Excel nezobrazí diakritiku zle
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

function SparePartsView({ spareParts, machines, myEmployee, user, today, targetDepo, onTargetDepoConsumed, onAdd, onApprove, onApproveBulk, onReject, onRestore, onUpdate, onDelete, onImport }) {
  const canManage = can(user, "sparepart_manage");
  const myDepo = myEmployee?.depo || "";
  // "Vedúci technik" role vidí/objednáva len na svoje depá (napr. BA + NR),
  // ostatní s právom sparepart_manage (dispečer/vedúci servisu) na všetky.
  const allowedDepos = myAssignableDepos(user);
  const depoOptions = [...(allowedDepos || DEPO_OPTIONS.filter((d) => d !== "Externé")), ...(!allowedDepos && spareParts.some((p) => !p.depo) ? [""] : [])];
  // Najprv vlastné depo (ak ho smie spravovať), inak prvé povolené.
  const [activeDepo, setActiveDepo] = useState(canManage ? (depoOptions.includes(myDepo) ? myDepo : depoOptions[0]) : myDepo);
  const [dodavatelFilter, setDodavatelFilter] = useState(null); // null = všetko zaškrtnuté (predvolené)
  const [periodMode, setPeriodMode] = useState("month"); // month | all | custom
  const [customStart, setCustomStart] = useState(today.slice(0, 8) + "01");
  const [customEnd, setCustomEnd] = useState(today);
  const [showAdd, setShowAdd] = useState(false);
  const [rejectingId, setRejectingId] = useState(null);
  const [uncheckedPendingIds, setUncheckedPendingIds] = useState(() => new Set()); // pri hromadnom schválení — odškrtnuté id sa vynechajú
  const [confirmMessage, setConfirmMessage] = useState(null); // krátky zatvárateľný pás po odoslaní požiadavky
  const [searchQuery, setSearchQuery] = useState(""); // vyhľadávanie histórie naprieč všetkými depami a celým časom
  const [showImport, setShowImport] = useState(false);

  // Prišli sme sem kliknutím na notifikáciu o konkrétnom diele — prepneme
  // rovno na jeho depo, nech ho vedúci/dispečer nemusí ručne hľadať.
  useEffect(() => {
    if (targetDepo && canManage && (!allowedDepos || allowedDepos.includes(targetDepo))) {
      setActiveDepo(targetDepo);
      setDodavatelFilter(null);
      onTargetDepoConsumed?.();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [targetDepo]);

  const depo = canManage ? activeDepo : myDepo;
  const { start, end } = periodBounds(periodMode, today, customStart, customEnd);

  const depoRows = spareParts.filter((p) => (p.depo || "") === depo);
  // Filter obdobia sa týka LEN už objednaných položiek — nevybavené sa majú
  // vidieť vždy, nech sa nestratia z dohľadu len preto, že prešiel mesiac.
  const periodFiltered = periodMode === "all"
    ? depoRows
    : depoRows.filter((p) => p.stav !== SPAREPART_STAV.OBJEDNANE || !p.datumObjednania || (p.datumObjednania >= start && p.datumObjednania <= end));

  const dodavatelOptions = [...new Set(periodFiltered.map((p) => p.dodavatel || ""))].sort();
  const selectedDodavatelia = dodavatelFilter || new Set(dodavatelOptions);
  const rows = periodFiltered.filter((p) => selectedDodavatelia.has(p.dodavatel || ""));

  const pending = rows.filter((p) => p.stav === SPAREPART_STAV.CAKA_NA_SCHVALENIE);
  const zamietnute = rows.filter((p) => p.stav === SPAREPART_STAV.ZAMIETNUTE);
  // Objednané hore, zoradené podľa čísla nákupnej objednávky (od najmenšieho).
  const objednane = rows
    .filter((p) => p.stav === SPAREPART_STAV.OBJEDNANE)
    .sort((a, b) => (a.nakupnaObjednavka || "").localeCompare(b.nakupnaObjednavka || "", undefined, { numeric: true }));
  // Čaká na objednanie pod tým, zoradené podľa dodávateľa — nech sa dá kopírovať
  // dodávateľ po dodávateľovi bez miešania s už objednanými vecami.
  const cakaNaObjednanie = rows
    .filter((p) => p.stav === SPAREPART_STAV.CAKA_NA_OBJEDNANIE)
    .sort((a, b) => (a.dodavatel || "").localeCompare(b.dodavatel || ""));

  const columns = [
    { key: "dodavatel", label: "Dodávateľ" },
    { key: "cisloPolozky", label: "Číslo položky" },
    { key: "pocetKusov", label: "Počet kusov" },
    { key: "cisloDielu", label: "Číslo dielu" },
    { key: "popisDielu", label: "Popis dielu" },
    { key: "poznamka", label: "Poznámka" },
  ];

  // Vyhľadávanie histórie — naprieč VŠETKÝMI depami (u technika len jeho
  // vlastné) a CELÝM časom, nezávisle od filtra obdobia a aktívnej záložky.
  const searchScope = canManage
    ? (allowedDepos ? spareParts.filter((p) => allowedDepos.includes(p.depo)) : spareParts)
    : spareParts.filter((p) => p.depo === myDepo);
  const q = searchQuery.trim().toLowerCase();
  const searchResults = q
    ? searchScope
        .filter((p) => (p.cisloDielu || "").toLowerCase().includes(q) || (p.popisDielu || "").toLowerCase().includes(q))
        .sort((a, b) => (b.requestedAt || "").localeCompare(a.requestedAt || ""))
    : [];

  // Kopírovanie stĺpca — malá sivá ikona priamo pri názve stĺpca.
  const CP_BTN = { minHeight: 0, padding: "0 4px", fontSize: 13, border: "none", background: "transparent", color: "var(--text-dim)", fontWeight: 400 };
  function renderGroupTable(groupRows, groupLabel, groupColor, showDodavatelFilter) {
    // Dátum objednania len ak ho niektorý riadok má/potrebuje — tabuľka sa tak zmestí na 1360 px.
    const showDate = groupRows.some((p) => p.stav === SPAREPART_STAV.OBJEDNANE || p.datumObjednania);
    return (
      <div style={{ marginBottom: 20 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "16px 0 8px" }}>
          <h2 className="today-sec" style={{ margin: 0 }}>
            <span style={{ color: groupColor }}>●</span> {groupLabel} · {groupRows.length}
          </h2>
          {groupRows.length > 0 && (
            <button
              className="btn btn-outline"
              style={{ minHeight: 32, fontSize: 13, padding: "2px 10px" }}
              onClick={() => exportSparePartsCSV(groupRows, `nahradne-diely-${depo}-${groupLabel.toLowerCase().replace(/\s+/g, "-")}.csv`)}
            >
              ⬇ Export do Excelu
            </button>
          )}
        </div>
        <div className="panel table-wrap jobs-wrap" style={{ padding: 0, boxShadow: "none", borderRadius: 12 }}>
          <table className="table-cards jobs-table sp-table" style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                {columns.map((c) => (
                  <th key={c.key} style={{ whiteSpace: "normal" }}>
                    {c.label}
                    {c.key === "dodavatel" && showDodavatelFilter && (
                      <ColumnFilterButton label="Dodávateľ" options={dodavatelOptions} selected={selectedDodavatelia} onChange={setDodavatelFilter} />
                    )}
                    {"\u00a0"}
                    <button className="btn" style={CP_BTN} title={`Kopírovať stĺpec ${c.label}`} onClick={() => copyColumn(groupRows, c.key, c.label)}>⧉</button>
                  </th>
                ))}
                <th style={{ whiteSpace: "nowrap" }}>
                  Určenie {" "}
                  <button className="btn" style={CP_BTN} title="Kopírovať stĺpec Určenie" onClick={() => copyColumn(groupRows.map((p) => ({ urcenieText: urcenieLabel(p.urcenie) })), "urcenieText", "Určenie")}>⧉</button>
                </th>
                <th style={{ whiteSpace: "normal" }}>Stav objednania</th>
                {showDate && <th style={{ whiteSpace: "normal" }}>Dátum objednania</th>}
                <th style={{ whiteSpace: "normal" }}>
                  Nákupná objednávka{"\u00a0"}
                  <button className="btn" style={CP_BTN} title="Kopírovať stĺpec Nákupná objednávka" onClick={() => copyColumn(groupRows, "nakupnaObjednavka", "Nákupná objednávka")}>⧉</button>
                </th>
                {canManage && <th></th>}
              </tr>
            </thead>
            <tbody>
              {groupRows.length === 0 ? (
                <tr><td className="td-plain" colSpan={11} style={{ color: "var(--text-dim)" }}>Žiadne položky nezodpovedajú filtru.</td></tr>
              ) : (
                groupRows.map((p) => (
                  <tr key={p.id} id={`sp-${p.id}`}>
                    {columns.map((c) =>
                      canManage ? (
                        <td key={c.key} data-label={c.label}>
                          <BlurInput
                            type={c.key === "pocetKusov" ? "number" : "text"}
                            value={String(p[c.key] ?? "")}
                            aria-label={c.label}
                            onCommit={(v) => onUpdate(p.id, { [c.key]: v })}
                            style={{ fontSize: 13, width: "100%", minWidth: c.key === "pocetKusov" ? 48 : 72, maxWidth: c.key === "popisDielu" ? 160 : c.key === "pocetKusov" ? 60 : 100 }}
                          />
                        </td>
                      ) : (
                        <td key={c.key} data-label={c.label}>{p[c.key] || "—"}</td>
                      )
                    )}
                    <td style={{ whiteSpace: "nowrap" }} data-label="Určenie">{urcenieLabel(p.urcenie)}</td>
                    <td data-label="Stav objednania">
                      {canManage ? (
                        <select
                          aria-label="Stav objednania"
                          value={p.stav}
                          onChange={(e) => {
                            const newStav = e.target.value;
                            // Objednané len s dodávateľom a číslom objednávky (rozhodnutie 23. 10.).
                            if (newStav === SPAREPART_STAV.OBJEDNANE && (!String(p.dodavatel || "").trim() || !String(p.nakupnaObjednavka || "").trim())) {
                              showNotice(`Pred označením „Objednané“ doplňte ${[!String(p.dodavatel || "").trim() && "dodávateľa", !String(p.nakupnaObjednavka || "").trim() && "číslo nákupnej objednávky"].filter(Boolean).join(" a ")}.`);
                              return;
                            }
                            onUpdate(p.id, newStav === SPAREPART_STAV.OBJEDNANE ? { stav: newStav, datumObjednania: today } : { stav: newStav });
                          }}
                          className={`spill ${p.stav === SPAREPART_STAV.OBJEDNANE ? "spill-done" : "spill-wait"}`}
                          style={{ border: "none", fontFamily: "inherit", cursor: "pointer" }}
                        >
                          <option value={SPAREPART_STAV.CAKA_NA_OBJEDNANIE}>Čaká na objednanie</option>
                          <option value={SPAREPART_STAV.OBJEDNANE}>Objednané</option>
                        </select>
                      ) : (
                        <span className={`spill ${p.stav === SPAREPART_STAV.OBJEDNANE ? "spill-done" : "spill-wait"}`}>
                          {p.stav}
                        </span>
                      )}
                    </td>
                    {showDate && <td data-label="Dátum objednania">
                      {canManage ? (
                        <input type="date" aria-label="Dátum objednania" value={p.datumObjednania || ""} onChange={(e) => onUpdate(p.id, { datumObjednania: e.target.value })} style={{ fontSize: 12 }} />
                      ) : (
                        <span className="tnum">{p.datumObjednania ? fmtDate(p.datumObjednania) : "—"}</span>
                      )}
                    </td>}
                    <td data-label="Nákupná objednávka">
                      {canManage ? (
                        <BlurInput value={p.nakupnaObjednavka || ""} aria-label="Nákupná objednávka" onCommit={(v) => onUpdate(p.id, { nakupnaObjednavka: v })} style={{ fontSize: 12, width: "100%", minWidth: 80, maxWidth: 110 }} />
                      ) : (
                        <span className="tnum">{p.nakupnaObjednavka || "—"}</span>
                      )}
                    </td>
                    {canManage && (
                      <td className="td-actions">
                        <button className="btn btn-ghost" style={{ padding: "2px 8px", color: "var(--danger)" }} title="Vymazať riadok" aria-label="Vymazať riadok" onClick={() => onDelete(p.id)}>🗑</button>
                      </td>
                    )}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="tbar">
        {canManage ? (
          <div className="seg" role="group" aria-label="Depo">
            {depoOptions.map((d) => (
              <button key={d} type="button" className={activeDepo === d ? "on" : ""} aria-pressed={activeDepo === d} onClick={() => { setActiveDepo(d); setDodavatelFilter(null); }}>
                <span className="depo-chip-full">{d || "Bez depa"}</span><span className="depo-chip-short">{DEPO_SHORT_LABELS[d] || d || "Bez depa"}</span>
                {(() => { const n = spareParts.filter((p) => (p.depo || "") === d && p.stav === SPAREPART_STAV.CAKA_NA_SCHVALENIE).length; return n ? <span className="seg-n" title="Čaká na schválenie">{n}</span> : null; })()}
              </button>
            ))}
          </div>
        ) : (
          <div style={{ fontSize: 15, fontWeight: 600 }}>Depo: {myDepo || "— nemáte priradené depo —"}</div>
        )}
        <div style={{ display: "flex", gap: 8, marginLeft: "auto" }}>
          {(canManage || can(user, "sparepart_request")) && (
            <button className="btn btn-accent" onClick={() => setShowAdd(true)}>+ Nová požiadavka</button>
          )}
          <KebabMenu label="⋯" name="Ďalšie akcie" actions={[
            isAdminUser(user) && !q && { label: `Importovať históriu z Excelu (pre ${depo})`, onClick: () => setShowImport(true) },
          ]} />
        </div>
      </div>

      {confirmMessage && (
        <div
          style={{
            display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12,
            background: "var(--ok-fill)", color: "#fff", padding: "10px 14px", borderRadius: 8, marginBottom: 16, fontSize: 13,
          }}
        >
          <span>✓ {confirmMessage}</span>
          <button className="btn btn-ghost" style={{ color: "#fff", padding: "2px 8px" }} onClick={() => setConfirmMessage(null)}>✕</button>
        </div>
      )}

      <div className="tbar" style={{ marginBottom: 4 }}>
        <SearchInput placeholder="Hľadať v histórii podľa čísla alebo popisu dielu (naprieč všetkými depami a celým časom)…" value={searchQuery} onChange={setSearchQuery} style={{ flex: 1, maxWidth: 480 }} />
        {q && <button className="btn btn-outline" onClick={() => setSearchQuery("")}>✕ Zrušiť hľadanie</button>}
        {!q && (
          <div className="seg" role="group" aria-label="Obdobie objednania">
            {[["month", "tento mesiac"], ["all", "všetko"], ["custom", "Vlastný rozsah"]].map(([id, label]) => (
              <button key={id} type="button" className={periodMode === id ? "on" : ""} aria-pressed={periodMode === id} onClick={() => setPeriodMode(id)}>
                {id !== "custom" && <span className="who-hide-mobile">Objednané: </span>}{label}
              </button>
            ))}
          </div>
        )}
        {!q && periodMode === "custom" && (
          <>
            <input type="date" value={customStart} onChange={(e) => setCustomStart(e.target.value)} />
            <span style={{ color: "var(--text-dim)" }}>—</span>
            <input type="date" value={customEnd} onChange={(e) => setCustomEnd(e.target.value)} />
          </>
        )}
      </div>

      {q ? (
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "16px 0 8px" }}>
            <h2 className="today-sec" style={{ margin: 0 }}>
              Výsledky hľadania · {searchResults.length}
            </h2>
            {searchResults.length > 0 && (
              <button className="btn btn-outline" style={{ minHeight: 32, fontSize: 13, padding: "2px 10px" }} onClick={() => exportSparePartsCSV(searchResults, `nahradne-diely-hladanie-${q}.csv`)}>
                ⬇ Export do Excelu
              </button>
            )}
          </div>
          <div className="panel table-wrap jobs-wrap" style={{ padding: 0, boxShadow: "none", borderRadius: 12 }}>
            <table className="table-cards jobs-table" style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  <th style={{ whiteSpace: "nowrap" }}>Depo</th>
                  <th style={{ whiteSpace: "nowrap" }}>Určenie</th>
                  <th style={{ whiteSpace: "nowrap" }}>Stav</th>
                  <th style={{ whiteSpace: "nowrap" }}>Dátum objednania</th>
                  <th style={{ whiteSpace: "nowrap" }}>Nákupná objednávka</th>
                  <th style={{ whiteSpace: "nowrap" }}>Dodávateľ</th>
                  <th style={{ whiteSpace: "nowrap" }}>Počet kusov</th>
                  <th style={{ whiteSpace: "nowrap" }}>Číslo dielu</th>
                  <th style={{ whiteSpace: "nowrap" }}>Popis dielu</th>
                </tr>
              </thead>
              <tbody>
                {searchResults.length === 0 ? (
                  <tr><td className="td-plain" colSpan={9} style={{ color: "var(--text-dim)" }}>Nič sa nenašlo.</td></tr>
                ) : (
                  searchResults.map((p) => (
                    <tr key={p.id} id={`sp-${p.id}`}>
                      <td data-label="Depo">{p.depo}</td>
                      <td style={{ whiteSpace: "nowrap" }} data-label="Určenie">{urcenieLabel(p.urcenie)}</td>
                      <td data-label="Stav">
                        <span className={`spill ${p.stav === SPAREPART_STAV.OBJEDNANE ? "spill-done" : p.stav === SPAREPART_STAV.ZAMIETNUTE ? "spill-problem" : "spill-wait"}`}>
                          {p.stav}
                        </span>
                      </td>
                      <td data-label="Dátum objednania">{p.datumObjednania ? fmtDate(p.datumObjednania) : "—"}</td>
                      <td data-label="Nákupná objednávka">{p.nakupnaObjednavka || "—"}</td>
                      <td data-label="Dodávateľ">{p.dodavatel || "—"}</td>
                      <td data-label="Počet kusov">{p.pocetKusov || "—"}</td>
                      <td data-label="Číslo dielu">{p.cisloDielu}</td>
                      <td data-label="Popis dielu">{p.popisDielu}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
      <>
      {pending.length > 0 && !canManage && (
        <div style={{ marginBottom: 20 }}>
          <h2 className="today-sec" style={{ margin: "16px 0 8px" }}><span style={{ color: "var(--warn)" }}>●</span> Čaká na schválenie · {pending.length}</h2>
          <div className="panel" style={{ padding: "8px 14px", boxShadow: "none", borderRadius: 12 }}>
            {pending.map((p) => (
              <div key={p.id} id={`sp-${p.id}`} style={{ padding: "6px 0", borderBottom: "1px solid var(--border)" }}>
                <b>{p.popisDielu || "—"}</b> · <span className="tnum">{p.pocetKusov || "—"} ks</span>
                <div className="cell-sub">diel {p.cisloDielu || "—"}{p.urcenie ? ` · ${urcenieLabel(p.urcenie)}` : ""}</div>
              </div>
            ))}
          </div>
        </div>
      )}
      {pending.length > 0 && canManage && (
        <div style={{ marginBottom: 20 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "16px 0 8px", flexWrap: "wrap" }}>
            <h2 className="today-sec" style={{ margin: 0 }}>
              <span style={{ color: "var(--warn)" }}>●</span> Čaká na schválenie · {pending.length}
            </h2>
            {pending.length > 1 && (
              <button
                className="btn btn-outline"
                style={{ minHeight: 32, fontSize: 13, padding: "2px 10px" }}
                onClick={() => {
                  onApproveBulk(pending.filter((p) => !uncheckedPendingIds.has(p.id)).map((p) => p.id));
                  setUncheckedPendingIds(new Set());
                }}
              >
                Schváliť vybrané ({pending.filter((p) => !uncheckedPendingIds.has(p.id)).length})
              </button>
            )}
          </div>
          <div className="panel table-wrap jobs-wrap" style={{ padding: 0, boxShadow: "none", borderRadius: 12 }}>
            <table className="table-cards jobs-table" style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  {pending.length > 1 && <th><span className="sr-only">Vybrať</span></th>}
                  <th className="m-only" />
                  {columns.map((c) => <th key={c.key} style={{ whiteSpace: "nowrap" }}>{c.label}</th>)}
                  <th style={{ whiteSpace: "nowrap" }}>Určenie</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {pending.map((p) => (
                  <tr key={p.id} id={`sp-${p.id}`}>
                    {pending.length > 1 && (
                      <td data-label="Vybrať">
                        <input
                          type="checkbox"
                          checked={!uncheckedPendingIds.has(p.id)}
                          onChange={(e) =>
                            setUncheckedPendingIds((prev) => {
                              const next = new Set(prev);
                              if (e.target.checked) next.delete(p.id); else next.add(p.id);
                              return next;
                            })
                          }
                        />
                      </td>
                    )}
                    <td className="td-plain m-only">
                      <span style={{ display: "flex", justifyContent: "space-between", width: "100%", gap: 8 }}><b>{p.popisDielu || "—"}</b><span className="tnum">{p.pocetKusov || "—"} ks</span></span>
                      <div className="cell-sub">{p.dodavatel || "—"} · diel <b style={{ color: "var(--text)" }}>{p.cisloDielu || "—"}</b>{p.urcenie ? ` · ${urcenieLabel(p.urcenie)}` : ""}</div>
                    </td>
                    {columns.map((c) => <td key={c.key} className="who-hide-mobile" data-label={c.label}>{c.key === "cisloDielu" && p[c.key] ? <b>{p[c.key]}</b> : p[c.key] || "—"}</td>)}
                    <td className="who-hide-mobile" style={{ whiteSpace: "nowrap" }} data-label="Určenie">{urcenieLabel(p.urcenie)}</td>
                    <td style={{ whiteSpace: "nowrap" }} className="td-actions">
                      <button className="btn btn-outline" onClick={() => onApprove(p.id)}>Schváliť</button>{" "}
                      <button className="btn btn-ghost" style={{ color: "var(--danger)", borderColor: "var(--danger)" }} onClick={() => setRejectingId(p.id)}>Zamietnuť</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {renderGroupTable(objednane, "Objednané", "var(--ok)", false)}
      {renderGroupTable(cakaNaObjednanie, "Čaká na objednanie", "var(--warn)", true)}
      {zamietnute.length > 0 && (
        <div style={{ marginBottom: 20 }}>
          <h2 className="today-sec red" style={{ margin: "16px 0 8px" }}>
            Zamietnuté · {zamietnute.length}
          </h2>
          <div className="panel table-wrap jobs-wrap" style={{ padding: 0, boxShadow: "none", borderRadius: 12 }}>
            <table className="table-cards jobs-table" style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  {columns.map((c) => <th key={c.key} style={{ whiteSpace: "nowrap" }}>{c.label}</th>)}
                  <th style={{ whiteSpace: "nowrap" }}>Určenie</th>
                  <th style={{ whiteSpace: "nowrap" }}>Dôvod</th>
                  {canManage && <th></th>}
                </tr>
              </thead>
              <tbody>
                {zamietnute.map((p) => (
                  <tr key={p.id} id={`sp-${p.id}`}>
                    {columns.map((c) => <td key={c.key} data-label={c.label}>{p[c.key] || "—"}</td>)}
                    <td style={{ whiteSpace: "nowrap" }} data-label="Určenie">{urcenieLabel(p.urcenie)}</td>
                    <td style={{ color: "var(--danger-text)" }} data-label="Dôvod">{p.rejectionReason}</td>
                    {canManage && (
                      <td style={{ whiteSpace: "nowrap" }} className="td-actions">
                        <button className="btn btn-outline" onClick={() => onRestore(p.id)}>Obnoviť</button>{" "}
                        <button className="btn btn-ghost" style={{ padding: "2px 8px", color: "var(--danger)" }} title="Vymazať riadok" aria-label="Vymazať riadok" onClick={() => onDelete(p.id)}>🗑</button>
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {isAdminUser(user) && showImport && (
        <SparePartsImportButton depo={depo} onImport={onImport} onClose={() => setShowImport(false)} />
      )}
      </>
      )}

      {showAdd && (
        <AddSparePartModal
          canManage={canManage}
          defaultDepo={depo}
          depoOptions={depoOptions}
          machines={machines}
          onClose={() => setShowAdd(false)}
          onSave={(data) => {
            if (onAdd(data) === false) return;
            setShowAdd(false);
            if (!canManage) {
              setConfirmMessage(
                data.length === 1
                  ? `Požiadavka odoslaná na schválenie: ${data[0].pocetKusov}× ${data[0].cisloDielu} — ${data[0].popisDielu}`
                  : `Požiadavka odoslaná na schválenie: ${plural(data.length, "položka", "položky", "položiek")}`
              );
            }
          }}
        />
      )}
      {rejectingId && (
        <RejectSparePartModal
          onClose={() => setRejectingId(null)}
          onConfirm={(reason) => { onReject(rejectingId, reason); setRejectingId(null); }}
        />
      )}
    </div>
  );
}

// Import histórie dielov — okno sa otvára z ⋯ v Náhradných dieloch (onClose ho zavrie).
function SparePartsImportButton({ depo, onImport, onClose }) {
  const show = true;
  const setShow = (v) => { if (!v) onClose(); };
  const [rows, setRows] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [mapDodavatel, setMapDodavatel] = useState("");
  const [mapCisloPolozky, setMapCisloPolozky] = useState("");
  const [mapPocetKusov, setMapPocetKusov] = useState("");
  const [mapCisloDielu, setMapCisloDielu] = useState("");
  const [mapPopisDielu, setMapPopisDielu] = useState("");
  const [mapStav, setMapStav] = useState("");
  const [mapDatum, setMapDatum] = useState("");
  const [mapObjednavka, setMapObjednavka] = useState("");
  const [mapPoznamka, setMapPoznamka] = useState("");

  function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (res) => {
        setHeaders(res.meta.fields || []);
        setRows(res.data);
      },
    });
  }

  function doImport() {
    const items = rows
      .map((r) => ({
        depo,
        dodavatel: mapDodavatel ? (r[mapDodavatel] || "").toString().trim() : "",
        cisloPolozky: mapCisloPolozky ? (r[mapCisloPolozky] || "").toString().trim() : "",
        pocetKusov: mapPocetKusov ? (r[mapPocetKusov] || "").toString().trim() : "",
        cisloDielu: mapCisloDielu ? (r[mapCisloDielu] || "").toString().trim() : "",
        popisDielu: mapPopisDielu ? (r[mapPopisDielu] || "").toString().trim() : "",
        stav: mapStav && (r[mapStav] || "").toString().trim() ? (r[mapStav] || "").toString().trim() : SPAREPART_STAV.OBJEDNANE,
        datumObjednania: mapDatum ? parseImportDate(r[mapDatum]) : "",
        nakupnaObjednavka: mapObjednavka ? (r[mapObjednavka] || "").toString().trim() : "",
        poznamka: mapPoznamka ? (r[mapPoznamka] || "").toString().trim() : "",
      }))
      .filter((x) => x.cisloDielu);
    onImport(items);
    setShow(false);
    setRows([]);
    setHeaders([]);
  }

  return (
    <>
      {show && (
        <Modal title={`Import histórie náhradných dielov — ${depo}`} onClose={() => setShow(false)} wide>
          <Field label="Vyberte CSV súbor (exportovaný z Excelu, len pre toto depo)">
            <input type="file" accept=".csv" onChange={handleFile} />
          </Field>
          {headers.length > 0 && (
            <>
              <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 14 }}>
                {[
                  ["Dodávateľ", mapDodavatel, setMapDodavatel],
                  ["Číslo položky", mapCisloPolozky, setMapCisloPolozky],
                  ["Počet kusov", mapPocetKusov, setMapPocetKusov],
                  ["Číslo dielu", mapCisloDielu, setMapCisloDielu],
                  ["Popis dielu", mapPopisDielu, setMapPopisDielu],
                  ["Stav objednania", mapStav, setMapStav],
                  ["Dátum objednania", mapDatum, setMapDatum],
                  ["Nákupná objednávka", mapObjednavka, setMapObjednavka],
                  ["Poznámka", mapPoznamka, setMapPoznamka],
                ].map(([label, val, setter]) => (
                  <Field key={label} label={`Stĺpec = ${label}`}>
                    <select value={val} onChange={(e) => setter(e.target.value)} style={{ width: "100%" }}>
                      <option value="">—</option>
                      {headers.map((h) => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </Field>
                ))}
              </div>
              <button className="btn btn-accent" disabled={!mapCisloDielu} onClick={doImport}>Importovať {plural(rows.length, "riadok", "riadky", "riadkov")} do depa {depo}</button>
            </>
          )}
        </Modal>
      )}
    </>
  );
}

// Stránka s neuloženou zmenou (Checkeri) — menu sa pred odchodom opýta (ako okno s rozpísanými údajmi).
// shortcut: stráži len prechod cez menu (navGo), nie skok z vyhľadávania/upozornenia; rozšíriť, ak to bude treba aj inde.
let _leaveGuard = null;
function DepoCheckerSettingsView({ depoCheckers, technicians, checkerSubstitutions, onDeleteSubstitution, onSave }) {
  const [values, setValues] = useState(depoCheckers || {});
  // Stav pri otvorení — uloží sa len to, čo zmenil tento človek (kolega mohol medzitým nastaviť iné depo).
  const initialRef = useRef(depoCheckers || {});
  const valuesRef = useRef(values);
  valuesRef.current = values;
  // Zmena od kolegu (realtime) — prevziať do depa, ktoré tu nikto neupravuje; rozpísané depo ostáva.
  useEffect(() => {
    const init = initialRef.current, cur = valuesRef.current, next = { ...cur }, nextInit = { ...init };
    for (const d of DEPO_OPTIONS) {
      if ((cur[d] || "") !== (init[d] || "")) continue;
      next[d] = depoCheckers?.[d]; nextInit[d] = depoCheckers?.[d];
    }
    initialRef.current = nextInit;
    setValues(next);
  }, [depoCheckers]);
  const technicianName = (id) => technicians.find((t) => t.id === id)?.name || "—";
  const changed = (d) => (values[d] || "") !== (initialRef.current[d] || "");
  const dirty = DEPO_OPTIONS.some(changed);
  useEffect(() => {
    if (!dirty) return;
    const onBeforeUnload = (e) => { e.preventDefault(); e.returnValue = ""; };
    window.addEventListener("beforeunload", onBeforeUnload);
    _leaveGuard = () => window.confirm("Odísť zo stránky? Zmenení checkeri sa neuložia.");
    return () => { window.removeEventListener("beforeunload", onBeforeUnload); _leaveGuard = null; };
  }, [dirty]);

  return (
    <div>
      <h1 className="page-h1">Checkeri podľa depa</h1>
      <p className="page-intro">
        Kto skontroluje/pripraví stroj na danom depe pri vývoze aj zvoze — platforma to už nebude pýtať pri
        každej zákazke zvlášť. Zmeňte tu kedykoľvek (dovolenka, zmena osoby na tejto úlohe a pod.) —
        pri zadaní dovolenky checkerovi priamo v Pláne servisu platforma navyše sama ponúkne dočasnú náhradu.
      </p>
      <div style={{ maxWidth: 560 }}>
        <div className="panel jobs-wrap" style={{ boxShadow: "none", borderRadius: 12, marginBottom: 14 }}>
          <table className="table-cards jobs-table dense">
            <thead><tr><th>Depo</th><th>Checker</th></tr></thead>
            <tbody>
              {DEPO_OPTIONS.map((depo) => (
                <tr key={depo}>
                  <td className="td-plain" style={{ fontWeight: 600 }}>
                    {depo}
                    {changed(depo) && <span title="Neuložená zmena" style={{ marginLeft: 8, fontSize: 12, fontWeight: 600, color: "var(--warn)" }}>● neuložené</span>}
                  </td>
                  <td className="td-plain">
                    <select
                      aria-label={`Checker — ${depo}`}
                      value={values[depo] || ""}
                      onChange={(e) => setValues((v) => ({ ...v, [depo]: e.target.value || undefined }))}
                      style={{ width: "100%", height: 40, fontSize: 15, color: values[depo] ? undefined : "var(--text-dim)" }}
                    >
                      <option value="">— nenastavené —</option>
                      {technicians.filter((t) => !t.archived).map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
                    </select>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <button
          className="btn btn-accent"
          style={{ marginBottom: 20 }}
          disabled={!dirty}
          onClick={() => {
            // vyčistí prázdne hodnoty, nech sa v databáze nehromadí "undefined"
            const cleaned = {};
            Object.entries(values).forEach(([k, v]) => {
              if (v) cleaned[k] = v;
            });
            // Ďalšie uloženie v tom istom okne porovnáva s tým, čo sa práve uložilo;
            // zablokované (bez signálu) sa vráti na uložený stav, nech sa dá zopakovať.
            if (onSave(cleaned, initialRef.current) === false) setValues(depoCheckers || {});
            else { initialRef.current = cleaned; setValues(cleaned); }
          }}
        >
          Uložiť
        </button>
      </div>
      {checkerSubstitutions && checkerSubstitutions.length > 0 && (
        <>
          <h2 className="today-sec">
            Aktívne/naplánované náhrady (dovolenka)
          </h2>
          <div style={{ display: "flex", flexDirection: "column", gap: 6, maxWidth: 560 }}>
            {checkerSubstitutions.map((s) => (
              <div key={s.id} className="panel" style={{ padding: "10px 14px", display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", fontSize: 14, boxShadow: "none" }}>
                <span><strong>{s.depo}</strong>: {technicianName(s.originalTechnicianId)} → {technicianName(s.substituteTechnicianId)}</span>
                <span className="tnum" style={{ color: "var(--text-dim)" }}>({fmtDate(s.startDate)} – {fmtDate(s.endDate)})</span>
                <button
                  className="btn btn-ghost"
                  style={{ color: "var(--danger)", marginLeft: "auto" }}
                  onClick={() => onDeleteSubstitution(s.id)}
                >
                  Zmazať
                </button>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// Audit log (13.3) — kto čo zmenil/zmazal. Dáta sa neťahajú pri štarte appky ako
// ostatné (bolo by to zbytočné pre 99% otvorení appky) — načíta sa až pri otvorení
// tejto záložky. Prístup majú len administrátori (rovnako obmedzené aj v RLS).
const AUDIT_TABLE_LABELS = {
  partHandovers: "Výdaj dielov",
  damages: "Poškodenia / servis",
  jobs: "Zákazky (požičovňa)",
  machines: "Stroje",
  spareParts: "Náhradné diely",
  handoverProtocols: "Protokoly o odovzdaní",
  employees: "Zamestnanci",
  profiles: "Účty (rola, prístup)",
};
const AUDIT_ACTION_LABELS = { insert: "Vytvorené", update: "Upravené", delete: "Zmazané" };
const AUDIT_FIELD_LABELS = { assignedDate: "dátum pridelenia", assignmentId: "úloha", archivedDate: "dátum archivácie", archivedReason: "dôvod archivácie", archivedNote: "poznámka k archivácii", stav: "stav", status: "stav", resolved: "vyriešené", technicianId: "technik", technicianIds: "technici", popis: "popis", customer: "zákazník", machineId: "stroj", driverId: "šofér", returnDriverId: "šofér zvozu", startDate: "od", endDate: "do", depo: "depo", role: "rola", active: "prístup", archived: "archivovaný", name: "meno", phone: "telefón", email: "email", linkedUserId: "prepojený účet", note: "poznámka" };
// Čo sa zmenilo pri úprave: old_data = staré hodnoty zmenených polí (step113), inak predošlý načítaný zápis záznamu.
function auditChange(e, prevData, nameOf) {
  if (e.action !== "update") return "";
  const now = e.new_data || {};
  if (!e.old_data && !prevData) return "";
  const was = e.old_data ? { ...now, ...e.old_data } : prevData;
  const fmt = (k, v) => (v === null || v === undefined || v === "" ? "—" : typeof v === "boolean" ? (v ? "áno" : "nie") : k === "role" ? roleLabel(v) : (nameOf[v] || String(v)).slice(0, 30));
  const out = [];
  const stav = e.table_name === "damages" && damageLabel(was) !== damageLabel(now);
  if (stav) out.push(`stav: ${damageLabel(was)} → ${damageLabel(now)}`);
  const keys = [...new Set([...Object.keys(was), ...Object.keys(now)])].filter((k) => !k.startsWith("_") && !/At$/.test(k) && !(stav && ["stav", "resolved"].includes(k)) && JSON.stringify(was[k] ?? null) !== JSON.stringify(now[k] ?? null));
  // Zoznamy a vnorené údaje (fotky, checklist) len názvom poľa.
  keys.forEach((k) => { const lbl = AUDIT_FIELD_LABELS[k] || (FIELD_LABELS[k] || k).toLowerCase(); out.push(typeof (now[k] ?? was[k]) === "object" ? `${lbl} (zmenené)` : `${lbl}: ${fmt(k, was[k])} → ${fmt(k, now[k])}`); });
  return out.length > 3 ? `${out.slice(0, 3).join(" · ")} · +${out.length - 3}` : out.join(" · ");
}
const AUDIT_OPEN_TYPE = { damages: "damage", jobs: "job", machines: "machine" };
export const _testAdmin = { auditChange, trashSubline, accountRoleDiffers }; // admin.test.js
// Úvodný sprievodca — prechádza skutočné obrazovky platformy (prepne modul/záložku) a vysvetlí ich kartičkou dole.
// Krok s obrazovkou sa ukáže len tomu, kto ju v menu má; roles: null = všetkým.
const FIELD_ROLES = ["sofer", "externy_sofer", "technik", "veduci_technik_ba"];
const POZ_OFFICE = ["dispecer_pozicovne", "veduci_pozicovne", "obchodnik", "fakturant_pozicovna"];
const SRV_OFFICE = ["dispecer_servisu", "veduci_servisu", "fakturant_servis", "veduci_technik_ba"];
const TOUR_STEPS = [
  { title: "Vitaj v platforme mateco", text: "Tento krátky sprievodca ťa prevedie hlavnými časťami platformy — prepína obrazovky za teba, stačí klikať „Ďalej“. Znova ho otvoríš v menu účtu (vpravo hore) → 🧭 Sprievodca platformou." },
  { go: ["dnes", "dnes"], title: "Dnes", text: "Tvoje úlohy na dnes s priamymi tlačidlami — začni deň vždy tu. Číslo pri položke menu ukazuje, koľko vecí na teba čaká." },
  { needsActions: true, title: "＋ Nové", text: "Nové veci zakladáš tlačidlom ＋ — na počítači v hlavičke, na mobile v strede spodnej lišty: zákazka, protokol, nahlásenie poruchy… podľa toho, čo tvoja rola smie." },
  { go: ["poziciovna", "calendar"], roles: [...POZ_OFFICE, "sofer", "technik"], title: "Kalendár strojov", text: "Kto má ktorý stroj a dokedy. Červené bunky = porucha, uhlopriečka = deň výmeny. Po prejdení myšou sa ukáže detail, klikom otvoríš zákazku." },
  { go: ["poziciovna", "jobs"], roles: POZ_OFFICE, title: "Zákazky", text: "Všetky zákazky s rýchlymi filtrami: po termíne, končí čoskoro, bez šoféra. Klik na zákazku otvorí jej kartu so všetkými krokmi." },
  { go: ["poziciovna", "prepravy"], roles: ["sofer", "dispecer_pozicovne", "veduci_pozicovne"], title: "Prepravy", text: "Vývozy, zvozy a prevozy medzi depami. Šofér tu vypíše protokol o odovzdaní či vrátení a pri prevoze klikne „Prevezené“." },
  { go: ["poziciovna", "dispeceri"], roles: ["dispecer_pozicovne", "veduci_pozicovne"], title: "Dispečeri", text: "Kto rieši ktoré depo, dovolenky a zástupy. Upozornenia k zákazke idú jej dispečerovi (počas dovolenky jeho zástupu)." },
  { go: ["servis", "plan"], roles: ["technik", ...SRV_OFFICE], title: "Plán servisu", text: "Plán technikov: servisné zásahy, kontroly strojov (checker), pohotovosti a dovolenky. Technik tu vidí svoje úlohy a otvorí z nich protokol." },
  { go: ["servis", "poskodenia"], roles: SRV_OFFICE, title: "Poškodenia", text: "Nahlásené poruchy strojov — priradenie technikovi a stav opravy. Kým nie je opravené, svieti stroj v kalendári červeno." },
  { go: ["servis", "diely"], roles: SRV_OFFICE, title: "Náhradné diely", text: "Objednávky dielov na schválenie a výdaj dielov zákazníkom s podpisom." },
  { go: ["administrativa", "zamestnanci"], roles: ["veduci_pozicovne", "veduci_servisu", "admin"], title: "Administratíva", text: "Zamestnanci a ich roly, checkeri podľa depa, štatistiky." },
  { roles: FIELD_ROLES, title: "Bez signálu", text: "Protokoly a kontroly vypĺňaj pokojne aj bez signálu — uložia sa v telefóne a odošlú sa samé. Hore vtedy svieti počet čakajúcich zmien; kým nie je nula, neodhlasuj sa." },
  { title: "Upozornenia", text: "🔔 v hlavičke zbiera upozornenia, ktoré sa ťa týkajú. V menu účtu → Notifikácie si zapni upozornenia do telefónu a vyber, o čom chceš vedieť." },
  { title: "Hotovo", text: "To je všetko. Ak ti niečo nejde alebo máš nápad, pošli pripomienku ako doteraz e-mailom. Ak už sprievodcu nechceš vidieť pri každom otvorení, zaškrtni „Už nezobrazovať“." },
];
function PlatformTour({ role, modules, hasActions, hidden, onGo, onClose, bottom }) {
  const has = (m, v) => modules.some((x) => x.id === m && x.tabs.some((t) => t.id === v || (t.group || []).includes(v)));
  const steps = TOUR_STEPS.filter((st) => (!st.roles || role === "admin" || st.roles.includes(role)) && (!st.go || has(...st.go)) && (!st.needsActions || hasActions));
  const [i, setI] = useState(0);
  const [hide, setHide] = useState(!!hidden);
  const st = steps[Math.min(i, steps.length - 1)];
  useEffect(() => { if (st.go) onGo(...st.go); }, [i]); // eslint-disable-line react-hooks/exhaustive-deps
  const last = i >= steps.length - 1;
  return (
    <div role="dialog" aria-label="Sprievodca platformou" style={{ position: "fixed", left: "50%", transform: "translateX(-50%)", bottom, zIndex: 9000, width: "min(520px, calc(100vw - 24px))", background: "var(--panel)", border: "2px solid var(--accent)", borderRadius: 14, boxShadow: "0 10px 32px rgba(0,0,0,.28)", padding: "14px 16px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
        <div style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--accent)" }}>Sprievodca · {i + 1} / {steps.length}</div>
        <button type="button" aria-label="Zavrieť sprievodcu" onClick={() => onClose(hide)} style={{ border: 0, background: "none", fontSize: 22, lineHeight: 1, cursor: "pointer", color: "var(--text-dim)", minWidth: 44, minHeight: 44 }}>×</button>
      </div>
      <div style={{ fontSize: 17, fontWeight: 700, margin: "4px 0 6px" }}>{st.title}</div>
      <div style={{ fontSize: 14, lineHeight: 1.5, marginBottom: 12 }}>{st.text}</div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
        <label style={{ fontSize: 13, display: "flex", alignItems: "center", gap: 6, cursor: "pointer" }}>
          <input type="checkbox" checked={hide} onChange={(e) => setHide(e.target.checked)} /> Už nezobrazovať
        </label>
        <div style={{ display: "flex", gap: 8 }}>
          {i > 0 && <button className="btn btn-ghost" onClick={() => setI(i - 1)}>Späť</button>}
          <button className="btn btn-accent" onClick={() => (last ? onClose(hide) : setI(i + 1))}>{last ? "Hotovo" : "Ďalej"}</button>
        </div>
      </div>
    </div>
  );
}
// Stav platformy (admin): nočné úlohy, chyby push/webhookov, staré kontroly, platforma u ľudí — step89.
function PlatformStatusView({ profiles = [], employees = [], onGo, onOpenUser }) {
  const [st, setSt] = useState(null);
  const [err, setErr] = useState(null);
  const load = useCallback(() => {
    setErr(null);
    supabase.rpc("admin_platform_status").then(({ data, error }) => (error ? setErr(error.message) : setSt(data)));
  }, []);
  useEffect(load, [load]);
  const downloadBackup = async (id) => {
    const { data, error } = await supabase.rpc("admin_backup_get", { p_id: id });
    if (error || !data) return showNotice(`Zálohu sa nepodarilo stiahnuť${error ? `: ${error.message}` : ""}.`);
    const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }));
    const a = document.createElement("a");
    a.href = url; a.download = `mateco-zaloha-auto-${id}.json`;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  const ago = (t) => { if (!t) return "—"; const h = (Date.now() - new Date(t).getTime()) / 3600000; return h < 1 ? `${Math.max(1, Math.round(h * 60))} min` : h < 48 ? `${Math.round(h)} h` : `${Math.round(h / 24)} d`; };
  const when = (t) => (t ? new Date(t).toLocaleString("sk-SK", { day: "numeric", month: "numeric", hour: "2-digit", minute: "2-digit" }) : "—");
  const head = { textAlign: "left", padding: "10px 12px", position: "static", fontFamily: "'Barlow Condensed', sans-serif", fontSize: 14, fontWeight: 600, letterSpacing: ".05em", color: "var(--text-dim)", background: "var(--panel)" };
  const td = { padding: "10px 12px", fontSize: 14, borderTop: "1px solid var(--border)" };
  // Nevyhovujúci stav (nedostupné, chyba) — ⚠ s podfarbením, nech sa odlíši od „v poriadku“.
  const bad = (t) => <div className="spill spill-problem" style={{ display: "block", whiteSpace: "normal", borderRadius: 8, padding: "8px 12px", fontSize: 14 }}>⚠ {t}</div>;
  const box = (title, children, id) => (
    <>
      <h2 className="today-sec" id={id} style={{ scrollMarginTop: 80 }}>{title}</h2>
      <div className="panel" style={{ padding: 14, marginBottom: 14, boxShadow: "none", borderRadius: 12 }}>
        {children}
      </div>
    </>
  );
  const H1 = <h1 className="page-h1" style={{ marginBottom: 14 }}>Stav platformy</h1>;
  if (err) return <div>{H1}<div className="panel" style={{ padding: 14, boxShadow: "none" }}>{bad(`Stav sa nenačítal: ${err} (spustený step89?)`)} <button className="btn btn-outline" style={{ marginTop: 10 }} onClick={load}>Skúsiť znova</button></div></div>;
  if (!st) return <div>{H1}<div style={{ color: "var(--text-dim)" }}>Načítava sa…</div></div>;
  const clients = st.clients || [];
  const old = clients.filter((c) => c.version && c.version !== APP_VERSION);
  const queued = clients.filter((c) => c.queued > 0);
  const toBox = (id) => () => document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" });
  const roleDiff = profiles.map((p) => [p, employees.find((e) => e.linkedUserId === p.id && !e.archived)]).filter(([p, e]) => accountRoleDiffers(p, e));
  const nQueued = queued.reduce((n, c) => n + c.queued, 0);
  const nErr = st.httpErrors ? st.httpErrors.length : 0;
  // Číslo > 0 vedie na zoznam, kde sa to rieši; odmietnuté zmeny rieši dispečing (Prepravy).
  const tiles = [
    { label: "Čakajúce zmeny bez signálu", n: nQueued, onClick: nQueued ? (queued.some((c) => c.blocked) ? () => onGo("poziciovna", "prepravy") : toBox("stav-ludia")) : undefined },
    { label: "Staršia verzia platformy", n: old.length, onClick: old.length ? toBox("stav-ludia") : undefined },
    { label: "Kontroly stroja z minulých dní", n: st.oldInspections || 0, tone: "red", onClick: st.oldInspections ? () => onGo("servis", "plan") : undefined },
    { label: "Chyby push / webhookov", n: nErr, tone: "red", onClick: nErr ? toBox("stav-chyby") : undefined },
    { label: "Rola účtu ≠ rola karty", n: roleDiff.length, tone: "red", onClick: roleDiff.length ? toBox("stav-roly") : undefined },
  ].map((t) => ({ ...t, always: true }));
  return (
    <div>
      {H1}
      <div className="tbar">
        <span className="tnum" style={{ fontSize: 14, color: "var(--text-dim)" }}>Stav k {when(st.now)} · táto verzia {APP_VERSION}</span>
        <button className="btn btn-outline" onClick={load}>Obnoviť</button>
      </div>
      <TodayTiles tiles={tiles} />
      {box("Nočné úlohy (databáza)", st.cron ? (
        <div style={{ overflowX: "auto" }}><table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead><tr><th style={head}>Úloha</th><th style={head}>Kedy (UTC)</th><th style={head}>Posledný beh</th><th style={head}>Výsledok</th></tr></thead>
          <tbody>{st.cron.map((c) => (
            <tr key={c.name}>
              <td style={td}>{c.name}{!c.active && <span className="spill spill-wait" style={{ marginLeft: 6 }}>vypnutá</span>}</td>
              <td style={td}>{c.schedule}</td>
              <td style={td}>{when(c.start)}</td>
              <td style={{ ...td, color: c.status === "succeeded" ? "var(--ok)" : c.status ? "var(--danger)" : "var(--text-dim)" }}>{c.status === "succeeded" ? "OK" : c.status ? `${c.status}${c.message ? ` — ${c.message}` : ""}` : "ešte nebežala"}</td>
            </tr>
          ))}</tbody>
        </table></div>
      ) : bad("Plánovač úloh (pg_cron) nie je dostupný."))}
      {box("Účty, kde sa rola účtu líši od roly aktívnej karty", roleDiff.length ? (
        <div style={{ fontSize: 14 }}>
          {roleDiff.map(([p, e], i) => (
            <div key={p.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, flexWrap: "wrap", padding: "4px 0", borderTop: i ? "1px solid var(--border)" : 0 }}>
              <span><strong>{p.name || p.email}</strong> · účet: {roleLabel(p.role)} · karta: {roleLabel(e.role)}</span>
              {onOpenUser && <button className="btn btn-outline" style={{ minHeight: 34 }} onClick={() => onOpenUser(p)}>Otvoriť účet</button>}
            </div>
          ))}
        </div>
      ) : <div style={{ fontSize: 14, color: "var(--ok)" }}>✓ Rola každého účtu sa zhoduje s jeho kartou zamestnanca.</div>, "stav-roly")}
      {box("Platforma u ľudí", (
        <div style={{ overflowX: "auto" }}><table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead><tr><th style={head}>Meno</th><th style={head}>Rola</th><th style={head}>Verzia</th><th style={head}>Čaká na odoslanie</th><th style={head}>Odmietnuté upozornenia</th><th style={head}>Naposledy online</th></tr></thead>
          <tbody>
            {clients.length === 0 && <tr><td style={td} colSpan={6}>Zatiaľ nikto (hlási sa od verzie 1.0.787).</td></tr>}
            {clients.map((c) => (
              <tr key={c.id}>
                <td style={td}>{c.name || "—"}</td>
                <td style={td}>{ROLES.find((r) => r.id === c.role)?.label || c.role || "—"}</td>
                <td style={{ ...td, color: c.version !== APP_VERSION ? "var(--warn)" : undefined }}>{c.version || "—"}</td>
                <td style={{ ...td, color: c.blocked ? "var(--danger)" : c.queued ? "var(--warn)" : undefined }}>
                  {c.queued ? `${c.queued}${c.blocked ? ` (${c.blocked} odmietnuté)` : ""} · ${ago(c.queueSince)}` : "—"}
                </td>
                <td style={{ ...td, color: c.dropped ? "var(--danger)" : undefined }} title="Upozornenia, ktoré databáza odmietla (napr. bez autora) — od otvorenia platformy">{c.dropped || "—"}</td>
                <td style={td}>{ago(c.lastSeen)}</td>
              </tr>
            ))}
          </tbody>
        </table></div>
      ), "stav-ludia")}
      {box("Automatické zálohy (každú noc, 14 dní)", st.backups ? (st.backups.length ? (
        <div style={{ fontSize: 13 }}>
          {(Date.now() - new Date(st.backups[0].at).getTime()) / 3600000 > 26 && <div style={{ marginBottom: 6 }}>{bad("Posledná záloha je staršia ako deň — skontrolujte nočnú úlohu mateco-backup.")}</div>}
          {st.backups.map((b) => (
            <div key={b.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, padding: "4px 0", borderTop: "1px solid var(--border)" }}>
              <span>{fmtDate(b.id)} · {when(b.at)} · {Math.max(1, Math.round((b.size || 0) / 1024))} kB</span>
              <button className="btn btn-outline" style={{ minHeight: 34 }} onClick={() => downloadBackup(b.id)}>Stiahnuť</button>
            </div>
          ))}
          <div style={{ fontSize: 13, color: "var(--text-dim)", marginTop: 6 }}>Obnova: menu účtu → Import dát → vybrať stiahnutý súbor.</div>
        </div>
      ) : <div style={{ fontSize: 14, color: "var(--text-dim)" }}>Zatiaľ žiadna — prvá vznikne v noci.</div>) : bad("Nedostupné (spustený step91?)."))}
      {box("Chyby push / webhookov (posledných ~6 h)", st.httpErrors ? (st.httpErrors.length ? (
        <div style={{ fontSize: 14 }}>{st.httpErrors.map((h, i) => <div key={i} style={{ padding: "4px 0", borderTop: i ? "1px solid var(--border)" : 0 }}><strong>{when(h.at)}</strong> · {h.status || "bez odpovede"} · {h.error || ""}</div>)}</div>
      ) : <div style={{ fontSize: 14, color: "var(--ok)" }}>✓ Bez chýb.</div>) : bad("Nedostupné."), "stav-chyby")}
      <div className="page-intro">Kontroly z minulých dní ráno presúva databáza (cez víkend nie) — číslo nad 0 v pracovný deň po 6:00 znamená, že ranný presun neprebehol. Čakajúce zmeny u človeka sa ukážu, keď je online; „odmietnuté“ treba vyriešiť v dispečingu.</div>
    </div>
  );
}
function AuditLogView({ profiles, employees = [], machines = [], onOpen }) {
  const [entries, setEntries] = useState(null); // null = ešte sa načítava
  const [tableFilter, setTableFilter] = useState("");
  const [hideSystem, setHideSystem] = useState(true);
  const [who, setWho] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [error, setError] = useState(null);
  const profileById = useMemo(() => Object.fromEntries(profiles.map((p) => [p.id, p])), [profiles]);
  const nameOf = useMemo(() => Object.fromEntries([...machines.map((m) => [m.id, m.code]), ...employees.map((x) => [x.id, x.name]), ...profiles.map((p) => [p.id, p.name])]), [machines, employees, profiles]);

  useEffect(() => {
    let cancelled = false;
    setEntries(null);
    let q = supabase.from("audit_log").select("*");
    // Filtre na serveri — inak by sa hľadalo len v posledných 300 zmenách.
    if (who) q = q.eq("changed_by", who);
    else if (hideSystem) q = q.not("changed_by", "is", null);
    if (from) q = q.gte("changed_at", new Date(`${from}T00:00`).toISOString());
    if (to) q = q.lt("changed_at", new Date(`${addDaysISO(to, 1)}T00:00`).toISOString()); // polnoc nasledujúceho dňa (deň zmeny času má 25 h)
    q.order("changed_at", { ascending: false })
      .limit(300)
      .then(({ data, error: err }) => {
        if (cancelled) return;
        if (err) {
          console.error("Načítanie audit logu zlyhalo", err);
          setError(err.message || "Neznáma chyba");
          return;
        }
        setEntries(data || []);
      });
    return () => { cancelled = true; };
  }, [who, from, to, hideSystem]);

  // Systémové = bez autora (databáza) alebo automatický tiket revízie/ÚS, ktorý založila platforma u prihláseného.
  const auto = (e) => !e.changed_by || (e.table_name === "damages" && e.action === "insert" && /^(rev|us)-/.test(e.record_id));
  const filtered = (entries || []).filter((e) => (!tableFilter || e.table_name === tableFilter) && !(hideSystem && !who && auto(e)));
  // Hromadné systémové zápisy za sebou (napr. automatické tikety revízií) — jeden riadok.
  const rows = [];
  filtered.forEach((e) => {
    const last = rows[rows.length - 1];
    if (auto(e) && last && auto(last) && last.changed_by === e.changed_by && last.table_name === e.table_name && last.action === e.action) last.group.push(e);
    else rows.push({ ...e, group: [e] });
  });

  return (
    <div>
      <h1 className="page-h1">Audit log</h1>
      <p className="page-intro">
        Posledných {entries?.length || 0} zmien v citlivých tabuľkách (poškodenia/servis, zákazky, stroje, náhradné
        diely, protokoly o odovzdaní, zamestnanci, roly a prístup účtov) — zaznamenáva sa priamo v databáze, nedá sa obísť z platformy.
      </p>
      <div className="tbar">
        <select aria-label="Kto" value={who} onChange={(e) => setWho(e.target.value)} style={{ minHeight: 40 }}>
          <option value="">Všetci</option>
          {[...profiles].sort((a, b) => (a.name || "").localeCompare(b.name || "", "sk")).map((p) => <option key={p.id} value={p.id}>{p.name || p.email}</option>)}
        </select>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 14 }}>Od <input type="date" value={from} onChange={(e) => setFrom(e.target.value)} style={{ minHeight: 40 }} /></label>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 14 }}>do <input type="date" value={to} onChange={(e) => setTo(e.target.value)} style={{ minHeight: 40 }} /></label>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 14 }}>
          <input type="checkbox" checked={hideSystem} disabled={!!who} onChange={(e) => setHideSystem(e.target.checked)} />
          Skryť systémové
        </label>
      </div>
      <div className="tbar">
        <div className="seg chip-scroll" role="group" aria-label="Tabuľka" style={{ flexWrap: "wrap" }}>
          <button type="button" className={!tableFilter ? "on" : ""} aria-pressed={!tableFilter} onClick={() => setTableFilter("")}>Všetko</button>
          {Object.entries(AUDIT_TABLE_LABELS).map(([t, label]) => (
            <button key={t} type="button" className={tableFilter === t ? "on" : ""} aria-pressed={tableFilter === t} onClick={() => setTableFilter(tableFilter === t ? "" : t)}>{label}</button>
          ))}
        </div>
      </div>
      {error && (
        <div className="panel" style={{ padding: 20, color: "var(--danger)" }}>
          Nepodarilo sa načítať audit log: {error}
        </div>
      )}
      {!error && entries === null && (
        <div className="panel">
          <SkeletonRows rows={6} cols={5} />
        </div>
      )}
      {!error && entries !== null && (
        <div className="panel jobs-wrap" style={{ boxShadow: "none", borderRadius: 12 }}>
          <table className="table-cards jobs-table dense">
            <thead>
              <tr>
                <th>Kedy</th>
                <th>Kto</th>
                <th>Tabuľka</th>
                <th>Akcia</th>
                <th>Záznam</th>
                <th>Zmena</th>
              </tr>
            </thead>
            <tbody>
              {rows.length === 0 && (
                <tr><td className="td-plain" colSpan={6} style={{ textAlign: "center", padding: 30, color: "var(--text-dim)" }}>Žiadne zmeny v tomto filtri.</td></tr>
              )}
              {rows.map((e) => {
                const whoName = e.changed_by ? profileById[e.changed_by]?.name || "— neznámy účet —" : "— systém —";
                const data = e.action === "delete" ? e.old_data : e.new_data;
                const label = data?.code || data?.name || data?.customer || data?.cisloDielu || e.record_id;
                const n = e.group.length;
                const revs = e.table_name === "damages" && e.action === "insert" && e.group.every((x) => ["revizia", "uradnaSkuska"].includes(x.new_data?.type));
                const at = filtered.findIndex((x) => x.id === e.id);
                const prev = e.action === "update" && !e.old_data ? filtered.slice(at + 1).find((x) => x.table_name === e.table_name && x.record_id === e.record_id)?.new_data : null;
                const openType = n === 1 && e.action !== "delete" && onOpen && AUDIT_OPEN_TYPE[e.table_name];
                return (
                  <tr key={e.id}>
                    <td className="tnum" style={{ whiteSpace: "nowrap" }} data-label="Kedy">{new Date(e.changed_at).toLocaleString("sk-SK")}</td>
                    <td data-label="Kto" style={e.changed_by ? undefined : { color: "var(--text-dim)" }}>{whoName}</td>
                    <td data-label="Tabuľka">{AUDIT_TABLE_LABELS[e.table_name] || e.table_name}</td>
                    <td data-label="Akcia">
                      <span className={`spill ${e.action === "delete" ? "spill-problem" : e.action === "insert" ? "spill-done" : "spill-active"}`}>
                        {AUDIT_ACTION_LABELS[e.action] || e.action}
                      </span>
                    </td>
                    <td className="tnum" style={{ fontWeight: 700 }} data-label="Záznam">
                      {n > 1 ? (revs ? `Systém vytvoril ${plural(n, "tiket revízie", "tikety revízií", "tiketov revízií")}` : plural(n, "záznam", "záznamy", "záznamov"))
                        : openType ? <button type="button" className="btn-link" style={{ fontWeight: 700 }} onClick={() => onOpen({ type: openType, id: e.record_id })}>{label}</button> : label}
                    </td>
                    <td data-label="Zmena" style={{ fontSize: 13 }}>{n > 1 ? "" : auditChange(e, prev, nameOf)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function UserAdminModal({ profiles, currentUser, initialSearch, onClose, onUpdate, onDelete, onResetPassword }) {
  const [search, setSearch] = useState(initialSearch || "");
  const [adminAsk, setAdminAsk] = useState(null); // { p, role } — zmena z/na Administrátora čaká na potvrdenie
  const [undo, setUndo] = useState(null); // { id, name, prev, role } — posledná zmena roly
  const q = search.trim().toLowerCase();
  // Nové účty bez roly navrch (inak sa medzi ostatnými stratia).
  const shown = profiles
    .filter((p) => !q || (p.name || "").toLowerCase().includes(q) || (p.email || "").toLowerCase().includes(q))
    .sort((a, b) => (b.role === "nezaradeny") - (a.role === "nezaradeny"));
  const setRole = (p, role) => { Promise.resolve(onUpdate(p.id, { role })).then((ok) => { if (ok !== false) setUndo({ id: p.id, name: p.name, prev: p.role, role }); }); }; // „Späť“ len po úspešnom uložení
  const pickRole = (p, role) => (role === "admin" || p.role === "admin" ? setAdminAsk({ p, role }) : setRole(p, role));
  const instant = (e) => e.stopPropagation(); // hľadanie a rola (ukladá sa hneď) nie sú rozpísané údaje — Esc sa nepýta
  return (
    <Modal title="Správa používateľov" onClose={onClose} xwide>
      <div className="fhint" style={{ marginTop: -8, marginBottom: 14, fontSize: 14 }}>
        Noví ľudia sa registrujú sami na prihlasovacej obrazovke — tu im len prideľte rolu, prípadne ich deaktivujte/zmažte.
      </div>
      <div className="tbar" onInput={instant} onChange={instant}>
        <input type="search" aria-label="Hľadať používateľa" placeholder="Hľadať meno alebo email…" value={search} onChange={(e) => setSearch(e.target.value)} style={{ minHeight: 40, flex: "1 1 240px", maxWidth: 360 }} />
      </div>
      {undo && (
        <div role="status" className="fnote fnote-g" style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, flexWrap: "wrap", marginBottom: 10 }}>
          <span>✓ Rola účtu {undo.name} zmenená: {roleLabel(undo.prev)} → {roleLabel(undo.role)}</span>
          <button type="button" className="btn btn-outline" style={{ minHeight: 36 }} onClick={() => { pickRole({ id: undo.id, name: undo.name, role: undo.role }, undo.prev); if (undo.prev !== "admin" && undo.role !== "admin") setUndo(null); }}>Späť</button>
        </div>
      )}
      {adminAsk && (
        <ConfirmActionModal
          message={adminAsk.role === "admin"
            ? `Dať účtu ${adminAsk.p.name} rolu Administrátor? Získa plný prístup ku všetkému vrátane správy používateľov.`
            : `Odobrať účtu ${adminAsk.p.name} rolu Administrátor (nová rola: ${roleLabel(adminAsk.role)})?`}
          confirmLabel={adminAsk.role === "admin" ? "Áno, dať rolu Administrátor" : "Áno, odobrať"}
          onClose={() => setAdminAsk(null)}
          onConfirm={() => setRole(adminAsk.p, adminAsk.role)}
        />
      )}
      <div style={{ border: "1px solid var(--border)", borderRadius: 12, overflow: "hidden" }} onInput={instant} onChange={instant}>
      <table className="table-cards jobs-table">
        <thead>
          <tr>
            <th>Meno</th>
            <th>Email</th>
            <th>Rola</th>
            <th>Stav</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {shown.length === 0 && (
            <tr><td className="td-plain" colSpan={5} style={{ textAlign: "center", padding: 30, color: "var(--text-dim)" }}>{q ? "Nikto nezodpovedá hľadaniu." : "Zatiaľ žiadni používatelia."}</td></tr>
          )}
          {shown.map((p) => (
            <tr key={p.id}>
              <td className="td-plain" style={{ fontWeight: 600, whiteSpace: "nowrap" }}>{p.name}{p.id === currentUser?.id ? " (vy)" : ""}{p.role === "nezaradeny" && <span className="spill spill-wait" style={{ marginLeft: 8 }}>čaká na rolu</span>}</td>
              <td data-label="Email" style={{ whiteSpace: "nowrap" }}>{p.email || (p.id === currentUser?.id ? currentUser.email : "—")}</td>
              <td data-label="Rola">
                {p.id === currentUser?.id ? (
                  <span
                    style={{ color: "var(--text-dim)" }}
                    title="Svoju vlastnú rolu si nemôžete zmeniť — musí ju zmeniť iný administrátor (poistka, aby platforma neostala bez admina)"
                  >
                    {roleLabel(p.role)}
                  </span>
                ) : (
                  <select
                    value={p.role}
                    aria-label={`Rola — ${p.name}`}
                    onChange={(e) => pickRole(p, e.target.value)}
                    style={{ minHeight: 40, minWidth: 190 }}
                  >
                    {ROLES.map((r) => <option key={r.id} value={r.id}>{r.label}</option>)}
                  </select>
                )}
              </td>
              <td data-label="Stav">{p.active === false ? <span className="spill spill-problem">⚠ Deaktivovaný</span> : <span className="spill spill-done">Aktívny</span>}</td>
              <td className="td-actions" style={{ textAlign: "right" }}>
                <KebabMenu
                  label="⋯"
                  name="Ďalšie akcie"
                  actions={[
                    (p.email || p.id === currentUser?.id) && { label: "Resetovať heslo", onClick: () => onResetPassword(p.email || currentUser.email) },
                    p.id !== currentUser?.id && { label: p.active === false ? "Aktivovať" : "Deaktivovať", onClick: () => onUpdate(p.id, { active: p.active === false ? true : false }) },
                    p.id !== currentUser?.id && { label: "Zmazať", onClick: () => onDelete(p.id), danger: true },
                  ]}
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      </div>
    </Modal>
  );
}

// Písmo Barlow cez <link> v hlavičke, nie @import v <style>: Safari (iPhone) nepoužije štýly
// z <style> s @import, kým sa externé písmo nestiahne — úvodná obrazovka bola dovtedy bez štýlov.
if (typeof document !== "undefined" && !document.getElementById("mateco-font")) {
  const l = document.createElement("link");
  l.id = "mateco-font"; l.rel = "stylesheet";
  l.href = FONT_CSS_URL;
  document.head.appendChild(l);
}
function GlobalStyle() {
  return (
    <style>{`
      *, *::before, *::after { box-sizing: border-box; }
      button, input, select, textarea { font-family: inherit; } /* prehliadač inak dá tlačidlám Arial (účet, zvonček, × v okne) */
      :root {
        --bg: #f0f0f0;
        --panel: #ffffff;
        --panel-2: #f4f4f4;
        --border: #e0e0e0;
        --text: #1a1a1a;
        --text-dim: #5A5A5A;
        --accent: #E30613;
        --accent-dark: #B5040F;
        --accent-light: #fdf0f0;
        --c1: #2a78d6; --c2: #eb6834; --c3: #168f64; --c4: #b97f00; --c5: #e87ba4; --c-bad: #e34948; --c-idle: #8e8e89; --c-prep: #92400e; /* V príprave: odlíšiteľné od poruchy aj rezervácií */ /* kontrast grafov ≥ 3:1 (kolo 32) */
        /* Nepriehľadná verzia accent-light — pre miesta, kde má farba
           NIEČO PREKRYŤ (roh nad menami strojov v gantte), nie len jemne
           podfarbiť cez existujúci obsah. accent-light je v tmavom režime
           zámerne poloPRIEHĽADNÁ (viď nižšie) pre zvýraznenie riadkov, čo je
           tu presne opačne — cez priehľadný roh presvitali mená strojov aj
           dni scrollované pod hlavičkou (svetlý režim to nebolo vidno, lebo
           tam #fdf0f0 nepriehľadná náhodou je). */
        --gantt-header-bg: #fdf0f0;
        --ok: #3b6d11;
        --ok-bg: #eaf3de;
        --warn: #854f0b;
        --warn-bg: #faeeda;
        --gantt-name-col: 150px;
        --gantt-day-col: 72px;
        --gantt-plan-day-col: 96px; /* štítok úlohy s krátkym popisom („S-115 · hydraulika“) */
        --danger: #C4040F;
        --danger-bg: #FDF1F1;
        --danger-text: #8E0A12;
        --danger-row-bg: rgba(227,6,19,.13);
        --info: #185fa5;
        --info-bg: #e6f1fb;
        --gantt-cell-bg: #e8eaed;
        --gantt-cell-border: #c9ccd1;
        /* v1.0.795 tmavý režim: plná červená pod bielym textom (hlavička, hlavné tlačidlo, odznaky),
           silnejšia čiara ovládačov a farby štítkov stavu — svetlé hodnoty = schválený dizajn. */
        --accent-fill: #E30613;
        --ok-fill: #3b6d11; --warn-fill: #854f0b;
        --accent-fill-hover: #B5040F;
        --line-strong: #CFCFCF;
        --s-neutral-bg: #EFEFEF; --s-neutral: #3A3A3A;
        --s-active-bg: #E7EEF9; --s-active: #1F4E99;
        --s-out-bg: #E8EDF2; --s-out: #3E5368;
        --s-done-bg: #E6F4EA; --s-done: #1E6B34;
        --s-wait-bg: #FFF4DB; --s-wait: #6B4A00;
        --control-bg: #fff;
        --control-line: #858585;
      }
      /* Predvolený 8px margin prehliadača na body nebol nikde resetovaný —
         cez tento okraj presvitalo biele pozadie body (appka naň nikdy
         nenastavovala žiadnu farbu) aj v tmavom režime, keďže --bg sa v
         tmavom režime prepisuje len v rámci .app-shell.dark, nie na body.
         .dark trieda na body (nastavovaná v JS podľa darkMode) drží pozadie
         pod appkou správne aj pri "gumovom" overscrolle. */
      html, body { margin: 0; }
      .today-sec { font-family: 'Barlow Condensed', sans-serif; font-size: 15px; font-weight: 600; text-transform: uppercase; letter-spacing: .06em; color: var(--text-dim); margin: 16px 0 8px; }
      .today-sec.red { color: var(--danger-text); }
      .panel.today-tile { display: flex; flex-direction: column; gap: 2px; text-align: left; font: inherit; color: var(--text); padding: 14px 18px; border-radius: 12px; box-shadow: none; }
      button.today-tile { cursor: pointer; }
      button.today-tile:hover { border-color: var(--text-dim); }
      button.today-tile { position: relative; padding-right: 40px; }
      .today-tile-go { position: absolute; right: 14px; top: 50%; transform: translateY(-50%); font-size: 28px; line-height: 1; color: var(--text-dim); }
      button.today-tile:hover .today-tile-go { color: var(--text); }
      .today-tile-n { font-size: 28px; font-weight: 700; line-height: 1.1; font-variant-numeric: tabular-nums; }
      .today-tile-n.problem { color: var(--danger-text); }
      .today-tile.zero .today-tile-n, .today-tile.zero .today-tile-go { color: var(--text-dim); }
      .today-tile.zero { background: transparent; }
      .panel.stat-click { display: block; width: 100%; text-align: left; font: inherit; color: var(--text); cursor: pointer; }
      .panel.stat-click:hover { border-color: var(--text-dim); }
      .panel.stat-click.on { border-color: var(--accent-fill); box-shadow: 0 0 0 1px var(--accent-fill); background: var(--accent-light); }
      @media (max-width: 640px) {
        .today-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 8px !important; }
        .panel.today-tile { padding: 10px 28px 10px 12px; }
        .today-tile-n { font-size: 22px; }
        .today-tile > span:nth-child(2) { font-size: 13px !important; line-height: 1.25; }
        .today-tile-go { right: 8px; font-size: 22px; }
      }
      .today-problem { background: var(--danger-bg) !important; }
      .today-problem-title { color: var(--danger-text); }
      .today-clamp2 { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; } /* dlhé hlásenie z portálu — celé na karte zákazky */
      .today-load { display: block; width: 120px; max-width: 100%; height: 6px; margin-top: 5px; border-radius: 4px; background: var(--panel-2); overflow: hidden; }
      .today-load > span { display: block; height: 100%; background: var(--info); }
      .today-hero { background: var(--panel); border: 1px solid var(--border); border-radius: 16px; padding: 20px; display: flex; flex-direction: column; gap: 10px; margin-bottom: 14px; }
      .today-hero-tag { font-family: 'Barlow Condensed', sans-serif; font-weight: 600; font-size: 16px; letter-spacing: .05em; text-transform: uppercase; color: var(--text-dim); }
      .today-hero-id { font-size: 26px; font-weight: 700; line-height: 1.15; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
      .today-hero-id small { font-size: 20px; font-weight: 500; color: var(--text-dim); }
      .today-hero-sub { font-size: 17px; line-height: 1.35; }
      .today-hero .btn { min-height: 48px; font-size: 16px; border-radius: 12px; display: flex; align-items: center; justify-content: center; gap: 6px; }
      .today-hero .btn.today-main { min-height: 56px; font-size: 18px; font-weight: 700; }
      .today-hero .btn.today-nav { min-height: 52px; font-size: 17px; font-weight: 700; border: 2px solid var(--text); }
      .today-hero-more { display: flex; gap: 8px; flex-wrap: wrap; }
      .today-hero-more .btn { flex: 1 1 120px; }
      .today-li.click { cursor: pointer; }
      .today-li.click:hover { background: var(--panel-2); }
      .today-row { display: flex; align-items: center; gap: 14px; width: 100%; min-height: 64px; padding: 8px 16px; margin-bottom: 8px; box-sizing: border-box; background: var(--panel); border: 1px solid var(--border); border-radius: 12px; font: inherit; font-size: 15px; color: var(--text); text-align: left; cursor: pointer; }
      .today-row-sub { display: block; font-size: 14px; color: var(--text-dim); }
      .sync-strip { background: var(--s-wait-bg); color: var(--s-wait); font-size: 14px; font-weight: 600; padding: 8px 24px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
      .sync-strip .sync-more { font-weight: 400; font-size: 13px; }
      @media (max-width: 720px), (max-width: 1000px) and (pointer: coarse) and (hover: none) {
        .who-hide-mobile { display: none !important; }
        .sync-strip { padding: 8px 16px; }
      }
      .header-damage-btn { color: var(--danger) !important; border-color: var(--danger) !important; font-weight: 700; }
      .header-damage-btn .hd-short, .job-form-foot .hd-short { display: none; }
      .binder { display: flex; margin-left: -20px; min-height: 200px; }
      .binder-tabs { flex: 0 0 34px; display: flex; flex-direction: column; gap: 6px; padding-top: 2px; }
      .binder-tab { writing-mode: vertical-rl; transform: rotate(180deg); padding: 14px 7px; border: 1px solid var(--border); border-right: none; border-radius: 8px 0 0 8px;
        background: var(--panel-2); color: var(--text-dim); font: 600 12px/1 inherit; font-family: inherit; cursor: pointer; text-align: center; white-space: nowrap; }
      .binder-tab:hover { color: var(--text); }
      .binder-tab.active { background: var(--accent-fill); color: #fff; border-color: var(--accent-fill); }
      .binder-body { flex: 1; min-width: 0; padding-left: 14px; }
      .binder-panel { animation: binderIn .18s ease-out; }
      @keyframes binderIn { from { opacity: 0; transform: translateX(-24px); } to { opacity: 1; transform: none; } }
      @media (max-width: 720px), (max-width: 1000px) and (pointer: coarse) and (hover: none) {
        .binder { margin-left: -12px; }
        .binder-body { padding-left: 10px; }
        .header-damage-btn .hd-full, .job-form-foot .hd-full { display: none; }
        .header-damage-btn .hd-short, .job-form-foot .hd-short { display: inline; }
      }
      body { background: #f0f0f0; }
      body.dark { background: #14171a; }
      .app-shell.dark {
        --bg: #14171a;
        --panel: #1e2226;
        --panel-2: #262b30;
        --border: #343b42;
        --text: #e8e6e3;
        --text-dim: #a0a8b0;
        --accent: #ff6b74;
        --accent-dark: #ff8a90;
        --accent-light: rgba(227,6,19,.18);
        --c1: #3987e5; --c2: #d95926; --c3: #199e70; --c4: #c98500; --c5: #d55181; --c-bad: #e66767; --c-idle: #7c8086; --c-prep: #b45309;
        --ok: #8fd18a;
        --ok-bg: rgba(59,109,17,.28);
        --warn: #e0a858;
        --warn-bg: rgba(133,79,11,.3);
        --danger: #ff6b6b;
        --danger-bg: rgba(163,45,45,.3);
        --danger-text: #ff9a9a;
        --danger-row-bg: rgba(255,90,90,.22);
        --info: #8cc4f0;
        --info-bg: rgba(24,95,165,.3);
        --gantt-cell-bg: #2c323a;
        --gantt-cell-border: #3f4750;
        --gantt-header-bg: #3a262a;
        --accent-fill: #C8101C;
        --ok-fill: #2f6a1f; --warn-fill: #8a5a0c;
        --accent-fill-hover: #A50C16;
        --line-strong: #737c85;
        --s-neutral-bg: #30363c; --s-neutral: #dfe3e6;
        --s-active-bg: #1c3350; --s-active: #a9c8f5;
        --s-out-bg: #26303a; --s-out: #b4c3d2;
        --s-done-bg: #1b3a25; --s-done: #93d6a3;
        --s-wait-bg: #3d3113; --s-wait: #f0c869;
        --control-bg: var(--panel-2);
        --control-line: var(--line-strong);
        color-scheme: dark;
      }
      .app-shell :is(input:not([type=checkbox]):not([type=radio]):not([type=range]), select, textarea):not(:focus) { border-color: var(--control-line); }
      .app-shell { background: var(--bg); color: var(--text); min-height: 100vh; font-family: 'Barlow', sans-serif; display: flex; flex-direction: column; padding-top: env(safe-area-inset-top); }

      .app-body-row { display: flex; flex: 1; min-height: 0; position: relative; }
      /* Ľavé menu na počítači — .side-menu-wrap len drží šírku vo flex riadku, panel je fixed. */
      .side-menu-wrap { width: 212px; flex-shrink: 0; }
      .side-menu-wrap.collapsed { width: 56px; }
      .side-menu { position: fixed; left: 0; bottom: 0; width: inherit; background: var(--panel); border-right: 1px solid var(--border); display: flex; flex-direction: column; box-sizing: border-box; z-index: 50; }
      .side-menu-wrap .side-menu { width: 212px; }
      .side-menu-wrap.collapsed .side-menu { width: 56px; }
      .side-menu-scroll { flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; padding: 8px; }
      .side-menu-foot { flex-shrink: 0; padding: 6px 8px 8px; border-top: 1px solid var(--border); display: flex; flex-direction: column; gap: 1px; }
      .nav-sec { font-family: 'Barlow Condensed', sans-serif; font-size: 13px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--text-dim); margin: 14px 10px 4px; }
      .nav-sec-line { height: 1px; background: var(--border); margin: 8px 4px; }
      .nav-it { display: flex; align-items: center; gap: 10px; width: 100%; padding: 7px 10px; border: none; background: transparent; border-radius: 8px; font: inherit; font-size: 13.5px; color: var(--text); cursor: pointer; text-align: left; position: relative; }
      .nav-it:hover { background: var(--panel-2); }
      .nav-it.active { background: var(--accent-light); color: var(--accent-dark); font-weight: 700; }
      .nav-it.nav-sub { padding-left: 38px; font-size: 12.5px; }
      .nav-it.nav-dim { color: var(--text-dim); font-size: 12px; }
      .nav-lbl { flex: 1; min-width: 0; }
      .nav-b { margin-left: auto; background: var(--text); color: var(--panel); border-radius: 10px; font-size: 11px; padding: 1px 7px; font-weight: 700; }
      .side-menu-wrap.collapsed .nav-it { justify-content: center; padding: 8px 0; }
      .nav-tip { position: fixed; left: 62px; transform: translateY(-50%); z-index: 300; pointer-events: none; background: var(--text); color: var(--panel); font-size: 13px; font-weight: 600; line-height: 1.2; padding: 6px 10px; border-radius: 6px; white-space: nowrap; box-shadow: 0 4px 12px rgba(0,0,0,.18); }
      .nav-b.nav-b-problem { background: var(--accent-fill); color: #fff; }
      .side-menu-wrap.collapsed .nav-b { position: absolute; top: 0; right: 2px; font-size: 9px; padding: 0 5px; }
      .header-new-wrap { position: relative; }
      /* iPhone/iPad (iOS 26 rozmazáva pás pod stavovou lištou): odznak zvončeka vpravo dole. */
      @supports (-webkit-touch-callout: none) { .bell-badge { top: auto !important; bottom: -5px !important; } }
      .bell-x { font-size: 22px; line-height: 1; padding: 0 !important; width: 36px; min-height: 36px !important; flex: 0 0 auto; }
      .bell-check { font-size: 14px; padding: 0 10px !important; min-height: 28px !important; margin-left: auto; }
      .header-new-btn { background: #fff; color: var(--accent-fill); border: none; border-radius: 8px; padding: 6px 12px; font: inherit; font-weight: 700; font-size: 13px; cursor: pointer; white-space: nowrap; }
      .header-new-drop { position: absolute; top: calc(100% + 6px); left: 0; z-index: 400; background: var(--panel); border: 1px solid var(--border); border-radius: 12px; box-shadow: 0 8px 24px rgba(0,0,0,.15); padding: 6px; min-width: 230px; }
      .header-new-drop .kebab-item { color: var(--text); padding: 9px 12px; font-size: 13.5px; }
      .header-phone-mobile { display: none; align-items: center; justify-content: center; width: 44px; height: 44px; border-radius: 50%; border: none; background: #fff; color: var(--accent-fill); cursor: pointer; }
      /* Spodná lišta na mobile (zobrazí sa len v mobilnom @media cez .mobile-tech-actions). */
      .mnav-t { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; border: none; background: transparent; font: inherit; font-size: 12px; color: var(--text-dim); position: relative; padding: 4px 0; cursor: pointer; min-width: 0; }
      .mnav-t.active { color: var(--accent); font-weight: 700; }
      .mnav-b { position: absolute; top: 0; left: 56%; background: var(--accent-fill); color: #fff; border-radius: 9px; font-size: 9.5px; padding: 0 5px; font-weight: 700; }
      .mnav-b.dot { width: 10px; height: 10px; padding: 0 !important; top: 4px; left: 58%; }
      .mnav-plus { width: 50px; height: 50px; border-radius: 50%; background: var(--accent-fill); color: #fff; display: flex; align-items: center; justify-content: center; margin-top: -22px; box-shadow: 0 4px 12px rgba(0,0,0,.2); }
      .mnav-sheet { position: absolute; left: 0; right: 0; bottom: 0; background: var(--panel); border-radius: 16px 16px 0 0; padding: 10px 14px calc(18px + env(safe-area-inset-bottom)); max-height: 80vh; overflow-y: auto; box-sizing: border-box; }
      .mnav-grab { width: 40px; height: 4px; border-radius: 2px; background: var(--border); margin: 0 auto 10px; }
      .mnav-sheet-title { font-weight: 700; margin: 2px 6px 6px; }
      .mnav-row { display: flex; align-items: center; gap: 12px; width: 100%; padding: 12px 6px; border: none; border-bottom: 1px solid var(--border); background: transparent; font: inherit; font-size: 15px; color: var(--text); text-align: left; cursor: pointer; }
      .mnav-row.active { color: var(--accent); font-weight: 700; }
      .mnav-row.nav-sub { padding-left: 38px; font-size: 14px; }
      .mnav-sheet .nav-sec { margin: 14px 6px 2px; }

      /* Tabuľka (.table-cards) sa na mobile prekreslí na kartičky — každý
         riadok = jedna karta, buňky pod sebou ako "label: hodnota" (label z
         data-label atribútu, keď ho buňka má). Webové zobrazenie (bežná
         tabuľka) je nezmenené, toto platí len pod @media nižšie.
         Druhá časť dotazu (max-width:1000px + pointer:coarse + hover:none)
         chytá aj TELEFÓN NA ŠÍRKU (otočený) — tam je šírka okna často nad
         720px (napr. 844px), takže by inak spadol do WEBOVÉHO rozloženia
         (ikonový pás, roztiahnutá hlavička) namiesto mobilného, aj keď ide
         stále o rovnaký úzky dotykový telefón, len otočený. pointer:coarse
         + hover:none vylúči bežné široké OKNO PREHLIADAČA NA POČÍTAČI
         (myš = pointer:fine/hover:hover), takže desktop v okne ~800px
         širokom zostáva nezmenený. */
      @media (max-width: 720px), (max-width: 1000px) and (pointer: coarse) and (hover: none) {
        table.table-cards thead { display: none; }
        table.table-cards, table.table-cards tbody { display: block; width: 100%; }
        table.table-cards tr { display: block; margin-bottom: 10px; border: 1px solid var(--border); border-radius: 12px; padding: 10px 12px; background: var(--panel); }
        table.table-cards td { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 5px 0; border: none; text-align: right; }
        table.table-cards td[data-label]::before { content: attr(data-label); font-size: 13px; font-weight: 600; color: var(--text-dim); text-align: left; margin-right: auto; flex-shrink: 0; }
        table.table-cards td.td-plain { display: block; text-align: left; }
        table.table-cards td.td-actions { justify-content: flex-end; }
        /* Vstupy/selecty v karte majú na desktope pevnú (úzku) šírku pre
           tabuľkový layout — na mobile namiesto toho vyplnia zvyšok riadku
           vedľa labelu, nech sa nemusí posúvať do boku ani pri dlhších
           hodnotách (popis dielu a pod.). */
        table.table-cards td input, table.table-cards td select { width: 100% !important; max-width: 200px; }
        /* Riadkové akcie (Zmazať a pod.) v karte — väčšie dotykové pole než
           na desktope, nech sa na mobile dá bezpečne trafiť prstom. */
        table.table-cards td.td-actions button { min-height: 36px; padding: 6px 14px !important; }
      }
      /* Tablet a úzke okno (návrh p9 A): Zákazky, Dáta požičovne a ERP podklady ako karty pod 1100 px — tabuľka by inak išla mimo obrazovky; bočné menu ostáva. */
      @media (max-width: 1100px) {
        table.tc900 thead { display: none; }
        table.tc900, table.tc900 tbody { display: block; width: 100%; }
        table.tc900 tr { display: block; margin-bottom: 10px; border: 1px solid var(--border); border-radius: 12px; padding: 10px 12px; background: var(--panel); }
        table.tc900 td, table.tc900 td.m-only { display: flex !important; justify-content: space-between; align-items: center; gap: 10px; padding: 5px 0 !important; border: none; text-align: right; font-size: 14px; position: static; box-shadow: none; background: transparent; }
        table.tc900 td[data-label]::before { content: attr(data-label); font-size: 13px; font-weight: 600; color: var(--text-dim); text-align: left; margin-right: auto; flex-shrink: 0; }
        table.tc900 td.td-plain { display: block !important; text-align: left; }
        table.tc900 td.td-actions { justify-content: flex-end; }
        table.tc900 tr.row-problem { background: var(--danger-bg); }
        table.tc900 tr.row-problem td { background: transparent; }
        table.tc900 .who-hide-mobile { display: none !important; }
        table.tc900 .m-only { display: inline-flex !important; }
        .jobs-wrap:has(> table.tc900) { background: transparent !important; border: 0 !important; }
      }
      /* ERP podklady majú viac stĺpcov — karty už pod 1280 px (iPad na šírku). */
      @media (max-width: 1280px) {
        table.tc1280 thead { display: none; }
        table.tc1280, table.tc1280 tbody { display: block; width: 100%; }
        table.tc1280 tr { display: block; margin-bottom: 10px; border: 1px solid var(--border); border-radius: 12px; padding: 10px 12px; background: var(--panel); }
        table.tc1280 td, table.tc1280 td.m-only { display: flex !important; justify-content: space-between; align-items: center; gap: 10px; padding: 5px 0 !important; border: none; text-align: right; font-size: 14px; position: static; box-shadow: none; background: transparent; }
        table.tc1280 td[data-label]::before { content: attr(data-label); font-size: 13px; font-weight: 600; color: var(--text-dim); text-align: left; margin-right: auto; flex-shrink: 0; }
        table.tc1280 td.td-plain { display: block !important; text-align: left; }
        table.tc1280 td.td-actions { justify-content: flex-end; }
        table.tc1280 tr.row-problem { background: var(--danger-bg); }
        table.tc1280 tr.row-problem td { background: transparent; }
        table.tc1280 .who-hide-mobile { display: none !important; }
        table.tc1280 .m-only { display: inline-flex !important; }
        .jobs-wrap:has(> table.tc1280) { background: transparent !important; border: 0 !important; }
      }

      /* Položka v kebab (⋮) menu — riadkové akcie skryté za jedným tlačidlom
         namiesto radu btn-ghost tlačidiel v tabuľke/karte. */
      .kebab-item {
        display: block; width: 100%; text-align: left; background: transparent; border: none;
        padding: 8px 10px; font-size: 13px; font-family: 'Barlow', sans-serif; cursor: pointer;
        border-radius: 5px; text-decoration: none;
      }
      .kebab-item:hover { background: var(--panel-2); }
      .kebab-drop { box-shadow: 0 10px 28px rgba(0,0,0,.18); }

      .mobile-nav-overlay { position: fixed; inset: 0; z-index: 300; display: flex; }
      .mobile-nav-scrim { position: absolute; inset: 0; background: rgba(0,0,0,.4); }
      /* Okamžitý tooltip nad blokom zákazky/rezervácie v Gantte — namiesto pomalého
         natívneho (title) sa objaví hneď pri prejdení myšou, čisto cez CSS.
         Zámerne NIŽŠIE ako .gantt-name-wrap (meno stroja), a to aj pri
         nabehnutí myšou — inak by zákazka pri nabehnutí myšou (keď "vyskočí"
         kvôli vlastnému tooltipu) prekryla meno stroja v tom istom riadku. */
      .gantt-bar-wrap { position: relative; z-index: 1; }
      .gantt-bar-wrap:hover { z-index: 10; }
      /* Porucha stroja v kalendári — pás ako zákazka (CalendarGrid, breakPieces). */
      /* Meno stroja (prvý stĺpec) — musí byť VŽDY nad zákazkami, aj tými, čo
         práve "vyskočili" pri nabehnutí myšou (10 vyššie) — preto tu základná
         hodnota (20) už sama o sebe prevyšuje aj tamten najvyšší prípad. */
      .gantt-name-wrap { position: relative; z-index: 20; }
      .gantt-name-wrap:hover { z-index: 30; }
      .gantt-tooltip {
        visibility: hidden;
        opacity: 0;
        position: absolute;
        bottom: 100%;
        left: 0;
        margin-bottom: 5px;
        background: #1a1a1a;
        color: #fff;
        font-size: 11px;
        line-height: 1.4;
        padding: 7px 10px;
        border-radius: 6px;
        white-space: normal;
        width: max-content;
        max-width: 260px;
        z-index: 50;
        pointer-events: none;
      }
      /* sticky bunka stroja má z-index:2 → pri hoveri ju zdvihnúť, inak bublinu prekryjú ďalšie riadky */
      .gantt-name-wrap:hover, .gantt-name-wrap:focus-within { z-index: 60 !important; }
      .gantt-bar-wrap:hover .gantt-tooltip, .gantt-name-wrap:hover .gantt-tooltip, .gantt-name-wrap:focus .gantt-tooltip, .gantt-transport-icon:hover .gantt-tooltip { visibility: visible; opacity: 1; }
      /* Ťahanie zákazky/rezervácie v Gantte (presun/zmena termínu) — stredná
         časť bloku = kurzor "uchopiť" (presun), tenké 8px pruhy na okrajoch =
         kurzor na zmenu šírky (zmena len začiatku/konca). Samotné ťahanie
         nižšie priamo mutuje DOM (style.gridColumn), nie React stav — tieto
         handle prvky sú len vizuálna/klikacia vrstva nad tým. */
      .gantt-bar-wrap.draggable { cursor: grab; }
      .gantt-bar-wrap.draggable:active { cursor: grabbing; }
      .gantt-drag-handle { position: absolute; top: 0; bottom: 0; width: 8px; cursor: ew-resize; z-index: 5; }
      .gantt-drag-handle.start { left: 0; }
      .gantt-drag-handle.end { right: 0; }
      /* Ikonka skutočného vývozu/zvozu (odlišného od zmluvného dátumu) — čisto
         vizuálna, nezasahuje do klikov na samotnú zákazku pod ňou. */
      /* Bez vlastného z-index na tomto boxe (len position:relative ako kotva
         pre tooltip) — icon tak zostáva v "auto" vrstve, VŽDY za menom
         stroja (to má z-index:2, teda vyššiu explicitnú vrstvu), zatiaľ čo
         jeho .gantt-tooltip (z-index:50) sa vie normálne vyšvihnúť nad
         VŠETKY riadky, lebo nie je zamknutý v nízkej lokálnej "stacking
         context" tohto boxu. */
      .gantt-transport-icon { position: relative; display: flex; align-items: center; justify-content: center; gap: 3px; font-size: 10px; font-weight: 600; color: #1a1a1a; pointer-events: auto; cursor: default; line-height: 1; }
      .app-shell.dark .gantt-transport-icon { color: #fff; }
      .label-font { font-family: 'Barlow Condensed', sans-serif; }
      .mono { font-family: 'Barlow', sans-serif; font-weight: 700; letter-spacing: .01em; }
      .panel { background: var(--panel); border: 1px solid var(--border); border-radius: 12px; box-shadow: 0 2px 12px rgba(0,0,0,.06); }
      .mobile-tech-actions { display: none; }
      .btn { min-height: 40px; padding: 7px 14px; border-radius: 6px; font-family: 'Barlow', sans-serif; font-weight: 600; font-size: 13px; cursor: pointer; border: 1px solid transparent; transition: .15s; display: inline-block; text-decoration: none; }
      /* Depo filter chipy — na desktope plný názov, na mobile skratka (BA/NR/ZV/ZA/PO/EXT), nech je to jednotné so ganttom. */
      .depo-chip-short { display: none; }
      .btn-accent { background: var(--accent-fill); color: #fff; }
      .btn-accent:hover { background: var(--accent-fill-hover); }
      /* v1.0.805: neaktívne hlavné tlačidlo čitateľné (aj v tmavom režime) — sivé, nie bledočervené. */
      .btn-accent:disabled { background: var(--s-neutral-bg); color: var(--text-dim); cursor: not-allowed; }
      .btn-ghost { background: transparent; border: 1px solid var(--border); color: var(--text); }
      .btn-ghost:hover { border-color: var(--accent); color: var(--accent); }
      .badge { display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 4px; font-family: 'Barlow', sans-serif; text-transform: uppercase; font-size: 10px; font-weight: 700; letter-spacing: .04em; }
      .badge-ok { background: var(--ok-bg); color: var(--ok); }
      .badge-warn { background: var(--warn-bg); color: var(--warn); }
      .badge-danger { background: var(--danger-bg); color: var(--danger); }
      .badge-info { background: var(--info-bg); color: var(--info); }
      /* Zdieľaný "počítací" odznak (aktívne filtre a pod.) — jeden radius/
         veľkosť namiesto toho, aby si ho každé miesto vyrábalo nanovo. */
      .count-badge { display: inline-flex; align-items: center; justify-content: center; background: var(--accent-fill); color: #fff; font-size: 10px; border-radius: 10px; min-width: 16px; height: 16px; padding: 0 5px; font-weight: 700; line-height: 1; }
      /* Zdieľané "×" tlačidlo na zatvorenie — tlmené (žiadne pozadie v pokoji,
         jemné pri hoveri), rovnaký jazyk ako .rail-icon namiesto textového
         tlačidla "Zavrieť" alebo červeného kruhu. */
      .modal-close-x {
        width: 30px; height: 30px; border-radius: 8px; display: flex; align-items: center; justify-content: center;
        background: transparent; border: none; color: var(--text-dim); font-size: 22px; line-height: 1; cursor: pointer;
        transition: background .15s ease, color .15s ease; flex-shrink: 0;
      }
      .modal-close-x:hover { background: var(--panel-2); color: var(--text); }
      /* Toast s potvrdením odoslania — hore na strede, sám zmizne po pár
         sekundách. z-index 250: nad kartami (160/170), pod dropdown/notif. (200+). */
      .app-toast {
        position: fixed; top: 12px; left: 50%; transform: translateX(-50%); z-index: 250;
        background: var(--ok-fill); color: #fff; padding: 9px 16px; border-radius: 8px;
        font-size: 13px; font-weight: 600; box-shadow: 0 4px 16px rgba(0,0,0,.15);
        animation: app-toast-in .2s ease;
      }
      @keyframes app-toast-in { from { opacity: 0; transform: translate(-50%, -8px); } to { opacity: 1; transform: translate(-50%, 0); } }
      .skeleton-bar {
        background: linear-gradient(90deg, var(--panel-2) 25%, var(--border) 50%, var(--panel-2) 75%);
        background-size: 200% 100%;
        animation: skeleton-shimmer 1.4s ease-in-out infinite;
      }
      @keyframes skeleton-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
      /* Karty s "eyebrow" titulkom (identita — zákazka, rezervácia, stroj,
         zákazník, auto) — horný toolbar riadok oddelený čiarou, mierne
         záporný margin nech siaha až po okraj panelu ako pri iných kartách. */
      .modal-toolbar { display: flex; align-items: center; justify-content: flex-end; gap: 10px; flex-wrap: wrap; margin: -20px -20px 14px; padding: 8px 12px; border-bottom: 1px solid var(--border); }
      .modal-title-block { margin-bottom: 16px; }
      .modal-eyebrow { font-family: 'Barlow Condensed', sans-serif; font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--text-dim); margin-bottom: 2px; }
      .modal-title-main { font-family: 'Barlow', sans-serif; font-size: 22px; font-weight: 700; color: var(--text); line-height: 1.2; margin: 0; font-variant-numeric: tabular-nums; }
      /* Bočný panel (Modal side — karta zákazky): vpravo cez celú výšku, vysunie sa sprava. */
      .modal-panel.modal-side-panel { height: 100%; overflow-y: auto; display: flex; flex-direction: column; border: none; border-left: 1px solid var(--border); border-radius: 0; box-shadow: -12px 0 32px rgba(0,0,0,.08); animation: side-in .2s ease-out; }
      @keyframes side-in { from { transform: translateX(100%); } }
      /* Jemné objavenie/zatvorenie okien a menu — len PC (na mobile sú okná cez celú obrazovku a WebKit s animáciou vrstiev zlobí). */
      @media (min-width: 1001px), (min-width: 721px) and (hover: hover) {
        .modal-overlay { animation: fade-in .15s ease-out; }
        .modal-panel:not(.modal-side-panel) { animation: pop-in .16s ease-out; }
        .modal-overlay.closing { animation: fade-out .16s ease-in forwards; }
        .modal-overlay.closing .modal-side-panel { animation: side-out .16s ease-in forwards; }
        .kebab-drop, .dropdown-panel, .header-new-drop { animation: fade-in .12s ease-out; } /* bez zmeny veľkosti — menu si pri otvorení meria polohu */
      }
      .mnav-sheet { animation: sheet-up .2s ease-out; }
      .btn:active:not(:disabled) { transform: scale(.97); }
      .row-saved > td, div.row-saved { animation: row-saved 1.6s ease-out; }
      @keyframes fade-in { from { opacity: 0; } }
      @keyframes fade-out { to { opacity: 0; } }
      @keyframes pop-in { from { opacity: 0; transform: scale(.98); } }
      @keyframes side-out { to { transform: translateX(100%); } }
      @keyframes sheet-up { from { transform: translateY(100%); } }
      @keyframes row-saved { from { background: var(--ok-bg); } }
      @media (prefers-reduced-motion: reduce) { .row-saved > td, div.row-saved { animation: none !important; background: var(--ok-bg); } }
      @media (prefers-reduced-motion: reduce) { .modal-panel.modal-side-panel { animation: none; } *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; } }
      .side-head { padding: 18px 28px 0; display: flex; flex-direction: column; gap: 10px; }
      .side-eyebrow { font-family: 'Barlow Condensed', sans-serif; font-weight: 600; font-size: 14px; letter-spacing: .07em; text-transform: uppercase; color: var(--text-dim); }
      .side-title { margin: 0; font-size: 26px; font-weight: 700; color: var(--text); display: flex; align-items: center; gap: 12px; flex-wrap: wrap; line-height: 1.2; font-variant-numeric: tabular-nums; }
      .side-title-sub { font-size: 19px; font-weight: 500; color: var(--text-dim); }
      .side-summary { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border: 1px solid var(--border); border-radius: 12px; }
      .side-summary > div { padding: 10px 12px; border-right: 1px solid var(--border); min-width: 0; }
      .side-summary > div:last-child { border-right: none; }
      .side-summary span { display: block; font-size: 13px; color: var(--text-dim); }
      .side-summary b { display: block; font-size: 14px; font-weight: 600; overflow-wrap: anywhere; }
      .side-summary b a { color: inherit; }
      .side-summary.s3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
      .tip-now { position: relative; }
      .tip-now:hover::after, .tip-now:focus-visible::after { content: attr(data-tip); position: absolute; top: calc(100% + 6px); left: 50%; transform: translateX(-50%); background: var(--text); color: var(--panel); font-size: 12px; font-weight: 600; padding: 3px 8px; border-radius: 6px; white-space: nowrap; z-index: 50; pointer-events: none; }
      .tnum { font-variant-numeric: tabular-nums; }
      .side-body { flex: 1; padding: 0 28px 20px; }
      .side-foot { position: sticky; bottom: 0; z-index: 5; background: var(--panel-2); border-top: 1px solid var(--border); padding: 14px 28px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
      .side-foot .btn { min-height: 44px; font-size: 14px; }
      /* Segmentovaný prepínač (stav/depo/doprava) — aktívne čierne, ostatné biele. */
      .stat-info { display: inline-block; vertical-align: middle; margin-left: 4px; }
      .stat-info-btn { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; margin: -8px 0; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--text-dim); cursor: pointer; }
      .stat-info-btn:hover, .stat-info-btn[aria-expanded="true"] { color: var(--text); background: var(--panel-2); }
      .stat-info-pop { position: absolute; z-index: 30; top: calc(100% + 6px); left: 12px; right: 12px; max-width: 560px; padding: 12px 14px; background: var(--panel); color: var(--text); border: 1px solid var(--line-strong); border-radius: 8px; box-shadow: 0 6px 24px rgba(0,0,0,.18); font-size: 13px; font-weight: 400; line-height: 1.5; cursor: auto; white-space: normal; }
      .chart-legend { display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 13px; margin-bottom: 10px; }
      .chart-legend span, .stack-legend span { display: inline-flex; align-items: center; gap: 6px; }
      .chart-legend i, .stack-legend i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; flex-shrink: 0; }
      .chart-empty { padding: 10px 0; font-size: 13px; color: var(--text-dim); }
      .chart-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr)); gap: 16px; margin-bottom: 16px; }
      .chart-card { background: var(--panel); border: 1px solid var(--border); border-radius: 10px; padding: 16px; min-width: 0; }
      .hbars { display: grid; gap: 8px 10px; align-items: center; font-size: 13px; }
      .stat-period-sel { display: none; }
      @media (max-width: 720px), (max-width: 1000px) and (pointer: coarse) and (hover: none) {
        .seg.stat-period-seg { display: none !important; }
        .stat-period-sel { display: block; flex: 1 1 100%; height: 44px; font-size: 16px; }
      }
      .hbar { display: contents; }
      .hbar-l { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
      .hbar-t { position: relative; height: 16px; }
      .hbar-fill { display: flex; gap: 2px; height: 16px; }
      .hbar-fill > div { min-width: 2px; }
      .hbar-fill > div:last-child { border-radius: 0 4px 4px 0; }
      .hbar-target { position: absolute; top: -4px; bottom: -4px; border-left: 2px solid var(--text); }
      .hbar-v { white-space: nowrap; font-weight: 600; }
      @media (max-width: 640px) {
        .hbars { grid-template-columns: minmax(0, 1fr) auto !important; row-gap: 4px; }
        .hbar-l { grid-column: 1 / -1; margin-top: 4px; }
        .hbar-v { font-size: 12px; }
      }
      .cols-wrap { display: flex; gap: 6px; }
      .cols-y { display: flex; flex-direction: column; justify-content: space-between; font-size: 11px; color: var(--text-dim); text-align: right; min-width: 24px; }
      .cols-main { flex: 1; min-width: 0; }
      .cols { display: flex; align-items: flex-end; gap: 4px; border-bottom: 1px solid var(--line-strong); }
      .col { flex: 1; display: flex; align-items: flex-end; gap: 2px; height: 100%; min-width: 0; }
      .col-bar { flex: 1; border-radius: 4px 4px 0 0; }
      .col-stack { width: 100%; display: flex; flex-direction: column-reverse; gap: 2px; }
      .col-stack > div { flex-basis: 0; min-height: 1px; }
      .col-stack > div:last-child { border-radius: 4px 4px 0 0; }
      .cols-x { display: flex; gap: 4px; font-size: 11px; color: var(--text-dim); margin-top: 4px; }
      .cols-x span { flex: 1; min-width: 0; white-space: nowrap; }
      .line-trend { display: block; max-width: 100%; }
      .stackbar { display: flex; gap: 2px; height: 24px; }
      .stackbar > div { min-width: 3px; flex-basis: 0; }
      .stackbar > div:first-child { border-radius: 4px 0 0 4px; }
      .stackbar > div:last-child { border-radius: 0 4px 4px 0; }
      .stack-legend { display: flex; flex-wrap: wrap; gap: 6px 18px; font-size: 13px; margin-top: 10px; }
      .seg { display: inline-flex; border: 1px solid var(--line-strong); border-radius: 8px; overflow: hidden; background: var(--panel); max-width: 100%; }
      .seg > button { min-height: 40px; padding: 0 14px; border: 0; border-left: 1px solid var(--border); background: transparent; font: inherit; font-size: 14px; color: var(--text); cursor: pointer; white-space: nowrap; flex: 1; }
      .seg > button:first-child { border-left: 0; }
      .seg > button.on { background: var(--text); color: var(--panel); font-weight: 600; }
      .seg > button:disabled { opacity: .5; cursor: not-allowed; }
      .seg-n { margin-left: 6px; font-variant-numeric: tabular-nums; opacity: .75; }
      .fchip { min-height: 36px; padding: 0 12px; border: 1px solid var(--line-strong); border-radius: 999px; background: var(--panel); font: inherit; font-size: 14px; color: var(--text); cursor: pointer; display: inline-flex; align-items: center; }
      .fchip:hover { border-color: var(--text); }
      .fchip.on { background: var(--text); color: var(--panel); border-color: var(--text); }
      .fchip.problem { background: var(--danger-bg); color: var(--danger-text); border-color: transparent; font-weight: 600; }
      .fchip.overdue { background: var(--warn-bg); color: var(--warn); border-color: transparent; font-weight: 600; }
      .fchip-x { margin-left: 6px; border: 0; background: transparent; font: inherit; font-weight: 700; color: inherit; cursor: pointer; padding: 0 2px; }
      .spill { display: inline-block; font-size: 13px; font-weight: 600; padding: 3px 10px; border-radius: 999px; white-space: nowrap; background: var(--s-neutral-bg); color: var(--s-neutral); }
      .spill-active { background: var(--s-active-bg); color: var(--s-active); }
      .spill-out { background: var(--s-out-bg); color: var(--s-out); } /* Čaká na vývoz — sivomodrá */
      .spill-done { background: var(--s-done-bg); color: var(--s-done); }
      .spill-wait { background: var(--s-wait-bg); color: var(--s-wait); }
      /* Farby stavov (jednotne): červená = blokuje, oranžová = treba riešiť, modrá = prebieha, zelená = v poriadku, sivá = neaktívne */
      .spill-problem { background: var(--danger-bg); color: var(--danger-text); }
      .spill-overdue { background: var(--warn-bg); color: var(--warn); } /* len „Po termíne“ (v1.0.816) */
      .spill-warn { background: var(--warn-bg); color: var(--warn); } /* oranžová mimo „Po termíne“: rola účtu ≠ karta, Kôš ≤ 3 dni */
      .btn-outline { background: var(--panel); border: 1px solid var(--text); color: var(--text); }
      .btn-outline:hover { background: var(--panel-2); }
      .btn-link { border: 0; background: none; padding: 0; min-height: 32px; font: inherit; color: var(--text); text-decoration: underline; text-underline-offset: 2px; cursor: pointer; text-align: left; }
      .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
      .cell-sub { font-size: 13px; color: var(--text-dim); margin-top: 2px; }
      .jobs-table th { position: static; }
      .jobs-table th { font-family: 'Barlow Condensed', sans-serif; font-size: 14px; font-weight: 600; letter-spacing: .05em; background: var(--panel); padding: 12px; }
      .jobs-table td { font-size: 15px; padding: 12px; vertical-align: middle; }
      .jobs-table th:first-child, .jobs-table td:first-child { padding-left: 20px; }
      .jobs-table th:last-child, .jobs-table td:last-child { padding-right: 20px; }
      @media (min-width: 900px) { .sp-table th, .sp-table td { padding-left: 8px; padding-right: 8px; } } /* Náhradné diely: 11 stĺpcov na 1360 px */
      .jobs-table tr.row-problem td { background: var(--danger-bg); }
      .jobs-table .btn { min-height: 36px; font-size: 14px; }
      .day-sec { font-family: 'Barlow Condensed', sans-serif; font-size: 15px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; margin: 18px 0 8px; font-variant-numeric: tabular-nums; }
      .day-sec.red { color: var(--danger-text); }
      .tr-row { display: grid; grid-template-columns: 90px minmax(0, 1fr) 200px 150px; gap: 12px; align-items: center; padding: 12px 20px; border-top: 1px solid var(--border); cursor: pointer; }
      .tr-row:first-child { border-top: 0; }
      .tr-row { outline-offset: -2px; } /* zvýraznenie (klik v Rýchlom prehľade) — panel má overflow: hidden */
      .tr-row.row-problem { background: var(--danger-bg); }
      .tr-row select { width: 100%; max-width: 200px; }
      .job-form-cols { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 400px), 1fr)); margin: 0 -20px; border-top: 1px solid var(--border); }
      .job-form-cols > fieldset { border: 0; margin: 0; padding: 16px 20px 4px; min-width: 0; }
      .job-form-cols > fieldset + fieldset { background: var(--panel-2); border-left: 1px solid var(--border); }
      .job-form-cols legend { float: left; width: 100%; padding: 0; margin-bottom: 12px; font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 15px; letter-spacing: .06em; }
      .job-form-cols legend + * { clear: both; }
      .job-form-cols .seg > button { min-width: 0; white-space: normal; padding: 0 8px; line-height: 1.15; }
      /* Pole pri fokuse (klávesnica) sa doscrolluje nad ukotvenú lištu, nie pod ňu. */
      :is(.modal-overlay, .modal-panel, .side-body):has(.job-form-foot:not(.ff-confirm)) { scroll-padding-bottom: 140px; }
      .job-form-foot { position: sticky; bottom: -20px; z-index: 5; margin: 0 -20px -20px; padding: 12px 20px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; background: var(--panel-2); border-top: 1px solid var(--border); border-radius: 0 0 10px 10px; }
      .job-form-foot .btn { min-height: 44px; font-size: 14px; }
      .miss-pill { font-size: 14px; color: var(--s-wait); background: var(--s-wait-bg); padding: 6px 10px; border-radius: 6px; }
      /* v1.0.805: kým sa neskúsilo uložiť — neutrálny sivý „Ešte treba“ / priebeh; žlté „Chýba“ a zvýraznenie polí až po pokuse. */
      .miss-pill.miss-soft { color: var(--s-neutral); background: var(--s-neutral-bg); }
      .ff-btns .btn:disabled, .ff-try .btn:disabled { pointer-events: none; }
      .modal-panel:has(.job-form-foot:not(.ff-tried)) .need-hint { display: none; }
      .modal-panel:focus { outline: none; }
      .modal-panel:has(.ff-tried) [data-miss], .modal-panel [data-miss-auto] { outline: 2px solid var(--danger); outline-offset: 2px; border-radius: 8px; }
      .modal-panel:has(.ff-tried) .cki[data-miss] { outline: none; box-shadow: inset 4px 0 0 var(--danger); background: var(--danger-bg); }
      .fck.fck-big { font-size: 16px; font-weight: 600; align-items: center; min-height: 52px; padding: 10px 12px; border: 1px solid var(--line-strong); border-radius: 10px; }
      .modal-panel label.fck-big > input[type=checkbox] { width: 28px; height: 28px; }
      .btn > svg, .btn > span > svg { vertical-align: -3px; }
      .fchips { display: flex; gap: 6px; flex-wrap: wrap; }
      /* Mobil: filtre v jednom vodorovne posuvnom riadku (návrh dizajnu 23. 10.) */
      @media (max-width: 640px) {
        .chip-scroll { flex-wrap: nowrap !important; overflow-x: auto; width: 100%; scrollbar-width: none; padding-bottom: 2px; -webkit-mask-image: linear-gradient(to right, #000 88%, transparent); mask-image: linear-gradient(to right, #000 88%, transparent); }
        .chip-scroll::-webkit-scrollbar { display: none; }
        .chip-scroll > * { flex-shrink: 0; white-space: nowrap; }
        .seg.chip-scroll { display: flex !important; }
        .seg.chip-scroll > button { flex: 0 0 auto; white-space: nowrap; }
        .tbar > .rev-depo { order: 1; } /* Revízie: hľadanie a ⋯ v riadku so stavom, depá pod nimi */
        .seg.rev-depo > button { padding: 0 14px; }
      }
      .jobs-table tr.row-click:not(.row-problem):hover td { background: var(--panel-2); }
      .jc-report-m { display: none; }
      .tr-filt2 { display: contents; }
      .side-dl-edit { background: var(--panel-2); border-radius: 12px; padding: 0 14px; }
      .side-dl-edit dt:last-of-type, .side-dl-edit dd:last-of-type { border-bottom: none; }
      .qs-table td.qs-send { width: 210px; min-width: 210px; height: 48px; padding-top: 4px; padding-bottom: 4px; }
      .qs-send-btn { font-size: 13px; padding: 4px 10px; min-height: 34px; white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; }
      .qs-n { color: var(--text-dim); }
      .qs-n.on { color: var(--text); font-weight: 700; }
      .qs-tiles { display: none; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
      .qs-tile { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; min-height: 76px; padding: 8px; border: 1px solid var(--border); border-radius: 10px; background: var(--panel); font: inherit; color: var(--text); text-align: left; cursor: pointer; }
      .qs-tile b { font-size: 13px; }
      .qs-tile-n { font-size: 18px; font-weight: 700; }
      .qs-tile-s { font-size: 12px; color: var(--text-dim); }
      .qs-tile.red { border-color: var(--danger); background: var(--danger-bg); }
      .qs-tile.red .qs-tile-s { color: var(--danger-text); font-weight: 700; }
      .tr-date { border: 0; background: none; padding: 4px 6px; margin-left: -6px; min-height: 36px; border-radius: 6px; font: inherit; font-weight: 600; color: var(--text); cursor: pointer; }
      .tr-date span { color: var(--text-dim); }
      .tr-date:hover { background: var(--panel-2); }
      .tr-row select.tr-assign { min-height: 44px; border: 2px solid var(--danger); font-weight: 700; color: var(--text); }
      /* Formuláre (v1.0.794): popisky 14 px, polia 44 px (mobil 48 px), spodná lišta FormFoot, rámiky, kroky, checklist. */
      .fld { margin-bottom: 14px; min-width: 0; }
      .fld-l { display: block; font-family: 'Barlow', sans-serif; font-size: 14px; font-weight: 600; color: var(--text); margin-bottom: 6px; }
      .modal-panel:not(.modal-side-panel) :is(input:not([type=checkbox]):not([type=radio]):not([type=file]):not([type=color]):not([type=range]), select) { min-height: 44px; font-size: 15px; }
      .modal-panel:not(.modal-side-panel) textarea { font-size: 15px; }
      .modal-panel label > input[type=checkbox] { width: 20px; height: 20px; accent-color: var(--text); flex: none; margin: 0; }
      /* Drobné inline písmo (10–12 px) v oknách → 13 px (minimum pre prácu v teréne). */
      .modal-panel:not(.modal-side-panel) :is([style*="font-size: 10px"], [style*="font-size: 11px"], [style*="font-size: 12px"]) { font-size: 13px !important; }
      .ff-btns { display: flex; gap: 8px; margin-left: auto; flex-wrap: wrap; align-items: center; }
      .job-form-foot .miss-pill { flex: 0 1 auto; }
      .btn-black { background: var(--text); color: var(--panel); border-color: var(--text); }
      .btn-black:hover { opacity: .88; }
      .btn-danger-outline { background: var(--panel); border: 1px solid var(--danger); color: var(--danger-text); }
      .btn-outline:disabled, .btn-danger-outline:disabled, .btn-black:disabled { opacity: .45; cursor: not-allowed; }
      .fnote { border-radius: 8px; padding: 10px 12px; font-size: 14px; line-height: 1.4; margin-bottom: 14px; }
      .fnote-i { background: var(--panel-2); border: 1px solid var(--border); color: var(--text); }
      .fnote-y { background: var(--s-wait-bg); color: var(--s-wait); }
      .fnote-g { background: var(--s-done-bg); color: var(--s-done); }
      .fnote-r { background: var(--danger-bg); color: var(--danger-text); border-left: 3px solid var(--danger); font-weight: 600; }
      .fhint { font-size: 13px; color: var(--text-dim); margin-top: 4px; font-weight: 400; }
      .fck { display: flex; gap: 10px; align-items: flex-start; font-size: 14px; color: var(--text); line-height: 1.35; margin: 2px 0 14px; cursor: pointer; }
      .fck small { display: block; font-size: 13px; color: var(--text-dim); margin-top: 2px; }
      .fgrid2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 12px; align-items: start; }
      .fstep { display: flex; align-items: center; gap: 10px; margin: 20px 0 10px; flex-wrap: wrap; }
      .fstep-n { width: 26px; height: 26px; border-radius: 50%; background: var(--text); color: var(--panel); font-weight: 700; font-size: 14px; display: inline-flex; align-items: center; justify-content: center; flex: none; }
      .fstep-t { flex: 1; font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 15px; letter-spacing: .06em; text-transform: uppercase; }
      .fstep .spill { text-transform: none; }
      .fdisc > summary { list-style: none; cursor: pointer; display: flex; align-items: center; gap: 6px; min-height: 44px; font-size: 14px; font-weight: 600; color: var(--text); }
      .fdisc > summary::-webkit-details-marker { display: none; }
      .fdisc-a { display: inline-block; transition: transform .15s; }
      .fdisc[open] .fdisc-a { transform: rotate(90deg); }
      .flegend { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 15px; letter-spacing: .06em; text-transform: uppercase; margin: 18px 0 10px; }
      .fsum { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 8px; margin-bottom: 14px; }
      .fsum > div { background: var(--panel-2); border-radius: 8px; padding: 8px 12px; font-size: 14px; min-width: 0; overflow-wrap: anywhere; }
      .fsum > div > span:first-child { display: block; font-family: 'Barlow Condensed', sans-serif; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; color: var(--text-dim); font-size: 13px; }
      .fsum a { color: var(--text); text-decoration: none; font-weight: 600; }
      .flist { border: 1px solid var(--border); border-radius: 8px; overflow: hidden; margin-bottom: 14px; }
      .flist > button { width: 100%; min-height: 48px; display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 0 14px; border: 0; border-top: 1px solid var(--border); background: var(--panel); font: inherit; font-size: 15px; color: var(--text); text-align: left; cursor: pointer; }
      .flist > button:first-child { border-top: 0; }
      .flist > button:hover, .flist > button.on { background: var(--panel-2); }
      .flist small { color: var(--text-dim); font-size: 14px; }
      /* Riadky zoznamu v okne (v1.0.795): deň technika, výdaj dielov, telefónny zoznam, merania EZ… */
      .frow { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 10px; padding: 12px 14px; min-height: 56px; }
      .frow + .frow { border-top: 1px solid var(--border); }
      .frow .btn { min-height: 40px; font-size: 14px; }
      .fintro { margin: -4px 0 14px; font-size: 14px; color: var(--text-dim); line-height: 1.4; }
      .ckl { border: 1px solid var(--border); border-radius: 12px; overflow: hidden; margin-bottom: 14px; }
      .cki { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 8px 12px; border-top: 1px solid var(--border); }
      .cki:first-child { border-top: 0; }
      .cki.prob { background: var(--danger-bg); }
      .ckt { flex: 1; min-width: 200px; font-size: 15px; }
      .cks { display: flex; border: 1px solid var(--line-strong); border-radius: 8px; overflow: hidden; background: var(--panel); }
      .cks > button { min-height: 48px; min-width: 104px; padding: 0 12px; font: inherit; font-size: 14px; border: 0; border-left: 1px solid var(--border); background: transparent; color: var(--text); cursor: pointer; }
      .cks > button:first-child { border-left: 0; }
      .cks > button.okon { background: var(--s-done-bg); color: var(--s-done); font-weight: 700; }
      .cks > button.pon { background: var(--danger-bg); color: var(--danger-text); font-weight: 700; box-shadow: inset 0 0 0 1.5px var(--danger); }
      .cki textarea { width: 100%; }
      .fphotos { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }
      .fphoto { position: relative; width: 84px; height: 84px; }
      .fphoto img { width: 84px; height: 84px; object-fit: cover; border-radius: 8px; border: 1px solid var(--border); cursor: pointer; }
      .fphoto button { position: absolute; top: -8px; right: -8px; width: 28px; height: 28px; border-radius: 50%; border: 1px solid var(--line-strong); background: var(--panel); color: var(--text); font-size: 13px; line-height: 1; cursor: pointer; }
      .ftable th { font-family: 'Barlow Condensed', sans-serif; font-size: 14px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; background: var(--panel-2); padding: 10px 8px; }
      .ftable td { padding: 8px; vertical-align: top; font-size: 14px; }
      .modal-panel .ftable :is(input, select) { min-height: 40px; font-size: 14px; }
      .ftable tr:hover td { background: transparent; }
      .print-bar-x { position: absolute; top: env(safe-area-inset-top); left: 0; height: 64px; max-width: min(46vw, 520px); display: flex; align-items: center; gap: 12px; padding: 0 16px; z-index: 2; }
      .print-bar-x .btn { min-height: 44px; font-size: 14px; flex: none; }
      .print-bar-title { min-width: 0; font-size: 15px; font-weight: 600; color: #1A1A1A; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
      @media (max-width: 720px), (max-width: 1000px) and (pointer: coarse) and (hover: none) {
        .tr-row { grid-template-columns: 70px minmax(0, 1fr); padding: 12px 14px; }
        .tr-row > :nth-child(n+3) { grid-column: 2; }
        .qs-tiles { display: grid; }
        .qs-wide { display: none; }
        .job-form-cols > fieldset + fieldset { border-left: 0; border-top: 1px solid var(--border); }
        .seg { display: flex; width: 100%; }
        .jobs-table tr.row-problem { background: var(--danger-bg); }
        .jobs-table tr.row-problem td { background: transparent; }
        .jobs-wrap { background: transparent !important; border: 0 !important; }
        .jobs-table td { font-size: 14px; }
        .jobs-table td:first-child, .jobs-table td:last-child { padding-left: 0; padding-right: 0; }
        .jobs-table td:first-child { position: static; box-shadow: none; background: transparent; }
      }
      /* Ostatné obrazovky (v1.0.793): nadpis obrazovky, popis pod ním, lišta nad tabuľkou, nadpis sekcie. */
      .page-h1 { margin: 0 0 4px; font-size: 24px; font-weight: 700; color: var(--text); }
      .page-intro { margin: 0 0 14px; font-size: 14px; color: var(--text-dim); max-width: 920px; line-height: 1.45; }
      .tbar { display: flex; gap: 10px; margin-bottom: 12px; flex-wrap: wrap; align-items: center; }
      .tbar .btn { min-height: 40px; font-size: 14px; }
      .unit-in { position: relative; display: inline-block; }
      .unit-in input { width: 92px; height: 38px; padding-right: 28px; font-size: 14px; }
      .unit-in i { position: absolute; right: 9px; top: 50%; transform: translateY(-50%); font-style: normal; font-size: 13px; color: var(--text-dim); pointer-events: none; }
      .models-table td { padding-top: 8px; padding-bottom: 8px; }
      .models-table select { height: 38px; font-size: 14px; }
      .jobs-table.dense td { padding-top: 8px; padding-bottom: 8px; }
      /* Prihlásenie / nové heslo / registrácia — karta s červeným pásom ako hlavička platformy. */
      .auth-page { display: flex; align-items: center; justify-content: center; min-height: 100vh; background: var(--bg); padding: 16px; }
      .panel.auth-card { width: 400px; max-width: 100%; padding: 0 !important; overflow: hidden; border-radius: 12px; }
      .auth-head { background: var(--accent-fill); padding: 14px 24px; }
      .auth-body { padding: 24px 28px 28px; }
      .auth-title { margin: 0 0 20px; font-size: 20px; font-weight: 700; color: var(--text); line-height: 1.25; }
      .auth-body label.label-font { font-family: 'Barlow', sans-serif; font-size: 14px !important; color: var(--text) !important; margin-bottom: 6px !important; }
      .auth-body input { height: 48px; font-size: 16px; }
      .auth-body .btn { min-height: 48px; font-size: 16px; border-radius: 8px; }
      .auth-body > div[style] { font-size: 14px !important; }
      .pw-wrap { position: relative; }
      .pw-wrap input { padding-right: 52px; }
      .pw-eye { position: absolute; right: 2px; top: 50%; transform: translateY(-50%); width: 44px; height: 44px; border: none; background: transparent; color: var(--text-dim); font-size: 18px; cursor: pointer; border-radius: 6px; }
      .pw-eye[aria-pressed="true"] { color: var(--text); }
      @media (max-width: 720px), (max-width: 1000px) and (pointer: coarse) and (hover: none) {
        .auth-body { padding: 20px 18px 24px; }
        .auth-body input { height: 52px; font-size: 16px !important; }
        .auth-body .btn { min-height: 52px; }
      }
      /* Lišta kalendára — na počítači ovládanie 34 px v jednom riadku (na mobile ostáva ako doteraz). */
      @media (min-width: 1001px), (min-width: 721px) and (hover: hover) {
        .cal-bar .seg > button { min-height: 34px; padding: 0 10px; }
        .cal-bar input, .cal-bar select { height: 34px !important; }
        .cal-bar button[aria-label$="mesiac"], .cal-bar .btn { min-height: 34px !important; min-width: 34px !important; height: 34px; padding-top: 0; padding-bottom: 0; }
      }
      .tbar input:not([type=checkbox]):not([type=radio]), .tbar select { min-height: 40px; font-size: 14px; }
      .jobs-table th.m-only + th, .jobs-table td.m-only + td { padding-left: 20px; }
      .m-only { display: none !important; }
      @media (max-width: 720px), (max-width: 1000px) and (pointer: coarse) and (hover: none) {
        .m-only { display: inline-flex !important; }
        table.table-cards td.m-only { display: flex !important; }
        table.table-cards td.m-only.td-plain { display: block !important; }
      }
      .utabs { display: flex; gap: 22px; border-bottom: 1px solid var(--border); margin-top: 6px; overflow-x: auto; }
      @media (max-width: 720px) { .utabs { gap: 14px; } .utab { font-size: 14px !important; } } /* „Časová os“ sa zmestí na mobile */
      .utab { padding: 10px 0; border: none; border-bottom: 2px solid transparent; background: transparent; font: inherit; font-size: 15px; color: var(--text-dim); cursor: pointer; white-space: nowrap; }
      .utab:hover { color: var(--text); }
      .utab.active { border-bottom-color: var(--accent); color: var(--text); font-weight: 700; }
      .side-dl { margin: 0; display: grid; grid-template-columns: 170px minmax(0, 1fr); }
      .side-dl dt { padding: 12px 12px 12px 0; border-bottom: 1px solid var(--border); color: var(--text-dim); font-size: 14px; }
      .side-dl dd { margin: 0; padding: 12px 0; border-bottom: 1px solid var(--border); font-size: 15px; color: var(--text); min-width: 0; overflow-wrap: anywhere; }
      .side-dl dd:has(select) { padding: 7px 0; }
      .side-dl select { height: 38px; min-width: 220px; max-width: 100%; font-size: 15px; }
      .side-dl a { color: var(--text); }
      .side-dl dd.warn { color: var(--danger-text); font-weight: 600; }
      /* Karta bez záložiek — obsah nesmie lepiť na súhrn v hlavičke. */
      .side-body > :first-child:not(.utabs) { margin-top: 16px; }
      .side-sec { font-family: 'Barlow Condensed', sans-serif; font-weight: 600; font-size: 14px; letter-spacing: .06em; text-transform: uppercase; color: var(--text-dim); margin: 22px 0 2px; }
      input, select, textarea { background: var(--control-bg); border: 1.5px solid var(--border); color: var(--text); border-radius: 6px; padding: 7px 10px; font-size: 14px; font-family: 'Barlow', sans-serif; }
      input:focus, select:focus, textarea:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px rgba(227,6,19,.25); }
      /* v1.0.805: viditeľný fokus pri ovládaní klávesnicou (Tab) — tmavý obrys, v tmavom režime a v červenej hlavičke svetlý. */
      :is(button, a, summary, label.btn, [tabindex]:not([tabindex="-1"]), input, select, textarea):focus-visible { outline: 2px solid #1A1A1A; outline-offset: 2px; }
      :is(input, select, textarea):focus-visible { outline-offset: 1px; }
      body.dark :is(button, a, summary, label.btn, [tabindex]:not([tabindex="-1"]), input, select, textarea):focus-visible,
      .header-topbar :focus-visible, .header-topbar :is(button, a, input, [tabindex]):focus-visible { outline-color: #F2F2F2; }
      #whatsnew-older:focus-visible { outline: 2px solid #1A1A1A; outline-offset: 2px; } /* hlavička verzie po „Staršie zmeny“ má tabindex -1 */
      body.dark #whatsnew-older:focus-visible { outline-color: #F2F2F2; }
      label.btn:has(input:focus-visible) { outline: 2px solid #1A1A1A; outline-offset: 2px; }
      body.dark label.btn:has(input:focus-visible) { outline-color: #F2F2F2; }
      .modal-panel [data-miss-auto]:focus-visible, .modal-panel:has(.ff-tried) [data-miss]:focus-visible { outline-color: var(--danger); }
      table { width: 100%; border-collapse: collapse; }
      th { text-align: left; font-family: 'Barlow', sans-serif; text-transform: uppercase; font-size: 10px; font-weight: 700; letter-spacing: .05em; color: var(--text-dim); padding: 10px; border-bottom: 1px solid var(--border); white-space: nowrap; background: var(--panel-2); position: sticky; top: var(--header-h, 62px); z-index: 40; }
      /* Tabuľky v paneli: na širokej obrazovke orezané (hlavička tabuľky ostáva prilepená pod lištou),
         na užšej sa dajú posúvať doľava/doprava — vtedy hlavička nie je prilepená (inak by sa posunula). */
      /* Tabuľka širšia ako jej panel: panel dostane .tw-scroll (useTableScrollFit) a dá sa posúvať doľava/doprava —
         aj hore-dole vo vlastnom okne na výšku obrazovky (vodorovný posuvník je tak vždy na očiach, hlavička ostáva prilepená). */
      .table-wrap, .jobs-wrap { max-width: 100%; }
      .tw-scroll { overflow: auto !important; position: relative; max-height: calc(100vh - var(--header-h, 62px) - 24px); }
      .tw-scroll th { top: 0; }
      /* V okne (Modal) sa nescrolluje celá stránka pod hlavičkou appky, ale
         samotný .modal-overlay — tabuľky vnútri sa preto lepia na vrch OKNA
         (0), nie o výšku hlavičky nižšie (tam by zbytočne visela medzera). */
      .modal-panel th { top: 0; }
      /* Rovnaký prípad ako vyššie — tabuľka vo vlastnom vnútornom scrolli
         (maxHeight + overflow), nie v okne (Modal). */
      .table-scroll-inner th { top: 0; }
      .skip-link { position: absolute; left: -9999px; top: 8px; z-index: 10000; }
      .skip-link:focus { left: 12px; padding: 8px 14px; border-radius: 8px; background: var(--panel); color: var(--text); border: 2px solid var(--accent); }
      /* Tabuľka vo vlastnom rolovacom/orezanom kontajneri: sticky top sa ráta od kontajnera, nie od hlavičky stránky — inak hlavička vlezie do riadkov. */
      [style*="overflow"] th { top: 0; }
      td { padding: 9px 10px; border-bottom: 1px solid var(--border); font-size: 13px; }
      tr:hover td { background: var(--accent-light); }

      /* ══════════════════════════════════════════════════════
         MOBILE — telefóny a malé tablety
         (aj telefón na šírku — viď vysvetlenie pri prvom @media vyššie)
         ══════════════════════════════════════════════════════ */
      /* Úzke okno PC (hlavička sa zalomí, zvonček je vľavo) — panel pod hlavičku k pravému okraju, nie mimo obrazovky. */
      @media (min-width: 721px) and (max-width: 1000px) { .dropdown-panel { position: fixed !important; left: auto !important; right: 8px !important; top: calc(var(--header-h, 62px) + 4px) !important; } }
      @media (max-width: 720px), (max-width: 1000px) and (pointer: coarse) and (hover: none) {
        /* iOS "gumové" posúvanie stránky mimo obrazovku (najmä šikmým ťahom prsta) —
           len na mobile, na PC by to blokovalo bežné rolovanie kolieskom/scrollbarom. */
        html, body { overscroll-behavior: none; overflow-x: hidden; }

        /* To isté pre servisný protokol — len na mobile, nech na PC ide bežné
           rolovanie kolieskom myši (predtým sa toto omylom aplikovalo vždy). */
        .protocol-overlay { overscroll-behavior: none; touch-action: pan-y; }

        /* Lišta „Prideliť vybrané“ — na mobile je posuvný body, sticky by nefungoval; nad spodnou lištou. */
        .bulk-bar { position: fixed !important; left: 8px; right: 8px; top: auto !important; bottom: calc(84px + env(safe-area-inset-bottom)); z-index: 150; margin: 0 !important; box-shadow: 0 4px 16px rgba(0,0,0,.18); }
        .bulk-bar { flex-wrap: nowrap !important; gap: 6px !important; padding: 6px 8px !important; }
        .bulk-bar .btn { white-space: nowrap; padding: 6px 8px !important; }

        /* Zvonček a menu používateľa — na mobile sa pripnú k okraju obrazovky
           namiesto malej ikonky, nech sa nikdy nezobrazia mimo viditeľnej plochy. */
        .dropdown-panel {
          position: fixed !important;
          left: 8px !important;
          right: 8px !important;
          top: calc(62px + env(safe-area-inset-top) + min(14px, env(safe-area-inset-top))) !important;
          width: auto !important;
          max-width: none !important;
        }
        /* Zvonček na mobile na celú výšku pod hlavičkou (návrh 4, k34) — pod ním nepresvitá Dnes. */
        .dropdown-panel.bell-panel { left: 0 !important; right: 0 !important; bottom: 0 !important; max-height: none !important; border-radius: 16px 16px 0 0; padding-bottom: calc(76px + env(safe-area-inset-bottom)) !important; } /* posledné upozornenie nad spodnou lištou */
        .bell-panel .bell-head { position: sticky; top: 0; z-index: 1; background: var(--panel); }
        .bell-panel .bell-title { font-size: 17px !important; }
        .bell-panel .bell-unread { background: transparent !important; }

        /* Tlačidlá pre technikov (Vypísať protokol, VTZ EZ...) — na mobile
           naťahovali hlavičku a zalamovali sa nečitateľne. Namiesto toho sa
           tam schovajú a zobrazí sa pevný pásik dole na obrazovke. */
        .header-tech-actions { display: none !important; }
        .mobile-tech-actions {
          display: flex !important;
          position: fixed;
          left: 0;
          right: 0;
          bottom: 0;
          z-index: 150;
          gap: 6px;
          padding: 6px 8px calc(6px + env(safe-area-inset-bottom)) 8px;
          background: var(--panel);
          border-top: 1px solid var(--border);
          box-shadow: 0 -2px 8px rgba(0,0,0,.08);
        }
        /* Táto lišta vedela na iOS presvitať/prekrývať sa s tlačidlami na
           spodku otvorenej karty aj napriek nižšiemu z-indexu (stacking
           kontext karty a hlavičky sú inde v strome, z-index medzi nimi
           nič nerieši) — kým je otvorené čo i len jedno okno, lišta sa
           radšej rovno schová celá. */
        body.has-open-modal .mobile-tech-actions { display: none !important; }
        /* Celoobrazovkové okná mimo Modal (protokol, tlačová verzia, podpis, fotka, mobilné menu) — lišta preč. */
        body:has(.protocol-overlay) .mobile-tech-actions,
        body:has(.fullscreen-overlay) .mobile-tech-actions,
        body:has(.mobile-nav-overlay) .mobile-tech-actions { display: none !important; }
        .app-main.has-mobile-tech-bar { padding-bottom: calc(76px + env(safe-area-inset-bottom)) !important; }

        /* maSKot bublina — na mobile by inak sedela presne v spodnej lište
           s tlačidlami pre technikov (keby mal daný účet aj tie práva) a
           prekrývala by ich. Posunutá vyššie vždy, nech je to jednoduché a
           spoľahlivé aj keď lišta zrovna nie je zobrazená. */

        /* To isté pre bublinu "čaká na zobrazenie" (skok na zvýraznené poškodenie). */
        .damage-toast-fab { bottom: calc(20px + 76px + env(safe-area-inset-bottom)) !important; }

        /* Na mobile namiesto ľavého menu spodná lišta (MobileTabBar), „+ Nové“ je pod „+“. */
        .side-menu-wrap, .header-new-wrap { display: none !important; }
        .header-phone-mobile { display: inline-flex; }
        .mnav-bar { gap: 0 !important; padding: 4px 4px calc(4px + env(safe-area-inset-bottom)) !important; }

        :root {
          --gantt-name-col: 92px;
          /* 53px — na užšom mobile (~331px na dni po odčítaní stĺpca s menom)
             vidno naraz cca 4,5 dňa. Na širšom mobile/tablete v tomto istom
             breakpointe to logicky ukáže viac dní naraz, lebo je tam viac
             miesta — rovnaká šírka bunky, len viac sa ich zmestí. */
          --gantt-day-col: 53px;
          --gantt-plan-day-col: 46px;
        }
        .app-main { padding: 10px !important; }
        /* flex-wrap ostáva "wrap" (nie nowrap) — je to poistka: ak by sa aj
           napriek nižšiemu doplneniu niečo nezmestilo, nech sa to zalomí na
           ďalší riadok, nie aby to odrezalo/schovalo zvonček mimo obrazovky
           (presne to sa predtým dialo s vynúteným nowrap). */
        /* Logo, názov+verzia, lupa, zvonček a avatar používateľa musia na
           mobile vyjsť do JEDNÉHO riadku (nowrap) — preto: lupa namiesto
           celého vyhľadávacieho poľa, iniciály namiesto celého mena, a
           flex-wrap sa tu (na rozdiel od zvyšku appky) vypína. */
        .header-topbar { padding: 6px 10px !important; gap: 6px !important; flex-wrap: nowrap !important; }
        .header-navbar { padding: 7px 10px !important; gap: 8px !important; }
        .header-logo-img { height: 20px !important; }
        .header-divider { display: none !important; }
        .header-brand-sub { display: none !important; }
        .user-menu-desktop-wrap { display: none !important; }
        .user-menu-mobile-wrap { display: block !important; }
        .header-top-actions { gap: 6px !important; flex: 0 0 auto; flex-wrap: nowrap !important; }
        /* Lupa (zbalená na ikonu) predtým sedela vo vlastnom, na stred
           zarovnanom "1 1 auto" bloku medzi nadpisom a zvončekom — v úzkej
           hlavičke to vyzeralo ako osamotená ikona uprostred prázdna. Bez
           roztiahnutia/centrovania sa "prisunie" hneď vedľa zvončeka. */
        .header-search-wrap { flex: 0 0 auto !important; justify-content: flex-start !important; min-width: 0 !important; margin-left: auto; }
        /* Lupa, zvonček a avatar používateľa — rovnaké kolieskové tlačidlo
           (veľkosť, tvar, priehľadné biele pozadie), nech na seba v hlavičke
           vizuálne sedia a nevyzerajú ako z inej appky. */
        .header-icon-btn {
          width: 44px !important;
          height: 44px !important;
          min-width: 44px !important;
          min-height: 44px !important;
          border-radius: 50% !important;
          padding: 0 !important;
          display: flex !important;
          align-items: center !important;
          justify-content: center !important;
          font-size: 15px !important;
        }
        /* Pole hľadania je na mobile schované, vidno len lupu — kliknutím
           naň (global-search-mobile-open) sa zobrazí ako riadok cez celú
           šírku POD prvým riadkom hlavičky (bežný tok, nie position:fixed —
           to na iOS pri otvorení klávesnice vedelo "poskakovať"/vykresliť sa
           na náhodnom mieste). */
        .header-topbar:has(.global-search-mobile-open) { flex-wrap: wrap !important; }
        .global-search-box { min-width: 0 !important; width: auto !important; flex: 0 0 auto; }
        .global-search-box.global-search-mobile-open { flex-basis: 100% !important; order: 5; margin-top: 4px; }
        .global-search-mobile-trigger { display: flex !important; }
        .global-search-input-wrap { display: none; }
        .global-search-box.global-search-mobile-open .global-search-mobile-trigger { display: none !important; }
        .global-search-box.global-search-mobile-open .global-search-input-wrap {
          display: flex !important;
          align-items: center;
          gap: 6px;
          width: 100%;
        }
        .global-search-box.global-search-mobile-open .global-search-input-wrap input { flex: 1 1 auto; }
        .global-search-mobile-close { display: flex !important; }
        .panel { padding: 12px !important; }
        /* display:flex tu MUSÍ byť tiež !important — kalendár požičovne má
           túto lištu nastavenú inline ako display:"grid" (3 stĺpce vedľa
           seba), čo sa nikdy nezalomí na užšom telefóne bez ohľadu na
           flex-wrap (tá vlastnosť na grid kontajner nemá vôbec žiaden efekt).
           Preto v portraite miznú/orezávajú sa tlačidlá napravo (→, Dnes,
           Normálny/Kompaktný) — grid stĺpce sa len stlačia/pretečú, nezalomí
           sa to na ďalší riadok tak ako pri flexboxe. */
        .quick-filters { display: flex !important; flex-wrap: wrap !important; justify-content: center !important; }
        /* Kalendár požičovne — namiesto (chipy) / (mesiac) / (Normálny+zoradenie)
           ako troch samostatných riadkov po zalomení: 1. riadok chipy+lupa+
           ozubené koliesko, 2. riadok mesiac — oboje na stred. Nastavenia
           (Normálny/Kompaktný, zoradenie) sú na mobile len za kolieskom
           (gantt-desktop-settings schované, gantt-mobile-settings viditeľné). */
        .quick-filters > div:first-child { width: 100%; justify-content: center; }
        .quick-filters > div:nth-child(2) { width: 100%; justify-content: center; }
        .gantt-desktop-settings { display: none !important; }
        .gantt-mobile-settings { display: inline-block !important; }

        /* Depo filter chipy skrátené na mobile (BA/NR/ZV/ZA/PO/EXT) — jednotné
           so skratkami, čo už mal gantt Kalendára/Požičovne. */
        .depo-chip-full { display: none !important; }
        .depo-chip-short { display: inline !important; }
        .depo-chip-btn { padding: 5px 8px !important; }

        /* Lupa namiesto trvalo otvoreného poľa vyhľadávania — v zoznamoch
           (Stroje, Zamestnanci, Diely...) rovnaký vzor ako vyhľadávanie v
           hlavičke: ikona, po kliknutí sa pole rozbalí v bežnom toku. */
        .list-search-mobile-trigger { display: flex !important; align-items: center; justify-content: center; }
        .list-search-input-wrap { display: none; }
        /* Volajúci väčšinou zvyknú posielať minWidth:200-280 (na plné pole
           na webe) — kým je zbalené na ikonu, to zbytočne naťahovalo celý
           box (aj keď v ňom bola vidno len 34px lupa), a napr. v riadku
           filtrov Kalendára to tlačilo lupu+koliesko na vlastný riadok. */
        .list-search-box:not(.list-search-mobile-open) { min-width: 0 !important; width: auto !important; }
        .list-search-box.list-search-mobile-open { flex: 1 1 100%; }
        .list-search-box.list-search-mobile-open .list-search-mobile-trigger { display: none !important; }
        .list-search-box.list-search-mobile-open .list-search-input-wrap { display: block !important; width: 100%; }

        /* Info-grid karty (Karta stroja, zákazky, šoféra, technika…) — jeden stĺpec pod sebou */
        .resp-grid { grid-template-columns: 1fr !important; }

        /* Modálne okná — takmer celá obrazovka, menší padding */
        /* transform:translateZ(0) tu nie je na rodičovi žiadneho sticky prvku
           (karty v modáloch žiadny sticky nemajú, na rozdiel od Ganttu vyššie,
           kde presne toto rozbíjalo position:sticky) — vynúti si to vlastnú
           GPU vrstvu pre scrollovanie dlhých kariet, čo je známa oprava pre
           WebKit chybu, keď pri rýchlom scrolle ostane "zamrznutý" starý
           vykreslený obsah cez novší (vyzerá to ako zle poskladané/prekryté
           texty, aj keď telefón už dávno nescrolluje).
           Predošlé pokusy (GPU vrstva na .modal-overlay aj na .modal-panel)
           nepomohli — stále sa spoliehali na to, že WebKit správne
           PREKRESLÍ pozadie karty pri scrolle. Namiesto opravy prekreslenia
           je tu teraz jednoduchší, spoľahlivejší prístup: na mobile je karta
           (.modal-panel) VŽDY presne cez celú obrazovku (šírka 100%, žiadny
           padding okolo, žiadne zaoblenie) — takže .modal-overlay pod ňou nie
           je normálne vidno ANI KUS. Keď teda .modal-overlay dostane rovnakú
           plnú (nepriehľadnú) farbu pozadia ako samotná karta namiesto
           tmavého priesvitného scrimu, je jedno, či sa kartička v nejakej
           oblasti nedokreslí — pod ňou nie je "diera" do stránky za modálom,
           len tá istá farba pozadia. Chyba tak zostáva neviditeľná, aj keď
           nastane. */
        .modal-overlay { padding: 0 !important; align-items: stretch !important; overscroll-behavior: contain; background: var(--panel) !important; }
        /* .panel (základná trieda) má vlastný 1px border a box-shadow —
           tie sa predtým nechávali, lenže farba borderu (var(--border), sivá)
           sa oproti bielemu/tmavému pozadiu vždy odlíši, takže presne na
           spodnej hrane karty (kde .modal-panel končí a .modal-overlay pod
           ňou pokračuje tou istou farbou) bola vidno tenká čiara — zvyšok
           po predošlej "diere" v pozadí. Border aj shadow tu vypnuté. */
        .modal-panel { width: 100% !important; max-width: 100% !important; min-height: 100dvh; border-radius: 0 !important; border: none !important; box-shadow: none !important; padding: 12px !important; padding-top: max(12px, calc(env(safe-area-inset-top) + min(14px, env(safe-area-inset-top)))) !important; padding-bottom: max(12px, env(safe-area-inset-bottom)) !important; }
        /* Dlhé karty (Karta stroja a pod.) — .modal-overlay je vlastný
           scroll-kontajner (overflowY:auto). Bez "overscroll-behavior" sa na
           iOS pri dotiahnutí na koniec obsahu "gumovo" preťahovalo ZA vlastný
           obsah a cez tú medzeru bolo krátko vidno, čo je pod modálom
           (vyzeralo to, akoby modálu na chvíľu zmizlo pozadie/prekrývalo sa
           to s obsahom pod ním). "contain" zastaví ten gumový efekt len na
           tomto kontajneri, nemení scrollovanie zvyšku appky. 100dvh namiesto
           100vh — na mobile Safari sa 100vh počíta podľa výšky BEZ schovanej
           adresovej lišty, takže po jej schovaní (počas scrollu) bola pod
           kartou viditeľná medzera bez pozadia. */
        .app-main { overscroll-behavior: contain; }
        /* Len -12px hore (nie aj safe-area-inset-top ako predtým) — inak sa
           táto lišta (má v sebe zatváracie ×) vytiahla úplne až za stavový
           riadok telefónu a × sa dala schovať za hodiny/batériu, nedalo sa
           na ňu kliknúť. Safe-area medzera nad ňou tak ostáva zachovaná. */
        .modal-toolbar { margin: -12px -12px 14px !important; }
        .modal-header h3 { font-size: 20px !important; }
        /* Formuláre (v1.0.794) na mobile: polia 48 px, lišta ukotvená dole na celú šírku. */
        .modal-panel:not(.modal-side-panel) :is(input:not([type=checkbox]):not([type=radio]):not([type=file]):not([type=color]):not([type=range]), select) { min-height: 48px; font-size: 16px; }
        .modal-panel:not(.modal-side-panel) textarea { font-size: 16px; }
        .modal-panel .btn { min-height: 48px; }
        .job-form-cols { margin: 0 -12px; }
        .job-form-cols > fieldset { padding: 14px 12px 4px; }
        .job-form-foot { margin: 0 -12px -12px; bottom: -12px; padding: 10px 12px max(12px, env(safe-area-inset-bottom)); border-radius: 0; flex-wrap: wrap; }
        .job-form-foot .miss-pill { order: -1; flex: 1 1 100%; }
        .job-form-foot .ff-btns { flex: 1 1 0; margin-left: 0; flex-wrap: nowrap; }
        .job-form-foot .ff-btns .btn, .job-form-foot > .btn { flex: 1; min-height: 52px; font-size: 15px; }
        .job-form-foot:not(.ff-confirm) .ff-cancel { display: none; }
        .job-form-foot.ff-confirm { position: fixed; left: 0; right: 0; bottom: 0; margin: 0; }
        .job-form-foot.ff-confirm .btn { min-height: 48px; }
        .fgrid2 { grid-template-columns: minmax(0, 1fr); }
        /* v1.0.805: bod a V poriadku/Problém v jednom riadku (na úzkom displeji sa zalomí). */
        .cks { margin-left: auto; }
        .cks > button { min-width: 82px; padding: 0 8px; }
        .ckt { min-width: 0; flex: 1 1 110px; }
        .cki { padding: 8px 10px; gap: 8px; }
        .side-foot .jc-report { display: none; }
        .jc-report-m { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 10px; }
        .jc-report-m .btn { flex: 1 1 140px; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 6px; }
        .side-foot:has(.one-row) { flex-wrap: nowrap; }
        .side-foot-btns.one-row { flex-wrap: nowrap !important; }
        .side-foot-btns.one-row .btn { flex: 1 1 0; min-width: 0; padding: 7px 8px; }
        .tr-filt2 { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; width: 100%; }
        .tr-filt2 > * { min-width: 0 !important; width: 100%; }
        .fsum { grid-template-columns: minmax(0, 1fr); }
        .ftable td, .ftable th { font-size: 14px; }
        .print-bar-x { height: 60px; max-width: 52vw; padding: 0 10px; gap: 8px; }
        .print-bar-long { display: none; }
        .modal-title-main { font-size: 20px !important; }
        /* Krížik na zatvorenie — 30px je na dotyk malé, na mobile väčší. */
        .modal-close-x { width: 44px !important; height: 44px !important; font-size: 26px !important; }
        /* Bočný panel zákazky = celoobrazovkový list; okraje rieši side-head/body/foot. */
        .modal-panel.modal-side-panel { padding: 0 !important; height: 100dvh; }
        .side-head { padding: max(10px, env(safe-area-inset-top)) 16px 0; }
        .side-title { font-size: 22px; }
        .side-body { padding: 0 16px 16px; }
        .side-foot { padding: 12px 16px max(12px, env(safe-area-inset-bottom)); }
        .side-foot .btn { min-height: 48px; }
        .side-foot-btns { flex: 1 1 0; min-width: 0; }
        .side-foot-btns .btn { flex: 1 1 100%; }
        .side-summary, .side-summary.s3 { grid-template-columns: 1fr 1fr; }
        .side-summary.s3 > div:last-child { grid-column: 1 / -1; }
        html:has(.mnav-bar) { scroll-padding-bottom: 84px; } /* fokus klávesnicou sa nezastaví pod spodným menu */
        .side-summary > div:nth-child(2) { border-right: none; }
        .side-summary > div:nth-child(-n+2) { border-bottom: 1px solid var(--border); }
        .side-dl { grid-template-columns: 1fr; }
        .side-dl dt { border-bottom: none; padding: 10px 0 0; font-size: 13px; }
        .side-dl dd { padding: 2px 0 10px; }
        .side-dl select { min-width: 0; width: 100%; height: 48px; }

        /* Tabuľky — radšej vodorovné rolovanie vnútri panelu než rozbitie stránky.
           Zámerne LEN pre panely s tabuľkou (:has), nie pre všetky .panel —
           overflow-x:auto totiž podľa CSS špecifikácie automaticky prepne aj
           overflow-y na "auto" (ak nie je nastavené inak), a to vedelo
           orezať/schovať rozbaľovacie zoznamy (dropdown), ktoré vnútri iného
           .panel (napr. filter/search panela) siahajú POD jeho okraj —
           presne ten efekt, čo vyzeral ako "odlepený"/zmiznutý dropdown. */
        .panel:has(table) { overflow-x: auto; }
        .panel:has(table) th { top: 0; }
        table { font-size: 11px; }
        th, td { padding: 6px 7px !important; }
        table th:first-child, table td:first-child {
          position: sticky;
          left: 0;
          background: var(--panel);
          z-index: 1;
          box-shadow: 2px 0 4px rgba(0,0,0,.08);
        }

        /* Väčšie, na dotyk pohodlnejšie tlačidlá */
        .btn { min-height: 48px; padding: 7px 14px; font-size: 15px; }

        /* Formulárové polia nech nikdy nepretečú cez okraj obrazovky */
        input, select, textarea { min-width: 0 !important; max-width: 100%; font-size: 13px; }

        h3.label-font { word-break: break-word; }

        /* Zákazky — rýchle rozbaľovacie zoznamy (po termíne/končí čoskoro/bez šoféra) */
        .quick-job-row { flex-direction: column !important; align-items: flex-start !important; gap: 6px !important; }
        .quick-job-info { font-size: 14px !important; }
        .quick-job-info .mono { font-size: 14px !important; }
        .quick-job-btn { margin-left: 0 !important; width: 100%; }

        /* Gantty (Kalendár, Plán servisu) — kompaktnejšie stĺpce, menšie písmo */
        .gantt-cell { font-size: 9px !important; }
        .gantt-header-cell { font-size: 9px !important; padding: 2px !important; }

        /* Vypísanie protokolu — na mobile naozaj cez celú obrazovku, žiadny okraj
           navyše, nech je čo najviac miesta na samotné vypĺňanie. */
        /* Odsadenie od stavového riadku telefónu si dnes rieši priamo
           ProtocolModal/PrintProtocolModal (inline štýl na .protocol-frame-wrap),
           .protocol-overlay samotný už žiadny padding navyše nepotrebuje/nesmie
           mať (zdvojilo by odsadenie). */
        .protocol-frame-wrap { border-radius: 0 !important; }
      }

      /* Spodná lišta (Telefón/Protokol/Porucha/Rezervácia/VTZ EZ) na šírku
         zaberá príliš veľa z už aj tak nízkej výšky obrazovky a pôsobí príliš
         výrazne (veľké tlačidlá s nápismi, plná červená farba na Protokole).
         Na šírku preto len ikony, nižšia a tichšia — bez plnej farby, len
         jemne zvýraznený okraj/ikona pre Protokol. */
      @media (max-width: 1000px) and (pointer: coarse) and (hover: none) and (orientation: landscape) {
        .mobile-tech-actions { padding: 3px 6px calc(3px + env(safe-area-inset-bottom)) 6px !important; gap: 4px !important; }
        .app-main.has-mobile-tech-bar { padding-bottom: calc(64px + env(safe-area-inset-bottom)) !important; }
      }

      /* v1.0.795 — tmavý režim a mobil (len vzhľad). */
      /* Bublina maSKota zakrývala spodné tlačidlá karty/okna — kým je okno otvorené, schová sa. */
      body.has-open-modal .maskot-fab, body:has(.fullscreen-overlay) .maskot-fab { display: none !important; }
      /* plávajúce maSKot tlačidlo nezakryje posledné tlačidlo v zozname */
      .maskot-fab { position: fixed; right: 0; top: 66%; transform: translateY(-50%); z-index: 261; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 9px 3px; border: 0; border-radius: 7px 0 0 7px; background: var(--accent-fill); color: #fff; font: 600 11px Barlow, sans-serif; cursor: pointer; box-shadow: -2px 2px 8px rgba(0,0,0,.16); }
      .maskot-fab span { writing-mode: vertical-rl; transform: rotate(180deg); letter-spacing: .04em; }
      .maskot-fab.open { right: min(400px, calc(100vw - 24px)); }
      body.has-open-modal .maskot-panel { display: none !important; } /* otvorené okno (karta) má prednosť; panel sa vráti po jeho zatvorení */
      @media (max-width: 768px) { .maskot-fab.open { display: none !important; } } /* na mobile otvorený panel zatvára × (úzka úchytka je na dotyk malá) */
      .maskot-fab:focus-visible { outline: 2px solid var(--text); outline-offset: 2px; }
      /* Kalendár vypĺňa obrazovku až po pätičku; na mobile je pätička pod spodným menu — na Kalendári sa skryje. */
      @media (min-width: 1001px), (min-width: 769px) and (hover: hover) { .app-main:has(.cal-bar) { padding-bottom: 0 !important; } .app-shell:has(.cal-bar) .app-footer { padding: 6px 12px !important; } }
      @media (max-width: 768px), (max-width: 1000px) and (pointer: coarse) and (hover: none) and (orientation: landscape) { .app-shell:has(.cal-bar) .app-footer { display: none; } }
      /* Kalendár na mobile na šírku (návrh p8): lišta v jednom riadku — depá ako výber, ikony a mesiac vedľa. */
      .cal-depo-sel { display: none; }
      @media (max-width: 1000px) and (pointer: coarse) and (hover: none) and (orientation: landscape) {
        .cal-bar { margin-bottom: 8px !important; gap: 8px !important; }
        .cal-bar .seg { display: none !important; }
        .cal-bar .cal-depo-sel { display: block; width: 150px; }
        .cal-bar > div { width: auto !important; }
        .cal-bar > div:last-child { margin: 0 0 0 auto !important; }
      }
      /* Užšie okno (tablet, malý notebook): vyhľadávanie Kalendára len ako lupa, nech sa lišta zmestí do 1–2 riadkov. */
      @media (min-width: 769px) and (max-width: 1100px) {
        .cal-bar .list-search-mobile-trigger { display: flex !important; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: 8px; }
        .cal-bar .list-search-input-wrap { display: none; }
        .cal-bar .list-search-box:not(.list-search-mobile-open) { min-width: 0 !important; width: auto !important; }
        .cal-bar .list-search-box.list-search-mobile-open .list-search-mobile-trigger { display: none !important; }
        .cal-bar .list-search-box.list-search-mobile-open .list-search-input-wrap { display: block !important; }
      }
      /* Pásy v pláne servisu majú biely text na farbe stavu — v tmavom režime sú tie farby svetlé, preto tu plné tmavšie. */
      .app-shell.dark .gantt-scroll .gantt-cell { --danger: #c62f36; --info: #2b6cb0; --ok: #3d7a28; --warn: #9a5f0c; }
      .app-shell.dark .global-search-input-wrap input { background: var(--bg) !important; }
      @media (max-width: 720px), (max-width: 1000px) and (pointer: coarse) and (hover: none) {
        /* Dotykové plochy min. 44 px (Gantt ostáva bez zmeny). */
        /* Len zväčšuje (nikdy nezmenšuje väčšie terénne 48–56 px): nulová špecificita pre triedy, !important len pre malé inline hodnoty. */
        :where(.app-shell) :where(.utab, .mnav-row, .kebab-item, summary, input:not([type=checkbox]):not([type=radio]):not([type=file]):not([type=range]):not([type=color]), select) { min-height: 44px; }
        .app-shell .seg > button, .app-shell .fchip, .app-shell .tbar :is(input:not([type=checkbox]):not([type=radio]), select), .app-shell :is(.jobs-table, .frow, .tbar) .btn { min-height: 44px; }
        :where(.app-shell) :where(.btn, .utab, button[aria-label$="mesiac"], .depo-chip-btn) { min-width: 44px; }
        .app-shell :is(button, a, select, input, summary, [role=button]):is([style*="min-height: 2"], [style*="min-height: 3"], [style*="min-height: 40px"], [style*="min-height: 41px"], [style*="min-height: 42px"], [style*="min-height: 43px"], [style*="height: 3"], [style*="height: 40px"]):not(.gantt-scroll *) { min-height: 44px !important; }
        .app-shell :is(button, a, [role=button]):is([style*="min-width: 2"], [style*="min-width: 3"], [style*="min-width: 40px"], [style*="min-width: 41px"], [style*="min-width: 42px"], [style*="min-width: 43px"]):not(.gantt-scroll *) { min-width: 44px !important; }
        /* Písmo min. 13 px — drobné inline veľkosti (9–12,5 px) mimo Ganttu, spodná lišta, odznaky, päta. */
        .app-shell :is([style*="font-size: 9px"], [style*="font-size: 9.5px"], [style*="font-size: 10px"], [style*="font-size: 10.5px"], [style*="font-size: 11px"], [style*="font-size: 11.5px"], [style*="font-size: 12px"], [style*="font-size: 12.5px"]):not(.gantt-scroll, .gantt-scroll *) { font-size: 13px !important; }
        .app-shell :is(.badge, .count-badge, th, .mnav-t, .nav-b):not(.gantt-scroll *) { font-size: 13px; }
        .app-shell :is(.depo-chip-short, .label-font):not(.gantt-scroll *) { font-size: max(13px, 1em); }
        .mnav-b { font-size: 13px; line-height: 16px; }
        .app-shell label:has(> input[type=checkbox], > input[type=radio]):not(.gantt-scroll *) { min-height: 44px; }
        /* Čísla strojov / telefóny ako odkaz v texte — väčšia dotyková plocha bez zmeny riadkovania. */
        .app-shell :is(button.tnum, a.tnum, a[href^="tel:"]):not(.btn):not(.gantt-scroll *) { padding-block: 14px !important; margin-block: -14px !important; }
        /* Samostatné zaškrtávacie políčko (hromadný výber) — aspoň 24 px. */
        .app-shell input[type=checkbox]:not(label *):not(.gantt-scroll *) { width: 24px; height: 24px; }
        .fphoto button { width: 44px; height: 44px; top: -14px; right: -14px; }
        /* Segmentový prepínač — jeden riadok rovnakých políčok, popis sa zalomí v políčku;
           od 5 možností mriežka po 3 (nie osamotené „Externé“ / „Minulý mesiac“ na novom riadku). */
        .seg { display: grid !important; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); width: 100%; }
        .seg > button { white-space: normal; min-width: 0; padding: 4px 6px; line-height: 1.15; }
        .seg:has(> :nth-child(5)):not(:has(> :nth-child(7))) { grid-auto-flow: row; grid-template-columns: repeat(3, minmax(0, 1fr)); }
        .seg:has(> :nth-child(5)):not(:has(> :nth-child(7))) > button:nth-child(n+4) { border-top: 1px solid var(--border); }
        .seg:has(> :nth-child(5)):not(:has(> :nth-child(7))) > button:nth-child(3n+1) { border-left: 0; }
        /* 4 voľby s dlhými slovami („Vyfakturované“) — 2×2, slovo sa nedá zalomiť. */
        .seg.seg-2x2 { grid-auto-flow: row; grid-template-columns: repeat(2, minmax(0, 1fr)); }
        .seg.seg-2x2 > button:nth-child(n+3) { border-top: 1px solid var(--border); }
        .seg.seg-2x2 > button:nth-child(odd) { border-left: 0; }
      }

    `}</style>
  );
}

// Čaká na jednorazový zdvih plošiny (riseMs) AJ na skutočné načítanie appky —
// podľa toho, čo trvá dlhšie. Ak sa appka načíta skôr, plošina si pokojne
// dobehne celý zdvih hore; ak trvá načítanie appky dlhšie, plošina hore
// jednoducho počká, nedvíha sa a nespúšťa dookola. isLoading musí pri každej
// novej fáze (napr. "načítavam dáta" → "načítavam profil") prejsť cez false,
// aby sa pri ďalšom "true" začal počítať nový zdvih od začiatku.
function useRiseThenReveal(isLoading, riseMs) {
  const [visible, setVisible] = useState(isLoading);
  const startRef = useRef(isLoading ? Date.now() : null);
  useEffect(() => {
    if (isLoading) {
      if (startRef.current === null) startRef.current = Date.now();
      setVisible(true);
      return;
    }
    if (startRef.current === null) {
      setVisible(false);
      return;
    }
    const remaining = riseMs - (Date.now() - startRef.current);
    if (remaining <= 0) {
      setVisible(false);
      startRef.current = null;
      return;
    }
    const timer = setTimeout(() => {
      setVisible(false);
      startRef.current = null;
    }, remaining);
    return () => clearTimeout(timer);
  }, [isLoading, riseMs]);
  return visible;
}

// Kontrola novej verzie appky — na rozdiel od prvej verzie tejto kontroly
// (čo appku hneď a potichu reštartovala) toto len NAHLÁSI, že je dostupná
// nová verzia, a nechá človeka rozhodnúť, kedy si to obnoví — nikdy to
// nespraví samo uprostred rozrobenej práce (napr. rozpísaný protokol).
// Kontroluje sa raz pri načítaní appky, a potom vždy znova, keď sa appka/karta
// vráti do popredia (odomknutie telefónu, prepnutie späť na kartu) — presne
// vtedy je najväčšia šanca, že technik nič práve nevypĺňa.
function useNewVersionCheck() {
  const [newVersionAvailable, setNewVersionAvailable] = useState(false);
  const pendingVersionRef = useRef(null);
  useEffect(() => {
    const STORAGE_KEY = "mateco_app_version";
    function check() {
      fetch(`${import.meta.env.BASE_URL}version.json?t=${Date.now()}`, { cache: "no-store" })
        .then((res) => (res.ok ? res.json() : null))
        .then((data) => {
          if (!data || !data.v) return;
          const stored = localStorage.getItem(STORAGE_KEY);
          if (!stored) {
            localStorage.setItem(STORAGE_KEY, data.v);
            return;
          }
          if (stored !== data.v) {
            pendingVersionRef.current = data.v;
            setNewVersionAvailable(true);
          }
        })
        .catch(() => {
          // Bez pripojenia alebo iná chyba — skúsi to znova nabudúce.
        });
    }
    check();
    function onVisible() {
      if (document.visibilityState === "visible") check();
    }
    document.addEventListener("visibilitychange", onVisible);
    // Aj PC s celý deň otvorenou kartou (druhý monitor) — každých 30 min (audit 23. 10.).
    const iv = setInterval(check, 30 * 60 * 1000);
    return () => { document.removeEventListener("visibilitychange", onVisible); clearInterval(iv); };
  }, []);
  function applyNewVersion() {
    if (!pendingVersionRef.current) return;
    localStorage.setItem("mateco_app_version", pendingVersionRef.current);
    const url = new URL(window.location.href);
    url.searchParams.set("_v", pendingVersionRef.current);
    window.location.replace(url.toString());
  }
  return { newVersionAvailable, applyNewVersion };
}

// Nožnicová plošina (4 stupne, v štýle veľkého teleskopického modelu ako
